export interface AppKnowledgeContent { anchor: string; caption: string; keyPoints: string[]; example: string }

export const appKnowledgeContent: Record<string, AppKnowledgeContent> = {
  "kp-m1-p1-c1-han-shu-de-gai-nian": {"anchor":"f: D → R，x ↦ y=f(x)","caption":"函数是「一个输入对应唯一输出」的对应关系，记作 y=f(x)。","keyPoints":["三要素：定义域、对应法则、值域（值域由前两者决定）","一个 x 只能对应一个 y，否则不是（单值）函数","定义域与对应法则都相同，才是同一个函数"],"example":"y=√(1−x²) 的定义域是 [−1,1]，值域是 [0,1]。"},
  "kp-m1-p1-c1-han-shu-de-biao-shi-fa": {"anchor":"y=f(x)；分段：f(x)=g₁(x)（x∈D₁）…","caption":"函数可以用解析式、图像、表格三种方式表示，它们是同一个对应关系的不同侧面：解析式便于计算，图像便于观察单调性与对称性。","keyPoints":["解析式适合计算，图像适合观察整体性质","分段函数是解析式的一种，按区间分别给法则","在表示之间转换时要保留定义域信息"],"example":"y=|x| 既可以写成解析式，也可以画成 V 形图像。"},
  "kp-m1-p1-c1-you-jie-xing": {"anchor":"∃M>0，∀x∈I：|f(x)|≤M","caption":"f 在区间 I 上有界，指存在 M>0 使 |f(x)|≤M 对 I 上所有 x 成立。","keyPoints":["有界 ⇔ 存在 M>0 使 |f(x)|≤M 在区间上恒成立","有界性依赖区间：1/x 在 (0,1) 无界、在 (1,2) 有界","闭区间上连续 ⇒ 有界（这是后面证明题的常用结论）"],"example":"sin x 在 R 上有界（取 M=1）；f(x)=x 在 R 上无界。"},
  "kp-m1-p1-c1-dan-diao-xing": {"anchor":"x₁<x₂ ⇒ f(x₁)≤f(x₂)（单调不减）","caption":"单调递增指 x₁<x₂ 时 f(x₁)≤f(x₂)（严格递增则严格小于）。","keyPoints":["单调性必须在指定区间上讨论","严格单调是反函数存在的充分条件","导数符号是判断单调性的常用工具"],"example":"f(x)=x³ 在 R 上严格递增，所以它有反函数。"},
  "kp-m1-p1-c1-ji-ou-xing": {"anchor":"奇：f(−x)=−f(x)；偶：f(−x)=f(x)","caption":"奇函数满足 f(−x)=−f(x)，图像关于原点对称；偶函数满足 f(−x)=f(x)，图像关于 y 轴对称。","keyPoints":["奇：f(−x)=−f(x)；偶：f(−x)=f(x)","定义域必须关于原点对称，否则无从谈奇偶性","奇函数在 0 处有定义时必有 f(0)=0"],"example":"x³ 是奇函数；cos x 是偶函数；x+1 非奇非偶。"},
  "kp-m1-p1-c1-zhou-qi-xing": {"anchor":"f(x+T)=f(x)","caption":"若存在 T>0 使 f(x+T)=f(x) 对定义域内所有 x 成立，就称 f 为周期函数，T 为它的一个周期；通常所说的周期指最小正周期。","keyPoints":["f(x+T)=f(x)，且 T>0","周期函数的图像每隔 T 重复一次","sin x、cos x 的最小正周期是 2π，|sin x| 是 π"],"example":"sin x 的周期为 2π；|sin x| 的周期为 π。"},
  "kp-m1-p1-c1-fu-he-han-shu": {"anchor":"(f∘g)(x)=f(g(x))","caption":"复合函数 y=f[g(x)] 是把 g 的输出作为 f 的输入；它成立的条件是 g 的值域与 f 的定义域有交集，定义域要同时满足两个函数的要求。","keyPoints":["要求 g 的值域落在 f 的定义域内（至少相交）","复合函数的定义域由内外两个函数共同限制","复合顺序不同，结果一般不同"],"example":"f(x)=√x、g(x)=1−x² 时，复合函数的定义域是 |x|≤1。"},
  "kp-m1-p1-c1-fan-han-shu": {"anchor":"f⁻¹(f(x))=x；f(f⁻¹(x))=x","caption":"若 y=f(x) 中 x 与 y 一一对应，就可以解出 x=f⁻¹(y)，得到反函数；反函数的定义域是原函数的值域，图像关于直线 y=x 对称。","keyPoints":["严格单调是反函数存在的充分条件","反函数的定义域 = 原函数的值域","f⁻¹(f(x))=x，f(f⁻¹(x))=x"],"example":"y=eˣ 的反函数是 y=ln x，定义域 x>0。"},
  "kp-m1-p1-c1-fen-duan-han-shu": {"anchor":"f(x)=g₁(x)（x∈D₁）；g₂(x)（x∈D₂）","caption":"分段函数在不同区间用不同表达式，它是一个函数而不是多个；求值、讨论连续性、求导时都要按「x 落在哪一段」分别处理。","keyPoints":["分段函数是「一个函数」，只是法则分段给出","分段点必须单独讨论连续性与可导性","分段点处要分别求左右极限与左右导数"],"example":"f(x)=x（x≥0）、−x（x<0）就是 f(x)=|x|。"},
  "kp-m1-p1-c1-ji-ben-chu-deng-han-shu-yu-chu-deng-han-1jy1n5": {"anchor":"xᵃ、aˣ、logₐx、sin x、arcsin x 等","caption":"基本初等函数包括幂函数、指数函数、对数函数、三角函数、反三角函数五类；","keyPoints":["五类基本初等函数：幂、指、对、三角、反三角","初等函数 = 基本初等函数经有限次四则运算与复合","初等函数在定义区间内连续，求极限可直接代入"],"example":"y=ln(sin x) 是初等函数，在定义区间内连续。"},
  "kp-m1-p1-c1-shu-lie-yu-ji-xian": {"anchor":"∀ε>0，∃N：n>N ⇒ |aₙ−A|<ε","caption":"数列极限 lim aₙ=A 的 ε-N 定义是：对任意 ε>0，都存在 N，当 n>N 时 |aₙ−A|<ε。","keyPoints":["ε-N 定义：∀ε>0，∃N，n>N ⇒ |aₙ−A|<ε","ε 是任意小的正数，N 依赖 ε","数列极限与前面有限项无关"],"example":"aₙ=1/n 的极限为 0：对任意 ε，取 N=1/ε 即可。"},
  "kp-m1-p1-c1-shou-lian-shu-lie-xing-zhi": {"anchor":"aₙ→A 且 aₙ→B ⇒ A=B","caption":"收敛数列有唯一极限、必定有界，并且具有保号性（极限为正则后面各项也为正）。","keyPoints":["极限唯一：若 aₙ→A 且 aₙ→B，则 A=B","收敛 ⇒ 有界，但有界 ⇏ 收敛","保号性：极限 >0 ⇒ 充分靠后的项都 >0"],"example":"(−1)ⁿ 有界但不收敛，说明有界不是充分条件。"},
  "kp-m1-p1-c1-ji-xian-cun-zai-zhun-ze": {"anchor":"gₙ≤aₙ≤hₙ，gₙ,hₙ→A ⇒ aₙ→A","caption":"两个常用准则：单调有界数列必收敛；若 gₙ≤aₙ≤hₙ 且 gₙ、hₙ 都趋于同一极限 A，则 aₙ 也趋于 A（夹逼准则）。","keyPoints":["单调有界 ⇒ 收敛（常用于递推数列）","夹逼准则：两侧夹住即可得极限","夹逼时两侧极限必须相同"],"example":"aₙ=(sin n)/n：由 −1/n≤aₙ≤1/n 夹逼得极限为 0。"},
  "kp-m1-p1-c1-x-x0-shi-han-shu-ji-xian": {"anchor":"lim_{x→x₀} f(x)=A","caption":"x→x₀ 时的极限描述的是「x 靠近 x₀ 但可以不等于 x₀ 时 f(x) 的趋势」，与 f 在 x₀ 处是否有定义、取值多少完全无关。","keyPoints":["极限与 f(x₀) 的值无关，f(x₀) 甚至可以没有定义","定义用去心邻域：0<|x−x₀|<δ","ε-δ 定义：∀ε>0，∃δ>0，0<|x−x₀|<δ ⇒ |f(x)−A|<ε"],"example":"lim_{x→1}(x²−1)/(x−1)=2，尽管 x=1 处函数没有定义。"},
  "kp-m1-p1-c1-zuo-ji-xian-yu-you-ji-xian": {"anchor":"lim_{x→x₀}f(x)=A ⇔ f(x₀−)=f(x₀+)=A","caption":"x→x₀ 时极限存在的充要条件是左右极限都存在且相等；只要两侧不相等，极限就不存在（对应跳跃间断点）。","keyPoints":["极限存在 ⇔ 左右极限存在且相等","分段函数在分段点必须分别求左右极限","e^{1/x}、arctan(1/x) 在 0 处的左右极限不同"],"example":"f(x)=|x|/x 在 0 处左右极限为 −1 与 1，故极限不存在。"},
  "kp-m1-p1-c1-x-shi-de-ji-xian": {"anchor":"lim_{x→∞}f(x)=A ⇔ lim_{x→+∞}f=lim_{x→−∞}f=A","caption":"x→∞ 时的极限考察 x 无限增大时 f(x) 的走向。","keyPoints":["x→∞ 含 +∞ 与 −∞ 两个方向","两个方向都存在且相等才算极限存在","arctan x 在两个方向上的极限不同，故 lim_{x→∞} 不存在"],"example":"lim_{x→∞} 1/x=0；lim_{x→∞} arctan x 不存在。"},
  "kp-m1-p1-c1-ji-xian-xing-zhi": {"anchor":"lim(f±g)=lim f±lim g；lim(fg)=lim f·lim g","caption":"函数极限具有唯一性、局部有界性与保号性，并满足四则运算：当各部分极限都存在时，和差积商的极限等于极限的和差积商（商的极限要求分母极限不为 0）。","keyPoints":["四则运算的前提是各部分极限都存在","商的极限要求分母极限不为 0","保号性：极限 >0 ⇒ 在去心邻域内函数值 >0"],"example":"lim_{x→1}(x²+3x)=1+3=4。"},
  "kp-m1-p1-c1-wu-qiong-xiao": {"anchor":"lim f(x)=0 ⇔ f 为无穷小","caption":"极限为 0 的变量称为无穷小，它是一个变量而不是「很小的常数」。","keyPoints":["无穷小是极限为 0 的变量，不是很小的数","lim f=A ⇔ f=A+α（α→0）","有限个无穷小的和、积仍是无穷小；无穷小与有界量的积也是无穷小"],"example":"x→0 时 sin x 是无穷小；而 10⁻¹⁰ 是常数，不是无穷小。"},
  "kp-m1-p1-c1-wu-qiong-da": {"anchor":"lim f(x)=∞ ⇔ lim 1/f(x)=0","caption":"当 |f(x)| 无限增大时称 f 为无穷大，记作 lim f=∞。","keyPoints":["无穷大是绝对值无限增大的变量","lim f=∞ ⇔ lim 1/f=0（同一过程，f≠0）","无穷大不是数，∞−∞、∞/∞ 都是未定式"],"example":"x→0 时 1/x 是无穷大，1/x² 也是（且趋于 +∞）。"},
  "kp-m1-p1-c1-wu-qiong-xiao-bi-jiao": {"anchor":"lim α/β=1 ⇔ α∼β","caption":"比较两个无穷小看它们的比值极限：比值为 0 说明前者是高阶无穷小，为非零常数说明同阶，为 1 说明等价，为 c≠0 时 α 是 β 的 k 阶无穷小。","keyPoints":["lim α/β=0 ⇒ α=o(β)（高阶无穷小）","lim α/β=c≠0 ⇒ 同阶；c=1 ⇒ 等价 α∼β","lim α/βᵏ=c≠0 ⇒ α 是 β 的 k 阶无穷小"],"example":"x→0 时 1−cos x∼x²/2，所以它是 x 的二阶无穷小。"},
  "kp-m1-p1-c1-chang-yong-deng-jia-wu-qiong-xiao-x-0": {"anchor":"sin x∼x，eˣ−1∼x，1−cos x∼x²/2，(1+x)^α−1∼αx","caption":"常用等价无穷小（x→0）：sin x∼x、tan x∼x、arcsin x∼x、arctan x∼x","keyPoints":["乘除结构可以直接替换，能大幅简化计算","加减结构不能随便替换（会丢失高阶项）","差函数要单独记：x−sin x∼x³/6、tan x−x∼x³/3"],"example":"lim_{x→0}(eˣ−1)/x=1，直接用 eˣ−1∼x。"},
  "kp-m1-p1-c1-di-yi-chong-yao-ji-xian": {"anchor":"lim_{x→0} sin x/x=1","caption":"lim_{x→0} sin x/x=1 是处理三角函数极限的基础，本质是「小角近似 sin x≈x」；","keyPoints":["lim_{x→0} sin x/x=1","结构必须一致：sin(□)/□，且 □→0","常与等价无穷小配合使用"],"example":"lim_{x→0} sin 3x/x=3·lim sin(3x)/(3x)=3。"},
  "kp-m1-p1-c1-di-er-chong-yao-ji-xian": {"anchor":"lim_{x→0}(1+x)^{1/x}=e","caption":"lim_{x→0}(1+x)^{1/x}=e，等价形式是 lim_{x→∞}(1+1/x)ˣ=e。","keyPoints":["lim_{x→0}(1+x)^{1/x}=e；lim_{x→∞}(1+1/x)ˣ=e","专治 1^∞ 型未定式","凑结构时指数与括号内要互为倒数"],"example":"lim_{x→∞}(1+2/x)ˣ=e²。"},
  "kp-m1-p1-c1-chang-jian-wei-ding-shi": {"anchor":"0/0、∞/∞、0·∞、∞−∞、1^∞、0⁰、∞⁰","caption":"求极限的第一步是判断类型：能直接代入得到确定值的叫定式，否则可能是七种未定式之一——0/0、∞/∞、0·∞、∞−∞","keyPoints":["先代入判断是定式还是未定式","七种未定式：0/0、∞/∞、0·∞、∞−∞、1^∞、0⁰、∞⁰","定式直接代入，未定式才需要继续处理"],"example":"lim_{x→1}(x²−1)/(x−1) 代入得 0/0，需要因式分解。"},
  "kp-m1-p1-c1-qiu-ji-xian-gong-ju-xiang": {"anchor":"0/0 与 ∞/∞ 型：lim f/g=lim f′/g′","caption":"求极限的常用手段有：直接代入、因式分解 / 有理化 / 通分、等价无穷小替换、重要极限、夹逼、洛必达、泰勒展开、换元。","keyPoints":["优先化简与等价替换，计算成本最低","洛必达要求满足条件（0/0 或 ∞/∞ 且可导）","泰勒展开适合处理加减结构中的高阶项"],"example":"lim_{x→0}(1−cos x)/x² 用等价无穷小一步得 1/2。"},
  "kp-m1-p1-c1-lian-xu-ding-yi": {"anchor":"lim_{x→x₀}f(x)=f(x₀)","caption":"f 在 x₀ 连续指 lim_{x→x₀}f(x)=f(x₀)，即函数值存在、极限存在、两者相等三条同时成立。","keyPoints":["三条：f(x₀) 有定义、极限存在、两者相等","等价写法：f(x₀−)=f(x₀+)=f(x₀)","连续是逐点概念，区间上连续指每一点都连续"],"example":"f(x)=x² 在 x=1 连续：极限为 1，等于 f(1)。"},
  "kp-m1-p1-c1-jian-duan-dian-fen-lei": {"anchor":"第一类：f(x₀−)、f(x₀+) 都存在","caption":"间断点按左右极限分两类：左右极限都存在的（可去、跳跃）是第一类；至少一侧不存在的（无穷、振荡）是第二类。","keyPoints":["第一类：左右极限都存在（可去 / 跳跃）","第二类：至少一侧极限不存在（无穷 / 振荡）","可去与跳跃的区别是左右极限是否相等"],"example":"f(x)=|x|/x 在 0 处左右极限为 −1 与 1，是跳跃间断点。"},
  "kp-m1-p1-c1-lian-xu-han-shu-yun-suan": {"anchor":"f、g 连续 ⇒ f±g、fg、f/g（g≠0）、f∘g 连续","caption":"连续函数的和、差、积、商（分母不为 0）仍连续，连续函数的复合也连续。","keyPoints":["四则运算保持连续（分母不为 0）","连续函数的复合仍连续，链条上处处连续即可","由此可对初等函数直接代入求极限"],"example":"lim_{x→2} ln(x²+1)=ln 5。"},
  "kp-m1-p1-c1-bi-qu-jian-lian-xu-han-shu-xing-zhi": {"anchor":"f(a)·f(b)<0 ⇒ ∃ξ∈(a,b)，f(ξ)=0","caption":"f 在闭区间 [a,b] 上连续，则它有界、能取到最大值与最小值，并具有介值性；特别地，f(a)·f(b)<0 时区间内必有零点（零点定理）。","keyPoints":["有界性与最值定理：闭区间上必取到最大值、最小值","介值定理：介于最小值与最大值之间的值都能取到","零点定理：f(a)·f(b)<0 ⇒ ∃ξ∈(a,b) 使 f(ξ)=0"],"example":"f(x)=x³−x−1 在 [1,2] 上连续且端点异号，故有零点。"},
  "kp-m1-p1-c2-dao-shu-ding-yi": {"anchor":"f′(x₀)=lim_{Δx→0}[f(x₀+Δx)−f(x₀)]/Δx","caption":"导数 f′(x₀)=lim_{Δx→0}[f(x₀+Δx)−f(x₀)]/Δx 是函数在一点处的瞬时变化率，它由差商的极限定义。","keyPoints":["导数是差商的极限，不是「变化量相除」","分段点处要用定义算左右导数，不能直接用求导公式","可导的等价形式：f(x₀+Δx)−f(x₀)=f′(x₀)Δx+o(Δx)"],"example":"f(x)=|x| 在 0 处：左右导数分别为 −1 与 1，故不可导。"},
  "kp-m1-p1-c2-dao-shu-ji-he-yi-yi": {"anchor":"y−f(x₀)=f′(x₀)(x−x₀)","caption":"f′(x₀) 就是曲线 y=f(x) 在点 (x₀,f(x₀)) 处切线的斜率","keyPoints":["f′(x₀) 是切线斜率，可导 ⇔ 有非竖直切线","切线方程 y−f(x₀)=f′(x₀)(x−x₀)","法线斜率是 −1/f′(x₀)（f′(x₀)≠0）"],"example":"y=x² 在 x=1 处：f(1)=1、f′(1)=2，切线为 y−1=2(x−1)。"},
  "kp-m1-p1-c2-dao-shu-wu-li-yi-yi": {"anchor":"v(t)=s′(t)，a(t)=s″(t)","caption":"导数是变化率：位移对时间的导数是速度，速度对时间的导数是加速度。","keyPoints":["v(t)=s′(t)，a(t)=v′(t)=s″(t)","导数的正负表示增或减，绝对值表示变化快慢","「速率」是速度的绝对值"],"example":"s(t)=t³−3t，则 v(t)=3t²−3，t=2 时 v=9。"},
  "kp-m1-p1-c2-ke-dao-yu-lian-xu": {"anchor":"可导 ⇒ 连续","caption":"可导一定连续，但连续不一定可导（如 y=|x| 在 0 处）。","keyPoints":["可导 ⇒ 连续；连续 ⇏ 可导","不连续 ⇒ 一定不可导（反向用）","连续但「尖点」或「竖直切线」处不可导"],"example":"y=|x| 在 0 处连续但不可导，说明连续不是充分条件。"},
  "kp-m1-p1-c2-wei-fen": {"anchor":"dy=f′(x)dx；Δy=dy+o(dx)","caption":"微分 dy=f′(x)dx 是函数增量 Δy 的线性主部：Δy=dy+o(dx)。","keyPoints":["dy=f′(x)dx，是 Δy 的线性主部","Δy=dy+o(dx)，误差是 dx 的高阶无穷小","可微与可导等价（一元函数）"],"example":"√(1.02)≈1+0.02/2=1.01（取 f(x)=√x，x₀=1）。"},
  "kp-m1-p1-c2-ji-ben-dao-shu-gong-shi": {"anchor":"(xᵃ)′=αxᵃ⁻¹；(eˣ)′=eˣ；(ln x)′=1/x","caption":"基本导数公式必须背熟：(xᵃ)′=αxᵃ⁻¹、(eˣ)′=eˣ、(ln x)′=1/x、(sin x)′=cos x","keyPoints":["幂、指、对、三角、反三角五类都要记","(ln|x|)′=1/x，注意绝对值","(arcsin x)′=1/√(1−x²)，(arctan x)′=1/(1+x²)"],"example":"(√x)′=(x^{1/2})′=1/(2√x)。"},
  "kp-m1-p1-c2-si-ze-yun-suan": {"anchor":"(uv)′=u′v+uv′；(u/v)′=(u′v−uv′)/v²","caption":"(u±v)′=u′±v′，(uv)′=u′v+uv′，(u/v)′=(u′v−uv′)/v²（v≠0）；这些法则要求各部分可导。","keyPoints":["(uv)′=u′v+uv′，不要写成 u′v′","(u/v)′ 的分母是 v²，分子是 u′v−uv′","商法则可由乘积法则推出"],"example":"(x sin x)′=sin x+x cos x。"},
  "kp-m1-p1-c2-fu-he-han-shu-qiu-dao": {"anchor":"dy/dx=dy/du·du/dx","caption":"复合函数求导的核心是链式法则：[f(g(x))]′=f′(g(x))·g′(x)。","keyPoints":["链式法则：外导乘内导","多层复合逐层相乘，不要漏层","复合函数的高阶导数同样要按链式法则处理"],"example":"(e^{x²})′=e^{x²}·2x。"},
  "kp-m1-p1-c2-fan-han-shu-qiu-dao": {"anchor":"(f⁻¹)′(y)=1/f′(x)","caption":"反函数的导数等于原函数导数的倒数：(f⁻¹)′(y)=1/f′(x)，其中 y=f(x)。","keyPoints":["(f⁻¹)′(y)=1/f′(x)（f′(x)≠0）","反函数的定义域是原函数的值域","arcsin、arctan 的导数公式都由它推出"],"example":"y=eˣ 的反函数 x=ln y，导数为 1/eˣ=1/y。"},
  "kp-m1-p1-c2-yin-han-shu-qiu-dao": {"anchor":"F(x,y)=0 ⇒ y′=−Fₓ/Fᵧ（Fᵧ≠0）","caption":"方程 F(x,y)=0 确定隐函数时，两边同时对 x 求导，把 y 视为 x 的函数（用链式法则），再解出 y′；结果一般同时含 x 与 y。","keyPoints":["两边对 x 求导，遇 y 的项要乘 y′","求导后把含 y′ 的项集中解出","高阶导数要在此基础上继续求导"],"example":"x²+y²=1 ⇒ 2x+2yy′=0 ⇒ y′=−x/y。"},
  "kp-m1-p1-c2-can-shu-fang-cheng-qiu-dao": {"anchor":"dy/dx=(dy/dt)/(dx/dt)；d²y/dx²=[d/dt(dy/dx)]/(dx/dt)","caption":"参数方程 x=x(t)、y=y(t) 的导数 dy/dx=(dy/dt)/(dx/dt)；","keyPoints":["dy/dx=(dy/dt)/(dx/dt)，要求 dx/dt≠0","二阶导数要对 dy/dx 再对 t 求导，再除以 dx/dt","摆线、星形线等常考参数方程求导"],"example":"x=t²、y=t³ 时 dy/dx=3t²/(2t)=3t/2。"},
  "kp-m1-p1-c2-dui-shu-qiu-dao-fa": {"anchor":"y=u^v ⇒ y′=y(v′ln u+v·u′/u)","caption":"对幂指函数 u(x)^{v(x)} 或多项连乘除的式子，先取对数把乘除变成加减，再两边求导，最后乘回原函数：y′=y·(ln y)′。","keyPoints":["适用于幂指函数与连乘除结构","取对数后求导，最后要乘回 y","幂指函数也可写成 e^{v ln u} 再求导"],"example":"y=xˣ ⇒ ln y=x ln x ⇒ y′=xˣ(ln x+1)。"},
  "kp-m1-p1-c2-fen-duan-han-shu-qiu-dao": {"anchor":"f′(a−)=f′(a+) ⇒ f 在 a 可导","caption":"分段函数在每段内部按普通公式求导，但在分界点必须回到导数定义，或比较左右导数是否相等；左右导数不相等就不可导。","keyPoints":["各段内部直接用求导公式","分界点必须用定义或左右导数判断","左右导数相等才可导，且导数值为该公共值"],"example":"f(x)=x²（x≥0）、x（x<0）在 0 处左右导数为 0 与 1，故不可导。"},
  "kp-m1-p1-c2-er-jie-san-jie-n-jie-dao-shu": {"anchor":"f⁽ⁿ⁾(x)=dⁿf/dxⁿ","caption":"高阶导数是对导数再求导；求 n 阶导数常用「先算前几阶找规律再归纳」的办法，乘积结构用莱布尼茨公式，有理分式先拆项。","keyPoints":["二阶导数是导数的导数，记作 f″","求 n 阶导数的套路：算前几阶 → 找规律 → 归纳","乘积的 n 阶导数用莱布尼茨公式"],"example":"y=1/(1+x) 的 n 阶导数为 (−1)ⁿn!/(1+x)^{n+1}。"},
  "kp-m1-p1-c2-chang-jian-han-shu-gao-jie-dao-shu-zhou-1atcff": {"anchor":"(sin x)⁽ⁿ⁾=sin(x+nπ/2)","caption":"sin x、cos x 的导数每四阶循环一次，e^{ax} 的 n 阶导数是 aⁿe^{ax}，1/(ax+b) 的 n 阶导数带 (−1)ⁿn!","keyPoints":["(sin x)⁽ⁿ⁾=sin(x+nπ/2)，(cos x)⁽ⁿ⁾=cos(x+nπ/2)","(e^{ax})⁽ⁿ⁾=aⁿe^{ax}","(1/(ax+b))⁽ⁿ⁾=(−1)ⁿaⁿn!/(ax+b)^{n+1}"],"example":"y=sin x 的 4 阶导数仍是 sin x。"},
  "kp-m1-p1-c2-lai-bu-ni-ci-gong-shi": {"anchor":"(uv)⁽ⁿ⁾=Σₖ₌₀ⁿ Cₙᵏu⁽ᵏ⁾v⁽ⁿ⁻ᵏ⁾","caption":"乘积的 n 阶导数用莱布尼茨公式：(uv)⁽ⁿ⁾=Σₖ₌₀ⁿ Cₙᵏu⁽ᵏ⁾v⁽ⁿ⁻ᵏ⁾，结构与二项式展开完全对应；","keyPoints":["(uv)⁽ⁿ⁾=Σₖ₌₀ⁿ Cₙᵏu⁽ᵏ⁾v⁽ⁿ⁻ᵏ⁾，系数是组合数","若其中一个是 k 次多项式，只需求到 k 阶","与二项式定理 (a+b)ⁿ 的结构一致"],"example":"(x²eˣ)‴=x²eˣ+3·2xeˣ+3·2eˣ=eˣ(x²+6x+6)。"},
  "kp-m1-p1-c2-fei-ma-ding-li": {"anchor":"f′(x₀)=0","caption":"费马定理：若 x₀ 是 f 的内点极值点且 f 在 x₀ 可导，则 f′(x₀)=0。","keyPoints":["条件：内点 + 极值 + 可导 ⇒ f′(x₀)=0","逆命题不成立（f′(x₀)=0 不一定是极值，如 y=x³）","端点极值不受此约束，费马定理只针对内点"],"example":"y=x³ 在 0 处导数为 0，但不是极值点，说明逆命题不成立。"},
  "kp-m1-p1-c2-luo-er-ding-li": {"anchor":"f(a)=f(b) ⇒ ∃ξ∈(a,b)，f′(ξ)=0","caption":"罗尔定理：f 在 [a,b] 上连续、(a,b) 内可导且 f(a)=f(b)，则存在 ξ∈(a,b) 使 f′(ξ)=0。","keyPoints":["三个条件：闭区间连续、开区间可导、端点值相等","结论：内部存在一点导数为 0","常用作构造辅助函数后证明存在性"],"example":"f(x)=x²−x 在 [0,1] 上满足条件，ξ=1/2 处导数为 0。"},
  "kp-m1-p1-c2-la-ge-lang-ri-zhong-zhi-ding-li": {"anchor":"f(b)−f(a)=f′(ξ)(b−a)","caption":"拉格朗日中值定理：f 在 [a,b] 上连续、(a,b) 内可导，则存在 ξ∈(a,b) 使 f(b)−f(a)=f′(","keyPoints":["公式：f(b)−f(a)=f′(ξ)(b−a)","可写成 f′(ξ)=[f(b)−f(a)]/(b−a)，即割线斜率等于某点切线斜率","常用来证明不等式与估计增量"],"example":"f(x)=x² 在 [1,2] 上：4−1=f′(ξ)(2−1) ⇒ ξ=3/2。"},
  "kp-m1-p1-c2-ke-xi-zhong-zhi-ding-li": {"anchor":"[f(b)−f(a)]/[g(b)−g(a)]=f′(ξ)/g′(ξ)","caption":"柯西中值定理：f、g 在 [a,b] 上连续、(a,b) 内可导且 g′(x)≠0","keyPoints":["公式：[f(b)−f(a)]/[g(b)−g(a)]=f′(ξ)/g′(ξ)","要求 g′(x)≠0（否则分母无意义）","取 g(x)=x 即退化为拉格朗日中值定理"],"example":"取 g(x)=x² 可推出 [f(b)−f(a)]/(b²−a²)=f′(ξ)/(2ξ)。"},
  "kp-m1-p1-c2-tai-le-ding-li": {"anchor":"f(x)=Σₖ₌₀ⁿ f⁽ᵏ⁾(x₀)(x−x₀)ᵏ/k!+Rₙ(x)","caption":"泰勒定理把 f(x) 在 x₀ 附近写成「n 次多项式 + 余项」：f(x)=Σ f⁽ᵏ⁾(x₀)(x−x₀)ᵏ/k!","keyPoints":["泰勒公式 = 多项式部分 + 余项","余项有两种：皮亚诺（定性，用于求极限）与拉格朗日（定量，用于估计）","在 x₀=0 处展开就是麦克劳林公式"],"example":"eˣ 在 0 处展开：1+x+x²/2!+…+xⁿ/n!+o(xⁿ)。"},
  "kp-m1-p1-c2-mai-ke-lao-lin-gong-shi": {"anchor":"f(x)=Σₖ₌₀ⁿ f⁽ᵏ⁾(0)xᵏ/k!+o(xⁿ)","caption":"麦克劳林公式是泰勒公式在 x₀=0 时的特例：f(x)=f(0)+f′(0)x+f″(0)x²/2!","keyPoints":["eˣ=1+x+x²/2!+…；sin x=x−x³/3!+x⁵/5!−…","cos x=1−x²/2!+x⁴/4!−…；ln(1+x)=x−x²/2+x³/3−…","(1+x)^α=1+αx+α(α−1)x²/2!+…"],"example":"e^x=1+x+x²/2+o(x²)。"},
  "kp-m1-p1-c2-ying-yong": {"anchor":"f(x)=Pₙ(x)+Rₙ(x)","caption":"泰勒（麦克劳林）展开的典型用途：求复杂极限、确定无穷小的阶、做近似计算、证明不等式；把函数展开到合适阶数是关键。","keyPoints":["求极限：展开到分母同阶","定阶数：看第一个非零项","近似与不等式：靠余项符号与大小"],"example":"lim_{x→0}(x−sin x)/x³=1/6 就是靠展开到三阶得到的。"},
  "kp-m1-p1-c2-0-0-xing": {"anchor":"lim f/g=lim f′/g′","caption":"0/0 型是洛必达最常见的适用场景；但能用因式分解、等价无穷小或泰勒时，往往比洛必达更快、更稳。","keyPoints":["先用等价替换或化简，再考虑洛必达","每次求导后都要重新验证类型","洛必达不适用时改用泰勒展开"],"example":"lim_{x→0}(eˣ−1)/x=1，等价替换一步即可。"},
  "kp-m1-p1-c2-xing": {"anchor":"lim xⁿ/eˣ=0（n 为任意正数）","caption":"∞/∞ 型可以比较分子分母的增长阶（ln x ≪ xᵏ ≪ aˣ），也可以用洛必达；两者都要求结构清楚。","keyPoints":["增长阶：ln x ≪ xᵏ ≪ aˣ（a>1）","洛必达要求可导且分母导数不为 0","多项式比大小看最高次项"],"example":"lim_{x→∞} x/eˣ=lim 1/eˣ=0。"},
  "kp-m1-p1-c2-qi-ta-wei-ding-shi-zhuan-hua": {"anchor":"1^∞：u^v=e^{v ln u}","caption":"0·∞ 化成商、∞−∞ 通分或有理化、1^∞/0⁰/∞⁰ 取对数，都能把未定式转化为 0/0 或 ∞/∞ 再处理。","keyPoints":["0·∞ ⇒ f/(1/g) 化成商","∞−∞ ⇒ 通分或有理化","1^∞、0⁰、∞⁰ ⇒ 取对数化成 0·∞"],"example":"lim_{x→0⁺} x ln x=lim (ln x)/(1/x)=0。"},
  "kp-m1-p1-c2-lian-xu-duo-ci-shi-yong": {"anchor":"lim f/g=lim f′/g′=lim f″/g″…","caption":"洛必达法则可以连续使用：只要每次求导后仍是 0/0 或 ∞/∞ 型且条件满足，就可以继续用，直到求出极限。","keyPoints":["每次求导后都要重新验证类型","连续使用时要保证每一步条件都成立","能化简时先化简，减少求导次数"],"example":"lim_{x→0}(1−cos x)/x²=lim sin x/(2x)=lim cos x/2=1/2。"},
  "kp-m1-p1-c2-bu-shi-yong-huo-shi-yong-hou-geng-fu-za-1fae59": {"anchor":"洛必达失效时改用其它方法","caption":"有些极限用洛必达会越算越复杂，或求导后极限不存在（此时洛必达失效）；这类情形应改用等价无穷小、泰勒展开、夹逼或直接变形。","keyPoints":["求导后极限不存在 ⇒ 洛必达失效，不能据此断言原极限不存在","含振荡因子（如 sin(1/x)）时洛必达常失效","等价替换与泰勒通常更省力"],"example":"lim_{x→0} x²sin(1/x)/x=0 用夹逼，洛必达会失效。"},
  "kp-m1-p1-c2-dan-diao-xing": {"anchor":"f′>0 ⇒ f 递增","caption":"f′>0 的区间上 f 单调递增，f′<0 的区间上单调递减；导数为 0 的点是分界点，需要判断符号是否变化。","keyPoints":["f′>0 ⇒ 递增；f′<0 ⇒ 递减（在区间上）","f′≡0 ⇒ f 为常数","求单调区间要先求定义域，再解 f′ 的符号"],"example":"f(x)=x³−3x：f′=3x²−3，在 (−∞,−1) 与 (1,+∞) 递增。"},
  "kp-m1-p1-c2-ji-zhi": {"anchor":"f′ 由正变负 ⇒ 极大值","caption":"极值是局部概念：f′ 由正变负处取极大值，由负变正处取极小值；f′(x₀)=0 只是必要条件，还要看符号变化或二阶导数。","keyPoints":["第一充分条件：f′ 变号（+→− 极大，−→+ 极小）","第二充分条件：f′(x₀)=0 且 f″(x₀)<0 为极大，>0 为极小","f′(x₀)=0 但不是极值的例子：y=x³"],"example":"y=x³−3x 在 x=−1 取极大值 2，在 x=1 取极小值 −2。"},
  "kp-m1-p1-c2-zui-da-zhi-yu-zui-xiao-zhi": {"anchor":"M=max{f(候选点)}","caption":"闭区间上求最值：算出所有驻点、不可导点与端点的函数值，比较大小即可；实际问题中若只有一个驻点且函数先增后减，该点就是最大值点。","keyPoints":["候选点：驻点、不可导点、区间端点","闭区间连续 ⇒ 一定有最大值与最小值","实际问题可用「唯一驻点 + 单调性」直接判定"],"example":"f(x)=x³−3x 在 [0,2] 上：比较 f(0)=0、f(1)=−2、f(2)=2，最大 2、最小 −2。"},
  "kp-m1-p1-c2-ao-tu-xing": {"anchor":"f″>0 ⇒ 凹","caption":"f″>0 时曲线是凹的（下凸），f″<0 时是凸的（上凸）；凹凸性也可以用弦与曲线的高低关系定义。","keyPoints":["f″>0 ⇒ 凹（下凸），f″<0 ⇒ 凸（上凸）","等价定义：凹 ⇔ f((x₁+x₂)/2)<[f(x₁)+f(x₂)]/2","凹凸性与一阶导数无关"],"example":"y=x² 的 f″=2>0，故曲线凹（开口向上）。"},
  "kp-m1-p1-c2-guai-dian": {"anchor":"f″ 变号 ⇒ 拐点","caption":"拐点是曲线凹凸性改变的点：f″ 在该点两侧变号；f″(x₀)=0 只是候选条件，必须验证符号确实变化。","keyPoints":["判据：f″ 在 x₀ 两侧变号","f″(x₀)=0 不一定是拐点（如 y=x⁴ 在 0 处）","f″(x₀)=0 且 f‴(x₀)≠0 ⇒ 是拐点"],"example":"y=x³ 在 0 处 f″=6x 变号，故 (0,0) 是拐点。"},
  "kp-m1-p1-c2-jian-jin-xian": {"anchor":"a=lim_{x→∞} f(x)/x，b=lim_{x→∞}[f(x)−ax]","caption":"渐近线有三类：铅直（x→x₀ 时 f→∞）、水平（x→∞ 时 f→b）、斜（f(x)−(ax+b)→0","keyPoints":["铅直渐近线出现在函数的无穷间断点处","水平渐近线是 x→∞ 时的极限值","斜渐近线要先求 a=lim f(x)/x，再求 b"],"example":"y=x+1/x 有铅直渐近线 x=0 与斜渐近线 y=x。"},
  "kp-m1-p1-c2-han-shu-tu-xing-miao-hui": {"anchor":"定义域 → f′ → f″ → 渐近线 → 描点","caption":"描绘函数图形按固定步骤：定义域与奇偶周期性 → 一阶导数定单调与极值 → 二阶导数定凹凸与拐点 → 渐近线 → 描点连线。","keyPoints":["先定定义域与对称性，能少算一半","f′ 定单调区间与极值","f″ 定凹凸与拐点，最后补渐近线"],"example":"y=x³−3x 的图形：两个极值点、一个拐点、无渐近线。"},
  "kp-m1-p1-c2-hu-wei-fen": {"anchor":"ds=√(1+y′²)dx；参数式 ds=√(x′²+y′²)dt","caption":"把曲线切得足够碎，每一小段都近似成直线段：横向走 dx、纵向变化 dy=y′dx，斜边就是这一小段的长度 ds，因此 ds=√(1+y′²)dx。","keyPoints":["ds=√(dx²+dy²)=√(1+y′²)dx","参数式：ds=√(x′²+y′²)dt","弧微分是长度元素，与曲率（方向变化率）是两回事"],"example":"y=x² 时 ds=√(1+4x²)dx；x=0 处 ds=dx。"},
  "kp-m1-p1-c2-qu-l-ding-yi": {"anchor":"κ=|dα/ds|","caption":"曲率的定义是「切线倾角的改变量除以弧长改变量」的极限：κ=|dα/ds|，其中 α 是切线倾角、s 是弧长。","keyPoints":["κ=|dα/ds|，α 为切线倾角","曲率与参数化无关，是曲线的内蕴性质","圆上每点曲率都是 1/R"],"example":"直线倾角不变，dα=0，故曲率为 0。"},
  "kp-m1-p1-c2-qu-l-gong-shi": {"anchor":"κ=|y″|/(1+y′²)^{3/2}","caption":"当曲线由 y=y(x) 给出时，曲率的计算公式是 κ=|y″|/(1+y′²)^{3/2}；","keyPoints":["直角坐标：κ=|y″|/(1+y′²)^{3/2}","参数式：κ=|x′y″−x″y′|/(x′²+y′²)^{3/2}","分母的三次方来自弧微分"],"example":"y=x² 在 x=0 处：y′=0、y″=2，κ=2。"},
  "kp-m1-p1-c2-qu-l-ban-jing": {"anchor":"ρ=1/κ","caption":"曲率半径 ρ=1/κ 是「与该点弯曲程度相当的圆的半径」：曲率越大，曲率半径越小。","keyPoints":["ρ=1/κ，与曲率互为倒数","直线的曲率半径为无穷大","圆的曲率半径就是它的半径"],"example":"y=x² 在 x=0 处 κ=2，故 ρ=1/2。"},
  "kp-m1-p1-c2-qu-l-yuan": {"anchor":"圆心 = 该点沿法线方向移动 ρ","caption":"曲率圆（密切圆）是与曲线在该点有相同切线、相同曲率的圆，圆心在曲线的凹侧、半径为曲率半径；它给出了曲线在该点附近的圆形近似。","keyPoints":["曲率圆与曲线在该点相切且曲率相同","圆心在法线上、位于凹侧，半径 ρ=1/κ","用圆近似曲线是曲率圆的实际意义"],"example":"y=x² 在 x=0 处曲率圆为 x²+(y−1/2)²=1/4。"},
  "kp-m1-p1-c3-yuan-han-shu-ding-yi": {"anchor":"F′(x)=f(x) ⇒ F 为 f 的原函数","caption":"若在区间 I 上处处有 F′(x)=f(x)，就称 F(x) 是 f(x) 在 I 上的一个原函数。","keyPoints":["F′=f ⇒ F 是 f 的原函数，方向不能反","原函数是「区间上」的概念，必须处处成立","连续函数一定有原函数（变限积分就是构造方法）"],"example":"sin x 是 cos x 的原函数，因为 (sin x)′=cos x。"},
  "kp-m1-p1-c3-yuan-han-shu-zu": {"anchor":"F(x)+C","caption":"同一函数的任意两个原函数只相差一个常数，所以全部原函数构成 F(x)+C 的形式，称为原函数族；这正是不定积分要加常数 C 的原因。","keyPoints":["两个原函数之差必为常数","原函数族 = F(x)+C（C 取遍实数）","C 的任意性来自「常数导数为 0」"],"example":"x²/2、x²/2+3、x²/2−1 都是 x 的原函数。"},
  "kp-m1-p1-c3-bu-ding-ji-fen": {"anchor":"∫f(x)dx=F(x)+C","caption":"不定积分 ∫f(x)dx=F(x)+C 表示 f 的全部原函数，它的结果是函数族而不是一个函数；求不定积分就是求原函数，结果必须带常数 C。","keyPoints":["∫f(x)dx=F(x)+C，结果是函数族","求导与积分互为逆运算：(∫f dx)′=f","不定积分与定积分的区别：前者是函数，后者是数"],"example":"∫2x dx=x²+C。"},
  "kp-m1-p1-c3-ji-fen-chang-shu": {"anchor":"∫f dx=F(x)+C","caption":"积分常数 C 表示原函数族的任意性，在不定积分里不可省略；而在定积分中，常数会在上下限相减时抵消，所以定积分结果里不写 C。","keyPoints":["不定积分必须写 +C","定积分由 F(b)−F(a) 得到，常数自动抵消","同一个不定积分可以写成不同形式（相差常数）"],"example":"∫cos x dx=sin x+C。"},
  "kp-m1-p1-c3-ji-ben-xing-zhi": {"anchor":"∫(k₁f+k₂g)dx=k₁∫f dx+k₂∫g dx","caption":"不定积分的基本性质有两条：线性性（常数可提、和差可拆）与互逆性（微分与积分互为逆运算）。","keyPoints":["线性：∫(k₁f+k₂g)dx=k₁∫f dx+k₂∫g dx","互逆：(∫f dx)′=f(x)，∫f′(x)dx=f(x)+C","没有「积的积分等于积分之积」这种法则"],"example":"∫(2x+cos x)dx=x²+sin x+C。"},
  "kp-m1-p1-c3-mi-han-shu": {"anchor":"∫xᵃdx=xᵃ⁺¹/(α+1)+C（α≠−1）","caption":"∫xᵃdx=xᵃ⁺¹/(α+1)+C（α≠−1）；α=−1 是唯一的例外，此时 ∫dx/x=ln|x|+C，不能套幂公式。","keyPoints":["∫xᵃdx=xᵃ⁺¹/(α+1)+C（α≠−1）","α=−1 时用 ∫dx/x=ln|x|+C","负指数、分数指数都按同一公式处理"],"example":"∫√x dx=∫x^{1/2}dx=(2/3)x^{3/2}+C。"},
  "kp-m1-p1-c3-zhi-shu-han-shu": {"anchor":"∫eˣdx=eˣ+C；∫aˣdx=aˣ/ln a+C","caption":"∫eˣdx=eˣ+C，∫aˣdx=aˣ/ln a+C（a>0 且 a≠1）。","keyPoints":["∫eˣdx=eˣ+C","∫aˣdx=aˣ/ln a+C，分母是 ln a","与导数对照记：求导乘 ln a，积分除 ln a"],"example":"∫2ˣdx=2ˣ/ln 2+C。"},
  "kp-m1-p1-c3-san-jiao-han-shu": {"anchor":"∫sin x dx=−cos x+C；∫cos x dx=sin x+C","caption":"常用三角积分：∫sin x dx=−cos x+C、∫cos x dx=sin x+C","keyPoints":["∫sin x dx=−cos x+C（注意负号）","∫cos x dx=sin x+C","∫dx/cos²x=tan x+C；平方项先降幂"],"example":"∫(sin x+cos x)dx=−cos x+sin x+C。"},
  "kp-m1-p1-c3-fan-san-jiao-jie-gou": {"anchor":"∫dx/(a²+x²)=(1/a)arctan(x/a)+C","caption":"形如 ∫dx/(1+x²)=arctan x+C、∫dx/√(1−x²)=arcsin x+C 的积分","keyPoints":["∫dx/(1+x²)=arctan x+C","∫dx/√(1−x²)=arcsin x+C","分母带系数时提出 1/a：∫dx/(a²+x²)=(1/a)arctan(x/a)+C"],"example":"∫dx/(4+x²)=(1/2)arctan(x/2)+C。"},
  "kp-m1-p1-c3-dui-shu-jie-gou": {"anchor":"∫f′(x)/f(x)dx=ln|f(x)|+C","caption":"对数型积分：∫f′(x)/f(x)dx=ln|f(x)|+C。","keyPoints":["∫f′/f dx=ln|f(x)|+C","分子与分母导数差常数倍时先调整系数","绝对值不能省（定义域可能为负）"],"example":"∫2x/(x²+1)dx=ln(x²+1)+C。"},
  "kp-m1-p1-c3-di-yi-lei-huan-yuan-cou-wei-fen": {"anchor":"∫f(g(x))g′(x)dx=∫f(u)du","caption":"第一类换元法把 ∫f(g(x))g′(x)dx 写成 ∫f(u)du：先把 g′(x)dx 凑成 dg(x)，再整体换元，积分后回代。","keyPoints":["∫f(g(x))g′(x)dx=∫f(u)du，u=g(x)","关键是「凑」出 du = g′(x)dx","换元后必须回代原变量"],"example":"∫2x e^{x²}dx=∫e^u du=e^{x²}+C。"},
  "kp-m1-p1-c3-di-er-lei-huan-yuan-bian-liang-dai-huan": {"anchor":"∫f(x)dx=∫f(φ(t))φ′(t)dt","caption":"第二类换元法令 x=φ(t)（φ 单调可导），把 ∫f(x)dx 变成 ∫f(φ(t))φ′(t)dt；它主要用于消去根号，积分完再把 t 换回 x。","keyPoints":["x=φ(t) 要求 φ 单调可导，保证可逆","dx=φ′(t)dt 不能漏","最后必须回代 t=φ⁻¹(x)"],"example":"∫√(1−x²)dx 令 x=sin t 化简。"},
  "kp-m1-p1-c3-san-jiao-dai-huan": {"anchor":"x=a sin t ⇒ √(a²−x²)=a cos t","caption":"遇到 √(a²−x²)、√(a²+x²)、√(x²−a²) 分别令 x=a sin t、x=a tan t","keyPoints":["√(a²−x²) ⇒ x=a sin t","√(a²+x²) ⇒ x=a tan t","√(x²−a²) ⇒ x=a sec t"],"example":"∫dx/√(1−x²)=arcsin x+C 就是 x=sin t 的结果。"},
  "kp-m1-p1-c3-gen-shi-dai-huan": {"anchor":"t=ⁿ√(ax+b) ⇒ x=(tⁿ−b)/a","caption":"被积函数含 ⁿ√(ax+b) 时，令 t=ⁿ√(ax+b)，把根号整体换成 t，从而化成有理函数积分；换元时 x 与 dx 都要用 t 表示。","keyPoints":["t=ⁿ√(ax+b) 一次消掉整个根号","要同时解出 x=(tⁿ−b)/a 与 dx","化成有理函数后再用部分分式"],"example":"∫dx/(1+√x) 令 t=√x，得 ∫2t/(1+t)dt。"},
  "kp-m1-p1-c3-u-dv-uv-v-du": {"anchor":"∫u dv=uv−∫v du","caption":"分部积分公式 ∫u dv=uv−∫v du 把原积分转化为另一个积分；","keyPoints":["∫u dv=uv−∫v du","u 按「反对幂三指」的优先级选","必要时可以连续多次分部，直到积出或循环"],"example":"∫x eˣ dx=x eˣ−∫eˣ dx=eˣ(x−1)+C。"},
  "kp-m1-p1-c3-duo-xiang-shi-zhi-shu": {"anchor":"∫xⁿeˣdx=xⁿeˣ−n∫xⁿ⁻¹eˣdx","caption":"多项式乘指数时取多项式作 u、指数作 dv，一次分部就把多项式次数降一；n 次多项式最多分部 n 次即可积完。","keyPoints":["u=多项式，dv=指数 dx","多项式因子每分部一次次数降一，最终耗尽","降次到常数后可直接积分"],"example":"∫x²eˣdx=eˣ(x²−2x+2)+C。"},
  "kp-m1-p1-c3-duo-xiang-shi-san-jiao": {"anchor":"∫x sin x dx=−x cos x+∫cos x dx","caption":"多项式乘三角函数同样取多项式作 u、三角作 dv；分部后多项式降次，注意 v 的符号（sin 积成 −cos 会带负号）。","keyPoints":["u=多项式，dv=三角函数 dx","求 v 时符号容易错（∫sin=−cos）","n 次多项式最多分部 n 次"],"example":"∫x cos x dx=x sin x+cos x+C。"},
  "kp-m1-p1-c3-duo-xiang-shi-dui-shu": {"anchor":"∫ln x dx=x ln x−x+C","caption":"对数求导后变成 1/x，所以含对数的积分取对数作 u、其余作 dv，一次分部就把对数消掉。","keyPoints":["u=对数函数（求导后变成有理式）","取 u 后其余部分整体作 dv，凑微分要顺手","一次分部即可去掉对数"],"example":"∫x ln x dx=(x²/2)ln x−x²/4+C。"},
  "kp-m1-p1-c3-fan-san-jiao-han-shu": {"anchor":"∫arctan x dx=x arctan x−ln(1+x²)/2+C","caption":"反三角函数求导后变成有理式或根式，所以含反三角的积分取它作 u、其余作 dv，一次分部就能化简。","keyPoints":["u=arcsin x / arctan x 等","取 u 后其余部分整体作 dv，凑微分要顺手","分部后化成有理式或根式积分"],"example":"∫arcsin x dx=x arcsin x+√(1−x²)+C。"},
  "kp-m1-p1-c3-you-li-han-shu-ji-fen": {"anchor":"P/Q → 多项式 + Σ 部分分式","caption":"有理函数积分的一般流程：假分式先做多项式除法化成「多项式 + 真分式」，真分式按分母因式分解拆成部分分式，再逐项积分（结果是对数或反正切）。","keyPoints":["假分式（分子次数≥分母）先做除法","真分式按分母因式拆部分分式","逐项积分得到对数或反正切"],"example":"∫dx/(x²−1)=(1/2)ln|(x−1)/(x+1)|+C。"},
  "kp-m1-p1-c3-bu-fen-fen-shi-fen-jie": {"anchor":"1/[(x−a)(x−b)]=A/(x−a)+B/(x−b)","caption":"部分分式分解要按分母因式的类型设项：单实根设 A/(x−a)，k 重根要写 A₁/(x−a)+…+Aₖ/(x−a)ᵏ","keyPoints":["单实根：A/(x−a)","k 重根：必须写满 k 项","不可约二次因式的分子设一次式"],"example":"1/[(x−1)(x+2)]=(1/3)/(x−1)−(1/3)/(x+2)。"},
  "kp-m1-p1-c3-san-jiao-han-shu-you-li-shi": {"anchor":"t=tan(x/2)，dx=2dt/(1+t²)","caption":"三角函数有理式可用万能代换 t=tan(x/2) 化成 t 的有理函数再积分；但能用凑微分或恒等变形解决时更快，不要一上来就万能代换。","keyPoints":["t=tan(x/2)：sin x=2t/(1+t²)，cos x=(1−t²)/(1+t²)","万能代换一定可行但计算量大","优先尝试凑微分与恒等变形"],"example":"∫dx/(1+cos x)=tan(x/2)+C。"},
  "kp-m1-p1-c3-jian-dan-wu-li-han-shu-ji-fen": {"anchor":"√(a²−x²) ⇒ x=a sin t","caption":"简单无理函数积分的思路是消去根号：ⁿ√(ax+b) 用根式代换，√(a²±x²) 用三角代换，化成有理函数后再积分。","keyPoints":["根式代换消 ⁿ√(ax+b)","三角代换处理 √(a²±x²) 型","目标都是化成有理函数"],"example":"∫√(a²−x²)dx 用 x=a sin t 化为三角积分。"},
  "kp-m1-p1-c3-ding-ji-fen-ding-yi": {"anchor":"∫ₐᵇf(x)dx=lim Σf(ξᵢ)Δxᵢ","caption":"定积分 ∫ₐᵇf(x)dx 是黎曼和的极限：把区间分成 n 份，每份取一点算 f(ξᵢ)Δxᵢ，求和后让最大区间长度趋于 0。","keyPoints":["定义是「分割—近似—求和—取极限」四步","定积分是数，不是函数族","可积的充分条件：连续，或只有有限个间断点的有界函数"],"example":"∫₀¹x dx=lim Σ(i/n)(1/n)=1/2。"},
  "kp-m1-p1-c3-ding-ji-fen-xing-zhi": {"anchor":"∫ₐᵇf=∫ₐᶜf+∫ᶜᵇf；|∫ₐᵇf|≤∫ₐᵇ|f|","caption":"定积分的性质：线性性、区间可加性、保号性（f≤g ⇒ ∫f≤∫g）、三角不等式 |∫f|≤∫|f|，以及估值定理 mL≤∫ₐᵇf≤ML。","keyPoints":["区间可加性：∫ₐᵇ=∫ₐᶜ+∫ᶜᵇ，与 a、b、c 的大小无关","保号性：f≤g ⇒ ∫ₐᵇf≤∫ₐᵇg","|∫ₐᵇf|≤∫ₐᵇ|f|，等号一般不成立"],"example":"∫₀¹x²dx≤∫₀¹x dx（因为 x²≤x 在 [0,1] 上）。"},
  "kp-m1-p1-c3-ding-ji-fen-zhong-zhi-ding-li": {"anchor":"∫ₐᵇf(x)dx=f(ξ)(b−a)","caption":"定积分中值定理：f 在 [a,b] 上连续，则存在 ξ∈[a,b] 使 ∫ₐᵇf(x)dx=f(ξ)(b−a)；","keyPoints":["∫ₐᵇf=f(ξ)(b−a)，ξ 在区间内","前提是 f 在闭区间上连续","函数平均值 f̄=(1/(b−a))∫ₐᵇf 就是 f(ξ)"],"example":"∫₀¹x²dx=1/3=f(ξ)，故 ξ=1/√3。"},
  "kp-m1-p1-c3-ji-fen-shang-xian-han-shu": {"anchor":"Φ(x)=∫ₐˣf(t)dt ⇒ Φ′(x)=f(x)","caption":"Φ(x)=∫ₐˣf(t)dt 称为积分上限函数，若 f 连续则 Φ′(x)=f(x)；它是构造原函数的工具，也是牛顿—莱布尼茨公式的基础。","keyPoints":["Φ′(x)=f(x)（f 连续）","上下限都是函数时：d/dx∫_{u}^{v}f=f(v)v′−f(u)u′","被积函数含 x 时要先换元或把 x 提出来"],"example":"d/dx∫₀^{x²}sin t dt=sin(x²)·2x。"},
  "kp-m1-p1-c3-niu-dun-lai-bu-ni-ci-gong-shi": {"anchor":"∫ₐᵇf(x)dx=F(b)−F(a)","caption":"牛顿—莱布尼茨公式 ∫ₐᵇf(x)dx=F(b)−F(a)（F′=f）把定积分化为原函数在端点的差，是计算定积分的基本工具。","keyPoints":["∫ₐᵇf(x)dx=F(b)−F(a)，F 是 f 的任一个原函数","把「求和取极限」变成「两点作差」","换元时上下限要同步替换"],"example":"∫₀¹2x dx=[x²]₀¹=1。"},
  "kp-m1-p1-c3-wu-qiong-qu-jian-fan-chang-ji-fen": {"anchor":"∫ₐ^{+∞}f(x)dx=lim_{R→+∞}∫ₐ^R f(x)dx","caption":"无穷区间反常积分用极限定义：∫ₐ^{+∞}f=lim_{R→+∞}∫ₐ^R f；极限存在且有限时称收敛，否则发散。","keyPoints":["∫ₐ^{+∞}f=lim_{R→+∞}∫ₐ^R f","p 积分：∫₁^{+∞}dx/xᵖ 在 p>1 时收敛，p≤1 时发散","必须用极限算，不能直接代 ∞"],"example":"∫₁^{+∞}dx/x²=1，收敛。"},
  "kp-m1-p1-c3-wu-jie-han-shu-fan-chang-ji-fen": {"anchor":"∫ₐᵇf=lim_{ε→0⁺}∫ₐ^{b−ε}f（瑕点在 b）","caption":"被积函数在某点无界（瑕点）时，用极限定义积分：若瑕点在 b，则 ∫ₐᵇf=lim_{ε→0⁺}∫ₐ^{b−ε}f。","keyPoints":["先找出瑕点（函数无界的位置）","瑕积分在瑕点处取单侧极限，极限存在才收敛","p 积分：∫₀¹dx/xᵖ 在 p<1 时收敛"],"example":"∫₀¹dx/√x=2，收敛。"},
  "kp-m1-p1-c3-shou-lian-yu-fa-san": {"anchor":"0≤f≤g 且 ∫g 收敛 ⇒ ∫f 收敛","caption":"反常积分收敛指相应的极限存在且有限，否则发散；判断时常用比较判别法，与已知敛散性的 p 积分比较。","keyPoints":["收敛 = 极限存在且有限","比较判别法：0≤f≤g，∫g 收敛 ⇒ ∫f 收敛","p 积分是最常用的比较基准"],"example":"∫₁^{+∞}dx/(x²+1) 收敛（与 1/x² 比较）。"},
  "kp-m1-p1-c3-chai-fen-qi-dian": {"anchor":"∫ₐᵇ=∫ₐᶜ+∫ᶜᵇ（c 为瑕点）","caption":"区间内部有瑕点时，必须以瑕点为界把积分拆成两段分别判断；只要有一段发散，整体就发散。","keyPoints":["内部瑕点必须拆开处理","拆出的两段反常积分都收敛，原来才收敛","拆分点必须选在瑕点处，分段后逐段讨论"],"example":"∫₋₁¹dx/x 拆成两段后都发散，故整体发散。"},
  "kp-m1-p1-c3-chang-jian-bi-jiao-si-xiang": {"anchor":"∞ 处 p>1；瑕点处 p<1","caption":"判断反常积分敛散最常用的思路是与 p 积分比较：无穷区间用 1/xᵖ（p>1 收敛），瑕点附近用 1/xᵖ（p<1 收敛）；用等价无穷小确定阶最方便。","keyPoints":["无穷区间：∫₁^{+∞}dx/xᵖ 收敛 ⇔ p>1","瑕点处：∫₀¹dx/xᵖ 收敛 ⇔ p<1","等价无穷小用来找主导项"],"example":"∫₁^{+∞}dx/x^{1.5} 收敛（p=1.5>1）。"},
  "kp-m1-p1-c3-ping-mian-tu-xing-mian-ji": {"anchor":"A=∫ₐᵇ[f(x)−g(x)]dx","caption":"平面图形面积用「上曲线减下曲线」积分：A=∫ₐᵇ[f(x)−g(x)]dx（f≥g）；若左右边界更简单，可改对 y 积分（右减左）。","keyPoints":["A=∫ₐᵇ(上−下)dx","也可对 y 积分（右−左）","先画图找交点确定积分限"],"example":"y=x 与 y=x² 围成的面积 =∫₀¹(x−x²)dx=1/6。"},
  "kp-m1-p1-c3-can-shu-qu-xian-mian-ji": {"anchor":"A=∫_{t₁}^{t₂}y(t)x′(t)dt","caption":"参数曲线围成的面积用换元：A=∫y dx=∫y(t)x′(t)dt，积分限换成对应的 t 值，并注意曲线走向对符号的影响。","keyPoints":["A=∫y(t)x′(t)dt","积分限换成 t 的范围","注意定向（走向）对正负的影响"],"example":"摆线一拱的面积 =3πa²。"},
  "kp-m1-p1-c3-ji-zuo-biao-mian-ji": {"anchor":"A=(1/2)∫_α^β r²(θ)dθ","caption":"极坐标下用扇形微元 dA=(1/2)r²dθ，面积 A=(1/2)∫_α^β r²(θ)dθ；关键是确定 θ 的范围，由图形边界（射线或交点）决定。","keyPoints":["A=(1/2)∫_α^β r²(θ)dθ","θ 的范围由边界决定","对称图形可算一半再乘 2"],"example":"圆 r=2cos θ 的面积 =π。"},
  "kp-m1-p1-c3-xuan-zhuan-ti-ti-ji": {"anchor":"V=π∫ₐᵇf²(x)dx","caption":"绕 x 轴旋转的体积用圆盘法 V=π∫ₐᵇf²(x)dx；若是两曲线之间的区域旋转，则 V=π∫(f²−g²)dx。","keyPoints":["V=π∫ₐᵇf²(x)dx（绕 x 轴）","两曲线之间：V=π∫(f²−g²)dx","绕 y 轴时改对 y 积分"],"example":"y=√x 在 [0,1] 绕 x 轴：V=π∫₀¹x dx=π/2。"},
  "kp-m1-p1-c3-ping-xing-jie-mian-ti-ji": {"anchor":"V=∫ₐᵇA(x)dx","caption":"若垂直于某轴的截面面积 A(x) 已知，体积 V=∫ₐᵇA(x)dx；这是「切片求和」的推广，适用于非旋转体。","keyPoints":["V=∫ₐᵇA(x)dx","关键是写出截面积函数","旋转体是平行截面体的特例，截面恰为圆"],"example":"已知正三角形截面的立体，A(x)=(√3/4)a²(x)。"},
  "kp-m1-p1-c3-qu-xian-hu-chang": {"anchor":"s=∫ₐᵇ√(1+y′²)dx","caption":"曲线弧长是弧微分的积分：s=∫ₐᵇ√(1+y′²)dx；参数式用 s=∫√(x′²+y′²)dt，极坐标用 s=∫√(r²+r′²)dθ。","keyPoints":["直角坐标：s=∫ₐᵇ√(1+y′²)dx","参数式：s=∫√(x′²+y′²)dt","极坐标：s=∫√(r²+r′²)dθ"],"example":"y=(2/3)x^{3/2} 在 [0,3] 上的弧长 =14/3。"},
  "kp-m1-p1-c3-xuan-zhuan-qu-mian-ce-mian-ji": {"anchor":"S=2π∫ₐᵇ|y|√(1+y′²)dx","caption":"绕 x 轴旋转的侧面积 S=2π∫ₐᵇ|y|√(1+y′²)dx：把弧微元旋转成圆环，周长 2π|y| 乘弧长 ds。","keyPoints":["S=2π∫|y|√(1+y′²)dx","侧面积微元必须带弧微分因子，不能只投 dxdy","与体积公式的区别：这里是一次方"],"example":"y=x（0≤x≤1）绕 x 轴：S=√2π。"},
  "kp-m1-p1-c3-gong": {"anchor":"W=∫ₐᵇF(x)dx","caption":"变力做功 W=∫ₐᵇF(x)dx；抽水做功要写清微元：每层水的重力乘以它被提升的距离。","keyPoints":["W=∫ₐᵇF(x)dx","抽水：微元重力 ρgA(x)dx × 提升距离","物理应用先写微元再积分，微元是建模关键"],"example":"把水抽到容器顶面：W=ρg∫₀ʰ(h−x)A(x)dx。"},
  "kp-m1-p1-c3-ye-ti-ya-li": {"anchor":"P=∫ρgx·L(x)dx","caption":"液体压力用微元法：深度 x 处压强为 ρgx，微元压力 dP=ρgx·L(x)dx，总压力 P=∫ρgx·L(x)dx。","keyPoints":["压强 = ρgx（x 为深度）","dP=ρgx·L(x)dx","关键是写出该深度处的宽度 L(x)"],"example":"宽 b、高 h 的矩形闸门顶与水面平齐：P=ρgbh²/2。"},
  "kp-m1-p1-c3-yin-li": {"anchor":"F=∫Gmρdx/r²（按方向分量积分）","caption":"细杆对质点的引力用微元法：把杆分成小段，每段质量 dm=ρdx，按万有引力定律写微元力，再沿杆积分（注意分解方向分量）。","keyPoints":["微元质量 dm=ρdx","微元力 dF=Gm·dm/r²","必须分解方向分量再积分"],"example":"细杆对延长线上距端点 a 处质点的引力含 ln(1+L/a)。"},
  "kp-m1-p1-c3-zhi-xin-xing-xin": {"anchor":"x̄=(1/A)∫ₐᵇx[f(x)−g(x)]dx","caption":"形心是几何图形的中心，质心是质量分布的加权平均位置；均匀物体的形心与质心重合，公式为 x̄=(1/A)∫x[f(x)−g(x)]dx。","keyPoints":["形心 = 面积加权平均位置","x̄=(1/A)∫ₐᵇx(上−下)dx","均匀物体的质心就是形心"],"example":"三角形的形心在中线交点（距底 h/3）。"},
  "kp-m1-p1-c3-han-shu-ping-jun-zhi": {"anchor":"f̄=(1/(b−a))∫ₐᵇf(x)dx","caption":"函数在 [a,b] 上的平均值 f̄=(1/(b−a))∫ₐᵇf(x)dx，几何意义是「等面积矩形的高度」，也正是定积分中值定理中的 f(ξ)。","keyPoints":["f̄=(1/(b−a))∫ₐᵇf(x)dx","几何意义：等面积矩形的高度","与中值定理中的 f(ξ) 相等"],"example":"f(x)=x 在 [0,2] 上的平均值为 1。"},
  "kp-m1-p1-c3-mian-ji-sao-miao-wei-yuan-tiao": {"anchor":"dA=(上−下)dx","caption":"面积计算可以理解为用竖条扫描区域：每条宽 dx、高 (上−下)，面积微元 dA=(上−下)dx，全部累加就是定积分。","keyPoints":["dA=(上−下)dx","扫描方向可换（横条对应对 y 积分）","微元法统一处理面积、体积、弧长"],"example":"y=x² 与 x 轴在 [0,1] 围成的面积 =1/3。"},
  "kp-m1-p1-c3-xuan-zhuan-ti-er-wei-qu-yu-rao-zhou-10yj3l": {"anchor":"V=π∫(R²−r²)dx","caption":"把平面区域绕某条直线旋转得到旋转体；垂直于旋转轴切一刀，截面是圆盘或圆环，这就是圆盘法/圆环法公式的来源。","keyPoints":["截面是圆盘（或圆环）","圆盘法：V=π∫r²dx","圆环法：V=π∫(R²−r²)dx"],"example":"y=x² 与 y=1 之间的区域绕 y 轴旋转用圆环法。"},
  "kp-m1-p1-c3-hu-chang-zhe-xian-fen-duan-bu-duan-xi-1yb2rx": {"anchor":"s=lim Σ√(Δx²+Δy²)=∫√(1+y′²)dx","caption":"弧长的思想是「以直代曲」：用折线逼近曲线，每段长 √(Δx²+Δy²)，分段不断细化后取极限就得到 ∫√(1+y′²)dx。","keyPoints":["折线逼近 → 取极限得弧长积分","每段长度来自勾股定理","这就是弧微分 ds 的来源"],"example":"圆的周长可由弧长积分算得 2πR。"},
  "kp-m1-p1-c4-xiang-liang-zuo-biao": {"anchor":"a=(x₂−x₁, y₂−y₁, z₂−z₁)","caption":"向量的坐标 = 终点坐标减起点坐标，a=(a₁,a₂,a₃)；有了坐标，向量的运算就全部化为数的运算，这是向量代数的基础。","keyPoints":["a=终点 M₂ − 起点 M₁ 的对应坐标差","坐标相等 ⇔ 向量相等（自由向量）","位置向量 OM 的坐标就是点 M 的坐标"],"example":"A(1,2,3)、B(4,6,8)：AB=(3,4,5)。"},
  "kp-m1-p1-c4-mo": {"anchor":"|a|=√(a₁²+a₂²+a₃²)","caption":"向量的模 |a|=√(a₁²+a₂²+a₃²) 是它的长度，由坐标用勾股定理算出；|a|=0 当且仅当 a 是零向量，模的值永不为负。","keyPoints":["|a|=√(a₁²+a₂²+a₃²)","|ka|=|k||a|（数乘伸缩模）","|a|=0 ⇔ a=0（零向量）"],"example":"a=(3,4,0)：|a|=5。"},
  "kp-m1-p1-c4-dan-wei-xiang-liang": {"anchor":"e=a/|a|","caption":"把向量除以自己的模得单位向量 a/|a|：方向不变、长度变成 1；题目只要「方向」时（如方向向量、法向量写标准形）都用单位向量表达。","keyPoints":["e=a/|a|，长度为 1","单位化只除模，不改方向","零向量没有单位向量（模为 0 不能除）"],"example":"a=(3,4,0)：e=(3/5,4/5,0)。"},
  "kp-m1-p1-c4-fang-xiang-jiao-yu-fang-xiang-yu-xian": {"anchor":"cos²α+cos²β+cos²γ=1","caption":"非零向量与 x、y、z 轴的夹角 α、β、γ 叫方向角，其余弦 cos α=a₁/|a| 等叫方向余弦；","keyPoints":["cos α=a₁/|a|，cos β=a₂/|a|，cos γ=a₃/|a|","cos²α+cos²β+cos²γ=1（自带约束）","方向余弦 = 单位向量的分量"],"example":"a=(3,4,0)：cos α=3/5、cos β=4/5、cos γ=0，γ=π/2。"},
  "kp-m1-p1-c4-xiang-liang-jia-jian-yu-shu-cheng": {"anchor":"(a±b)=(a₁±b₁, a₂±b₂, a₃±b₃)，ka=(ka₁,ka₂,ka₃)","caption":"加法按三角形/平行四边形法则，减法是加相反向量，数乘是同向（k>0）或反向（k<0）伸缩；坐标下逐分量加减与乘 k，运算完全线性。","keyPoints":["a+b：三角形法则（首尾相接）","a−b：从 b 的终点指向 a 的终点","ka：模乘 |k|，k<0 时反向"],"example":"a=(1,2,3)、b=(2,0,−1)：a+b=(3,2,2)，2a−b=(0,4,7)。"},
  "kp-m1-p1-c4-ding-yi": {"anchor":"a·b=|a||b|cosθ","caption":"数量积（点积）a·b=|a||b|cosθ 是一个实数，其中 θ 是两向量夹角；它把「一个向量在另一个方向上的有效贡献」压缩成一个数，物理上对应功。","keyPoints":["a·b=|a||b|cosθ，结果是标量","θ∈[0,π] 为两向量夹角","力 F 位移 s 做功 W=F·s"],"example":"|a|=2、|b|=3、θ=60°：a·b=2·3·(1/2)=3。"},
  "kp-m1-p1-c4-zuo-biao-gong-shi": {"anchor":"a·b=a₁b₁+a₂b₂+a₃b₃","caption":"坐标下数量积 a·b=a₁b₁+a₂b₂+a₃b₃，对应分量乘积再求和；这是夹角、投影、垂直判定全部公式的计算入口。","keyPoints":["a·b=a₁b₁+a₂b₂+a₃b₃","自乘得模方：a·a=|a|²","交换律、对加法的分配律都成立"],"example":"a=(1,2,3)、b=(4,5,6)：a·b=4+10+18=32。"},
  "kp-m1-p1-c4-jia-jiao": {"anchor":"cosθ=a·b/(|a||b|)","caption":"两非零向量夹角由 cosθ=a·b/(|a||b|) 反解，θ 取 [0,π]；这条公式把几何夹角问题化成坐标计算，是「点积管角度」的核心。","keyPoints":["cosθ=a·b/(|a||b|)，θ∈[0,π]","cosθ>0 锐角、<0 钝角、=0 直角","分子分母都来自点积公式"],"example":"a=(1,0,1)、b=(0,1,1)：a·b=1，|a||b|=2，θ=60°。"},
  "kp-m1-p1-c4-chui-zhi-pan-ding": {"anchor":"a⊥b ⇔ a·b=0","caption":"a⊥b ⇔ a·b=0（夹角 90°，cosθ=0）；零向量与任何向量都算垂直（也常算平行），这是点积最重要的几何判据。","keyPoints":["垂直 ⇔ a₁b₁+a₂b₂+a₃b₃=0","零向量约定与任何向量垂直","求垂直向量即解点积方程"],"example":"a=(2,−1,3) 与 b=(0,3,1) 垂直：点积 0−3+3=0。"},
  "kp-m1-p1-c4-tou-ying": {"anchor":"Prjₐb=a·b/|a|","caption":"向量 b 在 a 上的投影是一个数：Prjₐb=|b|cosθ=a·b/|a|；它可正可负（θ 为钝角时为负），是点积的几何解读之一。","keyPoints":["Prjₐb=a·b/|a|=|b|cosθ","投影是一个数，可正可负，钝角时为负","θ=90° 时投影为 0"],"example":"a=(1,0,0)、b=(1,2,3)：Prjₐb=1，即 b 在 x 轴上的投影。"},
  "kp-m1-p1-c4-ding-yi-2": {"anchor":"|a×b|=|a||b|sinθ","caption":"向量积（叉积）a×b 是一个向量：模为 |a||b|sinθ，方向由右手法则确定且同时垂直于 a 与 b；它管「垂直」与「面积」，与点积分工明确。","keyPoints":["a×b 是向量：模 |a||b|sinθ","方向 ⊥ a 且 ⊥ b（右手定则）","a×b=−b×a（反交换）"],"example":"i×j=k（x 轴叉 y 轴得 z 轴）。"},
  "kp-m1-p1-c4-fang-xiang-yu-you-shou-fa-ze": {"anchor":"(a×b)·a=0 且 (a×b)·b=0","caption":"a×b 的方向按右手法则确定：右手四指从 a 转向 b（转角小于 π），拇指所指即 a×b 方向；因此 a×b 垂直于 a、b 所张的平面。","keyPoints":["右手从 a 转向 b，拇指即方向","a×b 同时垂直 a 和 b","交换两向量方向即反（a×b=−b×a）"],"example":"i×j=k，j×i=−k。"},
  "kp-m1-p1-c4-zuo-biao-ji-suan": {"anchor":"a×b=(a₂b₃−a₃b₂, a₃b₁−a₁b₃, a₁b₂−a₂b₁)","caption":"坐标下 a×b 用三阶行列式计算：第一行 i、j、k，第二行 a 的坐标，第三行 b 的坐标；按第一行展开即得结果向量的三个分量。","keyPoints":["a×b=|i j k; a₁ a₂ a₃; b₁ b₂ b₃|","按第一行展开，分量为二阶行列式","行列式形式自带反交换性"],"example":"a=(1,2,3)、b=(4,5,6)：a×b=(2·6−3·5, 3·4−1·6, 1·5−2·4)=(−3,12,−3)。"},
  "kp-m1-p1-c4-ping-xing-pan-ding": {"anchor":"a₁/b₁=a₂/b₂=a₃/b₃ ⇔ a∥b","caption":"a∥b ⇔ a×b=0 ⇔ 对应坐标成比例 a₁/b₁=a₂/b₂=a₃/b₃（分母非零时）；夹角 0 或 π 使 sinθ=0，叉积的模自然为零。","keyPoints":["a×b=0 ⇔ 平行","坐标成比例是坐标判据","零向量与任何向量都平行（约定）"],"example":"a=(1,2,3) 与 b=(2,4,6) 平行：坐标比都是 1/2。"},
  "kp-m1-p1-c4-ping-xing-si-bian-xing-san-jiao-xing-0xwhg7": {"anchor":"S△=|AB×AC|/2","caption":"以 a、b 为邻边的平行四边形面积 = |a×b|（底乘高恰为 |a||b|sinθ），三角形面积再除以 2；这是叉积模的几何身份。","keyPoints":["平行四边形 S=|a×b|","三角形 S=|a×b|/2","三点 A、B、C 的面积用 AB×AC"],"example":"A(0,0,0)、B(1,0,0)、C(0,2,0)：|AB×AC|=|k·2|=2，三角形面积 1。"},
  "kp-m1-p1-c4-dian-fa-shi": {"anchor":"A(x−x₀)+B(y−y₀)+C(z−z₀)=0","caption":"过点 (x₀,y₀,z₀)、法向量 n=(A,B,C) 的平面方程为 A(x−x₀)+B(y−y₀)+C(z−z₀)=0","keyPoints":["代入点与法向量即得方程","平面上任意向量都与 n 垂直","点法式整理后就是一般式，两种写法等价"],"example":"点 (1,2,−1)、n=(2,1,3)：2(x−1)+(y−2)+3(z+1)=0。"},
  "kp-m1-p1-c4-yi-ban-shi": {"anchor":"Ax+By+Cz+D=0，n=(A,B,C)","caption":"平面的一般式 Ax+By+Cz+D=0 中，x、y、z 的系数 (A,B,C) 恰是法向量；读方程先读法向量，这是平面题的第一反应。","keyPoints":["n=(A,B,C) 直接来自系数","D=0 ⇔ 平面过原点","缺某个变量 ⇔ 平面平行于该坐标轴"],"example":"2x−y+3z−6=0：n=(2,−1,3)。"},
  "kp-m1-p1-c4-jie-ju-shi": {"anchor":"x/a+y/b+z/c=1","caption":"平面在 x、y、z 轴上的截距为 a、b、c（均不为 0）时，方程为 x/a+y/b+z/c=1；由截距式一眼看出平面与三轴的交点。","keyPoints":["x/a+y/b+z/c=1","三个截距都不能为 0（不过原点）","截距点：(a,0,0)、(0,b,0)、(0,0,c)"],"example":"截距 2、3、6：x/2+y/3+z/6=1，即 3x+2y+z=6。"},
  "kp-m1-p1-c4-fa-xiang-liang": {"anchor":"n=(A,B,C)，n·(平面内向量)=0","caption":"与平面垂直的非零向量叫法向量 n=(A,B,C)；同一平面的法向量有无穷多个（彼此相差常数倍），求两平面夹角或判断位置关系都靠它。","keyPoints":["n 与平面内任意向量垂直","kn（k≠0）都是同一平面的法向量","两向量都垂直 ⇒ 叉积可造法向量"],"example":"平面内向量 u=(1,0,1)、v=(0,1,1)：n=u×v=(−1,−1,1)。"},
  "kp-m1-p1-c4-dian-xiang-shi-dui-chen-shi": {"anchor":"(x−x₀)/m=(y−y₀)/n=(z−z₀)/p","caption":"过点 (x₀,y₀,z₀)、方向向量 s=(m,n,p) 的直线写为 (x−x₀)/m=(y−y₀)/n=(z−z₀)/","keyPoints":["分子是坐标差，分母是方向分量","某分量为 0 时理解为对应分子=0","由对称式可直接读出点与方向"],"example":"点 (1,2,3)、s=(2,0,−1)：(x−1)/2=(z−3)/(−1) 且 y=2（y 方向分量为 0）。"},
  "kp-m1-p1-c4-can-shu-shi": {"anchor":"x=x₀+mt，y=y₀+nt，z=z₀+pt","caption":"把对称式的公共比值记作 t，得参数式 x=x₀+mt、y=y₀+nt、z=z₀+pt；参数式逐分量独立，代值、求交点最方便。","keyPoints":["x=x₀+mt，y=y₀+nt，z=z₀+pt","t 是参数，每点对应唯一 t","参数式与对称式可随时互化，t 就是那个比值"],"example":"点 (1,2,3)、s=(2,0,−1)：x=1+2t、y=2、z=3−t。"},
  "kp-m1-p1-c4-liang-ping-mian-jiao-xian": {"anchor":"s=n₁×n₂","caption":"两平面 A₁x+B₁y+C₁z+D₁=0 与 A₂x+B₂y+C₂z+D₂=0 的交线即方程组的公共解集；","keyPoints":["交线方向 s=n₁×n₂","找特殊点：令某个坐标为 0 解另两个","交线的一般式就是两平面方程联立"],"example":"x+y=1 与 z=0 的交线：s=(1,1,0)×(0,0,1)=(1,−1,0)，过 (1,0,0)。"},
  "kp-m1-p1-c4-fang-xiang-xiang-liang": {"anchor":"s=(m,n,p)=(x₂−x₁, y₂−y₁, z₂−z₁)","caption":"与直线平行的非零向量 s=(m,n,p) 叫方向向量；同一直线的方向向量有无穷多个（相差常数倍），它决定直线的「走向」，对称式与参数式都由它生成。","keyPoints":["方向向量 s 平行于直线本身，差常数倍等价","ks（k≠0）是等价方向向量","两直线方向向量叉积/点积判位置"],"example":"直线过 (0,0,0)、(1,2,3)：s=(1,2,3)。"},
  "kp-m1-p1-c4-xian-xian-ping-xing-chui-zhi-yi-mian": {"anchor":"异面判定：(s₁×s₂)·AB≠0","caption":"两条直线用方向向量 s₁、s₂ 判关系：s₁∥s₂ 共线（平行或重合），s₁⊥s₂ 垂直；","keyPoints":["平行：s₁×s₂=0；垂直：s₁·s₂=0","异面 ⇔ 不共面 ⇔ 混合积 (s₁,s₂,AB)≠0","判断相交还要验证公共点"],"example":"s₁=(1,0,0)、s₂=(0,1,0)：方向垂直；若两直线无公共点，即方向垂直的异面直线。"},
  "kp-m1-p1-c4-xian-mian-ping-xing-chui-zhi": {"anchor":"线面平行 ⇔ s·n=0 且点不在面内","caption":"直线（方向 s）与平面（法向 n）的关系：s·n=0 时线面平行或线在面内，s∥n 时线面垂直；「线在面内」还要再验证一个点是否落在平面上。","keyPoints":["平行：s·n=0（再查直线上一点不在面内）","垂直：s∥n（即 s×n=0）","斜交时的角用 sinθ=|s·n|/(|s||n|)"],"example":"s=(1,2,−1)、n=(1,1,1)：s·n=2≠0 且不平行，直线与平面斜交。"},
  "kp-m1-p1-c4-mian-mian-ping-xing-chui-zhi": {"anchor":"n₁∥n₂ ⇔ A₁/A₂=B₁/B₂=C₁/C₂","caption":"两平面的关系由法向量 n₁、n₂ 决定：n₁∥n₂ 时两平面平行（或重合），n₁⊥n₂ 时两平面垂直；判断重合需再看一个点是否同属两平面。","keyPoints":["平行：n₁×n₂=0（成比例）","垂直：n₁·n₂=0","重合 = 平行 + 共点"],"example":"x+y+z=1 与 2x+2y+2z=5 平行不重合；x+y+z=1 与 x−y=0 垂直（点积 1−1=0）。"},
  "kp-m1-p1-c4-jia-jiao-2": {"anchor":"线线：cosθ=|s₁·s₂|/(|s₁||s₂|)；线面：sinθ=|s·n|/(|s||n|)","caption":"线线夹角用 cosθ=|s₁·s₂|/(|s₁||s₂|)；线面夹角用 sinθ=|s·n|/(|s||n|)（直线与平","keyPoints":["线线看 s₁、s₂ 的点积余弦","线面是 s 与 n 夹角的余角，用 sin","全部取绝对值，θ∈[0,π/2]"],"example":"s=(1,0,0)、n=(0,0,1)：sinθ=1，线面夹角 90°（直线垂直平面）。"},
  "kp-m1-p1-c4-dian-dao-ping-mian-ju-li": {"anchor":"d=|Ax₀+By₀+Cz₀+D|/√(A²+B²+C²)","caption":"点 (x₀,y₀,z₀) 到平面 Ax+By+Cz+D=0 的距离 d=|Ax₀+By₀+Cz₀+D|/√(A²+B²+","keyPoints":["d=|Ax₀+By₀+Cz₀+D|/√(A²+B²+C²)","分子带绝对值，距离非负","点在平面上时分子为 0"],"example":"点 (1,2,3) 到 x+y+z=1：|1+2+3−1|/√3=5/√3。"},
  "kp-m1-p1-c4-qiu-mian": {"anchor":"(x−x₀)²+(y−y₀)²+(z−z₀)²=R²","caption":"球面是到定点（球心）距离恒为 R 的点的轨迹：(x−x₀)²+(y−y₀)²+(z−z₀)²=R²；一般式展开后平方项系数相同，配方即回标准形。","keyPoints":["标准形 (x−x₀)²+(y−y₀)²+(z−z₀)²=R²","一般式 x²+y²+z²+Dx+Ey+Fz+G=0 配方可判","配方后常数 <0 则不表示实球面"],"example":"x²+y²+z²−2x+4z=0 配方：(x−1)²+y²+(z+2)²=5，球心 (1,0,−2)、半径 √5。"},
  "kp-m1-p1-c4-zhu-mian": {"anchor":"F(x,y)=0（母线 ∥ z 轴）","caption":"三元方程缺某个变量时表示柱面：如 F(x,y)=0 的母线平行于 z 轴，准线是 xy 面上的曲线 F(x,y)=0；","keyPoints":["F(x,y)=0：母线 ∥ z 轴","准线是该坐标面上的曲线","缺变量不是「变量不存在」而是「自由」"],"example":"x²+y²=1 在空间是圆柱面（不是圆），母线平行 z 轴。"},
  "kp-m1-p1-c4-xuan-zhuan-qu-mian": {"anchor":"f(x,z)=0 绕 z 轴 ⇒ f(±√(x²+y²), z)=0","caption":"平面曲线绕同一平面内的定轴旋转得旋转曲面；绕 z 轴时把曲线方程里的 x² 改成 x²+y²（z 保持不变）","keyPoints":["绕 z 轴：x 换成 ±√(x²+y²)","绕 x 轴：y 换成 ±√(y²+z²)","旋转轴对应的变量保持不变"],"example":"直线 z=x 绕 z 轴：z=±√(x²+y²)，即 z²=x²+y²（圆锥面）。"},
  "kp-m1-p1-c4-tuo-qiu-mian": {"anchor":"x²/a²+y²/b²+z²/c²=1","caption":"x²/a²+y²/b²+z²/c²=1 是椭球面，三个半轴 a、b、c 决定三个方向的「胖瘦」；全部由正项构成，是有界封闭曲面，截口都是椭圆。","keyPoints":["标准形三项全正且右边为 1","半轴 |x|≤a、|y|≤b、|z|≤c","a=b=c 时退化为球面"],"example":"x²/4+y²/9+z²=1：a=2、b=3、c=1 的椭球面。"},
  "kp-m1-p1-c4-shuang-qu-mian": {"anchor":"单叶 x²/a²+y²/b²−z²/c²=1；双叶 =−1","caption":"含一个负项的二次曲面：右边为 +1 是单叶双曲面（连通，如 x²/a²+y²/b²−z²/c²=1）","keyPoints":["单叶：=+1，连通成腰鼓形","双叶：=−1，分成上下两叶","负项对应的方向是双叶的「开口」方向"],"example":"x²/4+y²/4−z²=1 是单叶双曲面（绕 z 轴旋转单叶）。"},
  "kp-m1-p1-c4-pao-wu-mian": {"anchor":"z=x²/a²+y²/b²（椭圆抛物面）","caption":"椭圆抛物面 z=x²/a²+y²/b² 有一个一次项（开口方向），两个平方项同号；","keyPoints":["z=x²/a²+y²/b²：开口沿 +z","一次项变量指明开口方向","两平方项异号时是双曲抛物面（马鞍面）"],"example":"z=x²+y² 是旋转抛物面；z=x²−y² 是双曲抛物面（马鞍面）。"},
  "kp-m1-p1-c4-kong-jian-qu-xian-can-shu-fang-cheng": {"anchor":"Γ: x=x(t)，y=y(t)，z=z(t)，t∈[a,b]","caption":"空间曲线可用一个参数写出 x=x(t)、y=y(t)、z=z(t)；参数方程直接给出曲线上的点序列，求切线、计算曲线积分都以它为标准形态。","keyPoints":["曲线是一维：一个参数就够","x(t)、y(t)、z(t) 都连续（可微更好）","消参可得曲线的一般式（两曲面联立）"],"example":"螺旋线 x=cos t、y=sin t、z=t（t∈R）绕 z 轴上升。"},
  "kp-m1-p1-c4-tou-ying-qu-xian": {"anchor":"Γ 投影：F(x,y)=0，z=0","caption":"求空间曲线对 xy 面的投影：从两曲面方程联立中消去 z 得投影柱面 F(x,y)=0，再与 z=0 联立即投影曲线；对其他坐标面同理消对应变量。","keyPoints":["消 z ⇒ 对 xy 面的投影柱面","投影曲线 = 投影柱面 ∩ 坐标面","重积分定区域常用投影曲线"],"example":"z=x²+y² 与 z=1 的交线对 xy 面投影：x²+y²=1，z=0。"},
  "kp-m1-p1-c5-er-yuan-duo-yuan-han-shu": {"anchor":"z=f(x,y)，(x,y)∈D⊆R²","caption":"二元函数 z=f(x,y) 有两个独立自变量、一个因变量，多元函数同理；自变量是一对有序数组 (x,y)，函数关系是「每个点对应唯一的 z」。","keyPoints":["自变量个数 ≥2、因变量只有 1 个","(x₀,y₀) 是平面上的一点，不是两个数","对应关系必须单值：一个点只能有一个 z"],"example":"z=√(1−x²−y²) 表示单位圆盘上的上半球面。"},
  "kp-m1-p1-c5-ding-yi-yu": {"anchor":"如 z=ln(y−x²) 的定义域 D={y>x²}","caption":"二元函数的定义域是使表达式有意义的平面点集，常见限制来自负数开偶次方、零作分母、对数真数非正；通常画出区域图再判断开闭。","keyPoints":["开偶次方要求被开方数 ≥0","分母不为 0，对数真数 >0","边界含不含影响「闭区域」与最值存在性"],"example":"z=√(4−x²−y²) 的定义域是闭圆盘 x²+y²≤4（含边界）。"},
  "kp-m1-p1-c5-er-yuan-han-shu-ji-he-yi-yi": {"anchor":"曲面 Σ: z=f(x,y)，(x,y)∈D","caption":"z=f(x,y) 的图像是三维空间中的一张曲面：把每个定义域上的点 (x,y) 竖起高度 f(x,y) 连成曲面；","keyPoints":["图像是 R³ 中的曲面（一元函数是曲线）","固定 y 得平面截线，看单变量变化","等值线 f(x,y)=c 是曲面的水平切片投影"],"example":"z=x²+y² 是旋转抛物面，等值线是一族同心圆。"},
  "kp-m1-p1-c5-you-jie-bi-qu-yu-lian-xu-han-shu-xing-17hmgt": {"anchor":"∃(P₁,P₂)：f(P₁)=m（最小），f(P₂)=M（最大）","caption":"二元连续函数在有界闭区域上必有最大值与最小值，且能取到介于两者之间的一切值（介值定理）；这与一元闭区间连续函数的性质完全平行，是「最值必存在」的依据。","keyPoints":["有界 + 闭 ⇒ 最值一定存在","介值性：最大最小之间的一切值都取得到","前提缺一不可：开区域或无界都不保证"],"example":"f=x²+y² 在闭圆盘 x²+y²≤1 上必有最小值 0 与最大值 1。"},
  "kp-m1-p1-c5-er-chong-ji-xian": {"anchor":"lim₍ₓ,y₎→₍₀,₀₎f(x,y)=A ⇔ 沿任意路径均趋于 A","caption":"二重极限要求点 (x,y) 沿任意路径趋于 (x₀,y₀) 时函数值都趋于同一常数 A——路径无关是本质要求；这正是它与一元左右极限的根本区别。","keyPoints":["趋近方式任意：直线、曲线、螺旋都算","路径无关且都趋于同一个 A，才叫极限为 A","两条路径极限不同 ⇒ 极限不存在"],"example":"lim(x²y)/(x²+y²)=0：|x²y|≤(x²+y²)|y|→0，与路径无关。"},
  "kp-m1-p1-c5-duo-lu-jing-qu-jin": {"anchor":"lim_{y=kx→0}f(x,kx) 依赖 k ⇒ 极限不存在","caption":"多路径趋近是研究二重极限的基本手段：沿 y=kx、y=kx²、坐标轴等不同路径分别算极限；","keyPoints":["y=kx 一步就能试出直线方向的依赖","y=kx² 能试出比直线更细的差异","各路径一致 ⇒ 还需夹逼/极坐标确认存在"],"example":"xy/(x²+y²) 沿 y=kx 得 k/(1+k²)，随 k 变，极限不存在。"},
  "kp-m1-p1-c5-yong-lu-jing-zheng-ming-ji-xian-bu-cun-0o8ubh": {"anchor":"lim₁≠lim₂ ⇒ 极限不存在","caption":"证明二重极限不存在的标准套路：找两条趋于该点的路径，沿它们算出的极限不相等（或其中一条不存在），即可断言极限不存在；","keyPoints":["核心：两条路径的极限不相等","常备路径：y=kx、y=kx²、坐标轴","结论只用于「不存在」，不能证存在"],"example":"(x²−y²)/(x²+y²)：沿 y=0 得 1，沿 x=0 得 −1，极限不存在。"},
  "kp-m1-p1-c5-ji-zuo-biao-chu-li-er-yuan-ji-xian": {"anchor":"x²+y²=r²，|x|≤r，|y|≤r","caption":"令 x=r cosθ、y=r sinθ 后，(x,y)→(0,0) 变成 r→0；","keyPoints":["x=r cosθ、y=r sinθ，距离用 r 度量","对 θ 一致趋近才证明极限存在","θ 留在表达式里时要用 |cosθ|、|sinθ|≤1 放缩"],"example":"(x³+y³)/(x²+y²)：极坐标 =r(cos³θ+sin³θ)，|·|≤2r→0，极限为 0。"},
  "kp-m1-p1-c5-lian-xu-xing": {"anchor":"limₚ→ₚ₀ f(P)=f(P₀)","caption":"f 在点 P₀ 连续 = f 在 P₀ 有定义 + 二重极限存在 + 极限值恰等于函数值；","keyPoints":["连续三要素：有定义、极限存在、极限=函数值","初等函数在其定义区域内连续","间断点形态比一元丰富：可成曲线"],"example":"f=√(x²+y²) 在 (0,0) 连续：极限 0 恰等于函数值 0。"},
  "kp-m1-p1-c5-yi-jie-pian-dao": {"anchor":"f_x=lim_{Δx→0}（f(x+Δx,y)−f(x,y)）/Δx","caption":"f_x=lim_{Δx→0}[f(x+Δx,y)−f(x,y)]/Δx：固定 y 只让 x 变化的一元导数；","keyPoints":["定义：固定其余变量时的差商极限","记号 f_x、∂f/∂x、z_x 等价","偏导存在不代表函数连续（与一元不同）"],"example":"f=x²y+e^{xy}：f_x=2xy+ye^{xy}（把 y 当常数）。"},
  "kp-m1-p1-c5-gao-jie-pian-dao": {"anchor":"z_xy=(z_x)_y，z_xx=(z_x)_x","caption":"对一阶偏导再求偏导得到二阶偏导，如 z_xx、z_xy；二阶有四个（实际三类），更高阶类推，符号里字母顺序表示求导次序。","keyPoints":["z_xy 表示先对 x 再对 y","四个二阶偏导：xx、xy、yx、yy","计算就是逐次求一阶偏导"],"example":"z=x³y²：z_x=3x²y²，z_xy=6x²y，z_xx=6xy²。"},
  "kp-m1-p1-c5-hun-he-pian-dao": {"anchor":"f_xy=f_yx（连续时）","caption":"混合偏导 f_xy 与 f_yx 一般是先 x 后 y 与先 y 后 x 两种次序；","keyPoints":["f_xy 与 f_yx 在连续条件下相等","次序可换 ⇒ 挑简单的次序算","不连续时二者可以不相等"],"example":"z=x ln(xy)：两个混合偏导都等于 1/y——先 x 后 y 更好算。"},
  "kp-m1-p1-c5-pian-dao-shu-ji-he-yi-yi": {"anchor":"f_x(x₀,y₀)=tan α（截线切线的倾角）","caption":"f_x(x₀,y₀) 是曲面与平面 y=y₀ 的交线在 x₀ 处的切线对 x 轴的斜率；","keyPoints":["f_x：固定 y₀ 的截线在 x₀ 处斜率","f_y：固定 x₀ 的截线在 y₀ 处斜率","它不是「任意方向」的坡度（那是方向导数）"],"example":"z=x²+y² 在 (1,0) 处 f_x=2：沿 x 方向的截线在该点斜率为 2。"},
  "kp-m1-p1-c5-ke-wei-gai-nian": {"anchor":"Δz=AΔx+BΔy+o(ρ)","caption":"全增量 Δz 若能写成 AΔx+BΔy+o(ρ)（ρ=√(Δx²+Δy²)），就称 f 在该点可微；","keyPoints":["Δz=AΔx+BΔy+o(ρ) 是可微的定义","线性部分 AΔx+BΔy 叫全微分","ρ 是两点距离，o(ρ) 比 ρ 更快趋于 0"],"example":"z=xy 在 (1,1)：Δz=Δx+Δy+ΔxΔy，而 ΔxΔy=o(ρ)，故可微。"},
  "kp-m1-p1-c5-quan-wei-fen-gong-shi": {"anchor":"dz=f_x(x,y)dx+f_y(x,y)dy","caption":"f 可微时全微分 dz=f_x dx+f_y dy；系数 A、B 恰好是两个偏导，所以「先求偏导、再按公式拼装」就是求全微分的全部工作。","keyPoints":["全微分公式 dz=f_x dx+f_y dy，先求两个偏导","dx=Δx、dy=Δy（自变量增量）","可微是公式成立的前提"],"example":"z=xy 在 (1,2)：dz=2dx+dy。"},
  "kp-m1-p1-c5-pian-dao-cun-zai-yu-ke-wei-de-guan-xi": {"anchor":"偏导连续 ⇒ 可微 ⇒ 偏导存在、连续","caption":"可微必推出两个偏导存在，但偏导存在推不出可微（甚至推不出连续）；再加「偏导在该点连续」才足以推出可微——这条链是多元微分学的核心逻辑。","keyPoints":["可微 ⇒ 偏导都存在","偏导存在 ⇏ 可微、也 ⇏ 连续","偏导连续 ⇒ 可微（充分条件）"],"example":"f=xy/(x²+y²)（原点补 0）在原点两个偏导都存在，但极限不存在故不连续、更不可微。"},
  "kp-m1-p1-c5-ke-wei-yu-lian-xu-de-guan-xi": {"anchor":"Δz→0 ⇔ 连续；可微 ⇒ Δz=AΔx+BΔy+o(ρ)→0","caption":"可微的函数必连续：增量能写成线性主部加 o(ρ)，则 Δz→0，连续性立即成立；反向不成立，如 f=√(x²+y²) 在原点连续但不可微。","keyPoints":["可微 ⇒ 连续（反之不然）","连续 ⇏ 偏导存在，更 ⇏ 可微","√(x²+y²) 是「连续不可微」的标准反例"],"example":"f=√(x²+y²) 在 (0,0) 连续，但沿 x 方向增量/Δx=|Δx|/Δx 无极限，不可微。"},
  "kp-m1-p1-c5-lian-shi-fa-ze": {"anchor":"z=f(u,v)，u=u(x,y)，v=v(x,y)：z_x=f_u u_x+f_v v_x","caption":"多元复合求导沿用「沿线相乘、分线相加」：z 对每个中间变量求偏导、中间变量再对自变量求偏导，把所有路径的乘积加起来；树状图是防漏项的工具。","keyPoints":["每条路径贡献一个乘积","z_x=f_u·u_x+f_v·v_x（两条路径两条乘积）","先画树状图再动笔，防漏乘"],"example":"z=u²v，u=x+y，v=xy：z_x=2u·1+v·y=2(x+y)+xy²。"},
  "kp-m1-p1-c5-duo-zhong-jian-bian-liang": {"anchor":"dz/dt=f_u·u′(t)+f_v·v′(t)","caption":"当中间变量都只依赖同一个自变量 t（如 z=f(u(t),v(t))），复合后 z=f(u(t),v(t)) 是 t 的","keyPoints":["全部中间变量挂在同一个 t 上","dz/dt=f_u·u′(t)+f_v·v′(t)","结果是普通一元导数，不是偏导"],"example":"z=uv，u=eᵗ，v=sin t：dz/dt=eᵗ sin t+eᵗ cos t。"},
  "kp-m1-p1-c5-shu-zhuang-guan-xi": {"anchor":"路径数 = 乘积项数","caption":"复合关系复杂时先画树状图：根是因变量，枝是中间变量，叶是自变量；从根到叶每条路径对应一个乘积因子，所有路径相加——图不对，导数必错。","keyPoints":["树的层数 = 复合的层数","一条路径 = 一个乘积项","自变量有几个，结果就有几组偏导"],"example":"z=f(u,x)，u=xy：树给出 z_x=f_u·y+f_x（两条路径）。"},
  "kp-m1-p1-c5-yi-ge-fang-cheng-que-ding-yi-ge-yin-han-0090in": {"anchor":"z_x=−F_x/F_z","caption":"方程 F(x,y,z)=0 在某点附近确定隐函数 z=z(x,y) 时，对 x 求导（z 视为 x 的函数）得 z_x=","keyPoints":["z_x=−F_x/F_z，z_y=−F_y/F_z","推导：F(x,y,z(x,y))≡0 两边求偏导","公式只在 F_z≠0 的点可用"],"example":"x²+y²+z²=1：z_x=−x/z，在 z≠0 处成立。"},
  "kp-m1-p1-c5-fang-cheng-zu-que-ding-duo-ge-yin-han-0p8szs": {"anchor":"J=|F_u F_v; G_u G_v|≠0","caption":"方程组 F(x,y,u,v)=0、G(x,y,u,v)=0 在条件下确定 u、v 是 x、y 的隐函数；","keyPoints":["几个方程确定几个隐函数","对 x（或 y）求导后解二元线性方程组","系数行列式 J=∂(F,G)/∂(u,v)≠0 保证可解"],"example":"F=u+v−x、G=uv−y：对 x 求导解线性方程组得 u_x=u/(u−v)。"},
  "kp-m1-p1-c5-yin-han-shu-cun-zai-tiao-jian-de-li-jie": {"anchor":"F_z(P₀)≠0 ⇒ 存在邻域内唯一 z(x,y)","caption":"F 在点 P₀ 满足偏导连续且 F_z(P₀)≠0 时，方程 F=0 在 P₀ 附近唯一确定连续可微的隐函数 z(x,y","keyPoints":["F_z(P₀)≠0 是局部存在唯一的关键","结论是局部的：只在 P₀ 附近成立","顺带给出隐函数连续可微（可求偏导）"],"example":"x²+y²+z²=1 在 (0,0,1)：F_z=2z=2≠0，附近可解出 z=√(1−x²−y²)。"},
  "kp-m1-p1-c5-fang-xiang-dao-shu-ding-yi": {"anchor":"∂f/∂e=∇f·e=f_x cos α+f_y cos β","caption":"方向导数是函数沿单位方向 e 的变化率 ∂f/∂e=lim_{t→0⁺}[f(P₀+te)−f(P₀)]/t；","keyPoints":["定义：沿方向 e 截线的差商极限","可微时 ∂f/∂e=∇f·e（点积）","偏导是沿坐标轴方向的方向导数"],"example":"f=x²+y² 在 (1,1) 沿 e=(1/√2,1/√2)：∇f=(2,2)，方向导数=4/√2=2√2。"},
  "kp-m1-p1-c5-dan-wei-fang-xiang-xiang-liang": {"anchor":"e=(cos α, cos β)=l/|l|","caption":"方向只用「朝向」描述，因此要除以自身长度得单位向量 e=(cos α, cos β)；","keyPoints":["e=方向向量/|方向向量|","e² 的分量平方和为 1","相反方向的方向导数互为相反数"],"example":"方向 (3,4) 单位化 e=(3/5,4/5)，方向导数 ∂f/∂e=3f_x/5+4f_y/5。"},
  "kp-m1-p1-c5-ti-du": {"anchor":"grad f=∇f=(f_x, f_y)","caption":"梯度 grad f=∇f=(f_x, f_y) 是把各偏导排成的向量；它是个「向量场」，每一点的梯度指向该点函数上升最快的方向，长度就是最大变化率。","keyPoints":["∇f=(f_x, f_y)（二元时两个分量）","梯度是向量：有方向有大小","方向导数 = ∇f 点积单位方向"],"example":"f=x²+xy 在 (1,1)：∇f=(3,2)。"},
  "kp-m1-p1-c5-ti-du-yu-deng-zhi-xian-fa-xiang-guan-xi": {"anchor":"∇f ∥ 法向量，∇f·τ=0（τ 为等值线切向）","caption":"在等值线 f(x,y)=c 上函数值不变，所以沿等值线方向的方向导数为 0","keyPoints":["梯度 ⊥ 等值线（切线方向）","梯度指向函数值增大最快的方向","−∇f 指向下降最快（梯度下降的依据）"],"example":"f=x²+y² 的等值线是圆，梯度 (2x,2y) 沿半径方向，恰是圆的法向。"},
  "kp-m1-p1-c5-zui-da-fang-xiang-dao-shu": {"anchor":"max ∂f/∂e=|∇f|=√(f_x²+f_y²)","caption":"方向导数 ∂f/∂e=|∇f|cosθ 随方向变化，θ=0（沿梯度方向）时最大，等于 |∇f|；","keyPoints":["最大方向导数 = |∇f|，方向为梯度方向","最小值 −|∇f| 沿负梯度方向","为 0 的方向与梯度垂直"],"example":"f=x²+y² 在 (1,2)：|∇f|=|(2,4)|=2√5，沿 (1,2) 方向最陡。"},
  "kp-m1-p1-c5-kong-jian-qu-xian-qie-xian-yu-fa-ping-0aeozl": {"anchor":"T=(x′,y′,z′)|_{t₀}","caption":"曲线 Γ: x=x(t), y=y(t), z=z(t) 在 t₀ 处的切向量 T=(x′(t₀), y′(t₀), z","keyPoints":["切向量 = 参数导数三元组","切线：对称式 (x−x₀)/x′=(y−y₀)/y′=(z−z₀)/z′","法平面：x′(x−x₀)+y′(y−y₀)+z′(z−z₀)=0"],"example":"螺旋线 x=cos t、y=sin t、z=t 在 t=0：T=(0,1,1)，切线 x=0, (y−0)/1=(z−0)/1。"},
  "kp-m1-p1-c5-qu-mian-qie-ping-mian-yu-fa-xian": {"anchor":"切平面：F_x(x−x₀)+F_y(y−y₀)+F_z(z−z₀)=0","caption":"曲面 F(x,y,z)=0 在点 P₀ 的法向量 n=(F_x, F_y, F_z)|_{P₀}；","keyPoints":["n=(F_x, F_y, F_z) 在该点的值","切平面：F_x(x−x₀)+F_y(y−y₀)+F_z(z−z₀)=0","显式曲面 z−f(x,y)=0 时 n=(f_x, f_y, −1)"],"example":"z=x²+y² 即 F=x²+y²−z：在 (1,1,2) 的 n=(2,2,−1)，切平面 2x+2y−z=2。"},
  "kp-m1-p1-c5-wu-tiao-jian-ji-zhi": {"anchor":"∃U(P₀)：f(P)≤f(P₀) 对 P∈U","caption":"极值是比较函数在该点某个邻域内的取值：f(P₀)≥邻域内一切值即极大值；极值是局部概念，最大值是整体概念，二者没有必然包含关系。","keyPoints":["极值看邻域，最值看整个区域","极大值可能小于某个极小值（不同邻域）","极值点在定义域内部才有意义"],"example":"z=x²+y² 在 (0,0) 取极小值 0。"},
  "kp-m1-p1-c5-bi-yao-tiao-jian": {"anchor":"f_x(P₀)=0 且 f_y(P₀)=0","caption":"可微函数在极值点处两个偏导都必须为 0（驻点）；但驻点未必是极值点——马鞍面 z=xy 在原点驻点却非极值，驻点只是候选。","keyPoints":["极值点 ⇒ f_x=f_y=0（可微时）","驻点不一定是极值点，需过二阶充分条件","偏导不存在的点也可能是极值点"],"example":"z=xy：驻点 (0,0)，但 AC−B²=−1<0，不是极值点。"},
  "kp-m1-p1-c5-er-jie-chong-fen-tiao-jian": {"anchor":"Δ=AC−B²","caption":"记 A=f_xx、B=f_xy、C=f_yy（在驻点处取值）：AC−B²>0 时是极值（A<0 极大、A>0 极小）；","keyPoints":["AC−B²>0 且 A>0 ⇒ 极小","AC−B²>0 且 A<0 ⇒ 极大","AC−B²<0 非极值；=0 失效"],"example":"z=x²+y²：A=2、B=0、C=2，AC−B²=4>0 且 A>0，(0,0) 是极小值点。"},
  "kp-m1-p1-c5-zui-da-zhi-zui-xiao-zhi": {"anchor":"M=max{内部候选值, 边界最大值}","caption":"有界闭区域上连续函数必有最值：把内部驻点（及不可导点）的函数值与边界上的最值放在一起比大小，最大者即最大值；","keyPoints":["候选：内部驻点 + 边界最值点","比较所有候选的函数值","应用题：唯一驻点 + 最值必存在 ⇒ 即最值点"],"example":"f=x²+y² 在 x²+y²≤1：内部驻点 (0,0) 值 0，边界最大 1，故最大值 1 最小值 0。"},
  "kp-m1-p1-c5-la-ge-lang-ri-cheng-shu-fa": {"anchor":"f_x+λφ_x=0，f_y+λφ_y=0，φ=0","caption":"求 f 在约束 φ=0 下的极值，构造 L=f+λφ，令 L 的全部偏导为零解出驻点；它把「约束下的极值」化成无条件的方程组，数一数二通用。","keyPoints":["L(x,y,λ)=f(x,y)+λφ(x,y)","联立 L_x=L_y=L_λ=0","解出的点再按实际问题判别"],"example":"求 x+y 在 x²+y²=1 上的最值：L=x+y+λ(x²+y²−1) 解得 (±1/√2,±1/√2)，最值 ±√2。"},
  "kp-m1-p1-c5-yi-ge-yue-shu": {"anchor":"L_x=0，L_y=0，φ=0","caption":"一个约束 φ(x,y)=0 时，拉格朗日函数只有乘数 λ：未知数是 x、y、λ 三个，三个方程联立；解出的 (x,y) 代回 f 比较即得条件极值。","keyPoints":["未知数个数 = 2 + 约束个数","方程组 = 目标偏导 2 条 + 约束 1 条","利用约束先化简再解更快"],"example":"f=xy 在 x+y=1：L=xy+λ(x+y−1) 解得 x=y=1/2，最大值 1/4。"},
  "kp-m1-p1-c5-duo-ge-yue-shu-de-ji-ben-si-xiang": {"anchor":"L_x=L_y=L_z=λφ 项 + μψ 项 = 0，φ=0，ψ=0","caption":"多个约束（如 φ=0 且 ψ=0）时，每个约束配一个乘数：L=f+λφ+μψ，未知数与方程同步增加；思想不变——把条件极值化成无条件方程组。","keyPoints":["乘数个数 = 约束个数","L=f+λφ+μψ，全部偏导置零","方程个数 = 变量个数（含乘数）"],"example":"求 (x,y,z) 到原点距离在 x+y+z=1 与 x−y=0 下的极值：L=x²+y²+z²+λ(x+y+z−1)+μ(x−y)。"},
  "kp-m1-p1-c5-shi-ji-ying-yong": {"anchor":"max/min f s.t. φ=0","caption":"条件极值的应用题先写出目标函数与约束（几何、物理或成本条件），再用拉格朗日乘数法求解；若实际问题保证最值存在且解出唯一候选点，该点即所求最值点。","keyPoints":["目标函数与约束都来自题意","解出唯一候选 + 最值必存在 ⇒ 即最值","最后回答题目的量（别停在驻点坐标）"],"example":"周长一定的矩形面积最大：约束 x+y=常数，解得 x=y（正方形）。"},
  "kp-m1-p1-c6-ding-yi-yu-ji-he-yi-yi": {"anchor":"∬_D f(x,y)dσ=lim_{λ→0}Σf(ξᵢ,ηᵢ)Δσᵢ","caption":"二重积分 ∬_D f(x,y)dσ 是「分割、取点、求和、取极限」在平面区域上的推广；","keyPoints":["dσ=dxdy 是面积微元","f≥0：∬f dσ = 曲顶柱体体积","f≡1：积分 = 区域 D 的面积"],"example":"∬_D 1dσ（x²+y²≤1）=π，即圆的面积。"},
  "kp-m1-p1-c6-ji-ben-xing-zhi": {"anchor":"m·|D|≤∬_D f dσ≤M·|D|（m≤f≤M）","caption":"二重积分具有线性性、区域可加性、比较与估值定理，以及二重积分中值定理 f(ξ,η)=平均值——与定积分性质平行，是估算与化简的基础。","keyPoints":["线性：∬(kf+g)=k∬f+∬g","可加：D 拆成 D₁∪D₂，积分相加","中值定理：∃(ξ,η)，∬f=f(ξ,η)·面积"],"example":"f 在单位圆盘上介于 0 与 1：积分介于 0 与 π。"},
  "kp-m1-p1-c6-zhi-jiao-zuo-biao-ji-suan": {"anchor":"∬_D f dσ=∫ₐᵇdx∫_{y₁(x)}^{y₂(x)}f dy","caption":"直角坐标下二重积分化为二次积分：先定外层变量的范围（常数），再定内层变量的上下限（可以含外层变量）；画区域图是定限的第一步。","keyPoints":["∬f dxdy=∫dx∫f dy（或反过来）","内层限可以是外层变量的函数","二次积分的外层限必须是常数，内层才含变量"],"example":"D 由 y=x、y=0、x=1 围成：∫₀¹dx∫₀ˣf dy。"},
  "kp-m1-p1-c6-x-xing-qu-yu": {"anchor":"∫ₐᵇdx∫_{y₁(x)}^{y₂(x)}f dy","caption":"X 型区域 {a≤x≤b, y₁(x)≤y≤y₂(x)}：上下边界是 x 的函数，穿过区域的竖直线与边界交点不多于两个；","keyPoints":["特征：左右边界是竖直线 x=常数","外层 x 从 a 到 b（常数）","内层 y 从下边界到上边界"],"example":"D: 0≤x≤1, x²≤y≤x：∫₀¹dx∫_{x²}^x f dy。"},
  "kp-m1-p1-c6-y-xing-qu-yu": {"anchor":"∫_c^d dy∫_{x₁(y)}^{x₂(y)}f dx","caption":"Y 型区域 {c≤y≤d, x₁(y)≤x≤x₂(y)}：左右边界是 y 的函数，水平穿线与边界交点不多于两个；先对 x 积分，外层 y 是常数范围。","keyPoints":["特征：上下边界是水平线","外层 y 从 c 到 d","内层 x 从左边界到右边界"],"example":"D: 0≤y≤1, y≤x≤√y：∫₀¹dy∫_y^{√y} f dx。"},
  "kp-m1-p1-c6-jiao-huan-ji-fen-ci-xu": {"anchor":"∫ₐᵇdx∫_{y₁(x)}^{y₂(x)}f dy=∫_c^d dy∫_{x₁(y)}^{x₂(y)}f dx","caption":"交换积分次序的流程：由给定二次积分反推区域 D（把限翻译成不等式）→ 画图 → 按另一次序重新定限；某些积分只有换序后才积得动。","keyPoints":["交换次序时由限画图是关键一步，画错全错","换序后内外限全部重写","含 e^{y²}、sin y/y 等必须换序"],"example":"∫₀¹dx∫_x¹ e^{y²}dy 换序为 ∫₀¹dy∫₀^y e^{y²}dx=(e−1)/2。"},
  "kp-m1-p1-c6-dui-chen-xing": {"anchor":"D 对称于 y 轴、f(−x,y)=−f(x,y) ⇒ ∬_D=0","caption":"若区域 D 关于 y 轴对称，被积函数关于 x 为奇函数则积分为 0，为偶函数则等于半区域积分的两倍；","keyPoints":["区域关于 y 轴对称 + f 对 x 是奇 ⇒ 积分 0","偶函数 ⇒ 2×半区域积分","先看区域对称性，再看函数奇偶性"],"example":"∬(x³+y)dσ 在 x²+y²≤1：x³ 对 x 是奇，积分为 0，只剩 ∬y dσ=0。"},
  "kp-m1-p1-c6-x-r-cos-y-r-sin": {"anchor":"x=r cosθ，y=r sinθ","caption":"极坐标替换 x=r cosθ、y=r sinθ 把直角坐标的点 (x,y) 换成「距离 r + 角度 θ」；","keyPoints":["x=r cosθ、y=r sinθ","x²+y²=r²（圆方程瞬间化简）","arctan(y/x) 定角度"],"example":"x²+y²≤4 变成 0≤r≤2、0≤θ≤2π。"},
  "kp-m1-p1-c6-mian-ji-yuan-da-r-dr-d": {"anchor":"∬f dxdy=∬f(r cosθ,r sinθ)·r dr dθ","caption":"极坐标下面积微元 dA=dxdy 变成 r dr dθ：小扇形环的面积 ≈ r·dr·dθ；漏乘 r 是极坐标二重积分最常见的错误。","keyPoints":["dA=r dr dθ（r 是雅可比）","几何来源：扇环面积 rΔθ·Δr","被积函数同步换成极坐标形式"],"example":"∬_{x²+y²≤1}dxdy=∫₀^{2π}dθ∫₀¹r dr=π。"},
  "kp-m1-p1-c6-yuan-shan-xing-huan-xing-qu-yu": {"anchor":"环形域：R₁≤r≤R₂，α≤θ≤β","caption":"圆域、扇形、环形（圆环）区域在极坐标下的表示极其简单：r 是常数区间、θ 是角度区间；这些区域上的二重积分首选极坐标。","keyPoints":["圆盘：0≤r≤R，0≤θ≤2π","环形：R₁≤r≤R₂","扇形：θ 取一段角度区间"],"example":"1≤x²+y²≤4 上半部分：1≤r≤2，0≤θ≤π。"},
  "kp-m1-p1-c6-zuo-biao-xuan-ze-yuan-ze": {"anchor":"含 x²+y² 的函数 + 圆域 ⇒ 极坐标","caption":"选坐标系的两个依据：区域是圆/环/扇 → 极坐标；被积函数含 x²+y²、y/x 等径向结构 → 极坐标；","keyPoints":["选坐标系时区域形状优先看，函数结构其次","区域看完再看被积函数结构，含 x²+y² 用极坐标","含 e^{±x²}、sin x/x 时靠换序凑可积"],"example":"∬e^{x²+y²}dσ 在单位圆：极坐标 ∫∫e^{r²}r dr dθ 轻松积出。"},
  "kp-m1-p1-c6-ti-ji": {"anchor":"V=∬_D(z₂−z₁)dxdy","caption":"曲顶柱体体积 V=∬_D f dσ（f≥0）；一般立体（上下曲面夹住）的体积 V=∬_D(z 上 −z 下)dσ——「上","keyPoints":["V=∬_D z_上(x,y)−z_下(x,y) dσ","f≥0 时 ∬f dσ 本身就是体积","对称区域先用对称性化简，再动手积分"],"example":"球 x²+y²+z²≤R² 的体积：V=2∬_{x²+y²≤R²}√(R²−x²−y²)dxdy=4πR³/3。"},
  "kp-m1-p1-c6-qu-mian-mian-ji-de-xiang-guan-zhun-bei": {"anchor":"S=∬_D√(1+z_x²+z_y²)dxdy","caption":"曲面 z=z(x,y) 的面积微元 dS=√(1+z_x²+z_y²)dxdy——切平面一小块比它在 xy 面的投影大一","keyPoints":["dS=√(1+z_x²+z_y²)dxdy","平面时根号恰是 1/cosγ（倾斜角）","积分域是曲面的投影区域"],"example":"平面 z=x+y 在正方形上：dS=√3 dxdy，面积=√3×投影面积。"},
  "kp-m1-p1-c6-zhi-liang": {"anchor":"m=∬_D ρ(x,y)dxdy","caption":"面密度为 ρ(x,y) 的平面薄片质量 m=∬_D ρ(x,y)dσ——密度乘面积微元再累加；均匀薄片（ρ 常数）时退化为密度乘面积。","keyPoints":["m=∬_D ρ(x,y)dσ","均匀薄片 m=ρ×面积，密度直接约掉","同类套路：电荷量、热量都一样积"],"example":"ρ=x+y 在 D=[0,1]×[0,1]：m=∫∫(x+y)=1。"},
  "kp-m1-p1-c6-zhi-xin": {"anchor":"x̄=∬xρ dσ/m","caption":"平面薄片的质心坐标 x̄=(∬xρ dσ)/m、ȳ=(∬yρ dσ)/m，分母是质量；均匀薄片（ρ=常数）时质心只依赖区域形状，也叫形心。","keyPoints":["x̄=∬xρ dσ/m，ȳ=∬yρ dσ/m","均匀时 ρ 约掉，只剩几何量","区域对称 ⇒ 质心在对称轴上"],"example":"均匀半圆盘 x²+y²≤1、y≥0：由对称 x̄=0，ȳ=(∬y dσ)/面积=4/(3π)。"},
  "kp-m1-p1-c6-zhuan-dong-guan-liang": {"anchor":"I₀=∬_D(x²+y²)ρ dσ","caption":"薄片对轴（或点）的转动惯量 I=∬r²ρ dσ，r 是微元到轴（点）的距离：对 x 轴用 y²、对 y 轴用 x²","keyPoints":["对 x 轴：I_x=∬y²ρ dσ","对原点：I₀=∬(x²+y²)ρ dσ=I_x+I_y","惯性半径 r=√(I/m)"],"example":"均匀圆盘对中心轴：极坐标 I₀=ρ∫∫r²·r dr dθ=ρπR⁴/2=mR²/2。"},
  "kp-m1-p1-c6-ding-yi": {"anchor":"∭_Ω f dV=lim Σf ΔVᵢ","caption":"三重积分 ∭_Ω f(x,y,z)dV 是二重积分向空间区域的推广：分割立体、取点求和、取极限；f≡1 时积分等于区域 Ω 的体积。","keyPoints":["dV=dxdydz 是体积微元","f≡1：∭dV=Ω 的体积","物理上对应空间物体的质量"],"example":"∭_{x²+y²+z²≤R²}dV=4πR³/3。"},
  "kp-m1-p1-c6-zhi-jiao-zuo-biao": {"anchor":"∭_Ω f dxdydz=∬_D∫_{z₁(x,y)}^{z₂(x,y)}f dz dσ","caption":"三重积分直角坐标下化为三次积分：外两层由区域在 xy 面的投影决定，最内层 z 从下曲面到上曲面；「投影定 xy、穿线定 z」。","keyPoints":["∭f dV=∬_D dσ∫_{z₁}^{z₂}f dz","投影区域 D 定外两层限","内层限是 x、y 的函数"],"example":"Ω 由 z=0 与 z=1−x²−y² 围成：∬_{x²+y²≤1}∫₀^{1−x²−y²}f dz dσ。"},
  "kp-m1-p1-c6-zhu-zuo-biao": {"anchor":"∭f dV=∭f(r cosθ,r sinθ,z)·r dz dr dθ","caption":"柱坐标 = xy 面用极坐标 + 高度 z：x=r cosθ、y=r sinθ、z=z","keyPoints":["x=r cosθ，y=r sinθ，z=z","dV=r dz dr dθ（比直角多一个 r）","x²+y² 直接变 r²"],"example":"圆柱 x²+y²≤1、0≤z≤2 的体积：∫₀^{2π}dθ∫₀¹r dr∫₀²dz=2π。"},
  "kp-m1-p1-c6-qiu-zuo-biao": {"anchor":"x=r sinφ cosθ，y=r sinφ sinθ，z=r cosφ","caption":"球坐标：x=r sinφ cosθ、y=r sinφ sinθ、z=r cosφ（r 是到原点距离","keyPoints":["dV=r² sinφ dr dφ dθ","φ 从 z 轴正向量起（0 到 π）","x²+y²+z²=r²"],"example":"球体体积：∫₀^{2π}dθ∫₀^π sinφ dφ∫₀^R r²dr=4πR³/3。"},
  "kp-m1-p1-c6-tou-ying-fa": {"anchor":"∭=∬_D∫_{z₁(x,y)}^{z₂(x,y)}f dz dσ","caption":"投影法（先一后二）：先对 z 积一层（上下曲面之间的「竖线段」），再对投影区域做二重积分；区域是「柱体状」时最顺手。","keyPoints":["∭f=∬_D dσ∫_{z₁}^{z₂}f dz","先算 z 的上下界（常是曲面方程）","剩下的二重积分再选坐标系"],"example":"抛物面 z=x²+y² 与 z=1 之间：D 为单位圆盘，z 从 x²+y² 到 1。"},
  "kp-m1-p1-c6-jie-mian-fa": {"anchor":"∭=∫_{z₁}^{z₂}dz∬_{D(z)}f dσ","caption":"截面法（先二后一）：固定 z 切一片，先算截面 D(z) 上的二重积分，再对 z 积一次；截面面积好算（圆、随 z 线性变化）时效率极高。","keyPoints":["∭f=∫dz∬_{D(z)}f dσ","适合 D(z) 简单（如圆盘）的区域","被积函数只含 z 时 ∬=面积×f(z)"],"example":"旋转抛物面体 z≥x²+y²、z≤4：D(z) 半径 √z，体积=∫₀⁴πz dz=8π。"},
  "kp-m1-p1-c6-dui-chen-xing-2": {"anchor":"Ω 对 xOy 面对称、f 对 z 为奇 ⇒ ∭=0","caption":"三重积分的对称性：区域关于坐标面对称、函数对相应变量为奇则积分为 0，为偶则折半加倍；「轮换对称性」指区域方程轮换不变时积分可换变量名。","keyPoints":["坐标面对称 + 奇函数 ⇒ 积分 0","轮换对称：∬∫x²dV=∬∫y²dV=∬∫z²dV（球体）","先用对称化简再选坐标系"],"example":"球体上 ∭x²dV=∭y²dV=∭z²dV，三者之和=∭r²dV，各占三分之一。"},
  "kp-m1-p1-c7-dui-hu-chang-qu-xian-ji-fen": {"anchor":"∫_L f(x,y)ds=lim Σf(ξᵢ,ηᵢ)Δsᵢ","caption":"对弧长的曲线积分 ∫_L f(x,y)ds 把曲线切成小弧段、每段用「密度 f 乘弧长」累加；","keyPoints":["记号 ∫_L f ds，ds 是弧长微元","与方向无关：∫_L=∫_{L⁻}","物理原型：曲线形构件的质量"],"example":"∫_L ds=L 的弧长本身；f≡1 时积分就是弧长。"},
  "kp-m1-p1-c7-ding-yi": {"anchor":"∫_L f ds=lim_{λ→0}Σᵢ f(ξᵢ,ηᵢ)Δsᵢ","caption":"在曲线上依次插入分点把弧长分成 n 段，每段取一点乘以该段弧长再求和，最大弧段长趋于零时的极限即第一类曲线积分；定义与方向完全无关。","keyPoints":["λ=max Δsᵢ→0 时的和式极限","取点在弧段上任意（连续时结果一样）","极限存在 ⇔ 可积（连续函数必可积）"],"example":"线密度 ρ(x,y) 的曲线质量 m=∫_L ρ ds。"},
  "kp-m1-p1-c7-can-shu-hua-ji-suan": {"anchor":"∫_L f ds=∫_α^β f(x(t),y(t))√(x′²+y′²)dt","caption":"第一类曲线积分参数化后化为定积分：∫_L f ds=∫_α^β f(x(t),y(t))√(x′²(t)+y′²(t))","keyPoints":["ds=√(x′²+y′²)dt（平面）","空间加 z′²：ds=√(x′²+y′²+z′²)dt","α<β 保证 ds>0（弧长不为负）"],"example":"圆 x=cos t、y=sin t：ds=dt，∫(x²+y²)ds=∫₀^{2π}dt=2π。"},
  "kp-m1-p1-c7-ji-he-wu-li-yi-yi": {"anchor":"m=∫_L ρ(x,y)ds","caption":"第一类曲线积分的几何意义：以曲线为准线、母线平行 z 轴、高 f(x,y) 的柱面面积；物理意义：线密度为 f 的曲线的质量、重心、转动惯量。","keyPoints":["几何：f>0 时是柱面侧面积","质量 m=∫ρ ds，重心 x̄=∫xρ ds/m","f≡1 时退化为弧长"],"example":"半圆 x²+y²=1（y≥0）线密度 ρ=y：质量 ∫y ds=∫₀^π sin t dt=2。"},
  "kp-m1-p1-c7-dui-zuo-biao-qu-xian-ji-fen": {"anchor":"∫_L P dx+Q dy=lim Σ[P Δxᵢ+Q Δyᵢ]","caption":"对坐标的曲线积分 ∫_L P dx+Q dy 沿有向曲线把「P 乘 dx、Q 乘 dy」累加；","keyPoints":["记号 ∫_L P dx+Q dy","与方向有关：∫_{L⁻}=−∫_L","组合形式对应向量场沿曲线的积累"],"example":"∫_L xy dx 沿从 (0,0) 到 (1,1) 的曲线。"},
  "kp-m1-p1-c7-you-xiang-qu-xian": {"anchor":"∫_{AB}=−∫_{BA}","caption":"第二类曲线积分的积分弧段必须指明起点与终点，称为有向曲线；同一条曲线反向走积分值变号——检验计算对不对时先看方向。","keyPoints":["L⁻ 表示沿反方向走的曲线，积分变号","∫_{L⁻}P dx+Q dy=−∫_L P dx+Q dy","起终点写反是最常见的错误"],"example":"沿 y=x 从 (0,0) 到 (1,1) 与反向：两积分互为相反数。"},
  "kp-m1-p1-c7-can-shu-hua-ji-suan-2": {"anchor":"∫_a^b[P x′(t)+Q y′(t)]dt","caption":"第二类曲线积分参数化：∫_L P dx+Q dy=∫_a^b[P(x(t),y(t))x′(t)+Q(x(t),y(t)","keyPoints":["dx=x′(t)dt、dy=y′(t)dt 直接代入","下限=起点参数，上限=终点参数","下限大于上限是允许的（方向信息）"],"example":"∫_L x dy 沿 y=x² 从 (0,0) 到 (1,1)：∫₀¹x·2x dx=2/3。"},
  "kp-m1-p1-c7-yu-gong-de-lian-xi": {"anchor":"W=∫_L F·dr=∫_L P dx+Q dy","caption":"变力 F=(P,Q) 沿曲线 L 位移 dr=(dx,dy) 所做的功 W=∫_L F·dr=∫_L P dx+Q dy","keyPoints":["W=∫_L P dx+Q dy（力·位移的积累）","F 与路径垂直的分段不做功","保守力做功与路径无关"],"example":"F=(y,x) 沿 y=x 从 (0,0) 到 (1,1)：W=∫(x+x)dx=1。"},
  "kp-m1-p1-c7-zheng-xiang-bian-jie": {"anchor":"∂D⁺：外逆内顺","caption":"格林公式的正向边界指：沿边界行进时区域始终在左侧——外边界取逆时针、内边界（洞）取顺时针；方向搞反，公式差一个负号。","keyPoints":["正向 = 区域在行进方向左侧","外边界逆时针，洞边界顺时针","边界绕向反向时，格林公式右端变号"],"example":"圆盘 x²+y²≤1 的正向边界是逆时针单位圆。"},
  "kp-m1-p1-c7-ge-lin-gong-shi": {"anchor":"∮P dx+Q dy=∬(Q_x−P_y)dxdy","caption":"格林公式：∮_L P dx+Q dy=∬_D(∂Q/∂x−∂P/∂y)dxdy，其中 L 是 D 的正向边界，P","keyPoints":["左闭线积分、右二重积分","被积式：∂Q/∂x−∂P/∂y（注意顺序）","条件：P、Q 偏导连续 + L 正向闭"],"example":"∮(x−y)dx+(x+y)dy 沿单位圆：Q_x−P_y=1−(−1)=2，积分=2·π=2π。"},
  "kp-m1-p1-c7-qu-xian-ji-fen-zhuan-er-chong-ji-fen": {"anchor":"∫_L=∮_{L∪L₁}−∫_{L₁}","caption":"非闭曲线上的第二类积分想用格林公式时，先补一段简单曲线（常取直线段）凑成闭路：原积分 = 闭路积分 − 补线积分，各自用格林与直接参数化计算。","keyPoints":["补线原则：越简单越好（常取坐标轴平行段）","∫(原)=∮(补后)−∫(补线)","偏导不连续的点要挖去（补圆挖洞）"],"example":"沿抛物线 y=x² 从 (0,0) 到 (1,1) 的积分：补 y=x 与 x=1 两段构成闭路。"},
  "kp-m1-p1-c7-ping-mian-qu-yu-mian-ji-gong-shi": {"anchor":"A=(1/2)∮_L x dy−y dx","caption":"取 P=−y、Q=x（或 Q=0、P=−y 等组合）使 ∂Q/∂x−∂P/∂y=1","keyPoints":["A=(1/2)∮x dy−y dx（正向边界）","变体：A=∮x dy=−∮y dx","参数化后直接积出面积"],"example":"椭圆 x=a cos t、y=b sin t：A=(1/2)∫(ab cos²t+ab sin²t)dt=πab。"},
  "kp-m1-p1-c7-lu-jing-wu-guan": {"anchor":"∂P/∂y=∂Q/∂x ⇔ 路径无关（单连通）","caption":"第二类曲线积分在区域内路径无关，指任意两点间的积分值只取决于起终点；","keyPoints":["路径无关 ⇔ 闭曲线积分恒为 0","单连通内 ⇔ ∂P/∂y=∂Q/∂x","复连通区域还要看「洞」里的奇点"],"example":"∫2xy dx+x² dy：P_y=2x=Q_x，路径无关，沿折线算即可。"},
  "kp-m1-p1-c7-yu-yuan-han-shu-cun-zai-de-guan-xi": {"anchor":"∫₍ₐ₎^₍ᵦ₎P dx+Q dy=u(B)−u(A)","caption":"单连通区域内 P dx+Q dy 是某函数 u 的全微分 ⇔ ∂P/∂y=∂Q/∂x；","keyPoints":["存在 u 使 du=P dx+Q dy ⇔ P_y=Q_x","u 的求法：先积 P 关于 x、再定 y 的函数","∫=u(终点)−u(起点)"],"example":"2xy dx+x² dy：u=x²y+C，从 (0,0) 到 (1,2) 积分 =2。"},
  "kp-m1-p1-c7-dui-mian-ji-qu-mian-ji-fen": {"anchor":"∬_Σ f dS=lim Σf(ξᵢ,ηᵢ,ζᵢ)ΔSᵢ","caption":"对面积的曲面积分 ∬_Σ f(x,y,z)dS 把曲面切成小面片按「f 乘面积」累加；与曲面朝哪一侧无关（dS 恒正），物理上是面密度求质量。","keyPoints":["记号 ∬_Σ f dS","第一类曲面积分与侧无关，两侧积分同值","f≡1 时积分 = 曲面面积"],"example":"面密度 ρ=z 的球面部分质量 m=∬_Σ z dS。"},
  "kp-m1-p1-c7-qu-mian-can-shu-hua-tou-ying-ji-suan": {"anchor":"∬_Σ f dS=∬_{D_xy}f(x,y,z(x,y))√(1+z_x²+z_y²)dxdy","caption":"曲面 z=z(x,y) 投影到 xy 面计算：dS=√(1+z_x²+z_y²)dxdy，积分化为投影区域上的二重积分；","keyPoints":["dS=√(1+z_x²+z_y²)dxdy","积分域换成投影区域 D_xy","也可投到另两个坐标面（用 x=x(y,z) 等）"],"example":"半球 z=√(1−x²−y²)：z_x=−x/z，dS=1/z·dxdy。"},
  "kp-m1-p1-c7-dui-zuo-biao-qu-mian-ji-fen": {"anchor":"Φ=∬_Σ P dydz+Q dzdx+R dxdy","caption":"对坐标的曲面积分 ∬_Σ P dydz+Q dzdx+R dxdy 沿指定侧把「分量乘对应坐标微元」累加；","keyPoints":["三项各配一对坐标微元","第二类曲面积分与侧有关，换侧积分变号","物理原型：向量场穿面的流量"],"example":"∬_Σ z dxdy 表示竖直分量的流量贡献。"},
  "kp-m1-p1-c7-qu-mian-ce": {"anchor":"∬_{Σ⁻}=−∬_{Σ⁺}","caption":"第二类曲面积分要在「有向曲面」上进行：光滑曲面分上下（前后、左右）两侧，选定一侧就是指定了法向量的指向；换一侧，积分值变号。","keyPoints":["双侧曲面指定「侧」才有积分","曲面换一侧，第二类积分整体变号","闭曲面积分默认取外侧，内侧要添负号"],"example":"z=z(x,y) 型曲面：上侧法向量与 z 轴正向夹角为锐角。"},
  "kp-m1-p1-c7-fa-xiang-liang-fang-xiang": {"anchor":"∬P dydz+Q dzdx+R dxdy=∬(P,Q,R)·n dS","caption":"指定侧的单位法向量 n=(cos α, cos β, cos γ)；","keyPoints":["n 的三个余弦分别管 dydz、dzdx、dxdy 的符号","上侧 cos γ>0；下侧 cos γ<0","第二类积分=∫(P,Q,R)·n dS（点积形式）"],"example":"上半球面外侧在赤道上 cos γ=0，dxdy 项贡献为零。"},
  "kp-m1-p1-c7-tou-ying-ji-suan": {"anchor":"∬_Σ R dxdy=±∬_{D_xy}R(x,y,z(x,y))dxdy","caption":"计算 ∬_Σ R dxdy：把曲面写成 z=z(x,y) 后化为 ±∬_{D_xy}R(x,y,z(x,y))dxdy","keyPoints":["∬R dxdy=±∬_{D_xy}R(x,y,z(x,y))dxdy","投影符号上侧取正、下侧取负","竖直柱面在 xy 面投影为零，dxdy 项为零"],"example":"平面上侧 z=1−x−y（第一卦限）的 ∬z dxdy=∫∫(1−x−y)dxdy。"},
  "kp-m1-p1-c7-bi-qu-mian-wai-ce": {"anchor":"∮ 外侧 = ∭(散度)dV","caption":"闭曲面（围成空间区域）的外侧指法向量指向区域外部；高斯公式正是在外侧成立——内侧用公式要添负号，开曲面要先补面凑闭。","keyPoints":["外侧 = 法向量朝区域外","高斯公式默认闭曲面外侧，开曲面先补面","开曲面用「补面法」凑闭"],"example":"球面外侧是标准外侧；用球面挖洞处理含奇点问题。"},
  "kp-m1-p1-c7-tong-liang": {"anchor":"Φ=∬_Σ P dydz+Q dzdx+R dxdy","caption":"向量场 A=(P,Q,R) 穿过曲面 Σ 指定侧的通量 Φ=∬_Σ A·n dS=∬P dydz+Q dzdx+R dx","keyPoints":["Φ=∬A·n dS（点积形式）","组合形式 dydz、dzdx、dxdy 各管一个分量","通量为 0：进出相抵"],"example":"A=(x,y,z) 穿过单位球面外侧：由高斯公式 Φ=∭3dV=4π。"},
  "kp-m1-p1-c7-san-chong-ji-fen-yu-qu-mian-ji-fen-02xgvr": {"anchor":"∬_{Σ⁺}=∭_Ω(∂P/∂x+∂Q/∂y+∂R/∂z)dV","caption":"高斯公式：闭曲面外侧的通量积分 = 区域上散度的三重积分，∬P dydz+Q dzdx+R dxdy=∭(∂P/∂x+∂","keyPoints":["右端被积式是散度 div A","要求偏导连续且曲面封闭","奇点在内部时挖洞处理"],"example":"div(x,y,z)=3：单位球内通量=3·(4π/3)=4π。"},
  "kp-m1-p1-c7-qu-mian-bian-jie-fang-xiang": {"anchor":"Γ⁺ 与 n 成右手系","caption":"斯托克斯公式中边界曲线 Γ 的方向按右手法则定：伸右手与曲面指定侧的法向量同向，四指弯曲方向即 Γ 的正向——「面定侧、手定边」。","keyPoints":["Γ 的方向与 Σ 的侧配套","右手法则：拇指沿 n，四指为 Γ 正向","换侧则边界方向同时反转"],"example":"上半球面取上侧，其边界（赤道圆）正向从 +z 轴往下看是逆时针。"},
  "kp-m1-p1-c7-qu-mian-ji-fen-yu-kong-jian-qu-xian-ji-07h92h": {"anchor":"∮_Γ F·dr=∬_Σ(curl F)·n dS","caption":"斯托克斯公式把沿空间闭曲线的第二类积分换成曲面上旋度的第二类面积分：∮_Γ P dx+Q dy+R dz=∬_Σ(cur","keyPoints":["右端被积向量是旋度 curl F","Γ 与 Σ 的方向按右手系配套","退化到 z=0 平面即格林公式"],"example":"F=(−y,x,0)：curl F=(0,0,2)，绕任意水平圆的环量=2×围面积。"},
  "kp-m1-p1-c8-ji-shu-yu-bu-fen-he": {"anchor":"S=limₙ→∞ Sₙ=limₙ→∞ Σᵢ₌₁ⁿuᵢ","caption":"级数 Σuₙ 是无穷个数依次相加，前 n 项之和 Sₙ=Σᵢ₌₁ⁿuᵢ 叫部分和；","keyPoints":["Sₙ=u₁+u₂+…+uₙ 是部分和","级数的和 = lim Sₙ（存在才有意义）","无穷相加不是普通加法，不能随便重排"],"example":"Σ1/(n(n+1)) 的 Sₙ=1−1/(n+1)→1，级数的和为 1。"},
  "kp-m1-p1-c8-shou-lian-fa-san": {"anchor":"收敛 ⇔ lim Sₙ=S（有限）","caption":"部分和数列收敛（lim Sₙ 存在）叫级数收敛，否则发散；发散级数没有和，部分和无界或振荡都算发散。","keyPoints":["收敛 ⇔ {Sₙ} 有极限","lim Sₙ=∞ 或不存在都叫发散","收敛时余项 rₙ=S−Sₙ→0"],"example":"Σ1/2ⁿ 的 Sₙ=1−1/2ⁿ→1 收敛；Σn 的 Sₙ→∞ 发散。"},
  "kp-m1-p1-c8-shou-lian-bi-yao-tiao-jian-u-n-0": {"anchor":"收敛 ⇒ lim uₙ=0","caption":"级数收敛则通项必趋于零：uₙ=Sₙ−Sₙ₋₁→0；逆否命题是常用判断——uₙ 不趋于 0 立即断言发散","keyPoints":["收敛推出 uₙ→0，逆否用来快速判发散","uₙ↛0 ⇒ 发散（第一步检查）","uₙ→0 ⇏ 收敛：Σ1/n 发散"],"example":"Σn/(n+1) 的通项→1≠0，发散；Σ1/n 通项→0 但发散。"},
  "kp-m1-p1-c8-ji-shu-ji-ben-xing-zhi": {"anchor":"Σ(uₙ±vₙ)=Σuₙ±Σvₙ","caption":"收敛级数可逐项乘常数、逐项相减相加（和差仍收敛），增删有限项不改变敛散性；收敛级数可以加括号，但加括号后收敛推不出原级数收敛。","keyPoints":["Σ(kuₙ±kvₙ)=kΣuₙ±kΣvₙ（都收敛时）","改变有限项不影响敛散性","收敛 ⇒ 加括号仍收敛；反之不成立"],"example":"Σ(1/2ⁿ+1/n²) 收敛（两个收敛级数之和）；Σ(1/2ⁿ−1/n) 发散。"},
  "kp-m1-p1-c8-ji-he-ji-shu": {"anchor":"Σaqⁿ=a/(1−q)（|q|<1）","caption":"几何级数 Σₙ₌₀^∞ aqⁿ（a≠0）当 |q|<1 时收敛于 a/(1−q)，当 |q|≥1 时发散；","keyPoints":["|q|<1：S=a/(1−q)","|q|≥1：发散（通项不趋零）","首项 a 与公比 q 要分清"],"example":"Σxⁿ/2ⁿ=Σ(x/2)ⁿ 当 |x|<2 收敛于 1/(1−x/2)=2/(2−x)。"},
  "kp-m1-p1-c8-p-ji-shu": {"anchor":"Σ1/nᵖ 收敛 ⇔ p>1","caption":"p 级数 Σ1/nᵖ 当 p>1 时收敛、p≤1 时发散；p=1 是调和级数（发散），p=2 收敛——它是比较判别法最常用的「标尺」。","keyPoints":["Σ1/nᵖ：p>1 收敛，p≤1 发散","p=1 调和级数发散（经典结论）","Σ1/nᵖ 与 Σ1/(n ln n) 等变体另判"],"example":"Σ1/n² 收敛；Σ1/√n（p=1/2）发散；Σ1/√(n³)（p=3/2）收敛。"},
  "kp-m1-p1-c8-bi-jiao-pan-bie-fa": {"anchor":"0≤aₙ≤bₙ：b 收 ⇒ a 收","caption":"正项级数里若 0≤aₙ≤bₙ（从某项起），则「大收则小收，小发则大发」：bₙ 收敛推 aₙ 收敛，aₙ 发散推 bₙ 发散；关键是找对可比的标尺级数。","keyPoints":["从某项起控制住即可（前几项无关）","b 收 ⇒ a 收；a 发 ⇒ b 发","标尺常取 p 级数与几何级数"],"example":"Σ1/(n²+n)≤1/n² 收敛，故收敛。"},
  "kp-m1-p1-c8-bi-jiao-pan-bie-fa-ji-xian-xing-shi": {"anchor":"lim aₙ/bₙ=λ（0<λ<∞）⇒ 同敛散","caption":"若 lim aₙ/bₙ=λ：0<λ<+∞ 时两级数同敛散；λ=0 时由 bₙ 收敛推 aₙ 收敛；","keyPoints":["同阶（λ 有限正）⇒ 同敛散","aₙ 是 bₙ 高阶无穷小且 b 收 ⇒ a 收","λ=∞ 且 b 发 ⇒ a 发"],"example":"Σtan(1/n) 与 Σ1/n 比：极限 1，同发散。"},
  "kp-m1-p1-c8-bi-zhi-pan-bie-fa": {"anchor":"lim aₙ₊₁/aₙ=ρ：ρ<1 收，ρ>1 发","caption":"正项级数算 lim aₙ₊₁/aₙ=ρ：ρ<1 收敛，ρ>1（含 ∞）发散，ρ=1 判别失效要换方法；通项含阶乘、指数幂时首选比值法。","keyPoints":["ρ<1 收敛；ρ>1 发散（通项不趋零）","ρ=1 失效：如 p 级数永远得 1","含 n!、kⁿ 优先用它"],"example":"Σ1/n!：比值 =1/(n+1)→0<1，收敛。"},
  "kp-m1-p1-c8-gen-zhi-pan-bie-fa": {"anchor":"lim ⁿ√aₙ=ρ：ρ<1 收，ρ>1 发，=1 失效","caption":"正项级数算 lim ⁿ√aₙ=ρ：ρ<1 收敛，ρ>1 发散，ρ=1 失效；通项整体带 n 次幂（如 (aₙ)ⁿ 形）时用它最顺手。","keyPoints":["ρ=lim ⁿ√aₙ","判法与比值法完全平行","通项形如 [f(n)]ⁿ 时首选"],"example":"Σ(n/(2n+1))ⁿ：ⁿ√aₙ=n/(2n+1)→1/2<1，收敛。"},
  "kp-m1-p1-c8-lai-bu-ni-ci-pan-bie-fa": {"anchor":"uₙ↓ 且 uₙ→0 ⇒ Σ(−1)ⁿ⁻¹uₙ 收敛","caption":"交错级数 Σ(−1)ⁿ⁻¹uₙ（uₙ>0）满足 uₙ 单调不增且趋于 0 时必收敛；三条要素里「趋零」是核心，「单调不增」保证部分和摆动幅度越来越小。","keyPoints":["条件：uₙ 单调不增 且 uₙ→0","莱布尼茨的结论是交错级数收敛，且误差可控","单调性只要求「最终」成立"],"example":"Σ(−1)ⁿ⁻¹/n：1/n 单调减趋于 0，收敛。"},
  "kp-m1-p1-c8-wu-cha-gu-ji-ji-ben-si-xiang": {"anchor":"|S−Sₙ|≤uₙ₊₁","caption":"莱布尼茨级数取前 n 项近似和时，误差不超过被舍弃的第一项：|S−Sₙ|≤uₙ₊₁；这正是交错级数「好估计」的原因，也是定精度求项数的依据。","keyPoints":["|rₙ|≤uₙ₊₁（舍去项的首项）","由精度反解需要的项数 n","只对莱布尼茨型级数成立"],"example":"Σ(−1)ⁿ⁻¹/n 取 n=10：误差 ≤1/11<0.1。"},
  "kp-m1-p1-c8-jue-dui-shou-lian": {"anchor":"Σ|uₙ| 收敛 ⇒ Σuₙ 绝对收敛","caption":"若 Σ|uₙ| 收敛，则称 Σuₙ 绝对收敛；绝对收敛是更强的收敛——它同时说明「正项化后也收敛」，正项级数的全部判别法因此都能用上。","keyPoints":["Σ|uₙ| 收敛 ⇒ 绝对收敛","绝对收敛必收敛（蕴含定理）","判绝对收敛：对 |uₙ| 用正项级数方法"],"example":"Σ(−1)ⁿ/n²：Σ1/n² 收敛，故绝对收敛。"},
  "kp-m1-p1-c8-tiao-jian-shou-lian": {"anchor":"Σuₙ 收敛 且 Σ|uₙ| 发散 ⇔ 条件收敛","caption":"Σuₙ 收敛而 Σ|uₙ| 发散，称为条件收敛；典型代表是 Σ(−1)ⁿ⁻¹/n——莱布尼茨保证收敛，调和级数说明不绝对，它的和依赖项的排列顺序。","keyPoints":["条件收敛 = 收敛 + 不绝对收敛","典型：Σ(−1)ⁿ⁻¹/n","条件收敛级数重排可改变和"],"example":"Σ(−1)ⁿ⁻¹/n 条件收敛；Σ(−1)ⁿ⁻¹/n² 绝对收敛。"},
  "kp-m1-p1-c8-jue-dui-shou-lian-yun-han-shou-lian": {"anchor":"绝对收敛 ⇒ 收敛（反之不然）","caption":"定理：若 Σ|uₙ| 收敛，则 Σuₙ 必收敛；思路来自 |uₙ|=uₙ⁺+uₙ⁻（正部加负部取正号），两个正项级数都收敛即可推得。","keyPoints":["Σ|uₙ| 收敛 ⇒ Σuₙ 收敛","反向不成立（条件收敛存在）","任意项级数第一步先判绝对"],"example":"Σsin(n)/n²：|sin n|/n²≤1/n² 收敛，绝对收敛故收敛。"},
  "kp-m1-p1-c8-shou-lian-ban-jing": {"anchor":"R=1/ρ","caption":"幂级数 Σaₙxⁿ 的系数满足 lim|aₙ₊₁/aₙ|=ρ 时，收敛半径 R=1/ρ（ρ=0 时 R=+∞","keyPoints":["R=1/ρ，ρ=lim|aₙ₊₁/aₙ|","ρ=0 ⇒ R=∞（处处收敛）","ρ=∞ ⇒ R=0（只在 x=0 收敛）"],"example":"Σxⁿ/n!：ρ=lim 1/(n+1)=0，R=∞，处处收敛。"},
  "kp-m1-p1-c8-shou-lian-qu-jian": {"anchor":"收敛区间 (−R, R)","caption":"幂级数的收敛区间指 (−R, R)：区间内绝对收敛，区间外发散；「收敛域」则还要把端点 x=±R 的收敛情况并入——区间是开的，域可能闭。","keyPoints":["收敛区间 = (−R, R)，不含端点","收敛域 = 区间 + 判定的端点","题目问「域」必须验端点"],"example":"Σxⁿ/n：R=1，区间 (−1,1)；端点 x=−1 收敛、x=1 发散，域为 [−1,1)。"},
  "kp-m1-p1-c8-duan-dian-dan-du-pan-duan": {"anchor":"x=±R：逐点代入判别","caption":"x=±R 处幂级数退化为数项级数，收敛性要单独判别（常交错判别、p 级数比较）；同一级数两个端点可以一收一发，收敛域因此有开有闭。","keyPoints":["端点代入后是数项级数问题，逐个判敛","x=R 与 x=−R 分别判","端点收敛时收敛域写成闭端，区间仍开"],"example":"Σxⁿ/n² 在 ±1 都是 Σ(±1)ⁿ/n²，绝对收敛，域 [−1,1]。"},
  "kp-m1-p1-c8-he-han-shu": {"anchor":"S(x)=Σaₙxⁿ，x∈收敛域","caption":"幂级数在收敛域内逐点求和得到函数 S(x)=Σaₙxⁿ，叫和函数；求和函数就是把级数往几何级数或已知展开式上凑，定义域恰是收敛域。","keyPoints":["S(x)=limₙ Sₙ(x)，定义域=收敛域","求法：逐项求导/积分化成几何级数","S′ 与 ∫S 都在区间内逐项进行"],"example":"Σn xⁿ⁻¹ 是 Σxⁿ 逐项求导的结果，和函数 S(x)=1/(1−x)²（|x|<1）。"},
  "kp-m1-p1-c8-zhu-xiang-qiu-dao": {"anchor":"S′(x)=Σₙ₌₁^∞ n aₙxⁿ⁻¹","caption":"幂级数在收敛区间内可逐项求导：S′(x)=Σn aₙxⁿ⁻¹，收敛半径不变；端点的收敛性可能改变（范围可能缩小），所以逐项操作后要重验端点。","keyPoints":["区间内：S′=Σn aₙxⁿ⁻¹","求导不改变收敛半径 R","端点收敛性要重新判断"],"example":"Σxⁿ=1/(1−x) 求导：Σn xⁿ⁻¹=1/(1−x)²，半径仍 1。"},
  "kp-m1-p1-c8-zhu-xiang-ji-fen": {"anchor":"∫₀ˣ S(t)dt=Σ aₙxⁿ⁺¹/(n+1)","caption":"幂级数在收敛区间内可逐项积分：∫₀ˣS(t)dt=Σ aₙxⁿ⁺¹/(n+1)，收敛半径不变；积分只会让通项变小，端点反而可能由发散变收敛。","keyPoints":["∫₀ˣS=Σ aₙxⁿ⁺¹/(n+1)","逐项积分不改变收敛半径，端点可能变好","端点可能变得更好（发散→收敛）"],"example":"Σxⁿ 积分：Σxⁿ⁺¹/(n+1)=−ln(1−x)（|x|<1，x=−1 也成立）。"},
  "kp-m1-p1-c8-1-1-x": {"anchor":"1/(1−x)=Σₙ₌₀^∞ xⁿ（|x|<1）","caption":"1/(1−x)=Σₙ₌₀^∞ xⁿ（|x|<1）是最基本的函数展开：它就是首项 1、公比 x 的几何级数；其余多数和函数问题最终都往这个形式上凑。","keyPoints":["1/(1−x)=1+x+x²+…（|x|<1）","收敛半径 R=1，端点 x=±1 都发散","逐项求导/积分可生成新和函数"],"example":"x=1/2 时 Σ(1/2)ⁿ=1/(1−1/2)=2。"},
  "kp-m1-p1-c8-e-x": {"anchor":"eˣ=Σₙ₌₀^∞ xⁿ/n!","caption":"eˣ=Σₙ₌₀^∞ xⁿ/n!","keyPoints":["eˣ=Σ xⁿ/n!（−∞<x<∞）","收敛半径 R=∞（比值法得 0）","代 x=1 得 e=Σ1/n!（数 e 的级数定义）"],"example":"e^{−x}=Σ(−1)ⁿxⁿ/n! 对一切 x 成立。"},
  "kp-m1-p1-c8-sin-x": {"anchor":"sin x=x−x³/3!+x⁵/5!−…","caption":"sin x=Σₙ₌₀^∞ (−1)ⁿ x^{2n+1}/(2n+1)!","keyPoints":["sin x=Σ(−1)ⁿx^{2n+1}/(2n+1)!","sin x 的 R=∞，展开只含奇次幂","逐项求导得 cos x 的展开"],"example":"sin x 的前三项：x−x³/6+x⁵/120。"},
  "kp-m1-p1-c8-cos-x": {"anchor":"cos x=1−x²/2!+x⁴/4!−…","caption":"cos x=Σₙ₌₀^∞ (−1)ⁿ x^{2n}/(2n)!","keyPoints":["cos x=Σ(−1)ⁿx^{2n}/(2n)!","cos x 的 R=∞，展开只含偶次幂","逐项求导得 −sin x"],"example":"lim_{x→0}(1−cos x)/x² 用展开：1−cos x∼x²/2，极限 1/2。"},
  "kp-m1-p1-c8-ln-1-x": {"anchor":"ln(1+x)=x−x²/2+x³/3−…（−1<x≤1）","caption":"ln(1+x)=Σₙ₌₁^∞ (−1)ⁿ⁻¹xⁿ/n，由 1/(1+t) 的几何级数逐项积分而来；","keyPoints":["ln(1+x)=Σ(−1)ⁿ⁻¹xⁿ/n","收敛域 (−1,1]","代 x=1 得 ln2=Σ(−1)ⁿ⁻¹/n"],"example":"ln2 的级数：1−1/2+1/3−1/4+…。"},
  "kp-m1-p1-c8-1-x": {"anchor":"(1+x)^α=1+αx+α(α−1)x²/2!+…（|x|<1）","caption":"(1+x)^α=1+Σₙ₌₁^∞ α(α−1)…(α−n+1)/n!","keyPoints":["系数是「降阶乘」除 n!","R=1（除非 α 为非负整数）","α=−1 时退化为几何级数 1/(1+x)"],"example":"α=1/2：√(1+x)=1+x/2−x²/8+x³/16−…（|x|<1）。"},
  "kp-m1-p1-c8-zhou-qi-han-shu": {"anchor":"f(x+T)=f(x)","caption":"若 f(x+T)=f(x) 对一切 x 成立（T>0 最小者叫最小正周期），则 f 是周期函数；","keyPoints":["f(x+T)=f(x) 是定义式","周期函数积分一个周期即可代表全体","非周期函数可通过周期延拓展开"],"example":"sin x、cos x 以 2π 为周期；方波以 2l 为周期。"},
  "kp-m1-p1-c8-fu-li-ye-xi-shu": {"anchor":"aₙ=(1/π)∫_{−π}^{π}f cos nx dx，bₙ=(1/π)∫_{−π}^{π}f sin nx dx","caption":"以 2π 为周期的函数的傅里叶系数：aₙ=(1/π)∫_{−π}^{π}f(x)cos nx dx","keyPoints":["aₙ 配 cos、bₙ 配 sin，积分一周期","正交性：不同频率乘积积分为 0","系数唯一由 f 决定"],"example":"f(x)=x（−π<x≤π）：aₙ=0（奇函数），bₙ=2(−1)ⁿ⁺¹/n。"},
  "kp-m1-p1-c8-zheng-xian-yu-xian-zhan-kai": {"anchor":"奇：f=Σbₙ sin nx；偶：f=a₀/2+Σaₙ cos nx","caption":"奇函数的傅里叶级数只含正弦项（bₙ，正弦级数），偶函数只含余弦项与常数项（aₙ，余弦级数）；","keyPoints":["奇函数 ⇒ 只有 bₙ（正弦展开）","偶函数 ⇒ 只有 aₙ（余弦展开）","半区间函数靠奇/偶延拓二选一"],"example":"f=x（0<x<π）奇延拓得正弦级数 2Σ(−1)ⁿ⁺¹sin nx/n。"},
  "kp-m1-p1-c8-di-li-ke-lei-shou-lian-ding-li-de-shi-1wptws": {"anchor":"S(x₀)=[f(x₀⁻)+f(x₀⁺)]/2（间断点）","caption":"狄利克雷定理：f 满足收敛定理条件时，傅里叶级数在连续点收敛于 f(x)","keyPoints":["连续点：和 = f(x₀)","间断点：和 = 左右极限的平均","端点/延拓点按延拓后的间断算"],"example":"方波在跳变点处的级数和 = 跳变两侧值的平均。"},
  "kp-m1-p1-c8-ji-shu-yi-xiang-xiang-die-jia-xian-shi-1m2lye": {"anchor":"Sₙ=Σᵢ₌₁ⁿuᵢ，S=lim Sₙ","caption":"把级数的前 n 项和 Sₙ 看成逐次叠加：每加一项，Sₙ 向总和逼近一步；观察 {Sₙ} 是否稳定，是「收敛/发散」最直观的动态图像。","keyPoints":["S₁, S₂, …, Sₙ 是逐步叠加的过程","稳定在某个值附近 ⇒ 收敛","无界或来回大幅振荡 ⇒ 发散"],"example":"Σ1/n² 的部分和迅速稳定在 π²/6 附近。"},
  "kp-m1-p1-c8-fu-li-ye-zhu-jian-zeng-jia-xie-bo-shu-1rmai0": {"anchor":"f≈a₀/2+Σₙ₌₁ᴺ(aₙcos nx+bₙsin nx)","caption":"傅里叶级数把周期函数分解成频率倍增的正弦波（谐波）之和：取的项数越多，叠加曲线与目标函数贴合得越好；在间断点附近会看到「过冲」但整体收敛。","keyPoints":["每项是一个谐波（频率 n 倍）","项数增加 ⇒ 逼近更好","间断点收敛到左右极限平均"],"example":"方波只用奇次正弦谐波叠加：项数越多棱角越清晰。"},
  "kp-m1-p1-c9-wei-fen-fang-cheng": {"anchor":"y′=f(x,y) 或 F(x,y,y′,…,y⁽ⁿ⁾)=0","caption":"微分方程是联系自变量、未知函数及其导数的方程，未知函数是一元函数时叫常微分方程；方程里出现导数，解它就是求函数而不是求数。","keyPoints":["方程必须含未知函数的导数，否则只是普通方程","未知函数是一元的叫常微分方程（本册范围）","解微分方程 = 由含导数的关系式求出未知函数"],"example":"y′=2x 是最简单的微分方程，解为 y=x²+C。"},
  "kp-m1-p1-c9-jie": {"anchor":"y″+2y′+y=0 是二阶方程","caption":"微分方程的阶就是方程中出现的最高阶导数的阶数；n 阶方程的通解里应含 n 个独立的任意常数，阶数与常数个数要对上。","keyPoints":["看最高阶导数定阶，不是看项数或次数","y⁽ⁿ⁾ 出现即至少 n 阶","n 阶方程通解含 n 个独立常数"],"example":"y⁽³⁾+(y″)⁴=y′ 是三阶方程——虽然 y″ 有四次方，阶只看导数的最高阶数。"},
  "kp-m1-p1-c9-jie-2": {"anchor":"把 y=φ(x) 代入，要求 F≡0","caption":"微分方程的解是代入方程后两端恒等的函数；解可以显式写成 y=f(x)，也可以由隐式方程 Φ(x,y)=0 确定，两者都算解。","keyPoints":["验证解：求导代入，要求两端恒等","显式解 y=f(x) 与隐式解 Φ(x,y)=0 都可以","解是函数，不是一个数"],"example":"y=e²ˣ 是 y″−4y=0 的解：4e²ˣ−4e²ˣ=0。"},
  "kp-m1-p1-c9-tong-jie": {"anchor":"二阶通解形如 y=C₁y₁(x)+C₂y₂(x)","caption":"n 阶微分方程的通解是含 n 个相互独立任意常数的解；「独立」指常数不能合并。","keyPoints":["通解含 n 个独立任意常数（n=方程阶数）","常数独立：合并后只剩一个就不算","通解未必是全部解（可能漏奇解）"],"example":"y″+y=0 的通解 y=C₁cos x+C₂sin x 恰含 2 个独立常数。"},
  "kp-m1-p1-c9-te-jie": {"anchor":"由 y(x₀)=y₀ 定 C","caption":"特解是不含任意常数的解，通常由初始条件把通解中的常数确定后得到；题目问「满足某条件的解」就是要找特解。","keyPoints":["特解不含任意常数，由初始条件定下来","由初始条件定出通解的常数","几何上是从通解曲线族中选出一条"],"example":"通解 y=Ceˣ 加条件 y(0)=3 得特解 y=3eˣ。"},
  "kp-m1-p1-c9-chu-shi-tiao-jian": {"anchor":"y(x₀)=y₀，y′(x₀)=y₁，…","caption":"初始条件是在某一点处给出的函数值与各阶导数值，如 y(x₀)=y₀、y′(x₀)=y₁；n 阶方程需要 n 个条件才能确定通解中的 n 个常数。","keyPoints":["n 阶方程配 n 个初始条件","条件都给在同一点 x₀ 处","一阶给函数值，二阶再加导数值"],"example":"y″+y=0 配 y(0)=1、y′(0)=0 得特解 y=cos x。"},
  "kp-m1-p1-c9-chu-zhi-wen-ti": {"anchor":"y′=f(x,y)，y(x₀)=y₀","caption":"初值问题由微分方程和初始条件一起构成，求的是满足条件的特解；考试里的应用题几乎都是初值问题：先列方程，再给条件定常数。","keyPoints":["初值问题 = 方程 + 初始条件","目标是特解，不是通解","步骤：解通解 → 定常数 → 写特解"],"example":"y′=y，y(0)=2 ⇒ y=2eˣ。"},
  "kp-m1-p1-c9-ke-fen-li-bian-liang-fang-cheng": {"anchor":"dy/dx=f(x)g(y) ⇒ ∫dy/g(y)=∫f(x)dx+C","caption":"可分离变量方程能整理成 dy/dx=f(x)g(y) 的形状，把 y 全移一边、x 全移另一边后直接两边积分；这是最基础的一阶解法，别的类型常化成它。","keyPoints":["标准形 dy/dx=f(x)g(y)","分离成 dy/g(y)=f(x)dx 后两边积分","通解可能是隐式（积不出来 y 显式也算对）"],"example":"dy/dx=2xy ⇒ dy/y=2x dx ⇒ ln|y|=x²+C，即 y=Ce^{x²}。"},
  "kp-m1-p1-c9-qi-ci-wei-fen-fang-cheng": {"anchor":"dy/dx=φ(y/x)，令 y=ux","caption":"齐次微分方程指能写成 dy/dx=φ(y/x) 的方程（右端只依赖比值 y/x），令 u=y/x 就化成可分离变量方程；","keyPoints":["齐次型方程的标志：右端只含 y/x","令 u=y/x 化为可分离变量","与齐次线性（y′+Py=0）是两个概念"],"example":"y′=y/x+1 是齐次型（右端 =1+u）；y′+y=0 是齐次线性——两个「齐次」别混。"},
  "kp-m1-p1-c9-yi-jie-xian-xing-wei-fen-fang-cheng": {"anchor":"y′+P(x)y=Q(x)","caption":"一阶线性微分方程关于未知函数及其导数都是一次的，标准形为 y′+P(x)y=Q(x)；Q≡0 时叫齐次线性（可分离变量解），否则用通解公式。","keyPoints":["标准形 y′+P(x)y=Q(x)","线性指 y 与 y′ 都是一次且不作乘积","Q≡0 齐次线性；否则非齐次"],"example":"y′+y=x 是线性非齐次；y′+y²=x 关于 y 是二次，不是线性。"},
  "kp-m1-p1-c9-bo-nu-li-fang-cheng-zuo-wei-li-jie-kuo-1vbqd7": {"anchor":"z′+(1−n)P(x)z=(1−n)Q(x)","caption":"伯努利方程 y′+P(x)y=Q(x)yⁿ（n≠0,1）是带其他幂次的方程，令 z=y^{1−n} 就化成一阶线性方程；","keyPoints":["标准形 y′+P(x)y=Q(x)yⁿ，n≠0,1","令 z=y^{1−n} 化为线性方程","解出 z 后回代 y=z^{1/(1−n)}"],"example":"y′−y=xy² 令 z=y^{1−2}=1/y，化成 z′+z=−x。"},
  "kp-m1-p1-c9-y-f-x": {"anchor":"y″=f(x) ⇒ y=∫(∫f dx)dx+C₁x+C₂","caption":"y″=f(x) 直接积分两次，每积一次出一个常数；这是可降阶方程里最简单的一类，也是「积分一次降一阶」思想的原型。","keyPoints":["第一次积分得 y′=∫f(x)dx+C₁","第二次积分得 y=∫(∫f dx)dx+C₁x+C₂","两个初始条件分别定 C₁、C₂"],"example":"y″=6x ⇒ y′=3x²+C₁ ⇒ y=x³+C₁x+C₂。"},
  "kp-m1-p1-c9-y-f-x-y": {"anchor":"p′=f(x,p)，y=∫p dx+C","caption":"方程不含 y 时（y″=f(x,y′)），令 p=y′ 把它降为关于 p 的一阶方程 p′=f(x,p)","keyPoints":["缺 y ⇒ 令 p=y′，此时 y″=p′","先解一阶方程 p′=f(x,p)","再积 p=dy/dx 得 y"],"example":"xy″+y′=0 令 p=y′：xp′+p=0 ⇒ p=C₁/x ⇒ y=C₁ ln|x|+C₂。"},
  "kp-m1-p1-c9-y-f-y-y": {"anchor":"y″=p·dp/dy（链式法则）","caption":"方程不含 x 时（y″=f(y,y′)），令 p=y′ 并用链式法则把 y″ 写成 p·dp/dy","keyPoints":["缺 x ⇒ 令 p=y′，且 y″=p·dp/dy","先解 p 关于 y 的一阶方程","再解 dy/dx=p(y)（可分离）"],"example":"y″=2yy′ 令 p=y′：p dp/dy=2yp ⇒ p=y²+C₁，再解 dy/dx=y²+C₁。"},
  "kp-m1-p1-c9-xian-xing-wei-fen-fang-cheng-jie-de-0wfpub": {"anchor":"L[y₁+y₂]=L[y₁]+L[y₂]，L[Cy]=CL[y]","caption":"线性齐次方程的解乘常数、相加后仍是解；非齐次方程的两个特解之差是对应齐次方程的解","keyPoints":["齐次解的线性组合仍是齐次解","非齐次两特解之差是齐次解","特解按右端叠加：y₁*+y₂* 对应 f₁+f₂"],"example":"y₁*、y₂* 分别是 y″+y=x 与 y″+y=eˣ 的特解，则 y₁*+y₂* 是 y″+y=x+eˣ 的特解。"},
  "kp-m1-p1-c9-qi-ci-fang-cheng-jie-de-jie-gou": {"anchor":"y=C₁y₁+C₂y₂，y₁/y₂≢常数","caption":"二阶齐次线性方程的两个解 y₁、y₂ 若线性无关（之比不是常数），通解就是它们的线性组合 C₁y₁+C₂y₂；「线性无关」保证两个常数真正独立。","keyPoints":["通解 = C₁y₁+C₂y₂（y₁、y₂ 线性无关）","线性无关 ⇔ y₁/y₂ 不恒为常数","两个相关解拼不成通解"],"example":"y″+y=0 有 y₁=cos x、y₂=sin x，之比 tan x 不是常数，通解 C₁cos x+C₂sin x。"},
  "kp-m1-p1-c9-fei-qi-ci-fang-cheng-jie-de-jie-gou": {"anchor":"y=C₁y₁+C₂y₂+y*","caption":"二阶非齐次线性方程的通解 = 对应齐次方程的通解 + 非齐次方程的任意一个特解；特解选哪一个都行，选不同特解的结果只差一个齐次解。","keyPoints":["y = C₁y₁+C₂y₂ + y*","y* 是任取的一个特解","解题顺序：先齐次，再凑特解"],"example":"y″+y=x²：齐次通解 C₁cos x+C₂sin x，特解 y*=x²−2，相加即通解。"},
  "kp-m1-p1-c9-te-zheng-fang-cheng": {"anchor":"r²+pr+q=0，r=(−p±√(p²−4q))/2","caption":"对常系数齐次方程 y″+py′+qy=0 试指数解 y=e^{rx}，约去 e^{rx} 得代数方程 r²+pr+q=0","keyPoints":["试 y=e^{rx}，约去 e^{rx} 得特征方程","特征方程 r²+pr+q=0","根的三种情况对应三种解形"],"example":"y″−5y′+6y=0 的特征方程 r²−5r+6=0，根 r=2、3。"},
  "kp-m1-p1-c9-liang-ge-bu-tong-shi-gen": {"anchor":"p²−4q>0 ⇒ y=C₁e^{r₁x}+C₂e^{r₂x}","caption":"特征方程有两个不同实根 r₁≠r₂ 时，齐次通解为 y=C₁e^{r₁x}+C₂e^{r₂x}；两个指数函数之比不是常数，天然线性无关。","keyPoints":["y=C₁e^{r₁x}+C₂e^{r₂x}","判别式 p²−4q>0 时发生","两解之比 e^{(r₁−r₂)x} 非常数，无关"],"example":"r=2、3 ⇒ y=C₁e²ˣ+C₂e³ˣ。"},
  "kp-m1-p1-c9-er-chong-shi-gen": {"anchor":"p²−4q=0 ⇒ y=(C₁+C₂x)e^{rx}","caption":"特征方程二重根 r₁=r₂=r 时只出一个指数解，需补上 xe^{rx} 才凑齐两个线性无关解，通解为 y=(C₁+C₂x)e^{rx}。","keyPoints":["y=(C₁+C₂x)e^{rx}","xe^{rx} 与 e^{rx} 之比是 x，无关","判别式 p²−4q=0 的信号"],"example":"y″−4y′+4y=0 特征方程 (r−2)²=0，r=2 二重，y=(C₁+C₂x)e²ˣ。"},
  "kp-m1-p1-c9-gong-e-fu-gen": {"anchor":"r=α±βi ⇒ y=e^{αx}(C₁cos βx+C₂sin βx)","caption":"特征根为共轭复数 α±βi 时，齐次通解写成实形式 y=e^{αx}(C₁cos βx+C₂sin βx)；","keyPoints":["y=e^{αx}(C₁cos βx+C₂sin βx)","β 是振荡角频率，α 是衰减率","判别式 p²−4q<0 时发生"],"example":"y″+4y=0：r=±2i，α=0、β=2，y=C₁cos 2x+C₂sin 2x。"},
  "kp-m1-p1-c9-mou-xie-gao-yu-er-jie-chang-xi-shu-qi-1vwko2": {"anchor":"k 重根 r ⇒ e^{rx}, xe^{rx}, …, x^{k−1}e^{rx}","caption":"三阶及以上的常系数齐次方程同样令 y=e^{rx} 得特征方程；","keyPoints":["特征方程是 r 的 n 次代数方程","k 重根给 e^{rx}, xe^{rx}, …, x^{k−1}e^{rx}","全部线性无关解个数 = 方程阶数"],"example":"y⁽³⁾−y′=0 特征方程 r³−r=0，根 0、1、−1，通解 C₁+C₂eˣ+C₃e^{−x}。"},
  "kp-m1-p1-c9-duo-xiang-shi": {"anchor":"y*=x^k(aₘxᵐ+…+a₀)","caption":"右端是多项式 Pₘ(x) 时，设特解 y*=x^kQₘ(x)：Qₘ 是同次待定多项式，k 按「0 是不是特征根、是单根还是重根」取 0、1、2。","keyPoints":["y*=x^kQₘ(x)，Qₘ 与 Pₘ 同次","0 非特征根 k=0；单根 k=1；重根 k=2","代入比较系数定出 Qₘ"],"example":"y″−2y′=x²：0 是单特征根，设 y*=x(ax²+bx+c)。"},
  "kp-m1-p1-c9-zhi-shu-han-shu": {"anchor":"y*=x^k e^{λx}(aₘxᵐ+…+a₀)","caption":"右端为 e^{λx}Pₘ(x) 时设特解 y*=x^ke^{λx}Qₘ(x)","keyPoints":["y*=x^k e^{λx}Qₘ(x)","k=λ 的特征根重数：非根 0、单根 1、二重根 2","Qₘ 仍是同次待定多项式"],"example":"y″−y=eˣ：λ=1 是单特征根，设 y*=axeˣ，代回解得 a=1/2。"},
  "kp-m1-p1-c9-zheng-xian-yu-xian": {"anchor":"y*=x^k(M cos ωx+N sin ωx)","caption":"右端为 A cos ωx+B sin ωx（包括只有其中一项）时，特解必须同时设成 M cos ωx+N sin ωx ","keyPoints":["y*=x^k(M cos ωx+N sin ωx)，两项都设","只出现 cos 也必须带 sin 项","k=±ωi 是特征根时取 1，否则取 0"],"example":"y″+y=sin x：i 是单特征根，设 y*=x(M cos x+N sin x)。"},
  "kp-m1-p1-c9-shang-shu-han-shu-de-he-yu-ji": {"anchor":"y*=y₁*+y₂*（和的情形）","caption":"右端是几种类型之和时，按叠加原理分别设特解再相加；右端是乘积（如 x eˣ、x²sin x）时","keyPoints":["和：f₁+f₂ 的特解 = 各自特解之和","积：按乘积的整体形状设待定式","各部分自己的 x^k 修正照常生效"],"example":"y″+y=x+sin x：设 y*=(ax²+bx+c)+x(M cos x+N sin x) 两部分相加。"},
  "kp-m1-p1-c9-bian-hua-l-mo-xing": {"anchor":"dy/dt=k y（比例型最常见）","caption":"应用题里「变化率与某量成正比」「随某量而变」都翻译成 dy/dt 的表达式，先列微分方程再求解；建模的关键是把文字条件逐句翻译成导数关系。","keyPoints":["「变化率」= dy/dt（或 dx/dt）","「正比于 k」写成 =k·(那个量)","列完方程用初始条件定常数"],"example":"温度变化率正比于温差：dT/dt=−k(T−T₀)，解得 T=T₀+Ce^{−kt}。"},
  "kp-m1-p1-c9-yun-dong": {"anchor":"m x″=F(t,x,x′)","caption":"直线运动用 a=x″(t) 表示加速度，牛顿第二定律给出 mx″=F(t,x,x′)；","keyPoints":["a=x″，把 F 写成 t、x、x′ 的函数","mx″=F 是二阶方程（或先对 v=x′ 解一阶）","初始位置与初速度就是初始条件"],"example":"只受阻力 −kv：mv′=−kv ⇒ v=v₀e^{−kt/m}，速度按指数衰减。"},
  "kp-m1-p1-c9-zeng-zhang-shuai-jian": {"anchor":"N(t)=N₀e^{λt}","caption":"增长率与当前量成正比时 dN/dt=λN，解为 N=N₀e^{λt}：λ>0 指数增长、λ<0 指数衰减；人口增长、放射衰变、复利都是这一族模型。","keyPoints":["方程 dN/dt=λN，解 N=N₀e^{λt}","λ 的符号决定增长还是衰减","衰减情形半衰期 t=ln2/|λ|"],"example":"放射衰变 λ=−ln2/30 时，物质质量每 30 天减半。"},
  "kp-m1-p1-c9-ji-he-ying-yong": {"anchor":"切线：y−y₀=y′(x₀)(x−x₀)","caption":"几何应用题把曲线的切线、法线、弧长、面积等条件翻译成 y′（或 y″）满足的方程，解方程即得曲线；常用关系有切线截距、法线长、曲率等。","keyPoints":["切线斜率就是 y′，先写切线方程","几何条件翻译成含 y′（或 y″）的等式","解方程并保留几何上有意义的解"],"example":"切线在 y 轴的截距等于该点横坐标 ⇒ 由 y₀−x₀y′=x₀ 列方程求 y。"},
  "kp-m1-p1-c9-fang-xiang-chang-zhan-shi-bu-tong-chu-02v4i4": {"anchor":"dy/dx=f(x,y) 在 (x,y) 处画斜率 f(x,y)","caption":"方向场在平面上每一点画出以该点斜率 f(x,y) 为方向的小线段；从任一初始点出发顺着小线段延伸就得到解曲线——不解方程也能看出解的走势。","keyPoints":["每点小线段的斜率 = f(x,y)","解曲线处处与方向场的线段相切","不同初始点对应不同解曲线"],"example":"dy/dx=y 的方向场在 y 越高处线段越陡，解曲线 y=Ceˣ 恰好顺着它延伸。"},
  "kp-m1-p1-c9-er-jie-fang-cheng-yong-tan-huang-zu-ni-11vl4d": {"anchor":"mx″+cx′+kx=0，根 α±βi 时振荡","caption":"弹簧振子 mx″+cx′+kx=0 是二阶常系数方程的物理原型：两实根对应过阻尼不振动，重根是临界阻尼","keyPoints":["过阻尼（两实根）：缓慢回到平衡，不振荡","临界阻尼（重根）：最快回到平衡且不越过","欠阻尼（复根）：e^{αt} 包络下的衰减振动"],"example":"x″+2x′+5x=0 根 −1±2i：欠阻尼，解 x=e^{−t}(C₁cos 2t+C₂sin 2t) 衰减振动。"},
  "kp-m1-p2-c1-er-jie-san-jie-n-jie-hang-lie-shi": {"anchor":"|a b; c d|=ad−bc","caption":"二阶行列式是交叉相减，三阶按对角线法则或展开，n 阶用递归的展开定义；行列式最终是一个数，几何上二阶行列式的绝对值是平行四边形面积。","keyPoints":["二阶：ad−bc（主对角线减副对角线）","n 阶：按某行（列）展开的递归定义","|行列式的绝对值| = 对应平行四边形（体）的面积"],"example":"|1 2; 3 4|=4−6=−2，绝对值 2 是向量 (1,3)、(2,4) 张成的平行四边形面积。"},
  "kp-m1-p2-c1-pai-lie-yu-ni-xu-shu": {"anchor":"τ(3 1 2)=2（3 压 1、3 压 2）","caption":"逆序数 τ 是排列中「大数排在小数前面」的对数：逐个数每个数字前面比它大的数字个数再相加；逆序数的奇偶性决定排列的奇偶性。","keyPoints":["逆序：大数在前、小数在后的一对","τ(排列)=逆序总个数","τ 为奇 → 奇排列，为偶 → 偶排列"],"example":"排列 3 1 4 2：3 压 1、2 共 2 个，4 压 2 共 1 个，τ=3（奇排列）。"},
  "kp-m1-p2-c1-hang-lie-shi-zhan-kai-ding-yi-de-ji-ben-0r1i4g": {"anchor":"D=Σⱼ(−1)^{1+j}a₁ⱼM₁ⱼ","caption":"n 阶行列式的展开定义：取第一行各元素乘以划去该元素所在行列后的 n−1 阶行列式","keyPoints":["定义即「按第一行展开」的递归","符号由行标、列标排列的奇偶决定","思想：高阶化低阶，直到二、三阶"],"example":"三阶行列式按第一行展开成三个二阶行列式的组合。"},
  "kp-m1-p2-c1-zhuan-zhi-hou-zhi-bu-bian": {"anchor":"|Aᵀ|=|A|","caption":"行列式转置后值不变：D=Dᵀ；因此行列式「对行成立的性质对列全部自动成立」，记住了这一条，行、列两套话术只需记一套。","keyPoints":["对称矩阵的定义式 Dᵀ=D，元素关于对角线镜像","行的性质 ⇔ 列的性质","转置不改变行列式的值"],"example":"「两列相同行列式为 0」由「两行相同为 0」转置即得。"},
  "kp-m1-p2-c1-jiao-huan-liang-hang-lie-bian-hao": {"anchor":"rᵢ↔rⱼ ⇒ D′=−D","caption":"行列式交换任意两行（列）后变号：rᵢ↔rⱼ 乘 (−1)；连换两次不变号，这也解释了「两行相同则行列式为 0」。","keyPoints":["行列式一次行交换乘 −1，符号要记账","偶数次交换不变号，符号只看交换次数奇偶","两行相同：交换后 D=−D ⇒ D=0"],"example":"|1 2; 3 4| 交换两行得 |3 4; 1 2|=2=−(−2)。"},
  "kp-m1-p2-c1-mou-xing-lie-you-gong-yin-zi-ke-ti-chu": {"anchor":"|…kaᵢ…|=k|…aᵢ…|","caption":"行列式某一行（列）的公因子 k 可提到行列式外：|…ka…|=k|…|；注意这区别于矩阵数乘——数乘 k 阶矩阵提出的是 kⁿ。","keyPoints":["一行提出 k（不是 kⁿ）","整矩阵数乘提 kⁿ（n=阶数）","常用于提出 −1 或分数化整"],"example":"三阶行列式每行都提 2，共提出 2³=8——那是逐行各提一次。"},
  "kp-m1-p2-c1-liang-hang-lie-xiang-tong-huo-cheng-bi-10bb5d": {"anchor":"rᵢ=krⱼ ⇒ D=0","caption":"行列式两行（列）相同或对应成比例时行列式为 0；判断题里「看一眼成比例」往往直接出结论，省掉全部计算。","keyPoints":["两行相同 ⇒ D=0","两行成比例 ⇒ D=0","依据：交换变号 + 提公因子"],"example":"|1 2 3; 2 4 6; 1 0 1| 的前两行成比例（1:2），行列式为 0。"},
  "kp-m1-p2-c1-yi-hang-lie-de-bei-shu-jia-dao-ling-yi-1ofvvo": {"anchor":"rᵢ→rᵢ+krⱼ，D 不变","caption":"把某行的 k 倍加到另一行，行列式值不变——这是化三角形、化零展开的核心操作，也是初等行变换中唯一「免费」的一种。","keyPoints":["rᵢ+krⱼ：值不变","变换大法：造零、造阶梯","交换要变号、倍加不变号"],"example":"用 r₂→r₂−3r₁ 把 (3,4) 位置消成 0，行列式值不变。"},
  "kp-m1-p2-c1-hang-lie-shi-dui-mou-xing-lie-de-xian-1m8vqx": {"anchor":"|…(aᵢⱼ+bᵢⱼ)…|=|…aᵢⱼ…|+|…bᵢⱼ…|","caption":"行列式关于某一行（列）是线性的：该行各元素可以拆成两组分别计算再相加；注意「一次只能拆一行」，两行同时拆是错的。","keyPoints":["单行内拆分：|a+b 行| = |a 行|+|b 行|","拆行时其余行保持不变，只拆选定的一行","多行同时拆会指数爆炸且无意义"],"example":"某行为 (1+2, 3+4)：拆成 (1,3) 与 (2,4) 两个行列式相加。"},
  "kp-m1-p2-c1-yu-zi-shi-m-ij": {"anchor":"Mᵢⱼ=(−1 不带) 的余子行列式","caption":"余子式 Mᵢⱼ 是划去第 i 行第 j 列后剩下的 n−1 阶行列式——它是「数」不是「位置」；每个元素都有自己的余子式。","keyPoints":["Mᵢⱼ：划掉 i 行 j 列的余下行列式","阶数比原行列式低一阶","余子式带符号前是「中性」的"],"example":"三阶行列式的 M₁₁ 是右下角 2×2 块构成的行列式。"},
  "kp-m1-p2-c1-dai-shu-yu-zi-shi-a-ij-1-i-j-m-ij": {"anchor":"Aᵢⱼ=(−1)^{i+j}Mᵢⱼ","caption":"代数余子式 Aᵢⱼ=(−1)^{i+j}Mᵢⱼ：在余子式上按「+−+− 棋盘」补符号；i+j 为偶取正、为奇取负——展开定理的系数就是它。","keyPoints":["Aᵢⱼ=(−1)^{i+j}Mᵢⱼ","符号棋盘：左上角从 + 开始","展开求和时用的都是 Aᵢⱼ"],"example":"(2,3) 位置：i+j=5 为奇，A₂₃=−M₂₃。"},
  "kp-m1-p2-c1-la-pu-la-si-zhan-kai": {"anchor":"ΣⱼaᵢⱼAᵢⱼ=D；ΣⱼaₖⱼAᵢⱼ=0（k≠i）","caption":"展开定理：行列式等于任一行（列）各元素与其代数余子式乘积之和——按零最多的行（列）展开，一项都不用多算。","keyPoints":["ΣⱼaᵢⱼAᵢⱼ=D（按 i 行展开）","选零多的行列展开最省力","异行元素乘异行代数余子式之和为 0"],"example":"第一行只有 (2,0,3)：D=2A₁₁+3A₁₃ 两项搞定。"},
  "kp-m1-p2-c1-xuan-ze-ling-jiao-duo-de-xing-lie": {"anchor":"造零用 rᵢ→rᵢ+krⱼ（不变号）","caption":"展开前先看哪行（列）零多：零多意味着展开项数少；必要时先用倍加造零再展开——「造零 + 展开」是手算高阶行列式的标准路线。","keyPoints":["先造零再展开，两个动作配合","某行只有 1 个非零时展开最优","首列化成 (1,0,0,…) 是常见起手"],"example":"四阶行列式先用倍加把第一列化成 (1,0,0,0)，再按列展开降为三阶。"},
  "kp-m1-p2-c1-hua-san-jiao-xing": {"anchor":"D=∏ᵢaᵢᵢ（三角化后）","caption":"用倍加把行列式化成上（下）三角形后，值 = 主对角线元素乘积；这是计算机与手算通用的主流方法，全程只允许「倍加」就不必管符号。","keyPoints":["三角形行列式 = 对角线乘积","化三角形全程只用倍加，行列式值不变","需要交换行时记得变号"],"example":"四阶行列式消成上三角 (1,2,3,4) 对角线：D=24。"},
  "kp-m1-p2-c1-zhan-kai": {"anchor":"D=ΣaᵢⱼAᵢⱼ","caption":"「展开」作为计算方法指：先把某行（列）化出尽量多的零，再按该行（列）展开定理降阶，反复直到二阶——与化三角形殊途同归。","keyPoints":["展开 = 降阶的反复使用","展开时每次选零最多的行列，项数最少","高阶行列式的通用手算路线"],"example":"五阶行列式连续两次展开降到三阶再用对角线法则。"},
  "kp-m1-p2-c1-jia-bian": {"anchor":"典型加边：第一列 1，第一行 0","caption":"加边法：给 n 阶行列式添上一行一列升成 n+1 阶（值不变），新造的边让每行都能用倍加消出统一零——看似升阶，实则大幅化简。","keyPoints":["加边保持值不变（特殊构造）","常用于「对角 + 密度行」型行列式","目标：加边后全行可消成三角"],"example":"对角线上全 aᵢ、其余全 1 的行列式，加边后逐行减第一行化三角。"},
  "kp-m1-p2-c1-di-tui": {"anchor":"Dₙ=(a+b)Dₙ₋₁−abDₙ₋₂（三对角型）","caption":"按第一行（列）展开后，若出现与原行列式同型的 n−1 阶与 n−2 阶行列式，就建立递推公式 Dₙ=…，再逐阶递推（或取特征方程）求解。","keyPoints":["识别「同型子式」是递推的前提","写 Dₙ=aDₙ₋₁+bDₙ₋₂ 型关系","初值 D₁、D₂ 定系数"],"example":"三对角行列式递推 Dₙ=Dₙ₋₁−Dₙ₋₂，得周期 6 的通项。"},
  "kp-m1-p2-c1-chai-fen": {"anchor":"|…aᵢⱼ+bᵢⱼ…|=|…aᵢⱼ…|+|…bᵢⱼ…|","caption":"利用单行线性性质把某个「含和式」的行拆成两个行列式，其中至少一个是简单（如对角、零多）行列式——拆分常与倍加配合使用。","keyPoints":["拆分性质一次只拆一行（列），其余行照抄","拆出一个「好算」的行列式","常用于含 λ、x 的文字行列式"],"example":"含 (x+1) 的行拆成 x 行与 1 行，其中一个行列式两行相同为 0。"},
  "kp-m1-p2-c1-fan-de-meng-de-hang-lie-shi": {"anchor":"D=∏(xⱼ−xᵢ)，i<j","caption":"范德蒙德行列式：n 阶全部由 xᵢ 的幂排成，值等于所有对 (i<j) 的 (xⱼ−xᵢ) 连乘；见到「每行都是某数的幂」就往它身上套。","keyPoints":["D=∏_{1≤i<j≤n}(xⱼ−xᵢ)","底数大的行在后时为正","两数相等 ⇒ 行列式为 0（两行相同）"],"example":"三阶范德蒙德 (1,1,1; x,y,z; x²,y²,z²)=(y−x)(z−x)(z−y)。"},
  "kp-m1-p2-c2-ju-zhen-gai-nian": {"anchor":"A=(aᵢⱼ)ₘₓₙ，Aᵀ 把 aᵢⱼ 放到 (j,i)","caption":"矩阵是 m×n 个数排成的矩形数表，本身是一个「对象」而不是数；它与行列式的本质区别：矩阵是表、行列式是数，转置 ᵀ 把行变列、是矩阵的基本运算。","keyPoints":["m×n 矩阵：m 行 n 列的数表","矩阵与行列式：表 vs 数，别混写","转置 Aᵀ 交换行列位置（转置是矩阵运算的基础）"],"example":"2×3 矩阵转置后是 3×2 矩阵：行变列、列变行。"},
  "kp-m1-p2-c2-ling-ju-zhen": {"anchor":"Aₘₓₙ+Oₘₓₙ=A","caption":"零矩阵 O 是所有元素为 0 的矩阵，尺寸可以任意；它与零数的最大差别：两个非零矩阵相乘可以得到零矩阵——「没有零因子定律」。","keyPoints":["O 的任意元素都是 0","A+O=A（加法单位元）","AB=O ⇏ A=O 或 B=O"],"example":"A=(1 0; 0 0)、B=(0 0; 0 1)：AB=O 但 A、B 都非零。"},
  "kp-m1-p2-c2-dan-wei-ju-zhen": {"anchor":"Eₙ=(δᵢⱼ)，δᵢᵢ=1、其余 0","caption":"单位矩阵 E（I）是主对角线全 1、其余全 0 的方阵：AE=EA=A，是矩阵乘法的单位元；n 阶单位矩阵在一切 n 阶方阵中扮演「1」的角色。","keyPoints":["E 的对角线全 1、其余全 0（方阵）","AE=EA=A（左右乘都一样）","单位矩阵行列式 |E|=1，乘法单位元的值"],"example":"(A+E)²=A²+2A+E（E 与 A 可交换）。"},
  "kp-m1-p2-c2-shu-liang-ju-zhen": {"anchor":"(kE)ₙ 与一切 n 阶方阵交换","caption":"数量矩阵是 kE：对角线全为同一个数 k、其余为 0；它与任何同阶方阵可交换——「数乘矩阵」伪装成矩阵乘法的形式。","keyPoints":["数量矩阵 = kE（对角全 k）","(kE)A=A(kE)=kA（处处可交换）","k=1 时是单位矩阵，k=0 时是零矩阵"],"example":"(2E)A=2A：把数量矩阵当「标量」用。"},
  "kp-m1-p2-c2-dui-jiao-ju-zhen": {"anchor":"diag(a,b)·diag(c,d)=diag(ac,bd)","caption":"对角矩阵是主对角线以外全为 0 的方阵：diag(a₁,…,aₙ)；两个对角矩阵相乘就是各自对角线对应相乘，运算是所有方阵里最简单的。","keyPoints":["diag(a₁,…,aₙ) 只在对角线有元素","对角阵之积：对应对角元素相乘","对角阵之间永远可交换"],"example":"diag(1,2)³=diag(1,8)。"},
  "kp-m1-p2-c2-shang-xia-san-jiao-ju-zhen": {"anchor":"(AB)ᵢᵢ=aᵢᵢbᵢᵢ（三角矩阵）","caption":"上三角矩阵是对角线左下方全 0（下三角反之）；两个同侧三角矩阵相乘仍是同侧三角，且对角线元素等于各自对角元素的乘积。","keyPoints":["上三角：i>j 处 aᵢⱼ=0","上三角 × 上三角 = 上三角","积的对角线 = 对角线对应相乘"],"example":"diag(1,2)、diag(3,4) 都是（特殊的）三角矩阵。"},
  "kp-m1-p2-c2-dui-chen-ju-zhen": {"anchor":"(AB)ᵀ=BᵀAᵀ，对称时 (AB)ᵀ=BA","caption":"对称矩阵满足 Aᵀ=A：元素关于主对角线镜像（aᵢⱼ=aⱼᵢ）；对称矩阵的乘方仍对称、两个对称矩阵的乘积一般不对称（除非可交换）——它是二次型的主角。","keyPoints":["Aᵀ=A ⇔ aᵢⱼ=aⱼᵢ","Aᵏ 仍对称；AB 对称 ⇔ AB=BA","实对称矩阵可正交对角化（后续章）"],"example":"A、B 对称且 AB=BA ⇒ AB 对称；否则 (AB)ᵀ=BA≠AB。"},
  "kp-m1-p2-c2-fan-dui-chen-ju-zhen": {"anchor":"A_s=(A+Aᵀ)/2，A_a=(A−Aᵀ)/2","caption":"反对称矩阵满足 Aᵀ=−A：对角线元素全为 0、aᵢⱼ=−aⱼᵢ；任何方阵都能写成「对称 + 反对称」之和——A=(A+Aᵀ)/2+(A−Aᵀ)/2。","keyPoints":["Aᵀ=−A ⇒ aᵢᵢ=0","aᵢⱼ=−aⱼᵢ（镜像变号）","A = 对称部分 + 反对称部分"],"example":"A=(0 1; −1 0) 是反对称矩阵，对应「旋转 90°」。"},
  "kp-m1-p2-c2-zheng-jiao-ju-zhen": {"anchor":"AᵀA=E ⇒ |A|=±1","caption":"正交矩阵满足 AᵀA=E：列（行）向量组是标准正交组；它的转置就是逆（A⁻¹=Aᵀ），乘积保持长度与内积——是「旋转/反射」类变换的矩阵。","keyPoints":["AᵀA=E ⇔ A⁻¹=Aᵀ","列（行）向量都是单位向量且两两正交","正交变换保持长度：|Ax|=|x|"],"example":"平面旋转矩阵 (cosθ −sinθ; sinθ cosθ) 是正交矩阵。"},
  "kp-m1-p2-c2-jia-jian": {"anchor":"A+B=B+A，(A+B)+C=A+(B+C)","caption":"矩阵加减只在同型矩阵间进行：对应元素相加减；不满足交换律的问题在这里不存在（加法天然交换），关键约束是「同型」。","keyPoints":["A±B 要求同型（同行列数）","(A±B)ᵢⱼ=aᵢⱼ±bᵢⱼ","加法交换、结合律都成立"],"example":"(1 2)+(0 1)=(1 3)（1×2 矩阵）。"},
  "kp-m1-p2-c2-shu-cheng": {"anchor":"(kA)ᵢⱼ=k·aᵢⱼ","caption":"数乘 kA 是把 k 乘到每一个元素上；它与加法配合构成线性运算，满足 k(A+B)=kA+kB","keyPoints":["kA：每个元素乘 k","k(A+B)=kA+kB","|kA|=kⁿ|A|（n 阶方阵）"],"example":"2·(1 0; 0 1)=(2 0; 0 2)，行列式从 1 变 2²=4。"},
  "kp-m1-p2-c2-ju-zhen-cheng-fa": {"anchor":"(AB)ᵢⱼ=Σₖaᵢₖbₖⱼ","caption":"矩阵乘法 C=AB 的 (i,j) 元 = A 的第 i 行与 B 的第 j 列对应乘积之和；","keyPoints":["cᵢⱼ=Σₖ aᵢₖbₖⱼ（行乘列）","AₘₓₙBₙₓₛ 可乘，积为 m×s","AB≠BA 一般成立；AB=O ⇏ 有零因子"],"example":"(1 2)(2; 1)=1·2+2·1=4（1×1 矩阵）。"},
  "kp-m1-p2-c2-fang-zhen-de-mi": {"anchor":"A=αβᵀ ⇒ Aᵏ=(βᵀα)^{k−1}A","caption":"Aᵏ 是 k 个 A 相乘（A⁰=E），只有方阵可谈幂；对角矩阵的幂是各对角元的幂","keyPoints":["Aᵏ=A·A···A（k 个），A⁰=E","diag 的幂 = 各元素求幂","秩一矩阵：Aᵏ=(βᵀα)^{k−1}A"],"example":"A=(1 2; 2 4)=αβᵀ 且 βᵀα=5 ⇒ Aⁿ=5ⁿ⁻¹A。"},
  "kp-m1-p2-c2-zhuan-zhi": {"anchor":"(Aᵀ)ᵀ=A","caption":"转置 Aᵀ 把第 i 行变成第 i 列：(Aᵀ)ᵢⱼ=aⱼᵢ；","keyPoints":["(Aᵀ)ᵢⱼ=aⱼᵢ（行变列）","(AB)ᵀ=BᵀAᵀ（注意反序）","A+Aᵀ 必对称，A−Aᵀ 必反对称"],"example":"行向量 (1,2,3) 转置成列向量；再转回来。"},
  "kp-m1-p2-c2-yun-suan-gui-l": {"anchor":"(AB)C=A(BC)（结合律成立）","caption":"矩阵运算规律清单：加法交换结合成立、数乘结合分配成立、乘法结合与左右分配成立；不成立的是交换律与消去律——列清单比死记有效。","keyPoints":["成立：(AB)C=A(BC)、A(B+C)=AB+AC","不成立：AB=BA、由 AB=AC 推 B=C","E、kE 与任何方阵可交换"],"example":"A²−E=(A+E)(A−E) 成立（A 与 E 可交换）。"},
  "kp-m1-p2-c2-qiang-diao-yi-ban-ab-ba": {"anchor":"AB=BA（特殊时才成立）","caption":"矩阵乘法一般不满足交换律：AB 与 BA 甚至可能尺寸都不同；","keyPoints":["AB 与 BA 尺寸可能都不同","常见可交换对：A 与 Aᵏ、A 与 A⁻¹","「可交换」是题目的额外条件"],"example":"A²−B²=(A+B)(A−B) 仅当 A、B 可交换时成立。"},
  "kp-m1-p2-c2-ab-a-b": {"anchor":"|AB|=|A|·|B|","caption":"方阵乘积的行列式等于行列式的乘积：|AB|=|A||B|（要求 A、B 同阶方阵）；","keyPoints":["|AB|=|A||B|（同阶方阵）","幂的行列式 |Aᵏ|=|A|ᵏ，指数搬到行列式外","|A|=0 ⇔ A 不可逆"],"example":"|A|=2、|B|=3：|AB|=6，|A³B²|=8·9=72。"},
  "kp-m1-p2-c2-zhuan-zhi-de-hang-lie-shi": {"anchor":"|Aᵀ|=|A|","caption":"方阵转置的行列式不变：|Aᵀ|=|A|；配合 (AB)ᵀ=BᵀAᵀ 可以在行列式层面自由「反向」乘积：(AB)ᵀ 的行列式仍是 |A||B|。","keyPoints":["转置不变号 |Aᵀ|=|A|，行性质即列性质","|(AB)ᵀ|=|Bᵀ||Aᵀ|=|A||B|","转置是行列式性质的总开关"],"example":"|(AB)ᵀ|=|AB|=|A||B|。"},
  "kp-m1-p2-c2-mi-de-hang-lie-shi": {"anchor":"|Aᵏ|=|A|ᵏ","caption":"方阵幂的行列式等于行列式的幂：|Aᵏ|=|A|ᵏ；若 A 可逆，|A⁻¹|=1/|A|——「取值」与「乘方」两种运算在行列式层面可以交换。","keyPoints":["幂的行列式 |Aᵏ|=|A|ᵏ，指数搬到行列式外","|A⁻¹|=|A|⁻¹（可逆时）","伴随矩阵：|A*|=|A|ⁿ⁻¹"],"example":"|A|=−2：|A⁵|=(−2)⁵=−32。"},
  "kp-m1-p2-c2-ding-yi": {"anchor":"AA⁻¹=A⁻¹A=E","caption":"对 n 阶方阵 A，若存在方阵 B 使 AB=BA=E，则 B 是 A 的逆矩阵，记 B=A⁻¹；","keyPoints":["AB=BA=E（两侧都要）","可逆 ⇔ |A|≠0","逆唯一：一个方阵只有一个逆"],"example":"A=(2 0; 0 1) 的逆是 (1/2 0; 0 1)。"},
  "kp-m1-p2-c2-wei-yi-xing": {"anchor":"B=B(AC)=(BA)C=C","caption":"可逆方阵的逆矩阵唯一：若 B、C 都是 A 的逆，则 B=BE=B(AC)=(BA)C=EC=C；唯一性让「A⁻¹」这个记号合法。","keyPoints":["两个逆相等：B=B(AC)=(BA)C=C","唯一性支撑记号 A⁻¹","证明套路：两头往中间凑 E"],"example":"证明题标准套路：任何「两侧乘 E」的证明都长这样。"},
  "kp-m1-p2-c2-yun-suan-xing-zhi": {"anchor":"(A₁A₂…Aₛ)⁻¹=Aₛ⁻¹…A₂⁻¹A₁⁻¹","caption":"逆的运算性质：(AB)⁻¹=B⁻¹A⁻¹（反序）、(Aᵀ)⁻¹=(A⁻¹)ᵀ、(kA)⁻¹=(1/k)A⁻¹（k≠0）","keyPoints":["(AB)⁻¹=B⁻¹A⁻¹（反序！）","(Aᵀ)⁻¹=(A⁻¹)ᵀ","(kA)⁻¹=k⁻¹A⁻¹（k≠0）"],"example":"(AB)⁻¹ 先反序再各自求逆：B⁻¹A⁻¹。"},
  "kp-m1-p2-c2-ke-ni-de-chong-fen-bi-yao-tiao-jian": {"anchor":"A 可逆 ⇔ |A|≠0","caption":"n 阶方阵 A 可逆 ⇔ |A|≠0 ⇔ r(A)=n ⇔ 行（列）向量组线性无关 ⇔ Ax=0 只有零解——「满秩」是可逆的代数代名词。","keyPoints":["A 可逆 ⇔ |A|≠0 ⇔ r(A)=n","可逆 ⇔ 行/列向量组线性无关","可逆 ⇔ Ax=0 只有零解"],"example":"|A|=0 的矩阵不可逆（退化/奇异矩阵）。"},
  "kp-m1-p2-c2-ban-sui-ju-zhen-qiu-ni": {"anchor":"A⁻¹=A*/|A|","caption":"伴随矩阵 A* 由代数余子式按转置位置排成，A⁻¹=(1/|A|)A*（|A|≠0）；","keyPoints":["A* 的 (j,i) 元 = Aᵢⱼ（转置摆放！）","A⁻¹=(1/|A|)A*","AA*=A*A=|A|E"],"example":"二阶 (a b; c d) 的伴随是 (d −b; −c a)，逆=(1/(ad−bc))(d −b; −c a)。"},
  "kp-m1-p2-c2-san-lei-chu-deng-xing-bian-huan": {"anchor":"③rᵢ→rᵢ+krⱼ 最常用","caption":"三类初等行变换：①交换两行；②某行乘非零常数 k；③某行的 k 倍加到另一行；它们可逆、不改变矩阵的秩，是解方程组与求逆的全部操作。","keyPoints":["①换行 ②非零倍乘 ③倍加","三类初等变换都可逆，逆变换仍是初等变换","初等行变换不改变矩阵的秩，求秩靠它"],"example":"解 Ax=b 就是对增广矩阵做三类行变换。"},
  "kp-m1-p2-c2-san-lei-chu-deng-ju-zhen": {"anchor":"E₃(k)⁻¹=E₃(−k)（倍加的逆是反倍加）","caption":"对单位矩阵做一次初等变换得到初等矩阵：E₁（换行）、E₂(k)（倍乘）、E₃(k)（倍加）；初等矩阵都可逆，其逆还是初等矩阵。","keyPoints":["初等矩阵 = E 做一次初等变换","初等矩阵必可逆，逆仍是初等矩阵","初等矩阵的行列式 ≠ 0"],"example":"E=(1 0; 0 1) 把第二行乘 3 得初等矩阵 (1 0; 0 3)。"},
  "kp-m1-p2-c2-zuo-cheng-chu-deng-ju-zhen-yu-xing-bian-0fqwi1": {"anchor":"E₃(k)·A = A 的 rᵢ→rᵢ+krⱼ","caption":"用初等矩阵左乘 A，等价于对 A 做对应的初等行变换；右乘则等价于列变换——「左行右列」是把变换与矩阵乘法连起来的关键口诀。","keyPoints":["左乘初等矩阵 = 行变换","右乘初等矩阵 = 列变换","由此 BA 意味着「对 B 做行变换」"],"example":"P⁻¹AP 中的左乘 P⁻¹、右乘 P 是「一组」行变换加列变换。"},
  "kp-m1-p2-c2-yong-chu-deng-bian-huan-qiu-ni": {"anchor":"A⁻¹(A|E)=(E|A⁻¹)","caption":"求逆的实操方法：把 (A|E) 拼在一起做行变换，左边化成 E 时右边就是 A⁻¹；若左边化不出 E，说明 A 不可逆——一举两得。","keyPoints":["(A|E) →(行变换)→ (E|A⁻¹)","只许行变换，不许列变换","左边化不成 E ⇒ A 不可逆"],"example":"A=(1 2; 3 5)：行变换后右块得 (−5 2; 3 −1)。"},
  "kp-m1-p2-c2-zhi-de-ding-yi": {"anchor":"r(A)=max{k：存在非零 k 阶子式}","caption":"数一的「秩的定义」点：r(A) 定义为矩阵中非零子式的最高阶数，等价说法是行（列）向量组的极大无关组所含向量个数——三种定义同一数值。","keyPoints":["秩 = 最高阶非零子式的阶数","也 = 极大线性无关组的向量个数","行秩、列秩、矩阵秩三者相等"],"example":"有非零 2 阶子式、全部 3 阶子式为 0 ⇒ r(A)=2。"},
  "kp-m1-p2-c2-zui-gao-jie-fei-ling-zi-shi": {"anchor":"r(A)=最高阶非零子式的阶数","caption":"r(A)=k 的含义：存在 k 阶子式不为 0，而所有 k+1 阶子式全为 0；这个 k 阶非零子式就是「最高阶非零子式」，是秩的原始定义。","keyPoints":["存在非零 k 阶子式 ⇒ r(A)≥k","全部 k+1 阶子式为 0 ⇒ r(A)≤k","找出一个非零最高阶子式即可确定秩"],"example":"矩阵有非零 3 阶子式而所有 4 阶子式为 0 ⇒ 秩 3。"},
  "kp-m1-p2-c2-xing-jie-ti-xing-ju-zhen": {"anchor":"主元位置 (i,jᵢ)：j₁<j₂<…","caption":"行阶梯形：若某行是零行则其下全是零行；非零行的首非零元（主元）列号随行号严格增大；它是消元的「中间站」，非零行数即秩。","keyPoints":["行阶梯形要求零行沉底，主元逐行右移","主元列号自上而下严格增大","阶梯形的非零行数就是秩，数一眼出"],"example":"(1 2 3; 0 0 4; 0 0 0) 是行阶梯形，秩 2。"},
  "kp-m1-p2-c2-xing-zui-jian-xing": {"anchor":"(E B) 型主元块","caption":"行最简形：在行阶梯形基础上再把主元化成 1，并把主元所在列的其余元素全部消成 0；它唯一（阶梯形不唯一），是读出解与极大无关组的形态。","keyPoints":["行最简形要求主元全为 1，且列上其余清零","主元列其余元素全为 0","行最简形唯一（阶梯形不唯一）"],"example":"(1 0 2; 0 1 3; 0 0 0) 是行最简形。"},
  "kp-m1-p2-c2-chu-deng-bian-huan-qiu-zhi": {"anchor":"r(A)=非零行数","caption":"初等行变换不改变秩，因此求秩就是「化行阶梯形 + 数非零行」；这是求秩的标准方法，也顺带给出极大无关组（主元所在列对应的原向量）。","keyPoints":["行变换（列变换也行）不变秩","阶梯形非零行数 = r(A)","主元所在列 = 极大无关组的列"],"example":"行变换后得到 2 个非零行 ⇒ r(A)=2。"},
  "kp-m1-p2-c2-zhi-de-chang-yong-xing-zhi-he-bu-deng-0othuy": {"anchor":"r(A)+r(B)−n≤r(AB)≤min(r(A),r(B))","caption":"秩的常用结论：0≤r≤min(m,n)；r(Aᵀ)=r(A)；r(A±B)≤r(A)+r(B)；","keyPoints":["r(AB)≤min(r(A),r(B))","Sylvester：r(AB)≥r(A)+r(B)−n","A 可逆 ⇒ 左（右）乘不改变另一因子秩"],"example":"r(A)=r(B)=n（都满秩）⇒ r(AB)=n。"},
  "kp-m1-p2-c2-deng-jia-ju-zhen-gai-nian": {"anchor":"A≌B ⇔ r(A)=r(B)（同型）","caption":"若 B 可由 A 经一系列初等变换得到，称 A 与 B 等价（A≌B）；","keyPoints":["等价 = 初等变换互化","同型 + 等秩 ⇔ 等价","标准形：r 个 1 排对角，全库只有 n+1 个"],"example":"所有秩为 2 的 3×4 矩阵彼此等价。"},
  "kp-m1-p2-c2-yu-chu-deng-bian-huan-zhi-de-guan-xi": {"anchor":"B=PAQ，P、Q 可逆 ⇔ A≌B","caption":"A 与 B 等价 ⇔ 存在可逆矩阵 P、Q 使 B=PAQ ⇔ A、B 同型且秩相等；初等变换的矩阵语言就是「左乘可逆、右乘可逆」。","keyPoints":["B=PAQ（P、Q 可逆）","P 来自行变换、Q 来自列变换","秩相等是充要条件（同型时）"],"example":"化标准形的过程就是找 P、Q 使 PAQ=标准形。"},
  "kp-m1-p2-c2-fen-kuai-jia-jian": {"anchor":"(A₁ A₂; B₁ B₂)+(C₁ C₂; D₁ D₂)=(A₁+C₁ A₂+C₂; …)","caption":"分块加减：把同型矩阵按相同方式切分，对应块相加减；小矩阵（块）之间的加法与普通矩阵一样按元素进行——「块」就是抽象化了的元素。","keyPoints":["分块加减的切分方式必须一致，对应块运算","分块加减就是对应块相加减，块当元素","块可以是任意尺寸（对齐即可）"],"example":"两个 4×4 矩阵都按 2×2 分块，对应块相加。"},
  "kp-m1-p2-c2-fen-kuai-cheng-fa": {"anchor":"(A B; C D)(E F; G H)=(AE+BG AF+BH; CE+DG CF+DH)","caption":"分块乘法：把块当「元素」按普通乘法规则相乘，但块内乘法不可交换要按原序写；要求左矩阵的列分法与右矩阵的行分法一致。","keyPoints":["块的乘法形如 AB：内标匹配","块乘不可交换，保持顺序","对角块乘对角块，交叉块按公式"],"example":"分块对角阵相乘：对角块各自相乘即可。"},
  "kp-m1-p2-c2-fen-kuai-zhuan-zhi": {"anchor":"(AB 分块)ᵀ=BᵀAᵀ（分块版反序律）","caption":"分块矩阵转置要「两步走」：块的位置按转置排布，每个块自身还要转置——(A B; C D)ᵀ=(Aᵀ Cᵀ; Bᵀ Dᵀ)，外内两层都要转。","keyPoints":["块位置转置 + 块内转置","(A B; C D)ᵀ=(Aᵀ Cᵀ; Bᵀ Dᵀ)","只转一层是最常见错误"],"example":"分块 (A; B)（列块）转置成行块 (Aᵀ Bᵀ)。"},
  "kp-m1-p2-c2-fen-kuai-dui-jiao-ju-zhen": {"anchor":"diag(A,B)⁻¹=diag(A⁻¹,B⁻¹)","caption":"分块对角矩阵：非对角块全为零、对角块为小方阵；它的幂、行列式、逆都按对角块「各自处理」——大问题拆成小问题。","keyPoints":["分块对角矩阵要求非对角块全 O，各块独立运算","|diag(A,B)|=|A|·|B|","diag(A,B)ᵏ=diag(Aᵏ,Bᵏ)；逆 = 各块求逆"],"example":"diag(A,B) 的秩 = r(A)+r(B)。"},
  "kp-m1-p2-c2-jian-dan-fen-kuai-qiu-ni": {"anchor":"(A O; C B)⁻¹=(A⁻¹ O; −B⁻¹CA⁻¹ B⁻¹)","caption":"分块对角阵的逆 = 各对角块分别求逆；分块三角矩阵 (A O; C B) 的逆有公式（A","keyPoints":["diag 块逆 = 各块逆","下三角分块 (A O; C B)⁻¹=(A⁻¹ O; −B⁻¹CA⁻¹ B⁻¹)","原理：设逆块待定，解块方程"],"example":"零块位置不同的分块上三角同理（公式镜像）。"},
  "kp-m1-p2-c3-xing-xiang-liang-lie-xiang-liang": {"anchor":"α=(a₁,…,aₙ)ᵀ，αᵀβ=Σaᵢbᵢ","caption":"n 维行向量是 1×n 矩阵、列向量是 n×1 矩阵——向量就是特殊的矩阵；行与列通过转置互换，参与乘法时必须分清「形状」。","keyPoints":["行向量 = 1×n 矩阵，列向量 = n×1 矩阵","转置互换：αᵀ 把列变行","αᵀβ 是数（1×1），αβᵀ 是矩阵"],"example":"αᵀβ=3（内积），αβᵀ 是 n×n 矩阵（秩 1）。"},
  "kp-m1-p2-c3-ling-xiang-liang": {"anchor":"1·0+0·α₁+…+0·αₛ=0（系数不全为零）","caption":"零向量 0 是分量全为 0 的向量：任何向量组只要包含 0 就必线性相关（取 0 的系数为 1、其余为 0）；这是「判相关」的第一反应。","keyPoints":["0 = 分量全零的向量","含 0 的向量组必线性相关","单个零向量也线性相关"],"example":"组 (0,1,2)（1,1,1)：含零向量，线性相关。"},
  "kp-m1-p2-c3-k1-1-kn-n": {"anchor":"β 可表示 ⇔ r(A)=r(A,β)","caption":"β=k₁α₁+…+kₙαₙ 表示 β 可由向量组线性表示：找一组系数使等式成立；「能否表示」等价于非齐次方程组 (α₁,…,αₙ)x=β 是否有解。","keyPoints":["线性表示 ⇔ 方程组有解","解不唯一 ⇔ 表示方式不唯一（组相关时）","r(α₁…αₙ)=r(α₁…αₙ,β) 是有解条件"],"example":"β=(3,3)、α₁=(1,1)、α₂=(1,0)：β=2α₁+α₂。"},
  "kp-m1-p2-c3-yi-ge-xiang-liang-neng-fou-you-xiang-02v8uo": {"anchor":"可表示 ⇔ r(A)=r(A,β)","caption":"判断 β 能否由 α₁,…,αₛ 线性表示：对 (α₁,…,αₛ,β) 做行变换，比较系数矩阵与增广矩阵的秩；等秩可表示，秩差 1 不可表示。","keyPoints":["r(α 组)=r(α 组,β) ⇔ 可表示","不可表示时秩差恰为 1","行变换到行最简形即可下结论"],"example":"β=(1,0)、α₁=(0,1)：r=1 与 2 不等，不可表示。"},
  "kp-m1-p2-c3-ding-yi": {"anchor":"r(α₁,…,αₛ)=s ⇔ 线性无关","caption":"线性相关：存在不全为零的数 k₁,…,kₛ 使 k₁α₁+…+kₛαₛ=0；线性无关：上式成立必须所有 kᵢ=0。","keyPoints":["相关 ⇔ 有非零系数组合出 0","无关 ⇔ 只有全零系数","等价判定：r(组)<s ⇔ 相关"],"example":"α₁=(1,0)、α₂=(2,0)：2α₁−α₂=0，相关。"},
  "kp-m1-p2-c3-qi-ci-fang-cheng-zu-pan-ding": {"anchor":"s>r(A) ⇔ 线性相关","caption":"向量组 α₁,…,αₛ 线性相关 ⇔ 齐次方程组 x₁α₁+…+xₛαₛ=0 有非零解；数向量个数与秩即可判定：未知数多于秩时必有非零解。","keyPoints":["相关 ⇔ Ax=0 有非零解（A 由向量按列拼成）","s>r(A) ⇒ 必相关（解必存在）","s=r(A) ⇒ 无关"],"example":"3 个 2 维向量必相关：3>r((2×3 矩阵))≤2。"},
  "kp-m1-p2-c3-hang-lie-shi-pan-ding-fang-zhen-qing-0c62cf": {"anchor":"|A|≠0 ⇔ 列向量组线性无关","caption":"n 个 n 维向量（方阵情形）：按列拼成方阵 A 后，线性无关 ⇔ |A|≠0；行列式为 0 即相关——用行列式一把判定的快捷情形。","keyPoints":["方阵情形：|A|≠0 ⇔ 无关","|A|=0 ⇔ 相关","只适用于「个数 = 维数」"],"example":"α₁=(1,1)、α₂=(1,2)：|A|=1≠0，无关。"},
  "kp-m1-p2-c3-zhi-pan-ding": {"anchor":"r(α₁,…,αₛ)=s ⇔ 无关","caption":"一般情形的判定标准：向量组线性无关 ⇔ r(α₁,…,αₛ)=s（秩等于个数）；秩小于个数必相关——秩是相关性判定的「通用货币」。","keyPoints":["r=s ⇔ 无关；r<s ⇔ 相关","向量组求秩用行变换最直接，拼矩阵化阶梯","部分组秩 ≤ 整组秩"],"example":"4 个向量秩为 3 ⇒ 相关，且至少一个可由其余表示。"},
  "kp-m1-p2-c3-chang-yong-xing-zhi": {"anchor":"r(部分组)≤r(整组)","caption":"线性相关性常用性质：含零向量必相关；部分相关则整组相关；整组无关则部分无关；向量个数大于维数必相关；无关组添加向量后相关，则新向量可由原组唯一表示。","keyPoints":["部分相关 ⇒ 整组相关（逆否：整组无关 ⇒ 部分无关）","n+1 个 n 维向量必相关","无关组外添一个「可表示」向量 ⇒ 组相关"],"example":"α₁,α₂ 无关而 α₁,α₂,α₃ 相关 ⇒ α₃=λ₁α₁+λ₂α₂（表示唯一）。"},
  "kp-m1-p2-c3-2d-liang-ge-bu-gong-xian-xiang-liang-ke-15oxgx": {"anchor":"(1,0)、(0,1) 是标准基底","caption":"平面上两个不共线（不成比例）的向量线性无关，能张成整个平面：任何平面向量都是它们的线性组合；共线则只能张成一条直线。","keyPoints":["不共线 ⇔ 线性无关（2 个向量）","无关 ⇒ 成为平面的基底","共线 ⇔ 相关，张成一维"],"example":"α=(1,1)、β=(1,−1) 不共线：任意 (x,y) 都可写成组合。"},
  "kp-m1-p2-c3-3d-san-ge-gong-mian-xiang-liang-xian-0c2msj": {"anchor":"|α β γ|=0 ⇔ 共面（相关）","caption":"空间中三个向量若共面（混和积为零、行列式为零）则线性相关，最多张成一张平面；三个不共面的向量才线性无关，能张成整个三维空间。","keyPoints":["三向量共面 ⇔ 相关 ⇔ 行列式为 0","不共面 ⇒ 无关 ⇒ 空间基底","维数 = 无关向量的个数"],"example":"α=(1,0,0)、β=(0,1,0)、γ=(1,1,0)：共面（z=0 平面），相关。"},
  "kp-m1-p2-c3-ding-yi-2": {"anchor":"极大无关组含 r 个向量，r=向量组的秩","caption":"极大线性无关组：向量组中一个线性无关的部分组，再添入任何原组向量都变相关——「无关性 + 极大性」两条件；它所含向量个数就是向量组的秩。","keyPoints":["无关 + 再添任一原组向量变相关","极大无关组一般不唯一","所含向量个数 = 向量组的秩"],"example":"α₁=(1,0)、α₂=(2,0)、α₃=(0,1)：{α₁,α₃} 是极大无关组（{α₂,α₃} 也是）。"},
  "kp-m1-p2-c3-qiu-fa": {"anchor":"主元列号 = 极大无关组的下标","caption":"求极大无关组的标准流程：向量按列拼矩阵 → 行变换化行最简形 → 主元所在列对应的「原向量」构成一个极大无关组；其余列向量由主元列线性表出。","keyPoints":["按列拼、行变换、认主元列","主元列对应原向量（不是化简后的列）","非主元列的表示系数可从最简形读出"],"example":"最简形主元在第 1、3 列 ⇒ α₁、α₃ 是极大无关组，α₂ 的系数从第 2 列读出。"},
  "kp-m1-p2-c3-yu-yuan-xiang-liang-zu-deng-jia": {"anchor":"{极大组} ≌ {全组}","caption":"极大无关组与原向量组等价：互相可以线性表示——极大组能表示全组（构造），全组显然能表示极大组（子集）；等价组秩相等由此而来。","keyPoints":["极大组 ↔ 全组互相表示","全组任何向量 = 极大组的线性组合","这是「秩刻画向量组」的根基"],"example":"α₁=(1,0)、α₂=(2,0)、α₃=(0,1)：α₂=2α₁，{α₁,α₃} 表示 α₂。"},
  "kp-m1-p2-c3-ding-yi-3": {"anchor":"r(α₁,…,αₛ)≤s","caption":"向量组的秩 = 极大线性无关组所含向量的个数，记 r(α₁,…,αₛ)；它是向量组「有效维数」的度量，也是判定两向量组能否互相表示的核心量。","keyPoints":["秩 = 极大无关组的向量个数","全由零向量组成的组秩为 0，没有独立方向","r 组 ≤ 组内向量个数 s"],"example":"全由 (1,2) 的倍数组成的组：秩为 1。"},
  "kp-m1-p2-c3-yu-ju-zhen-xing-zhi-lie-zhi-de-guan-xi": {"anchor":"r(A)=r(Aᵀ)=列秩=行秩","caption":"把向量组按列拼成矩阵后，向量组的秩 = 矩阵的列秩；同时矩阵的行秩 = 列秩 = 矩阵秩——「三秩合一」让行向量组、列向量组、矩阵秩互相换算。","keyPoints":["列向量组的秩 = r(A)","行向量组的秩 = r(A)（=列秩）","r(A)=r(Aᵀ) 随时可用"],"example":"行向量组求秩：转置按列拼，或直接化行阶梯数非零行。"},
  "kp-m1-p2-c3-hu-xiang-xian-xing-biao-shi": {"anchor":"r(Ⅱ)=r(Ⅰ,Ⅱ) 且 r(Ⅰ)=r(Ⅰ,Ⅱ) ⇔ 等价","caption":"两向量组等价指它们能互相线性表示：每个组都能表示出另一组的全部向量；「能表示」是单向关系，等价要求双向都通。","keyPoints":["等价 = 双向都能线性表示","自反、对称、传递（是等价关系）","等价 ⇔ 互相表示 ⇔ 合起来秩不变"],"example":"极大无关组与全组等价：一个方向构造、一个方向天然。"},
  "kp-m1-p2-c3-deng-jia-xiang-liang-zu-zhi-xiang-deng": {"anchor":"Ⅰ≌Ⅱ ⇔ r(Ⅰ)=r(Ⅱ)=r(Ⅰ,Ⅱ)","caption":"等价向量组必有相等的秩；反之「秩相等」不足以等价（还要能互相表示）——秩相等是必要条件，合并组秩不变才是充要刻画。","keyPoints":["等价向量组秩必相等，反之还要看表示","秩相等 ⇏ 等价（还要比表示能力）","充要：r(Ⅰ)=r(Ⅱ)=r(Ⅰ,Ⅱ)"],"example":"α=(1,0) 与 β=(0,1)：秩都为 1 但互相表示不了，不等价。"},
  "kp-m1-p2-c3-nei-ji": {"anchor":"(α,β)=αᵀβ","caption":"n 维向量的内积 (α,β)=αᵀβ=a₁b₁+…+aₙbₙ，结果是数；","keyPoints":["(α,β)=Σaᵢbᵢ=αᵀβ","(α,α)=|α|²≥0","(α,β)=0 即正交"],"example":"α=(1,2,2)：(α,α)=1+4+4=9，|α|=3。"},
  "kp-m1-p2-c3-chang-du": {"anchor":"|α|=√Σaᵢ²","caption":"向量长度（模、范数）|α|=√(α,α)=√(a₁²+…+aₙ²)；长度为 1 的向量叫单位向量，|α|=0 当且仅当 α=零向量。","keyPoints":["|α|=√(α,α)","|kα|=|k|·|α|","单位化：α/|α|（α≠0）"],"example":"α=(3,4)：|α|=5，单位向量 (3/5,4/5)。"},
  "kp-m1-p2-c3-zheng-jiao": {"anchor":"(α,β)=0 ⇔ 正交","caption":"(α,β)=0 称 α 与 β 正交（n 维空间里的「垂直」）；零向量与任何向量正交，但谈正交组时通常只考虑非零向量。","keyPoints":["正交 ⇔ (α,β)=0","零向量与谁都正交（约定排除）","正交向量组（非零、两两正交）必线性无关"],"example":"(1,1,0) 与 (1,−1,0) 正交。"},
  "kp-m1-p2-c3-dan-wei-xiang-liang": {"anchor":"e=α/|α|","caption":"单位向量是长度为 1 的向量：非零向量 α 除以自身长度即得 α/|α|，方向不变；标准正交组就是「彼此正交的单位向量组」。","keyPoints":["单位向量的模 |e|=1，方向不变长度锁死","e=α/|α|（α≠0）","单位化保持方向、锁定长度"],"example":"α=(1,1)：e=(1/√2,1/√2)。"},
  "kp-m1-p2-c3-biao-zhun-zheng-jiao-zu": {"anchor":"(αᵢ,αⱼ)=0（i≠j），|αᵢ|=1","caption":"标准正交组：组内向量都是单位向量且两两正交；n 个 n 维标准正交向量拼成的矩阵是正交矩阵——它是空间里「一套标准直角坐标系」。","keyPoints":["(αᵢ,αⱼ)=δᵢⱼ（自己 1、别人 0）","标准正交组必线性无关","拼成矩阵 Q 满足 QᵀQ=E"],"example":"e₁=(1,0)、e₂=(0,1) 是最简单的标准正交组。"},
  "kp-m1-p2-c3-zheng-jiao-hua": {"anchor":"β₂=α₂−[(α₂,β₁)/(β₁,β₁)]β₁","caption":"施密特正交化的核心动作：从新向量里减去它在已有正交组上的投影，剩下的部分自然与已有向量正交——β₂=α₂−[(α₂,β₁)/(β₁,β₁)]β₁。","keyPoints":["施密特正交化从 β₁=α₁ 起步，之后逐个减投影","βₖ=αₖ−Σ(αₖ,βᵢ)/(βᵢ,βᵢ)·βᵢ","正交化不改变张成的空间"],"example":"α₁=(1,0)、α₂=(1,1)：β₂=(1,1)−(1,0)=(0,1)。"},
  "kp-m1-p2-c3-dan-wei-hua": {"anchor":"γᵢ=βᵢ/√(βᵢ,βᵢ)","caption":"正交化得到的是正交组（两两垂直但长度随意），再逐个除以自身长度就升级成标准正交组——「先正交、再单位」是标准流程，顺序不能反着混。","keyPoints":["γᵢ=βᵢ/|βᵢ|","先施密特正交化，后单位化","单位化不影响正交性，只把长度调到 1"],"example":"β=(0,1) 单位化还是 (0,1)；β=(2,2) 单位化得 (1/√2,1/√2)。"},
  "kp-m1-p2-c4-shi-yong-tiao-jian-xi-shu-ju-zhen-fang-16budt": {"anchor":"A 为 n 阶方阵且 |A|≠0","caption":"克拉默法则的使用条件有两条：方程个数 = 未知数个数（系数矩阵是方阵），且系数行列式 |A|≠0；","keyPoints":["系数矩阵为 n 阶方阵（n 个方程 n 个未知数）","|A|≠0（才有唯一解可求）","条件不满足时转秩判定求解"],"example":"二元一次方程组 |A|=5≠0：克拉默可直接用。"},
  "kp-m1-p2-c4-jie-de-gong-shi": {"anchor":"xᵢ=Dᵢ/D","caption":"克拉默公式：xᵢ=Dᵢ/D，其中 D 是系数行列式、Dᵢ 是把第 i 列换成常数列后的行列式；它给唯一解一个显式表达式，理论意义大于计算效率。","keyPoints":["xᵢ=Dᵢ/D（i=1,…,n）","Dᵢ：第 i 列换成常数项","适合低阶或文字型方程组"],"example":"D=2、D₁=4、D₂=−2：x₁=2、x₂=−1。"},
  "kp-m1-p2-c4-ax-b": {"anchor":"Ax=b ⇔ Σxⱼaⱼ=b（列向量的线性组合）","caption":"线性方程组写成矩阵形式 Ax=b：A 是系数矩阵、x 是未知数列、b 是常数列；","keyPoints":["A 为 m×n 系数矩阵，x 为 n 维未知数","b≠0：非齐次；b=0：齐次","解的存在唯一性由 r(A) 与 r(A,b) 决定"],"example":"「b 能否由 A 的列向量表示」就是「Ax=b 有无解」。"},
  "kp-m1-p2-c4-zeng-guang-ju-zhen": {"anchor":"(A|b) 的秩记 r(A,b)","caption":"增广矩阵 (A|b) 是在系数矩阵右侧拼上常数列得到的矩阵；方程组的全部信息（有解？","keyPoints":["(A|b)：比 A 多一列","r(A)=r(A|b) ⇔ 有解","行变换必须对整个增广矩阵做"],"example":"r(A)=2、r(A,b)=3 ⇒ 无解。"},
  "kp-m1-p2-c4-ax-0": {"anchor":"r(A)<n ⇔ 有非零解","caption":"齐次线性方程组 Ax=0：常数项全为零；它必有零解 x=0，所以问题从来不是「有没有解」，而是「有没有非零解」——由秩完全决定。","keyPoints":["齐次方程 b=0，必有零解，问的是非零解","有非零解 ⇔ r(A)<n","解集是 n−r 维线性空间"],"example":"A 为 3×4（n=4）、r=2：基础解系含 4−2=2 个向量。"},
  "kp-m1-p2-c4-ling-jie": {"anchor":"只有零解 ⇔ 列向量组线性无关","caption":"x=0 永远满足 Ax=0，称为零解（平凡解）；「只有零解」对应 r(A)=n（无关、满秩），「存在非零解」对应 r(A)<n——齐次方程组的两分法。","keyPoints":["x=0 必是 Ax=0 的解","只有零解 ⇔ r(A)=n","非零解 ⇔ r(A)<n"],"example":"A 满秩时 Ax=0 只有零解。"},
  "kp-m1-p2-c4-fei-ling-jie-cun-zai-tiao-jian": {"anchor":"r(A)<n ⇔ Ax=0 有非零解","caption":"齐次方程组 Ax=0 存在非零解的充要条件是 r(A)<n（未知数个数）：秩不够 n，自由未知量就出现，非零解随之出现。","keyPoints":["充要条件：r(A)<n","方程个数 m<n ⇒ 必有非零解","n 个未知 n 个方程时看 |A|：|A|=0 有非零解"],"example":"方阵 |A|=0 ⇒ r<n ⇒ 有非零解。"},
  "kp-m1-p2-c4-r-a-n": {"anchor":"dim(解空间)=n−r(A)","caption":"r(A)<n 是齐次方程组有非零解的等价刻画：n 是未知数个数；r 越小，解空间维数 n−r 越大，自由度越多。","keyPoints":["解空间维数 = n−r(A)","r(A)<n ⇔ 有非零解","r(A)=n ⇔ 只有零解"],"example":"r=1、n=3：解空间是二维平面（过原点）。"},
  "kp-m1-p2-c4-ji-chu-jie-xi": {"anchor":"ξ₁,…,ξ_{n−r} 线性无关，解集=span{ξ₁,…}","caption":"基础解系是齐次方程组解空间的极大无关组：n−r 个线性无关的解向量，所有解都是它们的线性组合——解出基础解系，齐次方程组就全部解完。","keyPoints":["含 n−r(A) 个线性无关的解向量","取法：自由未知量轮流取 1（其余取 0）","基础解系不唯一（但个数唯一）"],"example":"n=3、r=1：基础解系 2 个向量，通解 k₁ξ₁+k₂ξ₂。"},
  "kp-m1-p2-c4-tong-jie": {"anchor":"x=k₁ξ₁+…+k_{n−r}ξ_{n−r}+η*","caption":"齐次方程组的通解 = 基础解系的全部线性组合 x=k₁ξ₁+…+k_{n−r}ξ_{n−r}；非齐次的通解还要再「加一个特解」。","keyPoints":["齐次通解：k₁ξ₁+…+k_{n−r}ξ_{n−r}","非齐次通解 = 特解 + 齐次通解","通解覆盖且仅覆盖全部解"],"example":"r=2、n=4：通解 x=k₁ξ₁+k₂ξ₂+η*。"},
  "kp-m1-p2-c4-you-jie-tiao-jian-r-a-r-a-b": {"anchor":"r(A)=r(A,b) ⇔ Ax=b 有解","caption":"非齐次方程组 Ax=b 有解 ⇔ r(A)=r(A,b)：常数列 b 不能带来「新的秩」——即 b 能被 A 的列向量线","keyPoints":["r(A)=r(A,b) ⇔ 有解","r(A)<r(A,b) ⇔ 无解","几何：b 落在 A 列张成的空间内"],"example":"增广矩阵化阶梯出现 (0…0|c) 行（c≠0）⇒ 无解。"},
  "kp-m1-p2-c4-wei-yi-jie": {"anchor":"x=A⁻¹b（方阵可逆时）","caption":"Ax=b 有唯一解 ⇔ r(A)=r(A,b)=n：未知数全部被约束住，没有自由未知量；方阵情形对应 |A|≠0（可用克拉默或求逆）。","keyPoints":["唯一解 ⇔ r(A)=r(A,b)=n","唯一解意味着无自由未知量，秩等于 n","方阵时 ⇔ |A|≠0，x=A⁻¹b"],"example":"r(A)=r(A,b)=3、n=3：唯一解 x=(1,0,2)ᵀ 之类。"},
  "kp-m1-p2-c4-wu-qiong-duo-jie": {"anchor":"x=η*+k₁ξ₁+…+k_{n−r}ξ_{n−r}","caption":"Ax=b 有无穷多解 ⇔ r(A)=r(A,b)<n：有解但存在 n−r 个自由未知量，解集是「特解 + 齐次解空间」的仿射集合。","keyPoints":["无穷多解 ⇔ r(A)=r(A,b)<n","自由未知量 n−r 个","解集：特解 + 齐次通解"],"example":"n=3、r=2：解集是一条直线（1 维仿射集）。"},
  "kp-m1-p2-c4-wu-jie": {"anchor":"r(A)<r(A,b) ⇔ 无解","caption":"r(A)<r(A,b) ⇔ 无解：消元后出现「0=非零」的矛盾行；几何上是 b 落在了系数列向量张成空间之外。","keyPoints":["无解 ⇔ r(A)<r(A,b)","标志：矛盾行 (0…0|c)，c≠0","此时不存在特解与通解讨论"],"example":"(0 0 | 5) 一行出现 ⇒ 方程组无解。"},
  "kp-m1-p2-c4-qi-ci-jie-de-xian-xing-zu-he": {"anchor":"η₁,η₂ 是解 ⇒ k₁η₁+k₂η₂ 也是解","caption":"Ax=0 的任意两个解之和、解的数乘仍是解——齐次解集对线性运算封闭，构成（解空间的）线性空间，维数 n−r；这是「线性组合依然是解」的依据。","keyPoints":["齐次解之和、数乘仍是解，解集是子空间","解集 = n−r 维线性空间","基础解系就是这个空间的基"],"example":"r=1、n=2 的解集是过原点的一条直线（一维空间）。"},
  "kp-m1-p2-c4-fei-qi-ci-fang-cheng-ren-yi-liang-ge-1ymgql": {"anchor":"η₁−η₂ ∈ {x：Ax=0}","caption":"若 η₁、η₂ 都满足 Ax=b，则 A(η₁−η₂)=0：非齐次的任意两个解之差必是对应齐次方程的解——「特解 + 齐次通解」结构的直接来源。","keyPoints":["A(η₁−η₂)=0","由它推出解的结构定理","已知两特解 ⇒ 可得一个齐次解"],"example":"η₁=(1,2)、η₂=(0,1) 都解 Ax=b ⇒ (1,1) 是 Ax=0 的解。"},
  "kp-m1-p2-c4-fei-qi-ci-tong-jie-yi-ge-te-jie-dui-0n8v8t": {"anchor":"通解 = 特解 + 齐次通解","caption":"非齐次线性方程组的通解 = 任意一个特解 η* + 对应齐次方程组的通解 k₁ξ₁+…+k_{n−r}ξ_{n−r}：特","keyPoints":["x=η*+k₁ξ₁+…+k_{n−r}ξ_{n−r}","非齐次特解任取一个即可，常取自由变量为 0","解集是 n−r 维「仿射子空间」（不过原点）"],"example":"r=2、n=4：x=η*+k₁ξ₁+k₂ξ₂，解集是 4 维空间里的平面。"},
  "kp-m1-p2-c4-gao-si-xiao-yuan": {"anchor":"(A|b)→(行最简形)","caption":"高斯消元：对增广矩阵做初等行变换化行阶梯（判断解的情况），再继续化行最简形（直接读解）；全程只用三类行变换，方程组保持同解。","keyPoints":["高斯消元用行变换做同解变形，解集不变","阶梯形定解的状态（无解/唯一/无穷）","化到行最简形可直接读出通解，主变量用参数表示"],"example":"最简形中主元列对应主变量，其余是自由变量。"},
  "kp-m1-p2-c4-zi-you-wei-zhi-liang": {"anchor":"自由变量数 = n−r","caption":"行最简形中，非主元列对应的未知量是自由未知量，共 n−r 个；它们的取值一旦给定，主变量随之唯一确定——「自由」正是无穷多解的来源。","keyPoints":["自由未知量个数 = n−r(A)","一般取非主元列的变量","轮流取 1（其余取 0）生成基础解系"],"example":"n=4、r=2：x₃、x₄ 自由，令 (x₃,x₄)=(1,0),(0,1)。"},
  "kp-m1-p2-c4-can-shu-hua-tong-jie": {"anchor":"x=k₁ξ₁+…+k_{n−r}ξ_{n−r}(+η*)","caption":"设自由未知量为参数（k₁,…,k_{n−r}），把主变量用参数表出，整理成 x=k₁ξ₁+…+η* 的形式——通解的最终","keyPoints":["自由变量改名参数 k","回代时主变量用 k 表示，整理成向量形式","写成「特解 + 组合」标准形"],"example":"x₁=1−k₁, x₂=2+k₁+k₂ ⇒ x=(1,2,0,0)+k₁(−1,1,1,0)+k₂(0,1,0,1)。"},
  "kp-m1-p2-c5-a": {"anchor":"Aα=λα（α≠0）","caption":"特征值与特征向量的定义式 Aα=λα：方阵 A 作用在非零向量 α 上只产生「伸缩」不改变方向（或反向）","keyPoints":["Aα=λα 是定义等式（λ 复数域讨论）","α 方向不变（或恰好反向）","一个特征值对应无穷多个特征向量（差常数倍）"],"example":"A=(2 0; 0 3)：e₁ 满足 Ae₁=2e₁，λ=2 对应 e₁。"},
  "kp-m1-p2-c5-0": {"anchor":"α≠0 且 Aα=λα","caption":"特征向量必须是非零向量：α=0 时 A·0=λ·0 对任何 λ 都成立，定义就失效了；「α≠0」是定义的一部分，验证特征向量先查它。","keyPoints":["零向量不是任何特征值的特征向量","特征向量非零是定义要求","特征值可以为 0（A 不可逆时）"],"example":"λ=0 时特征向量仍非零：Aα=0 的非零解就是 λ=0 的特征向量。"},
  "kp-m1-p2-c5-te-zheng-zhi": {"anchor":"|λE−A|=0","caption":"特征值 λ 是特征方程 |λE−A|=0 的根：n 阶方阵有 n 个特征值（复数域计重数）；","keyPoints":["特征值 = |λE−A|=0 的根","n 个（计重数，复数域）","Σλᵢ=tr(A)，∏λᵢ=|A|（验算用）"],"example":"A=(1 2; 2 1)：|λE−A|=(λ−3)(λ+1)，特征值 3、−1。"},
  "kp-m1-p2-c5-te-zheng-xiang-liang": {"anchor":"(A−λE)x=0 的非零解","caption":"对应 λ 的特征向量是齐次方程组 (A−λE)x=0 的非零解：一个特征值对应无穷多个特征向量（相差非零常数倍都算），构成一个特征子空间。","keyPoints":["特征向量 ∈ ker(A−λE)，非零","同一 λ 的特征向量差常数倍等价","不同特征值的特征向量线性无关"],"example":"λ=3 对应 (A−3E)x=0 解出 α=(1,1)ᵀ，则 k(1,1)ᵀ（k≠0）全是。"},
  "kp-m1-p2-c5-te-zheng-fang-cheng-e-a-0": {"anchor":"|λE−A|=0（n 次方程）","caption":"特征方程 |λE−A|=0：左边是 λ 的 n 次多项式（特征多项式），求根即得全部特征值；展开时常用「对角线元素减 λ」的结构找因式。","keyPoints":["|λE−A| 是 λ 的 n 次首一多项式","解 n 次方程得 n 个特征值","技巧：某行（列）和相同先提公因式"],"example":"行和相等（都为 3）的矩阵：λ=3 是特征值（每行和相同 ⇒ A(1,…,1)ᵀ=3(1,…,1)ᵀ）。"},
  "kp-m1-p2-c5-dai-shu-zhong-shu": {"anchor":"(λ−λ₀)^k | f(λ) ⇒ 代数重数 k","caption":"代数重数：特征值 λ 作为特征多项式根的重数；全体代数重数之和为 n。","keyPoints":["代数重数 = 特征多项式中根的重数","Σ 代数重数 = n","几何重数 ≤ 代数重数（恒成立）"],"example":"f(λ)=(λ−2)²(λ+1)：λ=2 代数重数 2，λ=−1 重数 1。"},
  "kp-m1-p2-c5-jie-a-e-x-0": {"anchor":"ξ∈ker(A−λE)，ξ≠0","caption":"求特征向量：把 λ 代入，解齐次方程组 (A−λE)x=0，基础解系给出该特征值下线性无关的特征向量；每个非零解都是特征向量。","keyPoints":["(A−λE)x=0 的非零解即特征向量","基础解系含 n−r(A−λE) 个向量","几何重数 = n−r(A−λE)"],"example":"r(A−2E)=1（3 阶）：几何重数 2，基础解系 2 个向量。"},
  "kp-m1-p2-c5-tong-yi-te-zheng-zhi-dui-ying-te-zheng-11cfe8": {"anchor":"Vλ={x：Ax=λx}","caption":"同一特征值 λ 的全部特征向量加上零向量构成特征子空间 Vλ=ker(A−λE)：它的维数是几何重数，其中任取的基础解系就是「代表团」。","keyPoints":["Vλ=ker(A−λE) 是子空间","dim Vλ = 几何重数 ≤ 代数重数","不同特征值的子空间交只有零向量"],"example":"λ=2 的特征子空间是某条过原点直线：任何特征向量都在其上。"},
  "kp-m1-p2-c5-ji-yu-te-zheng-zhi-zhi-he": {"anchor":"tr(A)=λ₁+…+λₙ","caption":"方阵的迹 tr(A)=主对角线元素之和 = 全部特征值之和（计重数）：这一等式是求特征值最快的验算工具，也常用于「反求参数」。","keyPoints":["tr(A)=Σaᵢᵢ=Σλᵢ","特征值全部计重数地求和","验算或反求未知参数的利器"],"example":"A 对角线 (1,2,3)：特征值若为 2、2、2，和为 6=1+2+3 ✓。"},
  "kp-m1-p2-c5-hang-lie-shi-yu-te-zheng-zhi-zhi-ji": {"anchor":"|A|=λ₁λ₂…λₙ","caption":"方阵的行列式等于全部特征值的乘积：|A|=λ₁λ₂…λₙ（计重数）；立即可得「|A|≠0 ⇔ 0 不是特征值 ⇔ A 可逆」。","keyPoints":["行列式等于特征值连乘 |A|=∏λᵢ，判零即判可逆","0 是特征值 ⇔ |A|=0 ⇔ 不可逆","与迹公式联用快速定特征值"],"example":"特征值 1、2、3：|A|=6；若 |A|=0 则某特征值为 0。"},
  "kp-m1-p2-c5-a-k-de-te-zheng-zhi": {"anchor":"Aᵏα=λᵏα","caption":"若 Aα=λα，则 Aᵏα=λᵏα：A 的幂的特征值就是特征值的幂，特征向量不变；「f(A) 的特征值 = f(λ)」思想的特例。","keyPoints":["Aᵏ 的特征值 = λᵏ（同一 α）","Aᵏ、A⁻¹ 的特征向量不变，只有值在变","常用于求 Aⁿ 或判 Aᵏ=O 型题"],"example":"λ=2、−1：A³ 的特征值 8、−1。"},
  "kp-m1-p2-c5-a-1-de-te-zheng-zhi": {"anchor":"A⁻¹α=(1/λ)α","caption":"A 可逆时，A⁻¹ 的特征值是 1/λ（特征向量不变）：由 Aα=λα 两边左乘 A⁻¹ 得 A⁻¹α=(1/λ)α；","keyPoints":["A⁻¹ 的特征值 = 1/λ","前提：A 可逆（|A|≠0）","伴随矩阵 A* 的特征值 = |A|/λ"],"example":"λ=2、3：A⁻¹ 的特征值 1/2、1/3。"},
  "kp-m1-p2-c5-duo-xiang-shi-ju-zhen-han-shu-de-te-0hr478": {"anchor":"f(A) 的谱 = {f(λᵢ)}","caption":"核心思想：若 Aα=λα，则对任意多项式 f，有 f(A)α=f(λ)α——矩阵多项式的特征值就是特征值代入多项式，特征向量保持不变。","keyPoints":["f(A)α=f(λ)α","例：A²+2A+E 的特征值 = λ²+2λ+1","反向推原特征值时常配迹/行列式联立"],"example":"λ=1、−2，f(t)=t²：A² 的特征值 1、4。"},
  "kp-m1-p2-c5-b-p-1-ap": {"anchor":"B=P⁻¹AP","caption":"相似的定义：存在可逆矩阵 P 使 B=P⁻¹AP，称 A 相似于 B；相似是「同一线性变换在不同基下」的表现——同一个人换了套衣服。","keyPoints":["B=P⁻¹AP（P 可逆）⇔ A∽B","几何：同一线性变换在不同基下的矩阵","对角化 = 找 P 使相似对象是对角阵"],"example":"P=(α₁ α₂ … αₙ)（特征向量按列）时 P⁻¹AP=Λ。"},
  "kp-m1-p2-c5-xiang-si-guan-xi": {"anchor":"A∽B、B∽C ⇒ A∽C","caption":"相似关系是等价关系：自反（A∽A，取 P=E）、对称（B=P⁻¹AP ⇒ A=PBP⁻¹）、传递（A∽B","keyPoints":["相似关系满足自反、对称、传递三条","同类中最简代表是对角矩阵","P 因题而异，不唯一"],"example":"两个相似于同一对角阵的矩阵彼此相似。"},
  "kp-m1-p2-c5-xiang-si-bu-bian-liang": {"anchor":"A∽B ⇒ f_A(λ)=f_B(λ)","caption":"相似矩阵必同享：行列式、迹、秩、特征多项式与全部特征值（连带代数重数）；这些不变量常用来「反求相似中的参数」或判不相似。","keyPoints":["|A|=|B|、tr(A)=tr(B)、r(A)=r(B)","特征多项式相同 ⇒ 特征值相同","不变量不同 ⇒ 必不相似（逆否使用）"],"example":"A∽B 且 tr 差 1 ⇒ 题目给的 P 里藏参数，用 tr 列方程。"},
  "kp-m1-p2-c5-ke-dui-jiao-hua-de-ding-yi": {"anchor":"P⁻¹AP=Λ=diag(λ₁,…,λₙ)","caption":"A 可（相似）对角化：存在可逆 P 使 P⁻¹AP=Λ 为对角阵；","keyPoints":["可对角化 ⇔ 有 n 个无关特征向量","P=(α₁,…,αₙ) 按列放特征向量","Λ 对角元 = 对应特征值（顺序一致）"],"example":"特征值 1、2 各出一个特征向量：P=(α₁ α₂)，Λ=diag(1,2)。"},
  "kp-m1-p2-c5-n-ge-xian-xing-wu-guan-te-zheng-xiang-1tmz15": {"anchor":"Σ几何重数=n ⇔ 可对角化","caption":"A 可对角化 ⇔ A 有 n 个线性无关的特征向量 ⇔ 每个特征值的几何重数等于代数重数；不同特征值的特征向量天然无关，重根是唯一要小心的地方。","keyPoints":["充要：n 个线性无关特征向量","等价说法：每个 λ 的几何重数=代数重数","无重根 ⇒ 必可对角化"],"example":"三阶、特征值 1（单）、2（二重且几何重数 2）⇒ 可对角化。"},
  "kp-m1-p2-c5-bu-tong-te-zheng-zhi-dui-ying-te-zheng-1p0ge9": {"anchor":"λᵢ≠λⱼ ⇒ αᵢ、αⱼ 无关","caption":"定理：属于不同特征值的特征向量线性无关；推广版本是「k 个不同特征值各取若干个无关特征向量，合起来仍无关」——它是组装可逆 P 的合法性来源。","keyPoints":["不同特征值的特征向量必无关","推广：分组无关则并组无关","由此单根自动贡献一个无关向量"],"example":"三个不同特征值各取一个特征向量：必无关，直接组成 P。"},
  "kp-m1-p2-c5-zhong-gen-qing-xing-de-pan-duan": {"anchor":"n−r(A−λE)=k ⇔ 该 k 重根合格","caption":"k 重特征根能否对角化，看它的几何重数（无关特征向量个数 n−r(A−λE)）是否等于 k；每个重根都「跟上了」，才可对角化。","keyPoints":["几何重数 = n−r(A−λE)","几何重数=k（=代数重数）⇒ 该根合格","有一个不合格 ⇒ 不可对角化"],"example":"二重根 λ=2、r(A−2E)=2 ⇒ 几何重数 1≠2，不可对角化。"},
  "kp-m1-p2-c5-te-zheng-zhi-jun-wei-shi-shu": {"anchor":"A=Aᵀ、A 实 ⇒ λ∈R","caption":"实对称矩阵的特征值全部是实数：由 ᾱᵀAα=λ̄ᾱᵀα 与对称性比较即得；这保证了实对称矩阵可以在实数范围内完成全部对角化讨论。","keyPoints":["实对称 ⇒ 特征值全实","复根只会出现在非对称实矩阵上","配套：特征向量可取实向量"],"example":"实对称阵的特征多项式根全实（如 ±√2 而非 ±i）。"},
  "kp-m1-p2-c5-bu-tong-te-zheng-zhi-de-te-zheng-xiang-1txjy1": {"anchor":"(Aα,β)=(α,Aβ)（对称性）","caption":"实对称矩阵属于不同特征值的特征向量自动正交：(Aα)=λα、(Aβ)=μβ（λ≠μ）推出 λ(α,β)=(Aα,β)=(","keyPoints":["λ≠μ ⇒ (α,β)=0（实对称时）","同一特征值内部不保证正交","组 P 前需对重根内部施密特正交化"],"example":"λ=1、2 的特征向量 (1,1) 与 (1,−1) 正交。"},
  "kp-m1-p2-c5-yi-ding-ke-zheng-jiao-dui-jiao-hua": {"anchor":"QᵀQ=E 且 QᵀAQ=Λ","caption":"实对称矩阵必可正交对角化：存在正交矩阵 Q 使 QᵀAQ=Λ；","keyPoints":["实对称 ⇒ 存在正交 Q：QᵀAQ=Λ","步骤：特征值/向量 → 正交化 → 单位化","这是二次型正交变换法的引擎"],"example":"A=(2 1; 1 2)：特征向量 (1,1)、(1,−1) 正交，单位化拼 Q。"},
  "kp-m1-p2-c5-zheng-jiao-ju-zhen-q-man-zu-q-taq": {"anchor":"QᵀAQ=Λ","caption":"对实对称矩阵 A，存在正交矩阵 Q（列是单位正交的特征向量）使 QᵀAQ=Λ；Q 的求法与检验（QᵀQ=E）都是考试的标准动作。","keyPoints":["Q 由标准正交特征向量按列拼成","QᵀAQ=Λ 且 Q⁻¹=Qᵀ","Λ 对角元与 Q 列顺序一致"],"example":"Q=(1/√2)(1 1; 1 −1)：验证 QᵀQ=E。"},
  "kp-m1-p2-c6-er-ci-qi-ci-duo-xiang-shi": {"anchor":"f(x₁,…,xₙ)=Σaᵢᵢxᵢ²+2Σ_{i<j}aᵢⱼxᵢxⱼ","caption":"二次型是各变量次数之和恒为 2 的齐次多项式：平方项 xᵢ² 与交叉项 xᵢxⱼ 的组合，没有一次项与常数项；它是「变量的二次函数」的最简形态。","keyPoints":["只含平方项与交叉项（无一次项、常数项）","n 个变量的一般形式","对称矩阵表示是它的代数外衣"],"example":"f=x₁²+3x₁x₂+x₂² 是二次型；x₁²+x₁+1 不是（有一次项与常数项）。"},
  "kp-m1-p2-c6-f-x-tax": {"anchor":"f=xᵀAx，Aᵀ=A","caption":"二次型可写成矩阵形式 f=xᵀAx：x 是未知数列向量，A 是（实）对称矩阵——每给一个二次型就唯一确定一个对称矩阵，反之亦然。","keyPoints":["f=xᵀAx，A 为对称矩阵","A 的对角元 = 平方项系数","A 的非对角元 = 交叉项系数的一半"],"example":"f=x₁²+4x₁x₂+x₂² ⇒ A=(1 2; 2 1)（4 的一半 2 放两边）。"},
  "kp-m1-p2-c6-dui-chen-ju-zhen-biao-shi": {"anchor":"A=Aᵀ 且 f=xᵀAx","caption":"二次型的对称矩阵表示唯一：约定 A 必须对称后，f 的每种写法只对应一个 A；若不约定对称，同一个二次型能对应无穷多个矩阵——唯一性靠约定换来。","keyPoints":["约定对称 ⇒ 表示唯一","aᵢᵢ=平方项系数，aᵢⱼ=aⱼᵢ=交叉系数一半","由 f 读 A、由 A 还原 f 双向操作"],"example":"f=2x₁²−6x₁x₂ ⇒ A=(2 −3; −3 0)。"},
  "kp-m1-p2-c6-jiao-cha-xiang-xi-shu-yu-ju-zhen-yuan-1a99b1": {"anchor":"2aᵢⱼxᵢxⱼ（展开时自动出现）","caption":"交叉项 xᵢxⱼ 的系数 c 对应矩阵元素 aᵢⱼ=aⱼᵢ=c/2：因为对称矩阵的乘法会自动「加两次」（aᵢⱼ+aⱼᵢ）","keyPoints":["aᵢⱼ=c/2（c 是 xᵢxⱼ 的系数）","xᵀAx 中交叉项自动翻倍","反向读矩阵：2aᵢⱼ 才是交叉项系数"],"example":"交叉项 −2x₁x₃ ⇒ a₁₃=a₃₁=−1。"},
  "kp-m1-p2-c6-x-cy": {"anchor":"f=xᵀAx=(Cy)ᵀA(Cy)=yᵀ(CᵀAC)y","caption":"对二次型做可逆线性变换 x=Cy（C 可逆）：变量换了、二次型跟着换 f=yᵀ(CᵀAC)y；「可逆」保证变换能来回走、不丢信息。","keyPoints":["x=Cy，要求 C 可逆","新矩阵 B=CᵀAC","秩不变（可逆变换不降秩）"],"example":"x₁=y₁+y₂、x₂=y₁−y₂：写出 C 再算 B。"},
  "kp-m1-p2-c6-b-c-tac": {"anchor":"B=CᵀAC","caption":"线性变换 x=Cy 下二次型矩阵从 A 变成 B=CᵀAC：这种关系叫合同；「Cᵀ 在左、C 在右」与相似（P⁻¹ 在左）结构不同、别混写。","keyPoints":["B=CᵀAC（C 可逆）⇔ A 与 B 合同","与相似 P⁻¹AP 记号区分","合同变换保持惯性指数"],"example":"C=E 时 B=A（恒等变换）；C 换列时 B 是 A 的对称重排。"},
  "kp-m1-p2-c6-he-tong-ju-zhen": {"anchor":"B=CᵀAC，C 可逆","caption":"A 与 B 合同：存在可逆 C 使 B=CᵀAC（要求 A、B 对称）；","keyPoints":["合同：B=CᵀAC（对称矩阵间）","相似关系满足自反、对称、传递三条","合同 ⇔ 正负惯性指数对应相等"],"example":"A 与其标准形矩阵合同；实对称矩阵按惯性指数分类。"},
  "kp-m1-p2-c6-er-ci-xing-zhi-dui-ying-ju-zhen-de-zhi": {"anchor":"r(f)=r(A)","caption":"二次型的秩定义为其对称矩阵的秩：合同变换不改变秩，所以无论怎么化简，秩是不变量——它等于标准形中「非零平方项」的个数。","keyPoints":["二次型的秩 r(f)=r(A)，即标准形非零项个数","合同变换保持秩不变，规范形项数稳定","标准形中非零项个数 = r(f)"],"example":"A 秩为 2 ⇒ 标准形只有两个非零平方项。"},
  "kp-m1-p2-c6-biao-zhun-xing": {"anchor":"f=d₁y₁²+d₂y₂²+…","caption":"标准形：只含平方项（无交叉项）的二次型 Σdᵢyᵢ²；任何二次型都能经可逆线性变换化为标准形——配方法与正交变换法是两条路。","keyPoints":["标准形：Σdᵢyᵢ²（系数任意实数）","不唯一（系数随变换变化）","非零系数个数 = 秩（不变）"],"example":"f=x₁²+2x₁x₂+x₂² 配方成 (x₁+x₂)²=y₁²，标准形只有一项。"},
  "kp-m1-p2-c6-gui-fan-xing": {"anchor":"f=y₁²+…+y_p²−y_{p+1}²−…−y_{p+q}²","caption":"规范形：标准形的进一步规范——非零系数全部变成 +1 或 −1：f=y₁²+…+y_p²−y_{p+1}²−…−y_{p","keyPoints":["系数只取 1、−1、0","正项 p 个、负项 q 个","规范形唯一（实二次型）"],"example":"标准形 4y₁²−9y₂² ⇒ 规范形 y₁²−y₂²（p=q=1）。"},
  "kp-m1-p2-c6-zheng-guan-xing-zhi-shu": {"anchor":"p=#{λᵢ>0}","caption":"正惯性指数 p：标准形（或规范形）中正系数平方项的个数；它由二次型本身唯一决定（惯性定理），与用哪种方法化简无关。","keyPoints":["p = 正平方项个数","p = 正特征值的个数（正交变换下）","p 是合同分类的核心不变量"],"example":"特征值 2、−1、0：p=1、q=1。"},
  "kp-m1-p2-c6-fu-guan-xing-zhi-shu": {"anchor":"r(f)=p+q","caption":"负惯性指数 q：标准形中负系数平方项的个数；p−q 是符号差、p+q 是秩，三个数（p、q、n−p−q）共同给出规范形的全部信息。","keyPoints":["q = 负平方项个数 = 负特征值个数","二次型的秩 r=p+q，正负项个数之和","符号差 s=p−q（合同不变量）"],"example":"λ=1、1、−2：p=2、q=1、r=3。"},
  "kp-m1-p2-c6-ling-xiang-shu": {"anchor":"零项数=n−(p+q)=n−r(A)","caption":"规范形中系数为 0 的项数 = n−p−q，等于 n 减去矩阵的秩；它衡量二次型「退化」的程度——零项越多，二次型越「瘪」。","keyPoints":["零项数 = n−r(A)","由 r(A)=p+q 反推：零项数 =n−p−q","零项数>0 ⇔ A 不可逆"],"example":"n=3、p=1、q=1：零项 1 个，A 不可逆。"},
  "kp-m1-p2-c6-ke-ni-xian-xing-bian-huan-xia-zheng-fu-09uqjn": {"anchor":"合同 ⇒ p、q 对应相等","caption":"惯性定理：无论用哪种可逆线性变换化标准形，正、负惯性指数 p、q 都不变——系数可以千变万化，正负项的「个数」是二次型的签名。","keyPoints":["p、q 是合同不变量","不同方法化出的标准形 p、q 相同","惯性指数不变，所以规范形因此唯一"],"example":"配方法得 2y₁²−y₂²、正交变换法得 3z₁²−z₂²：p、q 都=1、1。"},
  "kp-m1-p2-c6-pei-fang-fa": {"anchor":"ax²+2bxy+cy²=a(x+b/a·y)²+(c−b²/a)y²","caption":"配方法化标准形：每次围绕一个「有平方项」的变量把含它的项配成完全平方，换元后交叉项减少一个；","keyPoints":["配方法逐变量配方消交叉项，每次少一项","无平方项先作差和换元造出平方项","变换写成 x=Cy 便于验可逆"],"example":"f=x₁²+2x₁x₂+3x₂²=(x₁+x₂)²+2x₂²。"},
  "kp-m1-p2-c6-zheng-jiao-bian-huan-fa": {"anchor":"f=λ₁y₁²+λ₂y₂²+…","caption":"正交变换法：求实对称矩阵 A 的特征值 λᵢ 与单位正交特征向量，用 x=Qy 变换后 f=Σλᵢyᵢ²——标准形系数恰","keyPoints":["x=Qy，Q 正交（QᵀQ=E）","标准形系数 = 特征值 λᵢ","p=正特征值个数、q=负特征值个数"],"example":"A 特征值 3、−1：正交变换下 f=3y₁²−y₂²。"},
  "kp-m1-p2-c6-zheng-ding-ding-yi": {"anchor":"xᵀAx>0（∀x≠0）","caption":"正定二次型：对任意非零向量 x 都有 f(x)=xᵀAx>0（对称 A）；几何上 f=1 的等值面是椭球面——「除原点外处处向上」。","keyPoints":["∀x≠0：xᵀAx>0 ⇔ 正定","正定 ⇒ A 对称且可逆","负定的定义关于 f<0 对称成立"],"example":"f=x₁²+x₂² 正定；f=x₁²−x₂² 不正定（x=(0,1) 时为负）。"},
  "kp-m1-p2-c6-te-zheng-zhi-pan-bie": {"anchor":"A 正定 ⇔ λᵢ>0 ∀i","caption":"正定的特征值判别法：A 正定 ⇔ A 的特征值全部大于 0；由正交变换 f=Σλᵢyᵢ² 一眼看出——各方向都「向上」等价于各方向伸缩率都正。","keyPoints":["正定 ⇔ λᵢ>0（全部）","负定 ⇔ λᵢ<0（全部）","半正定 ⇔ λᵢ≥0 且有 0"],"example":"特征值 1、2、3：正定；1、0、2：半正定不正定。"},
  "kp-m1-p2-c6-shun-xu-zhu-zi-shi-pan-bie": {"anchor":"Δₖ=|Aₖ|>0（k=1,…,n）","caption":"顺序主子式判别法：A 正定 ⇔ 各阶顺序主子式（左上角 1 到 n 阶行列式）全部大于 0；它免去了求特征值，是手算正定判别的主力。","keyPoints":["Δ₁>0、Δ₂>0、…、Δₙ>0 ⇔ 正定","只看「顺序」主子式（左上角）","负定对应「奇负偶正」的推广判据"],"example":"A=(2 1; 1 2)：Δ₁=2、Δ₂=3，都正 ⇒ 正定。"},
  "kp-m1-p2-c6-fu-ding-ban-zheng-ding-zuo-wei-kuo-zhan-12r70b": {"anchor":"f=x₁²−x₂² 是不定型（有正有负）","caption":"辨析：负定 ⇔ −A 正定（奇数阶顺序主子式 <0、偶数阶 >0）；半正定 ⇔ 特征值 ≥0（允许 0）⇔ 所有主子式 ≥0；正定是其中要求最严的。","keyPoints":["负定 ⇔ −A 正定 ⇔ λᵢ<0","半正定 ⇔ λᵢ≥0（允许取 0）","不正定 ≠ 负定（还可能不定）"],"example":"特征值 2、0：半正定；特征值 2、−1：不定。"},
  "kp-m1-p2-c6-jiang-er-wei-er-ci-xing-hua-cheng-tuo-1sftxk": {"anchor":"λ₁y₁²+λ₂y₂²=c 的形状由 λ 符号决定","caption":"二维二次型 f 的等值线 f=c 的形状由惯性指数决定：p=2 正定 → 椭圆；p=1 → 双曲线；","keyPoints":["p=2：椭圆（正定）","p=1：双曲线（不定）","p=0：空集或点（负定/退化）"],"example":"f=x²+4y² 的等值线是椭圆；f=x²−4y² 是双曲线。"},
  "kp-m1-p2-c6-zheng-jiao-bian-huan-dong-hua-zhong-0bbka5": {"anchor":"x=Qy（Q 旋转矩阵）","caption":"正交变换的几何形象是「旋转（或反射）坐标轴」：把轴转到特征向量方向后，交叉项 xy 消失、只剩平方项——曲线本身没变，只是换了描述角度。","keyPoints":["正交变换 = 旋转/反射坐标轴","新轴方向 = 特征向量方向","消去交叉项后 f=λ₁y₁²+λ₂y₂²"],"example":"f=x²+xy+y² 转轴 45° 后消去 xy 项，变成纯平方和与差。"},
  "kp-m1-p2-c6-zheng-ding-shi-zhan-shi-chu-yuan-dian-0cuwv1": {"anchor":"x≠0 ⇒ f(x)>0","caption":"正定二次型的图像是一个开口向上的「碗」：除原点（最小值 0）外，任何方向走一步函数值都严格为正——等值线是环绕原点的一圈圈椭圆。","keyPoints":["正定 ⇒ f 最小值 0 在原点","等值线 f=c（c>0）是一族椭圆","碗口方向没有「下坡」"],"example":"f=x²+y² 的图像是旋转抛物面碗，正定的标准形象。"},
  "kp-m1-p3-c1-sui-ji-shi-yan": {"anchor":"随机试验 = 可重复 + 结果不唯一 + 事前不可预言","caption":"随机试验要同时满足三条：条件可重复、结果不止一个、试验前无法确定哪一个结果会出现。","keyPoints":["可重复：在相同条件下能反复做同一次试验，这是谈概率的前提","结果不唯一：所有可能结果事先能列出来，只是不知道会出现哪一个","试验前不可预言：结果由偶然因素决定，而不是由已知条件唯一决定"],"example":"抛硬币记正反面是随机试验；解方程 2x=4 不是，因为结果唯一确定。"},
  "kp-m1-p3-c1-yang-ben-dian": {"anchor":"ω：一次试验的一个可能结果","caption":"样本点是试验的一个可能结果，用 ω 表示，它是样本空间里的「元素」。","keyPoints":["样本点对应一个不能再分的结果，再拆就没有意义了","一次试验只出现一个样本点，所以样本点之间互斥","不同试验的样本点不能混用，否则样本空间就对不上"],"example":"掷一颗骰子，ω=3 是一个样本点，六个样本点构成完整的样本空间。"},
  "kp-m1-p3-c1-yang-ben-kong-jian": {"anchor":"Ω={ω₁,ω₂,…,ωₙ}（有限情形）","caption":"样本空间是全部样本点构成的集合，记作 Ω，它是「全集」，任何事件都是它的子集。","keyPoints":["Ω 必须包含所有可能结果，漏一个就会让后面的概率之和不足 1","事件是 Ω 的子集，样本点是 Ω 的元素，两者层级不同","样本空间的粗细可以自己选，按题目关心的信息量决定"],"example":"抛两次硬币取 Ω={正正,正反,反正,反反}；若只关心正面个数，也可取 Ω={0,1,2}。"},
  "kp-m1-p3-c1-sui-ji-shi-jian": {"anchor":"A ⊆ Ω；A 发生 ⇔ ω ∈ A","caption":"随机事件就是样本空间的子集，也就是若干样本点凑成的一件事；事件发生当且仅当试验结果落在这个子集里。","keyPoints":["事件是集合，事件发生就是试验结果落在该集合内","Ω 是必然事件，∅ 是不可能事件，两者都是事件的极端情形","复合事件用集合运算表达，先翻译成集合再算概率"],"example":"掷骰子，A=「点数大于 3」={4,5,6}，是 Ω={1,…,6} 的子集。"},
  "kp-m1-p3-c1-bao-han": {"anchor":"A ⊂ B ⇒ P(A) ≤ P(B)","caption":"A ⊂ B 表示 A 的每个样本点都在 B 里：A 发生则 B 一定发生。","keyPoints":["A ⊂ B 等价于「A 发生必有 B 发生」，方向不能反","包含关系与概率大小没有必然联系，但一定给出不等式 P(A) ≤ P(B)","用包含关系常常能把复杂事件换成更好算的那个"],"example":"A=「点数为 6」，B=「点数为偶数」，A ⊂ B，故 1/6 = P(A) ≤ P(B) = 1/2。"},
  "kp-m1-p3-c1-xiang-deng": {"anchor":"A = B ⇔ A ⊂ B 且 B ⊂ A","caption":"A = B 当且仅当 A ⊂ B 且 B ⊂ A，也就是两个事件包含的样本点完全相同。","keyPoints":["相等要两个方向都验证，只验一个方向是不够的","判断的实用办法是化到「最简单的样本点集合」再比较","A = B 时概率一定相等，但概率相等推不出事件相等"],"example":"「点数大于 3」与「点数不小于 4」都等于 {4,5,6}，是同一个事件。"},
  "kp-m1-p3-c1-bing-jiao-cha": {"anchor":"A∪B、A∩B、A−B=A B̄","caption":"并 A∪B 表示「至少一个发生」，交 A∩B 表示「两个都发生」，差 A−B 表示「A 发生而 B 不发生」。","keyPoints":["A∪B 是「至少一个发生」，不是「恰好一个发生」","A∩B 是「同时发生」，与「至少一个」正好相对","A−B = A∩B̄，也就是 A 发生且 B 不发生"],"example":"A=「至少一次正面」，B=「两次都正面」：A∪B=A，A∩B=B，A−B=「恰有一次正面」。"},
  "kp-m1-p3-c1-dui-li-shi-jian": {"anchor":"A∪Ā=Ω，A∩Ā=∅，P(Ā)=1−P(A)","caption":"对立事件 Ā 就是「A 不发生」，满足 A∪Ā = Ω 且 A∩Ā = ∅。","keyPoints":["一个事件只有一个对立事件，而互斥事件可以有多个","对立要求并集恰为 Ω 且交集为空，缺一不可","P(Ā)=1−P(A) 是处理「至少」「至多」类问题的常用手段"],"example":"P(至少一次正面)=1−P(两次都反面)=1−1/4=3/4。"},
  "kp-m1-p3-c1-hu-chi-shi-jian": {"anchor":"A∩B=∅ ⇒ P(A∪B)=P(A)+P(B)","caption":"互斥指 A∩B = ∅，即两个事件不可能同时发生；但互斥并不要求它们的并集等于 Ω。","keyPoints":["A∩B=∅ 就是互斥，判断标准是看有没有公共样本点","互斥时并的概率等于概率之和，这是可加性最直接的应用","互斥与对立不等价：对立还要求两个事件合起来盖满 Ω"],"example":"掷骰子 A={1}、B={2} 互斥，但 A∪B={1,2}≠Ω，所以它们不对立。"},
  "kp-m1-p3-c1-de-mo-gen-l": {"anchor":"(A∪B)ᶜ=Ā∩B̄；(A∩B)ᶜ=Ā∪B̄","caption":"德摩根律讲「取非」如何穿过并和交：并的补等于补的交，交的补等于补的并。","keyPoints":["并的补等于各自补的交，交的补等于各自补的并","取非时并交必须互换，这是最容易漏的一步","多事件情形同样成立，可以整体取非再逐项拆"],"example":"「至少一次正面」的补是「两次都是反面」，用德摩根律一次就能写对。"},
  "kp-m1-p3-c1-fei-fu-xing": {"anchor":"P(A) ≥ 0，P(∅)=0","caption":"非负性规定任何事件的概率都大于等于 0，它给出概率的取值下界。","keyPoints":["对任意事件 A 都有 P(A) ≥ 0，出现负概率一定是算错了","不可能事件的概率为 0，但概率为 0 的事件未必是不可能事件","非负性与规范性合起来把概率限制在 [0,1] 内"],"example":"连续型随机变量取任一单点的概率都是 0，但「取到该点」并非不可能事件。"},
  "kp-m1-p3-c1-gui-fan-xing": {"anchor":"P(Ω)=1，P(Ā)=1−P(A)","caption":"规范性规定必然事件的概率为 1，即 P(Ω) = 1。","keyPoints":["P(Ω)=1，所有基本事件的概率之和必须等于 1","配合互补性得到 P(Ā)=1−P(A)","任何事件的概率都不会超过 1，超过就是样本空间或计算出了问题"],"example":"若 P(A)=0.3，则 P(Ā)=0.7，两者之和恰为 1。"},
  "kp-m1-p3-c1-ke-lie-ke-jia-xing-ji-ben-si-xiang": {"anchor":"AᵢAⱼ=∅（i≠j）⇒ P(∪Aᵢ)=ΣP(Aᵢ)","caption":"可列可加性说：若 A₁,A₂,… 两两互斥，则它们并的概率等于各自概率之和。","keyPoints":["只有两两互斥的事件列才能直接相加","不互斥时要用容斥公式把重复计算的部分减掉","把复杂事件拆成互斥小块是通用手法，拆分方式不唯一"],"example":"「恰有一次正面」拆成 {正反} 与 {反正}，两块互斥，概率相加得 1/2。"},
  "kp-m1-p3-c1-jia-fa-gong-shi": {"anchor":"P(A∪B)=P(A)+P(B)−P(AB)","caption":"加法公式 P(A∪B) = P(A) + P(B) − P(AB) 处理「至少一个发生」的概率，减掉的正是被重复计算的那部分。","keyPoints":["先加后减，减掉的是重复计算的交集部分","三事件要按「加单、减两两交、加三交」的顺序写全","互斥时交集为空，公式退化成概率直接相加"],"example":"P(A)=0.5、P(B)=0.4、P(AB)=0.2，则 P(A∪B)=0.5+0.4−0.2=0.7。"},
  "kp-m1-p3-c1-deng-ke-neng-ji-ben-shi-jian": {"anchor":"P(A)=k/n（有限等可能）","caption":"古典概型要求样本空间有限、且每个基本事件等可能，此时 P(A) 等于 A 包含的基本事件数除以基本事件总数。","keyPoints":["两个条件必须同时满足：样本空间有限 + 各基本事件等可能","概率 = 有利结果数 ÷ 总结果数，分子分母口径必须一致","等可能不成立时不能用这个公式，要回到条件概率或分布去算"],"example":"掷两颗骰子，点数和为 7 的概率是 6/36=1/6（36 种等可能结果）。"},
  "kp-m1-p3-c1-pai-lie-zu-he-ji-shu": {"anchor":"Aₙᵐ=n!/(n−m)!，Cₙᵐ=n!/[m!(n−m)!]","caption":"排列组合是古典概型的计数工具：有顺序用排列，无顺序用组合，分步相乘、分类相加。","keyPoints":["有序用排列、无序用组合，判断依据是交换顺序是否算新结果","分步计数用乘法、分类计数用加法，两类不能混用","分子分母必须用同一套计数规则，否则比值没有意义"],"example":"从 5 人中选 2 人值日（无序）有 C₅²=10 种；若分正副班长（有序）则是 A₅²=20 种。"},
  "kp-m1-p3-c1-chang-du-mian-ji-ti-ji-bi": {"anchor":"P = m(目标区域) / m(总区域)","caption":"几何概型把「等可能」从有限个点换成区域上的均匀取值：概率等于目标区域的测度与总区域测度之比。","keyPoints":["概率 = 目标区域测度 ÷ 总区域测度，长度、面积、体积同理","总区域的测度必须有限，否则不能直接用比值定义概率","先把事件画成区域，再算两个测度，不要凭直觉猜比例"],"example":"在 [0,2] 上随机取一点，落在 [0.5,1.5] 内的概率是 1/2。"},
  "kp-m1-p3-c1-p-a-b-p-ab-p-b": {"anchor":"P(A|B)=P(AB)/P(B)（P(B)>0）","caption":"条件概率 P(A|B) = P(AB)/P(B) 的含义是：在已知 B 发生的条件下，样本空间被压缩到 B 内部，再看 A 占多少。","keyPoints":["分母 P(B) 必须大于 0，否则条件概率没有定义","P(A|B) 与 P(B|A) 一般不相等，方向不能随便换","条件概率本身也是概率，同样满足三条公理"],"example":"掷骰子，已知点数为偶数，求点数大于 3 的概率 = P({4,6})/P({2,4,6})=2/3。"},
  "kp-m1-p3-c1-liang-shi-jian-cheng-fa-gong-shi-p-ab-p-1byc6m": {"anchor":"P(AB)=P(B)P(A|B)=P(A)P(B|A)","caption":"乘法公式把「两个都发生」拆成两步：先让 B 发生，再在 B 已发生的条件下让 A 发生。","keyPoints":["先发生的作条件、后发生的作条件事件，顺序可以互换","P(AB)=P(B)P(A|B)=P(A)P(B|A)，挑好算的那个方向用","独立时退化成 P(A)P(B)，这时乘法最省事"],"example":"5 件产品中有 1 件次品，不放回取两件都合格的概率 =(4/5)(3/4)=3/5。"},
  "kp-m1-p3-c1-duo-shi-jian-cheng-fa-gong-shi": {"anchor":"P(A₁A₂…Aₙ)=P(A₁)P(A₂|A₁)…P(Aₙ|A₁…Aₙ₋₁)","caption":"多事件乘法公式把 P(A₁A₂…Aₙ) 写成一条链：先算第一个事件的概率，再算「在前面的都发生」条件下的第二个概率，依此类推逐项相乘。","keyPoints":["每一步的条件都是「前面的事件全部发生」","顺序可以调整，挑条件概率好算的顺序写","不放回抽样时样本量逐次递减，每一项的分母都要跟着改"],"example":"10 件产品中 3 件次品，不放回取 3 件都合格 =(7/10)(6/9)(5/8)=7/24。"},
  "kp-m1-p3-c1-gai-l-shu-yan-yi-tiao-lu-jing-xiang-14qtqw": {"anchor":"P(路径)=∏ 沿路条件概率","caption":"概率树把多步试验画成分层结构：每一层是一次选择，从根到叶的一条路径对应一种完整结果，路径概率等于沿路各条件概率之积。","keyPoints":["一条路径的概率 = 沿路各条件概率连乘","同一父节点下各分支的概率之和必须等于 1","不同路径互斥，求「或」时把相应路径的概率相加"],"example":"两次抽奖各有 1/2 中奖，「恰好一次中奖」有两条路径，各为 1/4，合计 1/2。"},
  "kp-m1-p3-c1-wan-bei-shi-jian-zu-yu-quan-ji-fen-jie": {"anchor":"AᵢAⱼ=∅（i≠j），∪Aᵢ=Ω","caption":"完备事件组 A₁,…,Aₙ 是一组两两互斥、并为 Ω 的事件，等价于把样本空间完整切开。","keyPoints":["两两互斥且并为全集，两个条件缺一不可","常用的划分维度是「原因」「来源」或「机器」","划分必须完整：漏掉一块，算出来的概率一定偏小"],"example":"某产品由甲、乙两条生产线制造，则 {甲线生产, 乙线生产} 构成完备事件组。"},
  "kp-m1-p3-c1-quan-gai-l-gong-shi-p-b-p-a-p-b-a": {"anchor":"P(B)=Σᵢ P(Aᵢ)P(B|Aᵢ)","caption":"全概率公式把事件 B 按完备事件组 Aᵢ 拆成互斥的几块，再逐块用乘法公式相加。","keyPoints":["三步走：分解原因 → 逐块相乘 → 全部相加","每一块都是「该原因发生且结果发生」的概率","结果概率一定介于各 P(B|Aᵢ) 的最小值与最大值之间，可用来验算"],"example":"甲线产 60%（次品率 2%）、乙线产 40%（次品率 5%），任取一件为次品的概率 =0.6×0.02+0.4×0.05=0.032。"},
  "kp-m1-p3-c1-fen-lei-hui-zong-an-yuan-yin-fen-zu-hou-1cnldc": {"anchor":"P(B)=Σ 各组内乘积","caption":"分类汇总是全概率公式的直觉版本：把结果按「它可能从哪里来」分组，组内用乘法算这一组的贡献，组与组之间用加法汇总。","keyPoints":["组内相乘、组间相加，这是全概率公式的通俗说法","分组必须互斥且完整，否则会重复计算或漏算","分组越细结果不变，但计算量会变大，选合适的粒度即可"],"example":"把「迟到」按「坐地铁 / 坐公交」分组，分别算出概率再相加。"},
  "kp-m1-p3-c1-bei-ye-si-gong-shi-p-a-b-p-a-p-b-a-p-b": {"anchor":"P(Aⱼ|B)=P(Aⱼ)P(B|Aⱼ)/ΣᵢP(Aᵢ)P(B|Aᵢ)","caption":"贝叶斯公式在观察到结果 B 之后，反过来更新对原因 Aⱼ 的判断：分子是「这条路径」的概率，分母是所有路径概率之和（通常由全概率公式算出）。","keyPoints":["分母是 P(B)，用全概率公式在所有原因上求和得到","先验概率 P(Aⱼ) 被结果 B 修正为后验概率","P(B|Aⱼ) 高于平均水平时后验大于先验，反之小于先验"],"example":"上例中若抽到次品，它来自乙线的概率 =0.4×0.05/0.032=0.625。"},
  "kp-m1-p3-c1-hou-yan-gai-l": {"anchor":"P(Aⱼ|B) ∝ P(Aⱼ)P(B|Aⱼ)","caption":"后验概率是观察到结果之后重新计算的原因概率，它把先验概率和似然 P(B|A) 结合起来。","keyPoints":["后验 ∝ 先验 × 似然，三者构成贝叶斯公式的三块","证据的区分度越高，后验偏离先验越远","所有原因的后验概率之和必须等于 1，可用来验算"],"example":"检测灵敏度 95%、假阳性 5%、患病率 1% 时，阳性者真患病的后验约 16%。"},
  "kp-m1-p3-c1-fan-xiang-tui-duan-you-jie-guo-zhui-su-11l073": {"anchor":"P(原因|结果)=P(原因)P(结果|原因)/P(结果)","caption":"反向推断是先有结果、再问「最可能来自哪个原因」，属于贝叶斯公式的应用场景。","keyPoints":["正向是「原因→结果」，反向是「结果→原因」，所求量不同","反向推断必须借助全概率公式得到分母","所求通常是 P(原因|结果)，注意条件的写法"],"example":"「已知机器报警，求确实发生故障的概率」就是典型的反向推断。"},
  "kp-m1-p3-c1-liang-shi-jian-du-li": {"anchor":"P(AB)=P(A)P(B)","caption":"A 与 B 独立指 P(AB) = P(A)P(B)，当 P(B) > 0 时等价于 P(A|B) = P(A)。","keyPoints":["定义式是 P(AB)=P(A)P(B)，判断独立就验这一个式子","等价形式 P(A|B)=P(A) 更直观：条件不改变概率","独立与互斥是两个不同概念，不能互相推"],"example":"抛两次硬币，「第一次正面」与「第二次正面」独立：概率 =1/2×1/2=1/4。"},
  "kp-m1-p3-c1-duo-shi-jian-du-li": {"anchor":"P(Aᵢ₁…Aᵢₖ)=∏P(Aᵢⱼ)，1≤k≤n","caption":"n 个事件相互独立要求任意 k 个（k = 2,…,n）事件交的概率都等于各自概率之积，只验证两两独立是不够的。","keyPoints":["要验证所有 k 元子集（k≥2），不能只看两两","两两独立推不出相互独立，反之一定成立","考试里常给「两两独立但不相互独立」的反例来设陷阱"],"example":"存在三个事件两两独立，但 P(ABC) ≠ P(A)P(B)P(C)，说明两两独立不够。"},
  "kp-m1-p3-c1-du-li-yu-hu-chi-de-qu-bie": {"anchor":"互斥：A∩B=∅；独立：P(AB)=P(A)P(B)","caption":"互斥说的是「不能同时发生」（A∩B = ∅），独立说的是「发生与否互不影响」（P(AB) = P(A)P(B)）。","keyPoints":["互斥是集合不相交，独立是概率可乘，出发点不同","P(A)>0 且 P(B)>0 时，互斥与独立互相排斥","判断时先问「能不能同时发生」，再用乘积式检验独立"],"example":"抛一次硬币，{正面} 与 {反面} 互斥但不独立：P(正反)=0 ≠ 1/4。"},
  "kp-m1-p3-c2-ding-yi": {"anchor":"X=X(ω)，ω∈Ω","caption":"随机变量是把样本空间上的每个结果映射成一个实数的函数，记作 X=X(ω)。","keyPoints":["X 是定义在样本空间上的函数，不是普通的未知数","取值随试验结果而定，事前只知道取值范围","按取值集合分为离散型（有限或可列）与连续型（充满区间）"],"example":"掷两颗骰子，X=「点数之和」把 36 个结果映射到 2~12 的整数。"},
  "kp-m1-p3-c2-li-san-xing-lian-xu-xing": {"anchor":"离散：P{X=xᵢ}=pᵢ；连续：P(a<X≤b)=∫ₐᵇf(x)dx","caption":"离散型的取值是有限个或可列个，用分布律描述；连续型的取值充满一个区间，用概率密度描述。","keyPoints":["离散型用分布律 P{X=xᵢ}=pᵢ 描述，可逐点相加","连续型用密度描述，任一点的概率都是 0","混合型两者兼有，考研很少考但要能识别"],"example":"掷骰子的点数 X 是离散型；等车时间 T 是连续型。"},
  "kp-m1-p3-c2-f-x-p-x-x": {"anchor":"F(x)=P{X≤x}","caption":"分布函数 F(x)=P{X≤x} 表示 X 落在 x 左边的累积概率，对离散型和连续型都适用","keyPoints":["F(x) 是累积概率，右端含 x（≤ 不是 <）","离散型的 F 是阶梯函数，跳跃高度恰为该点的概率","连续型的 F 处处连续，且在密度连续点满足 F′=f"],"example":"掷骰子 X 的分布函数在 [1,6] 上呈阶梯：F(3.5)=P{X≤3}=1/2。"},
  "kp-m1-p3-c2-dan-diao-bu-jian": {"anchor":"x₁<x₂ ⇒ F(x₁)≤F(x₂)；P(a<X≤b)=F(b)−F(a)","caption":"分布函数单调不减：x₁<x₂ 时必有 F(x₁)≤F(x₂)，因为 {X≤x₁} 是 {X≤x₂} 的子集。","keyPoints":["x₁<x₂ ⇒ F(x₁)≤F(x₂)，累积概率不会变小","由此得到 P(a<X≤b)=F(b)−F(a)","单调不减 + 右连续 + 两端极限，是分布函数的充要条件"],"example":"若 F(2)=0.4、F(5)=0.9，则 P(2<X≤5)=0.9−0.4=0.5。"},
  "kp-m1-p3-c2-you-lian-xu": {"anchor":"F(x+0)=F(x)；P{X=x₀}=F(x₀)−F(x₀−0)","caption":"分布函数在每一点右连续：F(x+0)=F(x)。","keyPoints":["F(x+0)=F(x)，右连续是定义的一部分","离散型在跳点处左极限小于函数值，差值就是该点的概率","连续型不存在跳跃，左极限与函数值相等"],"example":"F(x)=1（x≥0）、0（x<0）在 0 点右连续，且 P{X=0}=1−0=1。"},
  "kp-m1-p3-c2-ji-xian-xing-zhi": {"anchor":"F(−∞)=0，F(+∞)=1","caption":"分布函数在两端有固定极限：F(−∞)=0、F(+∞)=1，它保证概率总和为 1。","keyPoints":["F(−∞)=0：往左累积到 0","F(+∞)=1：往右累积到 1","含参数的分布函数常靠这两条定常数"],"example":"若 F(x)=a+b·arctan x 是分布函数，由两端极限可解得 a=1/2、b=1/π。"},
  "kp-m1-p3-c2-fen-bu-l": {"anchor":"P{X=xᵢ}=pᵢ，Σpᵢ=1","caption":"分布律是离散型随机变量的取值与概率的对应表：P{X=xᵢ}=pᵢ，要求 pᵢ≥0 且所有 pᵢ 之和为 1。","keyPoints":["每条概率非负，且全部相加等于 1","分布律是离散型的完整描述，区间概率由它逐点累加","求分布律的关键是先把取值列全，再逐点算概率"],"example":"掷两枚硬币，X=正面个数：P{X=0}=1/4、P{X=1}=1/2、P{X=2}=1/4。"},
  "kp-m1-p3-c2-gai-l-zhi-liang-han-shu-si-xiang": {"anchor":"Σpᵢ=1（离散型的质量守恒）","caption":"概率质量函数把总概率 1 看作单位质量，按 pᵢ 分配到各个取值点上，某点的概率就是那一点的质量。","keyPoints":["总质量恒为 1，各点质量之和就是 1","某点概率等于该点的质量，可以直接读出来","连续型把质量铺在区间上，单点质量趋于 0"],"example":"不均匀硬币 P{正}=0.7，相当于把 0.7 的质量堆在「正」上。"},
  "kp-m1-p3-c2-0-1-fen-bu": {"anchor":"P{X=1}=p，P{X=0}=1−p，X~B(1,p)","caption":"0-1 分布描述只有两种结果的单次试验：P{X=1}=p、P{X=0}=1−p，记作 X~B(1,p)。","keyPoints":["只有 0 与 1 两个取值，参数只有一个 p","E(X)=p，D(X)=p(1−p)","它是 n=1 的二项分布，是伯努利试验的基本单元"],"example":"抛一次硬币，记正面为 1，则 X~B(1,1/2)。"},
  "kp-m1-p3-c2-er-xiang-fen-bu": {"anchor":"P{X=k}=Cₙᵏpᵏ(1−p)ⁿ⁻ᵏ，X~B(n,p)","caption":"二项分布 X~B(n,p) 描述 n 次独立重复试验中「成功」的次数：P{X=k}=Cₙᵏpᵏ(1−p)ⁿ⁻ᵏ。","keyPoints":["组合数 Cₙᵏ 来自「哪 k 次成功」，不能漏","三个前提：次数固定、各次独立、每次 p 相同","E(X)=np，D(X)=np(1−p)"],"example":"掷 5 次骰子，恰出现 2 次 6 点的概率 = C₅²(1/6)²(5/6)³。"},
  "kp-m1-p3-c2-bo-song-fen-bu": {"anchor":"P{X=k}=λᵏe^(−λ)/k!，E(X)=D(X)=λ","caption":"泊松分布 X~P(λ) 描述单位时间或单位面积内稀有事件发生的次数：P{X=k}=λᵏe^(−λ)/k!","keyPoints":["P{X=k}=λᵏe^(−λ)/k!，k 从 0 开始取遍非负整数","E(X)=D(X)=λ，这是它最好认的特征","二项分布 n 大 p 小时用 λ=np 作泊松近似"],"example":"某机器每小时平均故障 2 次，则 1 小时内故障 3 次的概率 = 2³e⁻²/3!。"},
  "kp-m1-p3-c2-chang-jian-mo-xing-shi-bie-yu-can-shu-15mdgo": {"anchor":"二项 B(n,p) / 泊松 P(λ) / 几何 G(p) / 超几何 H(N,M,n)","caption":"识别模型看三件事：试验结构（单次、重复、单位时间）、取值类型、参数的实际含义。","keyPoints":["二项分布：n 次独立重复、p 不变，问成功次数","泊松分布：单位时间内的稀有次数，参数是平均次数 λ","几何分布：首次成功所需次数；超几何分布：不放回抽取中的次品数"],"example":"「10 件产品有 2 件次品，不放回取 3 件，求次品数」用超几何分布，不是二项分布。"},
  "kp-m1-p3-c2-gai-l-mi-du": {"anchor":"f(x)≥0，∫₋∞^∞f(x)dx=1","caption":"概率密度 f(x) 满足 f(x)≥0 且 ∫f(x)dx=1，它本身不是概率，而是概率的密度：某区间上的概率等于密度在该区间上的积分。","keyPoints":["f(x)≥0，且全轴积分为 1","概率是密度的积分，不是密度值本身","密度可以大于 1，但概率永远不超过 1"],"example":"f(x)=2x（0<x<1）是密度，因为 ∫₀¹2x dx=1。"},
  "kp-m1-p3-c2-mi-du-yu-fen-bu-han-shu-guan-xi": {"anchor":"F(x)=∫₋∞ˣf(t)dt，F′(x)=f(x)","caption":"连续型里分布函数与密度互为积分与导数：F(x)=∫₋∞ˣf(t)dt，且在密度的连续点有 F′(x)=f(x)。","keyPoints":["F(x)=∫₋∞ˣf(t)dt，分段密度要按定义域拆开积分","在密度连续点处 F′(x)=f(x)","分段求 F 时每段都要从 −∞ 积到 x，累积不能丢"],"example":"f(x)=2x（0<x<1）：x≤0 时 F=0，0<x<1 时 F=x²，x≥1 时 F=1。"},
  "kp-m1-p3-c2-qu-jian-gai-l": {"anchor":"P(a<X<b)=∫ₐᵇf(x)dx=F(b)−F(a)","caption":"连续型随机变量在任意一点的概率都是 0，所以 P(a<X<b)、P(a≤X≤b)、P(a<X≤b) 完全相等","keyPoints":["单点概率为 0，端点的开闭不影响结果","P(a<X<b) 等于密度在该区间上的积分","离散型必须区分端点，两类型不能混用"],"example":"X~U(0,1) 时 P(0.2<X≤0.7)=0.5。"},
  "kp-m1-p3-c2-jun-yun-fen-bu": {"anchor":"f(x)=1/(b−a)（a<x<b）","caption":"均匀分布 X~U(a,b) 指 X 在 (a,b) 内取值，且落在等长小区间里的概率相同，密度是常数 1/(b−a)。","keyPoints":["密度 f(x)=1/(b−a)（a<x<b），区间外为 0","概率等于长度比：P(c<X<d)=(d−c)/(b−a)","E(X)=(a+b)/2，D(X)=(b−a)²/12"],"example":"X~U(2,5)，则 P(X>3)=(5−3)/(5−2)=2/3。"},
  "kp-m1-p3-c2-zhi-shu-fen-bu": {"anchor":"f(x)=λe^(−λx)，F(x)=1−e^(−λx)，E(X)=1/λ","caption":"指数分布 X~E(λ) 常用来描述等待时间或寿命，密度 f(x)=λe^(−λx)（x>0）","keyPoints":["f(x)=λe^(−λx)（x>0），F(x)=1−e^(−λx)","E(X)=1/λ，D(X)=1/λ²","无记忆性：P(X>s+t | X>s)=P(X>t)"],"example":"平均寿命 5 年（λ=1/5），寿命超过 10 年的概率 = e^(−2)≈0.135。"},
  "kp-m1-p3-c2-zheng-tai-fen-bu": {"anchor":"f(x)=(1/(√(2π)σ))·e^(−(x−μ)²/(2σ²))","caption":"正态分布 X~N(μ,σ²) 由均值 μ 与方差 σ² 完全确定，密度关于 x=μ 对称并在 μ 处取最大值；μ 决定位置、σ 决定胖瘦。","keyPoints":["X~N(μ,σ²)，两个参数分别是均值和方差","密度关于 x=μ 对称，故 P(X≤μ)=1/2","σ 越大曲线越平缓，取值越分散"],"example":"X~N(1,4)：μ=1、σ=2，所以 P(X≤1)=1/2。"},
  "kp-m1-p3-c2-biao-zhun-zheng-tai-fen-bu": {"anchor":"Φ(−x)=1−Φ(x)，Φ(0)=1/2","caption":"标准正态分布 N(0,1) 的分布函数记作 Φ(x)，它满足 Φ(−x)=1−Φ(x) 且 Φ(0)=1/2。","keyPoints":["Φ(x)=P{Z≤x}，其中 Z~N(0,1)","对称性 Φ(−x)=1−Φ(x)，这是最常用的一条","Φ(0)=1/2，且 P(|Z|≤a)=2Φ(a)−1"],"example":"P(Z≤−1.5)=1−Φ(1.5)=1−0.9332=0.0668。"},
  "kp-m1-p3-c2-biao-zhun-hua": {"anchor":"Z=(X−μ)/σ ~ N(0,1)；P(a<X<b)=Φ((b−μ)/σ)−Φ((a−μ)/σ)","caption":"标准化把任意正态分布化成标准正态：Z=(X−μ)/σ ~ N(0,1)，于是 P(X≤a)=Φ((a−μ)/σ)","keyPoints":["Z=(X−μ)/σ，减均值、除以标准差（不是方差）","P(X≤a)=Φ((a−μ)/σ)","区间概率化成两个 Φ 值之差"],"example":"X~N(2,9)，则 P(X≤5)=Φ((5−2)/3)=Φ(1)=0.8413。"},
  "kp-m1-p3-c2-fen-bu-han-shu-fa": {"anchor":"F_Y(y)=P{g(X)≤y}=P{X∈g⁻¹((−∞,y])}","caption":"求 Y=g(X) 的分布用分布函数法：先写 F_Y(y)=P{g(X)≤y}，再把不等式解成关于 X 的范围，最后用 X 的分布算出概率。","keyPoints":["第一步永远是写 F_Y(y)=P{g(X)≤y}，不要急着求导","把不等式化成 X 的区间后，代回 F_X 或对密度积分","要分段讨论 g 的单调性，并先确定 y 的取值范围"],"example":"X~U(0,1)、Y=X²：F_Y(y)=P{X≤√y}=√y（0<y<1），故 f_Y(y)=1/(2√y)。"},
  "kp-m1-p3-c2-dan-diao-bian-huan-gong-shi-si-xiang": {"anchor":"f_Y(y)=f_X(g⁻¹(y))·|(g⁻¹)′(y)|","caption":"当 y=g(x) 严格单调且可导时，可以直接用 f_Y(y)=f_X(g⁻¹(y))·|(g⁻¹)′(y)| 求密度","keyPoints":["单调可导时 f_Y(y)=f_X(g⁻¹(y))·|dx/dy|","雅可比因子 |dx/dy| 不能漏","非单调函数（如 y=x²）要分段求分布再相加"],"example":"X~N(0,1)、Y=2X+1 单调，故 f_Y(y)=φ((y−1)/2)/2。"},
  "kp-m1-p3-c3-lian-he-fen-bu-han-shu": {"anchor":"F(x,y)=P{X≤x, Y≤y}","caption":"联合分布函数 F(x,y)=P{X≤x, Y≤y} 是两个变量同时落在左下区域的概率。","keyPoints":["F(x,y)=P{X≤x, Y≤y}，两个条件要同时成立","对每个变量都单调不减、右连续，且边界上 F(−∞,y)=F(x,−∞)=0","F(+∞,+∞)=1，边界值常用来定待定常数"],"example":"两次抛硬币记 X、Y 为两次结果，则 F(1,1)=P{X≤1,Y≤1}=1。"},
  "kp-m1-p3-c3-lian-he-fen-bu-l": {"anchor":"P{X=xᵢ, Y=yⱼ}=pᵢⱼ，ΣᵢΣⱼpᵢⱼ=1","caption":"联合分布律是 (X,Y) 取各对值的概率表：P{X=xᵢ, Y=yⱼ}=pᵢⱼ，要求每个 pᵢⱼ 非负且总和为 1。","keyPoints":["pᵢⱼ≥0 且所有 pᵢⱼ 之和等于 1","行和、列和分别是 X、Y 的边缘分布律","求任意事件的概率就是把对应的 pᵢⱼ 相加"],"example":"两次抛硬币，(X,Y) 的四对取值各为 1/4，总和为 1。"},
  "kp-m1-p3-c3-lian-he-mi-du": {"anchor":"P{(X,Y)∈D}=∬_D f(x,y)dxdy","caption":"联合密度 f(x,y) 满足非负且全平面二重积分为 1，区域 D 上的概率等于 f 在 D 上的二重积分，它描述概率在平面上的分布密度。","keyPoints":["f(x,y)≥0，且 ∬f(x,y)dxdy=1","P{(X,Y)∈D}=∬_D f(x,y)dxdy","密度值本身不是概率，某点的密度没有概率意义"],"example":"单位圆内 f=1/π 时，∬f=1 成立，说明系数正确。"},
  "kp-m1-p3-c3-li-san-qing-xing-qiu-he": {"anchor":"P{X=xᵢ}=Σⱼpᵢⱼ，P{Y=yⱼ}=Σᵢpᵢⱼ","caption":"求离散型的边缘分布律就是把联合分布律按行或按列求和：X 的边缘分布是每一行的和，Y 的是每一列的和。","keyPoints":["P{X=xᵢ}=Σⱼpᵢⱼ（按行求和），P{Y=yⱼ}=Σᵢpᵢⱼ（按列求和）","边缘分布由联合分布唯一决定","反过来不成立：相同的边缘分布可以对应不同的联合分布"],"example":"联合分布律各行均为 (1/4,1/4) 时，两个边缘分布都是 (1/2,1/2)。"},
  "kp-m1-p3-c3-lian-xu-qing-xing-ji-fen": {"anchor":"f_X(x)=∫₋∞^∞f(x,y)dy","caption":"连续型的边缘密度是把联合密度对另一个变量积分：f_X(x)=∫f(x,y)dy。","keyPoints":["f_X(x)=∫₋∞^∞f(x,y)dy，f_Y(y)=∫₋∞^∞f(x,y)dx","积分限要按「固定 x 时 y 的取值范围」写","边缘密度同样满足积分为 1"],"example":"f(x,y)=1（0<x<1,0<y<1）时，f_X(x)=∫₀¹1dy=1（0<x<1）。"},
  "kp-m1-p3-c3-tiao-jian-fen-bu-l": {"anchor":"P{X=xᵢ|Y=yⱼ}=pᵢⱼ/P{Y=yⱼ}","caption":"条件分布律是已知 Y=yⱼ 时 X 的分布：P{X=xᵢ|Y=yⱼ}=pᵢⱼ/P{Y=yⱼ}，分母是 Y 的边缘概率。","keyPoints":["P{X=xᵢ|Y=yⱼ}=pᵢⱼ/P{Y=yⱼ}，分母必须大于 0","条件分布律对 xᵢ 求和必须为 1","条件分布与边缘分布不同，方向也不能颠倒"],"example":"各行均为 (1/4,1/4) 时，P{X=0|Y=0}=(1/4)/(1/2)=1/2。"},
  "kp-m1-p3-c3-tiao-jian-mi-du": {"anchor":"f_{X|Y}(x|y)=f(x,y)/f_Y(y)","caption":"连续型的条件密度是 f_{X|Y}(x|y)=f(x,y)/f_Y(y)（要求 f_Y(y)>0）。","keyPoints":["f_{X|Y}(x|y)=f(x,y)/f_Y(y)，分母是 Y 的边缘密度","条件密度对 x 积分为 1","X 与 Y 独立时条件密度退化为边缘密度"],"example":"f(x,y)=1（0<x,y<1）时 f_{X|Y}(x|y)=1，与 f_X(x)=1 相同，说明独立。"},
  "kp-m1-p3-c3-lian-he-fen-bu-fen-jie-tiao-jian": {"anchor":"f(x,y)=f_X(x)f_Y(y)；pᵢⱼ=pᵢ·p·ⱼ","caption":"X 与 Y 独立当且仅当联合分布等于边缘分布之积：离散型 P{X=xᵢ,Y=yⱼ}=P{X=xᵢ}P{Y=yⱼ}","keyPoints":["独立 ⇔ 联合分布 = 边缘分布的乘积","离散型与连续型各有一套写法，本质相同","只要有一对取值不满足乘积式，就不独立"],"example":"f(x,y)=1=1×1=f_X(x)f_Y(y)（0<x,y<1），故 X、Y 独立。"},
  "kp-m1-p3-c3-ji-ben-gai-nian": {"anchor":"均匀：f=1/S_D（(x,y)∈D）；正态：参数 (μ₁,μ₂,σ₁²,σ₂²,ρ)","caption":"二维均匀分布在区域 D 上密度为常数 1/S_D，概率就是面积比；二维正态分布由五个参数确定，密度曲面呈钟形，等值线是椭圆。","keyPoints":["二维均匀分布：概率等于面积比，密度为区域面积的倒数","二维正态由 μ₁、μ₂、σ₁²、σ₂²、ρ 五个参数确定","ρ 决定等值线椭圆的倾斜方向与扁平程度"],"example":"在单位圆内均匀取点，落在半径 1/2 的同心圆内的概率 =(π/4)/π=1/4。"},
  "kp-m1-p3-c3-er-wei-zheng-tai-de-xiang-guan-xing-yu-1li9xm": {"anchor":"二维正态：ρ=0 ⇔ 独立","caption":"二维正态分布有一条特别好的性质：X 与 Y 不相关（ρ=0）与它们独立是等价的。","keyPoints":["二维正态下 ρ=0 ⇔ X 与 Y 独立","两个边缘分布仍是正态，参数就是各自的 μ 与 σ²","X、Y 的线性组合仍服从正态分布"],"example":"(X,Y) 服从二维正态且 ρ=0 时，f(x,y)=f_X(x)f_Y(y) 成立。"},
  "kp-m1-p3-c3-x-y": {"anchor":"f_Z(z)=∫f(x,z−x)dx","caption":"求 Z=X+Y 的分布用分布函数法或卷积公式 f_Z(z)=∫f(x,z−x)dx。","keyPoints":["f_Z(z)=∫₋∞^∞f(x,z−x)dx，积分限由联合密度非零区域决定","独立时可写成 f_Z(z)=∫f_X(x)f_Y(z−x)dx","独立正态变量之和仍服从正态，参数相加"],"example":"两个独立标准正态变量之和服从 N(0,2)。"},
  "kp-m1-p3-c3-zui-da-zhi-zui-xiao-zhi": {"anchor":"F_max(z)=F_X(z)F_Y(z)；F_min(z)=1−[1−F_X(z)][1−F_Y(z)]","caption":"求 M=max(X,Y) 或 N=min(X,Y) 的分布用分布函数法：F_M(z)=P{X≤z, Y≤z}","keyPoints":["F_max(z)=P{X≤z,Y≤z}，独立时等于两个分布函数相乘","F_min(z)=1−[1−F_X(z)][1−F_Y(z)]（独立时）","n 个独立同分布变量的极值可同样推广"],"example":"两个独立 U(0,1) 变量的最大值：F_M(z)=z²，密度为 2z。"},
  "kp-m1-p3-c3-juan-ji-si-xiang": {"anchor":"f_{X+Y}(z)=∫f_X(x)f_Y(z−x)dx","caption":"卷积把「两个独立变量之和的密度」写成两个密度的积分叠加：f_Z(z)=∫f_X(x)f_Y(z−x)dx。","keyPoints":["卷积只对独立变量直接使用，不独立要回到联合密度","积分限由「两个密度同时非零」决定","常见结论：正态、泊松、Γ 分布的和仍属同族"],"example":"两个独立均匀分布之和的密度呈三角形。"},
  "kp-m1-p3-c4-li-san-xing-qi-wang": {"anchor":"E(X)=Σᵢ xᵢpᵢ","caption":"离散型期望 E(X)=Σxᵢpᵢ，是按概率加权的平均值，反映取值的中心位置。","keyPoints":["E(X)=Σxᵢpᵢ，权重就是各取值的概率","期望不一定是 X 的可能取值（骰子的期望是 3.5）","级数不绝对收敛时，期望不存在"],"example":"掷骰子：E(X)=(1+2+…+6)/6=3.5。"},
  "kp-m1-p3-c4-lian-xu-xing-qi-wang": {"anchor":"E(X)=∫₋∞^∞x f(x)dx","caption":"连续型期望 E(X)=∫xf(x)dx，把求和换成积分。","keyPoints":["E(X)=∫₋∞^∞x f(x)dx","积分限按密度非零的区间写，不要一律写 ±∞","关于原点对称的密度，其期望为 0（若存在）"],"example":"X~U(0,1)：E(X)=∫₀¹x dx=1/2。"},
  "kp-m1-p3-c4-sui-ji-bian-liang-han-shu-qi-wang": {"anchor":"E[g(X)]=∫g(x)f(x)dx","caption":"求 g(X) 的期望不必先求 g(X) 的分布，直接对原分布加权即可：E[g(X)]=Σg(xᵢ)pᵢ 或 ∫g(x)f","keyPoints":["E[g(X)]=Σg(xᵢ)pᵢ（离散）/ ∫g(x)f(x)dx（连续）","不需要先求出 g(X) 的分布","二维同理：E[g(X,Y)]=∬g(x,y)f(x,y)dxdy"],"example":"X~U(0,1) 时 E(X²)=∫₀¹x²dx=1/3。"},
  "kp-m1-p3-c4-qi-wang-xing-zhi": {"anchor":"E(aX+bY+c)=aE(X)+bE(Y)+c","caption":"期望最重要的性质是线性：E(aX+bY+c)=aE(X)+bE(Y)+c，**对任意 X、Y 都成立，不要求独立**。","keyPoints":["E(aX+bY+c)=aE(X)+bE(Y)+c，不需要独立性","E(XY)=E(X)E(Y) 需要独立或不相关","常数可以提出，且 E(C)=C"],"example":"E(2X−3Y+1)=2E(X)−3E(Y)+1，无需独立性。"},
  "kp-m1-p3-c4-ding-yi": {"anchor":"D(X)=E{[X−E(X)]²}","caption":"方差 D(X)=E{[X−E(X)]²} 衡量取值围绕均值的分散程度，它把偏离量平方后取期望，因此一定非负。","keyPoints":["D(X)=E{[X−E(X)]²}≥0，等于 0 说明 X 几乎处处为常数","标准差 σ=√D(X) 与 X 同量纲，比方差更直观","方差衡量分散程度，不衡量位置"],"example":"常数的方差为 0；两枚骰子之和的方差大于单枚骰子的方差。"},
  "kp-m1-p3-c4-d-x-e-x-e-x": {"anchor":"D(X)=E(X²)−[E(X)]²","caption":"计算方差常用 D(X)=E(X²)−[E(X)]²，它省去了构造 X−E(X) 的步骤：先算出 E(X) 与 E(X²) 两个数，相减即可。","keyPoints":["D(X)=E(X²)−[E(X)]²，右边两项分别计算","E(X²) 用 E[g(X)] 的公式算，不要与 [E(X)]² 混淆","离散型与连续型都适用这一式"],"example":"X~U(0,1)：E(X)=1/2、E(X²)=1/3，故 D(X)=1/3−1/4=1/12。"},
  "kp-m1-p3-c4-fang-cha-xing-zhi": {"anchor":"D(aX+b)=a²D(X)；D(X±Y)=D(X)+D(Y)（独立）","caption":"方差的性质：D(C)=0；D(aX+b)=a²D(X)，平移不改变方差、系数要平方；独立（或不相关）时 D(X±Y)=D(X)+D(Y)。","keyPoints":["D(aX+b)=a²D(X)，平移 b 不影响方差","独立或不相关时 D(X±Y)=D(X)+D(Y)，符号都是加","D(C)=0，常数没有分散性"],"example":"D(3X−2)=9D(X)；独立时 D(X−Y)=D(X)+D(Y)。"},
  "kp-m1-p3-c4-0-1": {"anchor":"E(X)=p，D(X)=p(1−p)","caption":"0-1 分布的期望等于成功概率 p，方差为 p(1−p)。","keyPoints":["E(X)=p，D(X)=p(1−p)","方差在 p=1/2 时最大，最大值为 1/4","它就是二项分布在 n=1 时的情形"],"example":"抛硬币记正面为 1：E=1/2，D=1/4。"},
  "kp-m1-p3-c4-er-xiang": {"anchor":"E(X)=np，D(X)=np(1−p)","caption":"二项分布 X~B(n,p) 的期望是 np、方差是 np(1−p)。","keyPoints":["E(X)=np，D(X)=np(1−p)","拆成 n 个独立 0-1 变量之和是最好用的推导方式","期望与方差都随 n 增大，方差还受 p 影响"],"example":"掷 100 次硬币的正面数：E=50，D=25。"},
  "kp-m1-p3-c4-bo-song": {"anchor":"E(X)=D(X)=λ","caption":"泊松分布 P(λ) 的期望与方差都等于 λ，这是它最显著的特征，常用来识别分布或由均值反推参数。","keyPoints":["E(X)=D(X)=λ，两者相等是泊松的标志","知道均值或方差中任一个就能确定 λ","与二项分布的近似关系：取 λ=np"],"example":"某路口每小时平均到达 5 辆车，则其方差也是 5。"},
  "kp-m1-p3-c4-jun-yun": {"anchor":"E(X)=(a+b)/2，D(X)=(b−a)²/12","caption":"均匀分布 U(a,b) 的期望是区间中点 (a+b)/2，方差是 (b−a)²/12。","keyPoints":["E(X)=(a+b)/2，即区间中点","D(X)=(b−a)²/12","区间长度翻倍，方差变为原来的 4 倍"],"example":"X~U(2,5)：E=3.5，D=9/12=0.75。"},
  "kp-m1-p3-c4-zhi-shu": {"anchor":"E(X)=1/λ，D(X)=1/λ²","caption":"指数分布 E(λ) 的期望是 1/λ、方差是 1/λ²。","keyPoints":["E(X)=1/λ，D(X)=1/λ²","λ 越大表示发生越频繁，平均等待越短","标准差等于期望，这是指数分布的特点"],"example":"平均寿命 5 年的元件：λ=1/5，E=5，D=25。"},
  "kp-m1-p3-c4-zheng-tai": {"anchor":"E(X)=μ，D(X)=σ²","caption":"正态分布 N(μ,σ²) 的两个参数恰好就是期望与方差：E(X)=μ、D(X)=σ²，这是正态分布最好记的一点。","keyPoints":["E(X)=μ，D(X)=σ²，参数即数字特征","σ 越大分布越分散，密度曲线越平缓","标准化后 Z=(X−μ)/σ 的期望为 0、方差为 1"],"example":"X~N(2,9)：E=2，D=9，标准差 σ=3。"},
  "kp-m1-p3-c4-ding-yi-2": {"anchor":"Cov(X,Y)=E(XY)−E(X)E(Y)","caption":"协方差 Cov(X,Y)=E{[X−E(X)][Y−E(Y)]} 衡量两个变量是否同向变化：为正表示同向，为负表示反向，为 0 表示不相关。","keyPoints":["Cov(X,Y)=E(XY)−E(X)E(Y)，这是最常用的计算式","Cov(X,X)=D(X)","协方差的大小受量纲影响，比较强弱要看相关系数"],"example":"若 X 增大时 Y 也增大，则协方差为正。"},
  "kp-m1-p3-c4-xing-zhi": {"anchor":"D(X±Y)=D(X)+D(Y)±2Cov(X,Y)","caption":"协方差对两个变量都满足线性（双线性）：Cov(aX+bY, Z)=aCov(X,Z)+bCov(Y,Z)。","keyPoints":["Cov 对每个变量都线性，可以直接展开","D(X±Y)=D(X)+D(Y)±2Cov(X,Y)","独立时 Cov=0，方差公式退化为相加"],"example":"X 与 Y 不独立时，方差不能直接相加，必须减去 2Cov(X,Y) 这一项。"},
  "kp-m1-p3-c4-ding-yi-3": {"anchor":"ρ_XY=Cov(X,Y)/(σ_Xσ_Y)","caption":"相关系数 ρ_XY=Cov(X,Y)/(σ_Xσ_Y) 是把协方差除以两个标准差得到的无量纲量，取值范围是 [−1,1]，用来衡量线性相关的强弱。","keyPoints":["ρ=Cov(X,Y)/(σ_Xσ_Y)，是无量纲的数","ρ 的符号与协方差一致，大小反映线性相关的强弱","ρ=±1 表示存在完全线性关系"],"example":"若 Y=2X+1，则 ρ=1，完全正线性相关。"},
  "kp-m1-p3-c4-qu-zhi-fan-wei": {"anchor":"|ρ_XY|≤1","caption":"相关系数的绝对值不超过 1：|ρ|≤1，等号成立当且仅当 X 与 Y 以概率 1 成线性关系。","keyPoints":["−1≤ρ≤1，算出界外一定是错的","|ρ|=1 ⇔ 存在 a、b 使 P{Y=aX+b}=1（a≠0）","ρ 只衡量线性关系，非线性关系可能算出 ρ≈0"],"example":"若 Y=X² 且 X 关于 0 对称，则 ρ=0，但两者并不独立。"},
  "kp-m1-p3-c4-xian-xing-xiang-guan-yi-yi": {"anchor":"|ρ|=1 ⇔ P{Y=aX+b}=1（a≠0）","caption":"概率论里说两个随机变量「线性相关」通常指 |ρ|=1，即它们以概率 1 满足 Y=aX+b；ρ 越接近 ±1，线性关系越强。","keyPoints":["|ρ|=1 ⇔ 以概率 1 存在线性关系","ρ=0 称为不相关，只说明没有线性关系","这里的「相关」与线性代数里向量组的线性相关是两回事"],"example":"Y=3X−2 时 ρ=1，两者完全线性相关。"},
  "kp-m1-p3-c4-0-yu-du-li-de-qu-bie": {"anchor":"独立 ⇒ ρ=0；二维正态下 ρ=0 ⇒ 独立","caption":"ρ=0 只说明不存在线性关系，称为「不相关」；独立要求联合分布等于边缘分布之积，是更强的条件。","keyPoints":["独立 ⇒ 不相关（Cov=0），反过来一般不成立","不相关只排除线性关系，非线性关系仍可能存在","二维正态下两者等价，这是特例而不是通例"],"example":"X~N(0,1)、Y=X²：ρ=0 但 X、Y 不独立。"},
  "kp-m1-p3-c4-yuan-dian-ju": {"anchor":"μ_k=E(Xᵏ)","caption":"k 阶原点矩是 E(Xᵏ)，一阶原点矩就是期望。","keyPoints":["k 阶原点矩 = E(Xᵏ)，一阶就是 E(X)","原点矩以原点为基准，中心矩以均值为基准","矩估计法就是用样本原点矩匹配总体原点矩"],"example":"k=1 时得到 E(X)；k=2 时得到 E(X²)。"},
  "kp-m1-p3-c4-zhong-xin-ju": {"anchor":"E{[X−E(X)]ᵏ}","caption":"k 阶中心矩是 E{[X−E(X)]ᵏ}，二阶中心矩就是方差。","keyPoints":["k 阶中心矩 = E{[X−E(X)]ᵏ}，二阶就是方差","一阶中心矩恒为 0，偏差正负抵消","三阶反映偏斜、四阶反映尖峭程度"],"example":"k=2 时中心矩等于 D(X)；k=1 时恒为 0。"},
  "kp-m1-p3-c5-yong-fang-cha-kong-zhi-pian-li-jun-zhi-0t98sf": {"anchor":"P{|X−EX|≥ε} ≤ D(X)/ε²","caption":"切比雪夫不等式给出「偏离均值」的概率上界：P{|X−EX|≥ε} ≤ D(X)/ε²。","keyPoints":["P{|X−EX|≥ε} ≤ D(X)/ε²，其中 ε 是任意正数","方差越小，偏离均值超过 ε 的概率上界越小","只要 EX 与 DX 存在就能用，不需要具体分布"],"example":"EX=10、DX=4，则 P{|X−10|≥5} ≤ 4/25=0.16。"},
  "kp-m1-p3-c5-qie-bi-xue-fu-da-shu-ding-l": {"anchor":"(1/n)ΣXᵢ →ᴾ (1/n)ΣE(Xᵢ)","caption":"切比雪夫大数定律说：若 Xᵢ 相互独立且方差一致有界，则样本均值依概率收敛到各自期望的平均值。","keyPoints":["条件：相互独立 + 方差一致有界","结论：样本均值依概率收敛到期望的平均值","证明工具正是切比雪夫不等式"],"example":"独立同分布且方差有限时，样本均值收敛到总体均值 μ。"},
  "kp-m1-p3-c5-bo-nu-li-da-shu-ding-l": {"anchor":"μₙ/n →ᴾ p","caption":"伯努利大数定律是切比雪夫大数定律在 0-1 分布上的特例：n 次独立重复试验中","keyPoints":["频率 μₙ/n 依概率收敛到概率 p","它是 0-1 分布上的切比雪夫大数定律特例","「次数越多频率越接近概率」的严格表述就是它"],"example":"抛硬币 10000 次，正面频率以很大概率落在 0.5 附近。"},
  "kp-m1-p3-c5-xin-qin-da-shu-ding-l": {"anchor":"(1/n)ΣXᵢ →ᴾ μ（独立同分布，E(X)=μ）","caption":"辛钦大数定律的条件最宽松：只要 Xᵢ 独立同分布且期望存在，样本均值就依概率收敛到 μ，**不要求方差存在**。","keyPoints":["条件：独立同分布 + 期望存在（不要求方差）","结论：样本均值依概率收敛到 μ","它比切比雪夫大数定律条件更弱，考试里更常用"],"example":"Xᵢ 独立同分布且服从参数为 λ 的指数分布，则样本均值收敛到 1/λ。"},
  "kp-m1-p3-c5-pin-l-wen-ding-dao-gai-l-de-si-xiang": {"anchor":"频率 μₙ/n ≈ p（n 充分大）","caption":"频率稳定性指：随试验次数增加，事件发生的频率会在概率附近摆动并逐渐稳定，这正是概率的统计性定义。","keyPoints":["频率是试验得到的值，概率是理论值，两者不是同一个东西","频率在概率附近稳定，是「用频率估计概率」的依据","次数越多越稳定，但不会精确相等"],"example":"抛硬币次数越多，正面频率越接近 0.5，但不会恰好等于 0.5。"},
  "kp-m1-p3-c5-du-li-tong-fen-bu-zhong-xin-ji-xian-1b8ul5": {"anchor":"(ΣXᵢ−nμ)/(σ√n) → N(0,1)","caption":"独立同分布中心极限定理说：Xᵢ 独立同分布且期望 μ、方差 σ² 存在时","keyPoints":["条件：独立同分布 + 期望与方差都存在","结论：标准化后的和依分布收敛到 N(0,1)","不论原来的分布是什么，和的分布都趋近正态"],"example":"掷 100 次骰子，点数之和近似服从 N(350, 100×35/12)。"},
  "kp-m1-p3-c5-di-mo-fu-la-pu-la-si-ding-li": {"anchor":"(X−np)/√(np(1−p)) → N(0,1)","caption":"棣莫弗—拉普拉斯定理是中心极限定理在二项分布上的特例：X~B(n,p) 时","keyPoints":["它是中心极限定理在 0-1 分布上的特例","要求 n 较大，且 np 与 n(1−p) 都不能太小","标准化时用 np 与 √(np(1−p))，别写成 np(1−p)"],"example":"抛 400 次硬币，正面数超过 220 的概率可用 N(200,100) 近似。"},
  "kp-m1-p3-c5-biao-zhun-hua": {"anchor":"(ΣXᵢ−nμ)/(σ√n)","caption":"中心极限定理里的标准化指把「和」减去期望、再除以标准差：(ΣXᵢ−nμ)/(σ√n)。","keyPoints":["分子是「和减去它的期望」，分母是「和的标准差」","分母用 σ√n，不是 σ，也不是 nσ","标准化之后才能用 Φ 表，这是做近似题的关键一步"],"example":"Xᵢ 独立同分布、μ=2、σ=3、n=100，则 ΣXᵢ 近似服从 N(200,900)。"},
  "kp-m1-p3-c5-er-xiang-fen-bu-zheng-tai-jin-si": {"anchor":"X~B(n,p) ≈ N(np, np(1−p))","caption":"二项分布在 n 较大时可用正态分布近似：X~B(n,p) 近似服从 N(np, np(1−p))","keyPoints":["近似分布是 N(np, np(1−p))，均值方差与二项分布一致","要求 n 较大，且 np、n(1−p) 不能太小","区间概率用两个 Φ 值相减得到"],"example":"抛 100 次硬币，正面数落在 45 到 55 之间的概率 ≈ Φ(1.1)−Φ(−1.1)。"},
  "kp-m1-p3-c6-zong-ti": {"anchor":"总体 X ~ F(x; θ)","caption":"总体是研究对象某项指标的全体取值，通常用一个随机变量 X 来刻画，总体的分布就是 X 的分布。","keyPoints":["总体 = 研究指标的全体取值，用随机变量描述","总体分布含未知参数，是统计推断的对象","同一批个体研究不同指标，总体就不同"],"example":"研究一批灯泡的寿命，「寿命」这个指标的全体就是总体，X 表示任取一只的寿命。"},
  "kp-m1-p3-c6-ge-ti": {"anchor":"Xᵢ ~ F(x; θ)（每个个体同分布）","caption":"个体是总体中的单个研究对象，一次抽样取到的就是一个个体（的指标值）。","keyPoints":["个体是总体的一个元素，取值服从总体分布","抽样就是随机取出若干个体","个体数与样本容量是两回事"],"example":"从一批灯泡中随机取一只，这只灯泡就是一个个体。"},
  "kp-m1-p3-c6-yang-ben": {"anchor":"X₁,…,Xₙ i.i.d.，联合密度 = ∏f(xᵢ;θ)","caption":"样本 X₁,…,Xₙ 是从总体中随机抽取的 n 个个体构成的随机变量组，它们相互独立且与总体同分布。","keyPoints":["样本是随机变量组，相互独立且与总体同分布","样本容量 n 是抽取的个体个数","样本的联合分布等于各边缘分布之积"],"example":"从 N(μ,σ²) 中抽 10 个，得到 X₁,…,X₁₀ 相互独立且都服从 N(μ,σ²)。"},
  "kp-m1-p3-c6-jian-dan-sui-ji-yang-ben": {"anchor":"X₁,…,Xₙ i.i.d. ~ F(x;θ)","caption":"简单随机样本要求抽样是独立进行的，即样本 X₁,…,Xₙ 相互独立且与总体同分布。","keyPoints":["两条要求：相互独立 + 与总体同分布","不放回抽样在小样本时不符合这一要求","它是后续所有统计方法的前提"],"example":"总体很大时不放回抽取可近似看作简单随机样本。"},
  "kp-m1-p3-c6-yang-ben-guan-ce-zhi": {"anchor":"x₁,…,xₙ（X₁,…,Xₙ 的一次实现）","caption":"样本观测值是抽样完成后得到的 n 个具体数值 x₁,…,xₙ，也就是样本 X₁,…,Xₙ 的一次实现；把观测值代入统计量就得到估计值。","keyPoints":["观测值是具体的数，样本是随机变量","同一总体反复抽样会得到不同的观测值","估计值 = 统计量代入观测值的结果"],"example":"抽 5 只灯泡测得 1000、1020、980、1010、990 小时，这五个数就是观测值。"},
  "kp-m1-p3-c6-ding-yi": {"anchor":"T=T(X₁,…,Xₙ)，不含未知参数","caption":"统计量是不含任何未知参数的样本函数，例如样本均值与样本方差。","keyPoints":["统计量必须是样本的函数，且不含未知参数","样本均值、样本方差、样本矩都是统计量","含未知参数的表达式不是统计量"],"example":"X̄ 与 S² 是统计量；当 μ 未知时，X̄−μ 不是统计量。"},
  "kp-m1-p3-c6-yang-ben-jun-zhi": {"anchor":"X̄=(1/n)ΣXᵢ，E(X̄)=μ，D(X̄)=σ²/n","caption":"样本均值 X̄=(1/n)ΣXᵢ 是最常用的统计量，它无偏地估计总体均值：E(X̄)=μ，并且 D(X̄)=σ²/n，样本量越大越集中。","keyPoints":["X̄=(1/n)ΣXᵢ，且 E(X̄)=μ（无偏）","D(X̄)=σ²/n，样本量越大越稳定","正态总体下 X̄ 服从 N(μ, σ²/n)"],"example":"n=100、σ²=4 时，X̄ 的方差为 0.04，标准差为 0.2。"},
  "kp-m1-p3-c6-yang-ben-fang-cha": {"anchor":"S²=(1/(n−1))Σ(Xᵢ−X̄)²","caption":"样本方差 S²=(1/(n−1))Σ(Xᵢ−X̄)² 用 n−1 作分母，这样 E(S²)=σ²，是无偏估计；若用 n 作分母，则系统性偏小。","keyPoints":["S²=(1/(n−1))Σ(Xᵢ−X̄)²，且 E(S²)=σ²","分母取 n−1 是为了无偏（用掉一个自由度估计均值）","正态总体下 S² 与 X̄ 相互独立"],"example":"观测值 1、3、5：X̄=3，Σ(Xᵢ−X̄)²=8，S²=8/2=4。"},
  "kp-m1-p3-c6-yang-ben-biao-zhun-cha": {"anchor":"S=√S²","caption":"样本标准差 S=√S² 与 X 同量纲，直观上更容易解释，但它本身一般不是 σ 的无偏估计，因为开方是非线性运算。","keyPoints":["S=√S²，与 X 同量纲","S² 无偏，但 S 一般不是 σ 的无偏估计","描述数据离散程度时常用 S"],"example":"S²=4 时，S=2。"},
  "kp-m1-p3-c6-yang-ben-ju": {"anchor":"A_k=(1/n)ΣXᵢᵏ","caption":"样本 k 阶原点矩 A_k=(1/n)ΣXᵢᵏ，样本 k 阶中心矩 B_k=(1/n)Σ(Xᵢ−X̄)ᵏ。","keyPoints":["A_k=(1/n)ΣXᵢᵏ，B_k=(1/n)Σ(Xᵢ−X̄)ᵏ","一阶样本原点矩就是 X̄","矩估计法就是令总体矩等于样本矩"],"example":"A₁=X̄；B₂=(1/n)Σ(Xᵢ−X̄)²（注意这里分母是 n）。"},
  "kp-m1-p3-c6-jing-yan-fen-bu-han-shu-de-jie-ti-tu-04kuw6": {"anchor":"Fₙ(x)=#{Xᵢ≤x}/n","caption":"经验分布函数 Fₙ(x) 等于样本中不超过 x 的比例，图像是阶梯形：每经过一个观测值就向上跳 1/n（有重复观测值时跳 k/n）。","keyPoints":["Fₙ(x)=(不超过 x 的观测值个数)/n","图像是阶梯函数，跳跃总高度为 1","Fₙ(x) 是总体分布函数 F(x) 的相合估计"],"example":"观测值 1、2、2、4 时，Fₙ(2)=3/4。"},
  "kp-m1-p3-c6-yang-ben-luo-zai-qu-jian-nei-de-pin-l": {"anchor":"频率 = #{Xᵢ∈(a,b)}/n","caption":"样本落在某区间内的频率就是落在该区间的观测值个数除以 n，用它近似该区间的概率，这正是直方图与经验分布的思想来源。","keyPoints":["频率 = 落在区间内的个数 / n","n 越大频率越接近概率（伯努利大数定律）","直方图的面积近似概率"],"example":"20 个观测值中有 7 个落在 (10,20) 内，频率为 0.35。"},
  "kp-m1-p3-c6-yong-yang-ben-fen-bu-jin-si-zong-ti-fen-0gcefa": {"anchor":"Fₙ(x) → F(x)（一致收敛，概率 1）","caption":"用样本分布近似总体分布是数理统计的基本思路：n 充分大时经验分布函数以概率 1 一致收敛于总体分布函数，这是「用样本推断总体」的理论依据。","keyPoints":["经验分布函数随 n 增大一致收敛到总体分布函数","这是统计推断的理论依据","推断总带不确定性，需要用概率语言描述"],"example":"n=1000 时经验分布已经能很好地近似总体分布的形状。"},
  "kp-m1-p3-c6-fen-bu": {"anchor":"χ²=Σᵢ₌₁ⁿ Zᵢ²，Zᵢ~N(0,1)","caption":"χ² 分布是 n 个相互独立的标准正态变量的平方和所服从的分布，记作 χ²(n)，自由度就是平方项的个数，它的期望恰好等于自由度。","keyPoints":["χ²(n)=ΣZᵢ²，其中 Zᵢ 独立且服从 N(0,1)","E(χ²(n))=n，D(χ²(n))=2n","只取正值，n 增大时形状趋于对称"],"example":"两个独立标准正态变量的平方和服从 χ²(2)，期望为 2。"},
  "kp-m1-p3-c6-t-fen-bu": {"anchor":"t=Z/√(χ²(n)/n)","caption":"t 分布由一个标准正态变量除以独立的 χ² 变量开方再除以自由度得到，记作 t(n)。","keyPoints":["t=Z/√(χ²(n)/n)，其中 Z 与 χ² 相互独立","关于 0 对称，尾部比标准正态厚","n→∞ 时 t(n) 趋于 N(0,1)"],"example":"正态总体、σ 未知时，(X̄−μ)/(S/√n) 服从 t(n−1)。"},
  "kp-m1-p3-c6-f-fen-bu": {"anchor":"F=(χ²(n₁)/n₁)/(χ²(n₂)/n₂)","caption":"F 分布是两个相互独立的 χ² 变量各除以自身自由度后的比值所服从的分布，记作 F(n₁,n₂)，两个自由度的顺序不能颠倒。","keyPoints":["F=(χ²(n₁)/n₁)/(χ²(n₂)/n₂)，两个 χ² 相互独立","分子、分母的自由度顺序固定","1/F ~ F(n₂,n₁)，这是查表常用的性质"],"example":"两个正态总体样本方差之比（各除以自身 σᵢ²）服从 F 分布。"},
  "kp-m1-p3-c6-xing-zhuang-he-can-shu-bian-hua": {"anchor":"χ²(n)、t(n)、F(n₁,n₂)","caption":"三个抽样分布的形状都随自由度变化：χ² 在自由度小时右偏、增大后趋于对称；t 分布尾部比正态厚、自由度大时接近正态；F 分布只取正值且右偏。","keyPoints":["χ²：右偏，n 增大趋于对称，期望为 n","t：对称，尾部厚于正态，n 大时近似标准正态","F 分布只取正值且右偏，常用于方差比检验"],"example":"自由度 45 的 t 分布与标准正态已非常接近。"},
  "kp-m1-p3-c6-yang-ben-jun-zhi-fen-bu": {"anchor":"X̄~N(μ, σ²/n)","caption":"正态总体 N(μ,σ²) 下样本均值 X̄ 服从 N(μ, σ²/n)；若总体不服从正态但 n 较大，可用中心极限定理作近似。","keyPoints":["正态总体：X̄~N(μ, σ²/n)，方差是总体的 1/n","非正态总体 n 大时近似 N(μ, σ²/n)","标准化后 (X̄−μ)/(σ/√n) ~ N(0,1)"],"example":"X~N(10,4)、n=16 时，X̄~N(10, 0.25)。"},
  "kp-m1-p3-c6-yang-ben-fang-cha-fen-bu": {"anchor":"(n−1)S²/σ² ~ χ²(n−1)","caption":"正态总体下 (n−1)S²/σ² 服从 χ²(n−1)。","keyPoints":["(n−1)S²/σ² ~ χ²(n−1)","自由度是 n−1（用掉一个自由度估计均值）","由该分布可直接推出 E(S²)=σ²"],"example":"n=10、S²=4、σ²=2 时，(n−1)S²/σ²=18，服从 χ²(9)。"},
  "kp-m1-p3-c6-yang-ben-jun-zhi-yu-yang-ben-fang-cha-1fk1at": {"anchor":"X̄ 与 S² 独立（正态总体）","caption":"正态总体下样本均值 X̄ 与样本方差 S² 相互独立。","keyPoints":["正态总体下 X̄ 与 S² 相互独立","这是 (X̄−μ)/(S/√n) 服从 t 分布的前提","其它分布一般不具备这条性质"],"example":"构造 (X̄−μ)/(S/√n) 时，分子与分母独立正是 t 分布的定义要求。"},
  "kp-m1-p3-c6-dan-zong-ti-yu-liang-zong-ti-chang-yong-0j6yn0": {"anchor":"U=(X̄−μ)/(σ/√n) ~ N(0,1)；T=(X̄−μ)/(S/√n) ~ t(n−1)","caption":"常用统计量就三套：σ² 已知时用 U=(X̄−μ)/(σ/√n)~N(0,1)；","keyPoints":["σ 已知用 U 统计量（标准正态）","σ 未知用 T 统计量（t 分布，自由度 n−1）","两总体：均值差用 U 或 T，方差比用 F"],"example":"σ 未知、n=16、X̄=52、S=4 时，T=(52−μ)/1 服从 t(15)。"},
  "kp-m1-p3-c7-can-shu": {"anchor":"总体 F(x; θ)，θ 未知","caption":"参数是总体分布中未知的常数，例如正态分布的 μ 与 σ²。","keyPoints":["参数是总体分布的未知常数，不是随机变量","点估计给出一个数值，区间估计给出一个范围","参数记作 θ，估计量记作 θ̂"],"example":"X~N(μ,σ²) 且 μ、σ² 都未知时，待估参数有两个。"},
  "kp-m1-p3-c7-gu-ji-liang": {"anchor":"θ̂=θ̂(X₁,…,Xₙ)","caption":"估计量是用于估计未知参数的统计量，它是样本的函数、本身是随机变量，常用 θ̂ 表示。","keyPoints":["估计量是统计量（随机变量），且不含未知参数","同一参数可以有多个估计量，需要比较优劣","好坏用无偏性、有效性、一致性衡量"],"example":"估计 μ 既可以用 X̄，也可以用样本中位数，两者都是估计量。"},
  "kp-m1-p3-c7-gu-ji-zhi": {"anchor":"θ̂(x₁,…,xₙ)","caption":"估计值是把样本观测值代入估计量后得到的具体数值，也就是估计量的一次实现。","keyPoints":["估计值是数，估计量是随机变量","同一估计量在不同样本下给出不同的估计值","最终答案通常要求给出估计值"],"example":"观测值为 1、3、5 时，X̄ 的估计值为 3。"},
  "kp-m1-p3-c7-zong-ti-ju": {"anchor":"E(X)、E(X²) 等","caption":"总体矩是总体分布的矩，通常含未知参数，例如 E(X)=μ、E(X²)=σ²+μ²。","keyPoints":["总体矩是理论值，通常含未知参数","一阶原点矩就是总体均值 μ","有几个未知参数就要列几个方程"],"example":"指数分布 E(λ) 中 E(X)=1/λ，令其等于 X̄ 得 λ̂=1/X̄。"},
  "kp-m1-p3-c7-yang-ben-ju": {"anchor":"A_k=(1/n)ΣXᵢᵏ","caption":"矩估计法中用样本矩去替换总体矩：样本 k 阶原点矩 A_k=(1/n)ΣXᵢᵏ。","keyPoints":["A_k=(1/n)ΣXᵢᵏ，是统计量","样本矩是总体矩的相合估计","矩估计不要求知道分布的具体形式（只要矩存在）"],"example":"A₁=X̄，A₂=(1/n)ΣXᵢ²。"},
  "kp-m1-p3-c7-yong-yang-ben-ju-pi-pei-zong-ti-ju": {"anchor":"E(Xᵏ) = (1/n)ΣXᵢᵏ（k=1,…,m）","caption":"矩估计法的核心是「用样本矩替换总体矩」：令总体矩等于对应的样本矩，得到关于未知参数的方程（组），解出即得矩估计量。","keyPoints":["有几个未知参数就令前几阶矩相等","总体矩写成含参数的表达式，样本矩用观测值计算","解出的解就是矩估计量"],"example":"均匀分布 U(0,θ)：E(X)=θ/2=X̄ ⇒ θ̂=2X̄。"},
  "kp-m1-p3-c7-si-ran-han-shu-ba-yang-ben-kan-cheng-yi-1cm919": {"anchor":"L(θ)=∏ᵢ₌₁ⁿ f(xᵢ; θ)","caption":"似然函数把样本观测值视为已知、把参数视为自变量：L(θ)=∏f(xᵢ;θ)。","keyPoints":["L(θ)=∏f(xᵢ;θ)，离散型用分布律","样本已知、参数为变量，这是它与联合密度的区别","使 L 最大的 θ 就是最大似然估计"],"example":"总体为 B(1,p)、观测到 1,0,1 时，L(p)=p²(1−p)。"},
  "kp-m1-p3-c7-qu-dui-shu-ba-cheng-ji-bian-cheng-he": {"anchor":"ln L(θ)=Σᵢ₌₁ⁿ ln f(xᵢ; θ)","caption":"连乘求导很麻烦，取对数后变成求和：ln L(θ)=Σln f(xᵢ;θ)。","keyPoints":["ln L(θ)=Σln f(xᵢ;θ)，连乘变求和","单调性保证最值点不变","这几乎是所有最大似然题的必经步骤"],"example":"L(p)=p²(1−p) 时，ln L=2ln p+ln(1−p)。"},
  "kp-m1-p3-c7-ling-dao-shu-wei-ling-bing-jian-cha-can-0ygy0z": {"anchor":"d ln L(θ)/dθ = 0","caption":"最大似然估计通过解 d ln L/dθ = 0 得到，但还必须检查驻点是否落在参数允许范围内、端点是否更优，参数范围往往是解题关键。","keyPoints":["解 d ln L/dθ=0 得到驻点","必须检查驻点是否在参数允许范围内","若 ln L 单调，则最优点出现在端点"],"example":"均匀分布 U(0,θ) 的似然函数在 θ≥max xᵢ 上单调递减，故 θ̂=max xᵢ。"},
  "kp-m1-p3-c7-wu-pian-xing": {"anchor":"E(θ̂)=θ","caption":"无偏性指 E(θ̂)=θ，即估计量在平均意义上等于真值。","keyPoints":["无偏：E(θ̂)=θ，平均不偏高也不偏低","X̄ 无偏估计 μ，S² 无偏估计 σ²","无偏性不保证单次估计的误差小"],"example":"E(X̄)=μ，所以 X̄ 是 μ 的无偏估计。"},
  "kp-m1-p3-c7-you-xiao-xing": {"anchor":"D(θ̂₁) < D(θ̂₂) ⇒ θ̂₁ 更有效","caption":"在两个无偏估计之间，方差更小的那个更有效，因为它的取值更集中、估计更稳定。","keyPoints":["前提是两个估计量都无偏","方差越小的估计越有效，波动小才可靠","所有无偏估计中方差最小的称为最小方差无偏估计"],"example":"正态总体中 X̄ 比样本中位数更有效（方差更小）。"},
  "kp-m1-p3-c7-yi-zhi-xing": {"anchor":"θ̂ₙ →ᴾ θ（n→∞）","caption":"一致性指 n→∞ 时估计量依概率收敛到参数：θ̂ₙ →ᴾ θ。","keyPoints":["一致性：θ̂ₙ 依概率收敛到 θ","样本矩都是一致估计（由大数定律保证）","一致性是大样本性质，n 小时不一定好"],"example":"X̄ 依概率收敛到 μ，这正是辛钦大数定律的内容。"},
  "kp-m1-p3-c7-zhi-xin-du": {"anchor":"P{L(X)≤θ≤U(X)}=1−α","caption":"置信度 1−α 表示在重复抽样中，置信区间包含真参数的概率，常用 0.95 或 0.99；α 是「没包含」的概率。","keyPoints":["置信度 = 1−α，常取 0.95、0.99","含义是「重复抽样时包含真值的比例」，不是「参数落在区间内的概率」","置信度越高，区间越宽"],"example":"95% 置信区间意味着反复抽样 100 次，约有 95 次的区间盖住真值。"},
  "kp-m1-p3-c7-zhi-xin-qu-jian": {"anchor":"P{L(X)≤θ≤U(X)}=1−α","caption":"置信区间是由样本构造的随机区间 [L(X),U(X)]，它以 1−α 的概率包含未知参数。","keyPoints":["置信区间是随机区间，随样本变化","构造步骤：找枢轴量 → 用分位数夹住 → 解出参数范围","置信度越高区间越宽，样本量越大区间越窄"],"example":"σ 已知时 μ 的 95% 置信区间为 X̄±1.96·σ/√n。"},
  "kp-m1-p3-c7-dan-zheng-tai-zong-ti-jun-zhi-zhi-xin-0mpil0": {"anchor":"σ 已知：X̄±z_{α/2}σ/√n；σ 未知：X̄±t_{α/2}(n−1)S/√n","caption":"σ² 已知时用 U=(X̄−μ)/(σ/√n)~N(0,1)，区间为 X̄±z_{α/2}·σ/√n；","keyPoints":["σ 已知：X̄±z_{α/2}·σ/√n","σ 未知：X̄±t_{α/2}(n−1)·S/√n","σ 未知时用 S 代替 σ，分位数改用 t 分布"],"example":"n=16、X̄=52、S=4、α=0.05 时，区间为 52±2.131×1。"},
  "kp-m1-p3-c7-dan-zheng-tai-zong-ti-fang-cha-zhi-xin-0tzaea": {"anchor":"(n−1)S²/χ²_{α/2}(n−1) ≤ σ² ≤ (n−1)S²/χ²_{1−α/2}(n−1)","caption":"方差的置信区间由 (n−1)S²/σ²~χ²(n−1) 反解得到，两端分别用 χ² 的右、左分位数，因此区间不是关于 S² 对称的。","keyPoints":["枢轴量是 (n−1)S²/σ² ~ χ²(n−1)","两端用 χ² 的左右分位数，位置不能颠倒","χ² 分布不对称，区间不对称"],"example":"n=10、S²=4、α=0.05 时，查 χ²(9) 的 0.025 与 0.975 分位数后代入。"},
  "kp-m1-p3-c7-liang-zheng-tai-zong-ti-can-shu-xiang-10u1wm": {"anchor":"F=(S₁²/σ₁²)/(S₂²/σ₂²) ~ F(n₁−1, n₂−1)","caption":"两总体情形主要估计均值差 μ₁−μ₂ 与方差比 σ₁²/σ₂²：均值差用两个样本均值之差（σ 已知用正态、未知但相等用 t）；方差比用 F 分布。","keyPoints":["X̄−Ȳ 是 μ₁−μ₂ 的无偏估计","方差比用 F=(S₁²/σ₁²)/(S₂²/σ₂²) ~ F(n₁−1, n₂−1)","前提是两个样本相互独立"],"example":"比较两条生产线的方差是否相当，用 F 分布构造 σ₁²/σ₂² 的置信区间。"},
  "kp-m1-p3-c8-yuan-jia-she-h0": {"anchor":"H0: μ=μ₀（等号放在 H0）","caption":"原假设 H0 是我们要检验的命题，通常取「没有差异」「参数等于某值」这类保守说法。","keyPoints":["H0 通常取等号形式（μ=μ₀、σ²=σ₀²）","H0 是「被保护」的假设，只有证据充分才拒绝它","不拒绝 H0 不等于证明 H0 正确"],"example":"检验某批零件平均长度是否等于 10cm：H0: μ=10。"},
  "kp-m1-p3-c8-bei-ze-jia-she-h1": {"anchor":"H1: μ≠μ₀（双侧）或 μ>μ₀ / μ<μ₀（单侧）","caption":"备择假设 H1 与 H0 对立：双侧检验写 μ≠μ₀，单侧检验写 μ>μ₀ 或 μ<μ₀，方向由题目的语义决定。","keyPoints":["H1 与 H0 互斥且覆盖参数空间","双侧用 ≠，单侧用 > 或 <","方向由「是否高于 / 低于」这类表述决定"],"example":"「平均寿命是否高于 1000 小时」→ H1: μ>1000（单侧）。"},
  "kp-m1-p3-c8-jian-yan-tong-ji-liang": {"anchor":"U=(X̄−μ₀)/(σ/√n) ~ N(0,1)（H0 成立时）","caption":"检验统计量把样本信息浓缩成一个数，用于判断是否拒绝 H0：均值检验用 U=(X̄−μ₀)/(σ/√n)，方差检验用 χ²=(n−1)S²/σ₀²。","keyPoints":["检验统计量在 H0 成立时分布已知","均值用 U 或 T，方差用 χ²，方差比用 F","统计量的值越极端，越倾向拒绝 H0"],"example":"检验 μ 且 σ 已知时，用 U 统计量。"},
  "kp-m1-p3-c8-xian-zhu-xing-shui-ping": {"anchor":"P{拒绝 H0 | H0 为真} = α","caption":"显著性水平 α 是事先规定的、允许犯第一类错误（H0 为真却拒绝）的最大概率，常取 0.05 或 0.01。","keyPoints":["α 是拒绝 H0 时可能犯错的概率上限","常取 0.05、0.01，由题目给出","α 越小，拒绝域越小，越不容易拒绝 H0"],"example":"α=0.05 的双侧 U 检验，临界值为 ±1.96。"},
  "kp-m1-p3-c8-ju-jue-yu": {"anchor":"双侧拒绝域：|U|>z_{α/2}","caption":"拒绝域是检验统计量取值的一个区域：统计量的值落在里面就拒绝 H0，否则不拒绝。","keyPoints":["拒绝域由 α 与 H1 的方向共同决定","双侧：|U|>z_{α/2}；右侧：U>z_α；左侧：U<−z_α","统计量落入拒绝域就拒绝 H0"],"example":"U 检验、α=0.05 双侧时，|U|>1.96 就拒绝 H0。"},
  "kp-m1-p3-c8-p-zhi-de-zhi-guan-li-jie-zuo-wei-fu-zhu": {"anchor":"P 值 = P{统计量更极端 | H0}","caption":"P 值是在 H0 成立时，出现「当前样本或更极端样本」的概率。","keyPoints":["P 值 = H0 成立时出现当前或更极端结果的概率","P<α 拒绝 H0，P≥α 不拒绝","P 值越小，样本与 H0 的冲突越强"],"example":"U=2.5 的双侧 P 值 =2(1−Φ(2.5))≈0.0124<0.05，拒绝 H0。"},
  "kp-m1-p3-c8-di-yi-lei-cuo-wu": {"anchor":"P{拒绝 H0 | H0 真} = α","caption":"第一类错误是「H0 为真却拒绝了 H0」，也叫弃真，其概率就是显著性水平 α，由研究者事先控制。","keyPoints":["第一类错误 = 弃真，概率为 α","α 由研究者事先给定","α 越小，越不容易犯第一类错误"],"example":"α=0.05 意味着 100 次检验中约有 5 次会误拒真实的 H0。"},
  "kp-m1-p3-c8-di-er-lei-cuo-wu": {"anchor":"P{不拒绝 H0 | H0 假} = β","caption":"第二类错误是「H0 为假却没有拒绝 H0」，也叫取伪，其概率记作 β。","keyPoints":["第二类错误 = 取伪，概率记作 β","样本量越大，β 越小","α 与 β 相互制约：减小 α 往往增大 β"],"example":"增大样本量可以在保持 α 的同时减小 β。"},
  "kp-m1-p3-c8-fang-cha-yi-zhi": {"anchor":"U=(X̄−μ₀)/(σ/√n) ~ N(0,1)","caption":"正态总体、σ² 已知时检验 μ 用 U=(X̄−μ₀)/(σ/√n)，H0 成立时服从 N(0,1)，按 α 查标准正态分位数即可。","keyPoints":["枢轴量 U=(X̄−μ₀)/(σ/√n) ~ N(0,1)","双侧临界值 ±z_{α/2}，单侧用 z_α","σ 已知是使用 U 检验的前提"],"example":"n=25、σ=2、X̄=10.5、μ₀=10：U=1.25<1.96，不拒绝 H0。"},
  "kp-m1-p3-c8-fang-cha-wei-zhi": {"anchor":"T=(X̄−μ₀)/(S/√n) ~ t(n−1)","caption":"σ² 未知时用样本标准差代替：T=(X̄−μ₀)/(S/√n)，H0 成立时服从 t(n−1)，按 t 分布查临界值。","keyPoints":["枢轴量 T=(X̄−μ₀)/(S/√n) ~ t(n−1)","自由度是 n−1：样本均值用掉一个约束","σ 未知时必须用 t 分布而不是标准正态"],"example":"n=16、S=4、X̄−μ₀=2 时 T=2，与 t(15) 的 2.131 比较。"},
  "kp-m1-p3-c8-fang-cha-jian-yan-shi-yong-tong-ji-liang": {"anchor":"χ²=(n−1)S²/σ₀² ~ χ²(n−1)","caption":"正态总体方差检验用 χ²=(n−1)S²/σ₀²，在 H0: σ²=σ₀² 成立时服从 χ²(n−1)，这是方差检验与均值检验最大的不同。","keyPoints":["枢轴量 χ²=(n−1)S²/σ₀² ~ χ²(n−1)","自由度是 n−1：样本均值用掉一个约束","χ² 分布不对称，左右临界值不对称"],"example":"n=10、S²=4、σ₀²=2 时，统计量的值为 18。"},
  "kp-m1-p3-c8-yuan-jia-she-yu-shuang-ce-dan-ce-ju-jue-0v353g": {"anchor":"双侧拒绝域：χ²>χ²_{α/2}(n−1) 或 χ²<χ²_{1−α/2}(n−1)","caption":"方差检验的拒绝域取决于 H1 的方向：双侧 H1: σ²≠σ₀² 时，χ² 落在两侧分位数之外才拒绝；单侧则只用一侧分位数。","keyPoints":["双侧：χ²>χ²_{α/2} 或 χ²<χ²_{1−α/2}","右侧单侧：χ²>χ²_α","左侧单侧：χ²<χ²_{1−α}"],"example":"n=10、α=0.05 双侧时，χ²(9) 的 0.025 与 0.975 分位数为 2.700 与 19.023。"},
  "kp-m1-p3-c8-gen-ju-lin-jie-zhi-zuo-chu-jian-yan-jie-07k3me": {"anchor":"统计量 ∈ 拒绝域 ⇒ 拒绝 H0","caption":"算出统计量的值后，与临界值比较：落入拒绝域就拒绝 H0，否则不拒绝。","keyPoints":["结论只有两种：拒绝 H0 或不拒绝 H0","不能写「接受 H0」——没有证明 H0 正确","要结合语境说明实际结论"],"example":"U=2.3>1.96，拒绝 H0，认为该批产品的平均长度与 10cm 有显著差异。"},
  "kp-m1-p3-c8-jun-zhi-cha": {"anchor":"T=(X̄−Ȳ)/√(S_w²(1/n₁+1/n₂)) ~ t(n₁+n₂−2)","caption":"检验两个正态总体均值是否相等，用两样本均值之差：σ 已知时构造 U 统计量（标准正态），σ 未知但相等时构造 T 统计量（自由度 n₁+n₂−2）。","keyPoints":["H0: μ₁=μ₂，统计量基于 X̄−Ȳ","σ 已知用 U；σ 未知但相等用合并方差的 T","T 统计量的自由度是 n₁+n₂−2"],"example":"比较两批产品的平均强度是否相同，用两样本 t 检验。"},
  "kp-m1-p3-c8-fang-cha-bi-de-ji-ben-jian-yan-jie-gou": {"anchor":"F=S₁²/S₂² ~ F(n₁−1, n₂−1)（H0 成立时）","caption":"检验两个正态总体方差是否相等，用样本方差之比构造 F 统计量：F=(S₁²/σ₁²)/(S₂²/σ₂²)","keyPoints":["H0: σ₁²=σ₂²，此时 F=S₁²/S₂² ~ F(n₁−1, n₂−1)","两个自由度的顺序与分子分母一致","F 检验同样分双侧与单侧"],"example":"判断两条生产线的方差是否相当：F=1.8 与 F(9,9) 的临界值比较。"},
  "kp-m2-p1-c1-han-shu-de-gai-nian": {"anchor":"f: D → R，x ↦ y=f(x)","caption":"函数是「一个输入对应唯一输出」的对应关系，记作 y=f(x)。","keyPoints":["三要素：定义域、对应法则、值域（值域由前两者决定）","一个 x 只能对应一个 y，否则不是（单值）函数","定义域与对应法则都相同，才是同一个函数"],"example":"y=√(1−x²) 的定义域是 [−1,1]，值域是 [0,1]。"},
  "kp-m2-p1-c1-han-shu-de-biao-shi-fa": {"anchor":"y=f(x)；分段：f(x)=g₁(x)（x∈D₁）…","caption":"函数可以用解析式、图像、表格三种方式表示，它们是同一个对应关系的不同侧面：解析式便于计算，图像便于观察单调性与对称性。","keyPoints":["解析式适合计算，图像适合观察整体性质","分段函数是解析式的一种，按区间分别给法则","在表示之间转换时要保留定义域信息"],"example":"y=|x| 既可以写成解析式，也可以画成 V 形图像。"},
  "kp-m2-p1-c1-you-jie-xing": {"anchor":"∃M>0，∀x∈I：|f(x)|≤M","caption":"f 在区间 I 上有界，指存在 M>0 使 |f(x)|≤M 对 I 上所有 x 成立。","keyPoints":["有界 ⇔ 存在 M>0 使 |f(x)|≤M 在区间上恒成立","有界性依赖区间：1/x 在 (0,1) 无界、在 (1,2) 有界","闭区间上连续 ⇒ 有界（这是后面证明题的常用结论）"],"example":"sin x 在 R 上有界（取 M=1）；f(x)=x 在 R 上无界。"},
  "kp-m2-p1-c1-dan-diao-xing": {"anchor":"x₁<x₂ ⇒ f(x₁)≤f(x₂)（单调不减）","caption":"单调递增指 x₁<x₂ 时 f(x₁)≤f(x₂)（严格递增则严格小于）。","keyPoints":["单调性必须在指定区间上讨论","严格单调是反函数存在的充分条件","导数符号是判断单调性的常用工具"],"example":"f(x)=x³ 在 R 上严格递增，所以它有反函数。"},
  "kp-m2-p1-c1-ji-ou-xing": {"anchor":"奇：f(−x)=−f(x)；偶：f(−x)=f(x)","caption":"奇函数满足 f(−x)=−f(x)，图像关于原点对称；偶函数满足 f(−x)=f(x)，图像关于 y 轴对称。","keyPoints":["奇：f(−x)=−f(x)；偶：f(−x)=f(x)","定义域必须关于原点对称，否则无从谈奇偶性","奇函数在 0 处有定义时必有 f(0)=0"],"example":"x³ 是奇函数；cos x 是偶函数；x+1 非奇非偶。"},
  "kp-m2-p1-c1-zhou-qi-xing": {"anchor":"f(x+T)=f(x)","caption":"若存在 T>0 使 f(x+T)=f(x) 对定义域内所有 x 成立，就称 f 为周期函数，T 为它的一个周期；通常所说的周期指最小正周期。","keyPoints":["f(x+T)=f(x)，且 T>0","周期函数的图像每隔 T 重复一次","sin x、cos x 的最小正周期是 2π，|sin x| 是 π"],"example":"sin x 的周期为 2π；|sin x| 的周期为 π。"},
  "kp-m2-p1-c1-fu-he-han-shu": {"anchor":"(f∘g)(x)=f(g(x))","caption":"复合函数 y=f[g(x)] 是把 g 的输出作为 f 的输入；它成立的条件是 g 的值域与 f 的定义域有交集，定义域要同时满足两个函数的要求。","keyPoints":["要求 g 的值域落在 f 的定义域内（至少相交）","复合函数的定义域由内外两个函数共同限制","复合顺序不同，结果一般不同"],"example":"f(x)=√x、g(x)=1−x² 时，复合函数的定义域是 |x|≤1。"},
  "kp-m2-p1-c1-fan-han-shu": {"anchor":"f⁻¹(f(x))=x；f(f⁻¹(x))=x","caption":"若 y=f(x) 中 x 与 y 一一对应，就可以解出 x=f⁻¹(y)，得到反函数；反函数的定义域是原函数的值域，图像关于直线 y=x 对称。","keyPoints":["严格单调是反函数存在的充分条件","反函数的定义域 = 原函数的值域","f⁻¹(f(x))=x，f(f⁻¹(x))=x"],"example":"y=eˣ 的反函数是 y=ln x，定义域 x>0。"},
  "kp-m2-p1-c1-fen-duan-han-shu": {"anchor":"f(x)=g₁(x)（x∈D₁）；g₂(x)（x∈D₂）","caption":"分段函数在不同区间用不同表达式，它是一个函数而不是多个；求值、讨论连续性、求导时都要按「x 落在哪一段」分别处理。","keyPoints":["分段函数是「一个函数」，只是法则分段给出","分段点必须单独讨论连续性与可导性","分段点处要分别求左右极限与左右导数"],"example":"f(x)=x（x≥0）、−x（x<0）就是 f(x)=|x|。"},
  "kp-m2-p1-c1-yin-han-shu": {"anchor":"F(x,y)=0 ⇒ y′=−Fₓ/Fᵧ（Fᵧ≠0）","caption":"隐函数是由方程 F(x,y)=0 确定的函数关系，未必能解出显式 y=f(x)。","keyPoints":["隐函数由方程 F(x,y)=0 确定，可以不显式解出","求导时把 y 视为 x 的函数（用链式法则）","求导结果一般同时含 x 与 y"],"example":"x²+y²=1 两边求导得 2x+2yy′=0，故 y′=−x/y。"},
  "kp-m2-p1-c1-ji-ben-chu-deng-han-shu": {"anchor":"aˣ>0；logₐx 要求 x>0；tan x 在 x=kπ+π/2 无定义","caption":"幂函数、指数函数、对数函数、三角函数、反三角函数合称五类基本初等函数，其余函数大多由它们运算、复合而来；","keyPoints":["五类基本初等函数：幂、指、对、三角、反三角","指对互为反函数：y=aˣ 与 y=logₐx 图像关于 y=x 对称","复合或四则之后，定义域取「能同时成立」的交集"],"example":"y=√(1−x²) 定义域 [−1,1]；y=ln(1+x) 定义域 x>−1。"},
  "kp-m2-p1-c1-shu-lie-yu-ji-xian": {"anchor":"∀ε>0，∃N：n>N ⇒ |aₙ−A|<ε","caption":"数列极限 lim aₙ=A 的 ε-N 定义是：对任意 ε>0，都存在 N，当 n>N 时 |aₙ−A|<ε。","keyPoints":["ε-N 定义：∀ε>0，∃N，n>N ⇒ |aₙ−A|<ε","ε 是任意小的正数，N 依赖 ε","数列极限与前面有限项无关"],"example":"aₙ=1/n 的极限为 0：对任意 ε，取 N=1/ε 即可。"},
  "kp-m2-p1-c1-ji-xian-xing-zhi": {"anchor":"aₙ→A，bₙ→B（B≠0）⇒ aₙ/bₙ→A/B","caption":"数列极限同样满足四则运算：若 aₙ→A、bₙ→B，则 aₙ±bₙ→A±B、aₙbₙ→AB，且当 B≠0 时 aₙ/bₙ→A/B。","keyPoints":["四则运算要求两个数列都收敛","商的极限要求分母极限不为 0","子数列收敛到同一极限（常用来证明极限不存在）"],"example":"aₙ=(2n+1)/n=2+1/n→2。"},
  "kp-m2-p1-c1-ji-xian-cun-zai-zhun-ze": {"anchor":"gₙ≤aₙ≤hₙ，gₙ,hₙ→A ⇒ aₙ→A","caption":"两个常用准则：单调有界数列必收敛；若 gₙ≤aₙ≤hₙ 且 gₙ、hₙ 都趋于同一极限 A，则 aₙ 也趋于 A（夹逼准则）。","keyPoints":["单调有界 ⇒ 收敛（常用于递推数列）","夹逼准则：两侧夹住即可得极限","夹逼时两侧极限必须相同"],"example":"aₙ=(sin n)/n：由 −1/n≤aₙ≤1/n 夹逼得极限为 0。"},
  "kp-m2-p1-c1-x-x0": {"anchor":"lim_{x→x₀} f(x)=A","caption":"x→x₀ 时的极限看的是 x 无限接近 x₀（但不等于 x₀）时 f(x) 的趋势，与 f(x₀) 的取值无关；这也是它可以处理「0/0」型的原因。","keyPoints":["极限与 f(x₀) 无关，f(x₀) 可以没有定义","去心邻域 0<|x−x₀|<δ 是定义的核心","存在极限时，左右极限必须都存在且相等"],"example":"lim_{x→0} sin x/x=1，而 x=0 处函数无定义。"},
  "kp-m2-p1-c1-zuo-ji-xian-you-ji-xian": {"anchor":"f(x₀−)=f(x₀+) ⇒ 极限存在","caption":"左极限 f(x₀−) 与右极限 f(x₀+) 分别描述从左右两侧靠近时的趋势；两者都存在且相等时，f 在 x₀ 处的极限才存在。","keyPoints":["左右极限都存在且相等 ⇔ 极限存在","分段函数、含绝对值的函数要分别求两侧","指数与反正切在 0 处是典型的左右不等例子"],"example":"f(x)=arctan(1/x) 在 0 处左右极限为 −π/2 与 π/2，极限不存在。"},
  "kp-m2-p1-c1-wu-qiong-yuan-chu-ji-xian": {"anchor":"lim_{x→±∞} f(x)","caption":"无穷远处极限指 x→+∞ 或 x→−∞ 时的极限；做题时先看清是哪一个方向，若是 x→∞ 则两个方向都要算且结果相同。","keyPoints":["先分清 x→+∞ 还是 x→−∞","x→∞ 要求两个方向结果相同","无穷远处的极限与函数在有限点处的取值无关"],"example":"lim_{x→+∞} e^{−x}=0，而 lim_{x→−∞} e^{−x}=+∞。"},
  "kp-m2-p1-c1-ji-xian-xing-zhi-2": {"anchor":"lim(f±g)=lim f±lim g；lim(fg)=lim f·lim g","caption":"函数极限具有唯一性、局部有界性与保号性，并满足四则运算：当各部分极限都存在时，和差积商的极限等于极限的和差积商（商的极限要求分母极限不为 0）。","keyPoints":["四则运算的前提是各部分极限都存在","商的极限要求分母极限不为 0","保号性：极限 >0 ⇒ 在去心邻域内函数值 >0"],"example":"lim_{x→1}(x²+3x)=1+3=4。"},
  "kp-m2-p1-c1-wu-qiong-xiao": {"anchor":"lim f(x)=0 ⇔ f 为无穷小","caption":"极限为 0 的变量称为无穷小，它是一个变量而不是「很小的常数」。","keyPoints":["无穷小是极限为 0 的变量，不是很小的数","lim f=A ⇔ f=A+α（α→0）","有限个无穷小的和、积仍是无穷小；无穷小与有界量的积也是无穷小"],"example":"x→0 时 sin x 是无穷小；而 10⁻¹⁰ 是常数，不是无穷小。"},
  "kp-m2-p1-c1-wu-qiong-da": {"anchor":"lim f(x)=∞ ⇔ lim 1/f(x)=0","caption":"当 |f(x)| 无限增大时称 f 为无穷大，记作 lim f=∞。","keyPoints":["无穷大是绝对值无限增大的变量","lim f=∞ ⇔ lim 1/f=0（同一过程，f≠0）","无穷大不是数，∞−∞、∞/∞ 都是未定式"],"example":"x→0 时 1/x 是无穷大，1/x² 也是（且趋于 +∞）。"},
  "kp-m2-p1-c1-wu-qiong-xiao-bi-jiao": {"anchor":"lim α/β=1 ⇔ α∼β","caption":"比较两个无穷小看它们的比值极限：比值为 0 说明前者是高阶无穷小，为非零常数说明同阶，为 1 说明等价，为 c≠0 时 α 是 β 的 k 阶无穷小。","keyPoints":["lim α/β=0 ⇒ α=o(β)（高阶无穷小）","lim α/β=c≠0 ⇒ 同阶；c=1 ⇒ 等价 α∼β","lim α/βᵏ=c≠0 ⇒ α 是 β 的 k 阶无穷小"],"example":"x→0 时 1−cos x∼x²/2，所以它是 x 的二阶无穷小。"},
  "kp-m2-p1-c1-chang-yong-deng-jia-wu-qiong-xiao": {"anchor":"sin x∼x（x→0）","caption":"x→0 时的常用等价无穷小是一张速查表：sin x、tan x、arcsin x、arctan x、ln(1+x)","keyPoints":["基本组：sin x∼tan x∼arcsin x∼arctan x∼ln(1+x)∼eˣ−1∼x","1−cos x∼x²/2，(1+x)^α−1∼αx","等价无穷小只在乘除结构中使用，加减慎用"],"example":"lim_{x→0} ln(1+x)/x=1。"},
  "kp-m2-p1-c1-lim-x-0-sin-x-x-1": {"anchor":"lim_{x→0} sin x/x=1","caption":"lim_{x→0} sin x/x=1 是三角函数极限的基准，它说明 x→0 时 sin x 与 x 是同阶等价的无穷小。","keyPoints":["lim_{x→0} sin x/x=1","与等价无穷小 sin x∼x 是同一件事的两种说法","常用于含三角函数的 0/0 型"],"example":"lim_{x→0} sin 5x/(2x)=5/2。"},
  "kp-m2-p1-c1-lim-x-0-1-x-1-x-e": {"anchor":"lim_{x→0}(1+x)^{1/x}=e","caption":"lim_{x→0}(1+x)^{1/x}=e 是处理 1^∞ 型未定式的标准结构，也可以用 lim_{x→∞}(1+1/x)ˣ=e 的等价形式。","keyPoints":["lim_{x→0}(1+x)^{1/x}=e","等价形式 lim_{x→∞}(1+1/x)ˣ=e","凑结构时括号内趋于 1、指数趋于 ∞ 且互为倒数"],"example":"lim_{x→0}(1−2x)^{1/x}=e^{−2}。"},
  "kp-m2-p1-c1-chang-jian-fu-he-bian-xing": {"anchor":"lim u^v=e^{lim v(u−1)}（1^∞ 型）","caption":"重要极限常需要先变形：提取常数、换元、凑倒数结构，或把 1^∞ 型写成 e^{lim v(u−1)} 的形式；变形的目标是让式子与标准结构一致。","keyPoints":["先凑成标准结构，再套结论","1^∞ 型可用 lim u^v=e^{lim v(u−1)}","换元后极限过程要一起换"],"example":"lim_{x→0}(cos x)^{1/x²}=e^{−1/2}。"},
  "kp-m2-p1-c1-0-0": {"anchor":"lim f/g（f→0，g→0）","caption":"0/0 型是最常见的未定式，处理思路是「把导致为 0 的因子约掉」：因式分解、有理化、等价无穷小替换、洛必达或泰勒都可以，按结构选最省力的。","keyPoints":["核心是约去公共的零因子","因式分解与有理化最直接","复杂结构用等价替换或泰勒展开"],"example":"lim_{x→2}(x²−4)/(x−2)=lim(x+2)=4。"},
  "kp-m2-p1-c1-x-045koy": {"anchor":"lim (aₙxⁿ+…)/(bₘxᵐ+…) = aₙ/bₘ（n=m）","caption":"∞/∞ 型的思路是「比较分子分母的增长速度」：多项式比值看最高次项，指数、幂函数、对数按增长速度排序。","keyPoints":["多项式：比较分子分母的最高次数","增长速度：ln x ≪ xᵏ ≪ aˣ（a>1）","也可以用洛必达（满足条件时）"],"example":"lim_{x→∞}(3x²+x)/(x²−1)=3。"},
  "kp-m2-p1-c1-0": {"anchor":"0·∞ ⇒ f/(1/g)","caption":"0·∞ 型要化成商：把其中一个因子取倒数放到分母，变成 0/0 或 ∞/∞，再用相应方法处理。","keyPoints":["变形目标：0/0 或 ∞/∞","选择便于求导的因子放到分母","对数与幂函数相乘时，通常把对数留在分子"],"example":"lim_{x→0⁺} x ln x=lim (ln x)/(1/x)=0。"},
  "kp-m2-p1-c1-x-1lez14": {"anchor":"√(x²+x)−x 有理化后求极限","caption":"∞−∞ 型先通分（分式差）或有理化（根式差），把它变成商的形式，再看是 0/0 还是 ∞/∞；也可以提取主项比较。","keyPoints":["分式差通分，根式差有理化","提取主项也是常用手段","∞−∞ 的目标是化成商的形式，再通分求极限"],"example":"lim_{x→∞}(√(x²+x)−x)=1/2。"},
  "kp-m2-p1-c1-1": {"anchor":"lim u^v=e^{lim v(u−1)}","caption":"1^∞ 型用 lim u^v=e^{lim v(u−1)} 处理，或取对数化成 0·∞ 再算；前提是底数趋于 1、指数趋于无穷。","keyPoints":["公式：lim u^v=e^{lim v(u−1)}（u→1，v→∞）","也可取对数，化成 0·∞ 处理","结果一般是 e 的某次幂"],"example":"lim_{x→0}(1+x)^{1/x}=e。"},
  "kp-m2-p1-c1-0-0-2": {"anchor":"u^v=e^{v ln u}","caption":"0⁰ 型取对数后变成 0·ln0（即 0·∞），再化成商的形式处理；结果通常形如 e^A。","keyPoints":["取对数：ln y=v ln u","化成 0·∞ 后再化为商","0⁰ 型的结果形如 e^A，指数由取极限算出"],"example":"lim_{x→0⁺} xˣ=e^{lim x ln x}=e⁰=1。"},
  "kp-m2-p1-c1-0-2": {"anchor":"u^v=e^{v ln u}","caption":"∞⁰ 型同样取对数化成 0·∞（此时是 0·ln∞），再化为商求极限，结果也是 e 的某次幂。","keyPoints":["与 0⁰ 同法：取对数 → 0·∞ → 商","底数趋于 ∞ 时 ln u→∞","结果通常为 e^A 或 1"],"example":"lim_{x→∞} x^{1/x}=e^{lim (ln x)/x}=e⁰=1。"},
  "kp-m2-p1-c1-zhi-jie-dai-ru": {"anchor":"lim_{x→a}f(x)=f(a)（f 在 a 连续时）","caption":"把 x 的趋向值直接代入，若得到确定的数，极限就是它。","keyPoints":["先代入判断类型，可能直接得到答案","代入得到确定常数时极限即为该常数","只有七种未定式才需要继续处理"],"example":"lim_{x→1}(x²+2x)=3。"},
  "kp-m2-p1-c1-yin-shi-fen-jie": {"anchor":"a²−b²=(a−b)(a+b)；a³−b³=(a−b)(a²+ab+b²)","caption":"0/0 型常用因式分解：把分子分母分解成乘积，约去导致为 0 的公因子，再代入求值。","keyPoints":["目标是找出并约去公因子 (x−a)","常用工具：提公因式、平方差、立方差、十字相乘","约去后必须把结果代回原式检验"],"example":"lim_{x→1}(x³−1)/(x−1)=lim(x²+x+1)=3。"},
  "kp-m2-p1-c1-you-li-hua": {"anchor":"(√a−√b)(√a+√b)=a−b","caption":"遇到根式相减或分母含根号时，用共轭式有理化，把根号差变成可约的形式，常用于 0/0 与 ∞−∞ 型。","keyPoints":["根式差乘以共轭式，用平方差消去根号","有理化后通常出现可约的公因子","√a−√b 的共轭式是 √a+√b"],"example":"lim_{x→0}(√(1+x)−1)/x=lim 1/(√(1+x)+1)=1/2。"},
  "kp-m2-p1-c1-tong-fen": {"anchor":"1/f−1/g=(g−f)/(fg)","caption":"∞−∞ 型的分式差用通分合并成一个分式，再看是 0/0 还是 ∞/∞，然后按相应方法处理。","keyPoints":["分式差先通分合并成一项，再约去零因子","通分后通常变成 0/0 或 ∞/∞","合并后常用等价无穷小或洛必达"],"example":"lim_{x→0}(1/sin x−1/x)=0。"},
  "kp-m2-p1-c1-ti-qu-zui-gao-ci-xiang": {"anchor":"lim (aₙxⁿ+…)/(bₘxᵐ+…)","caption":"处理 x→∞ 的 ∞/∞ 型时，把分子分母的最高次项提出来，其余项都趋于 0，极限就由最高次项之比决定。","keyPoints":["提最高次项后低次项趋于 0","分子次数高则极限为 ∞，低则为 0，相等则为系数比","根式里也要提最高次项（注意开方）"],"example":"lim_{x→∞}(2x²+3)/(x²−x)=2。"},
  "kp-m2-p1-c1-deng-jia-wu-qiong-xiao": {"anchor":"α∼β ⇒ lim α/γ=lim β/γ（乘除结构）","caption":"在乘除结构中可以用等价无穷小替换化简（如 x→0 时 sin x∼x）；加减结构不能随便替换，否则会丢失高阶项导致错误结论。","keyPoints":["乘除结构中的因子可直接替换，加减不能","加减结构要慎用，改用泰勒展开","替换前先确认变量趋于 0"],"example":"lim_{x→0} tan x/sin 2x=lim x/(2x)=1/2。"},
  "kp-m2-p1-c1-zhong-yao-ji-xian": {"anchor":"lim_{x→0} sin x/x=1；lim_{x→0}(1+x)^{1/x}=e","caption":"两个重要极限 lim_{x→0} sin x/x=1 与 lim_{x→0}(1+x)^{1/x}=e 是处理三角函数与","keyPoints":["sin x/x → 1（x→0）","(1+x)^{1/x} → e（x→0）","用前先凑结构，必要时换元"],"example":"lim_{x→0} sin 2x/x=2。"},
  "kp-m2-p1-c1-jia-bi": {"anchor":"g≤a≤h，lim g=lim h=A ⇒ lim a=A","caption":"夹逼准则：若 gₙ≤aₙ≤hₙ 且两侧趋于同一极限，则中间数列也趋于该极限；它常用于含 n 项和或带 n 次方的极限。","keyPoints":["夹逼的两侧极限必须相同，否则夹不出来","放缩时不等号方向要一致","常用于数列与 n 项和"],"example":"lim_{n→∞}(1/√(n²+1)+…+1/√(n²+n))=1。"},
  "kp-m2-p1-c1-luo-bi-da": {"anchor":"lim f/g=lim f′/g′","caption":"洛必达法则：0/0 或 ∞/∞ 型且满足可导条件时，lim f/g=lim f′/g′。","keyPoints":["只适用于 0/0 与 ∞/∞ 型","要求分子分母在去心邻域内可导且分母导数不为 0","求导后仍是未定式可以继续用"],"example":"lim_{x→0}(eˣ−1)/x=lim eˣ/1=1。"},
  "kp-m2-p1-c1-tai-le": {"anchor":"f(x)=Σ f⁽ᵏ⁾(0)xᵏ/k!+o(xⁿ)","caption":"泰勒（麦克劳林）展开把函数写成多项式加余项，处理加减结构的未定式最可靠：展开到「分子分母最低次幂相消」所需的阶数即可。","keyPoints":["展开阶数要够：分母是 xᵏ 就展到 xᵏ","加减结构用泰勒比等价替换更安全","常用展开：eˣ、sin x、cos x、ln(1+x)、(1+x)^α"],"example":"lim_{x→0}(x−sin x)/x³=lim (x³/6)/x³=1/6。"},
  "kp-m2-p1-c1-huan-yuan": {"anchor":"x→∞ 时令 t=1/x → 0","caption":"换元能把复杂结构化成标准形式：令 t=1/x 处理 x→∞，令 t=x−a 处理 x→a；换元时极限过程必须同步替换。","keyPoints":["换元后极限过程要一起改","t=1/x 常把 ∞ 化成 0","换元后式子更接近标准结构"],"example":"lim_{x→∞} x sin(1/x)=lim_{t→0} sin t/t=1。"},
  "kp-m2-p1-c1-lian-xu-ding-yi": {"anchor":"lim_{x→x₀}f(x)=f(x₀)","caption":"f 在 x₀ 连续指 lim_{x→x₀}f(x)=f(x₀)，即函数值存在、极限存在、两者相等三条同时成立。","keyPoints":["三条：f(x₀) 有定义、极限存在、两者相等","等价写法：f(x₀−)=f(x₀+)=f(x₀)","连续是逐点概念，区间上连续指每一点都连续"],"example":"f(x)=x² 在 x=1 连续：极限为 1，等于 f(1)。"},
  "kp-m2-p1-c1-jian-duan-dian": {"anchor":"第一类：左右极限都存在","caption":"间断点按左右极限的表现分类：左右极限都存在的是第一类（可去、跳跃），至少一侧不存在的是第二类（无穷、振荡）。","keyPoints":["可去间断点：左右极限存在且相等，但与函数值不等","跳跃间断点：左右极限存在但不相等","无穷 / 振荡间断点属于第二类"],"example":"f(x)=sin(1/x) 在 0 处是振荡间断点（第二类）。"},
  "kp-m2-p1-c1-chu-deng-han-shu-lian-xu-xing": {"anchor":"初等函数在定义区间内连续","caption":"基本初等函数在其定义域内连续，初等函数在其定义区间内连续；这条结论让求极限退化为代入求值，是最省力的一步。","keyPoints":["基本初等函数在定义域内连续","初等函数在定义区间内连续","求极限先尝试直接代入"],"example":"lim_{x→0}(eˣ+sin x)=1。"},
  "kp-m2-p1-c1-bi-qu-jian-lian-xu-han-shu-xing-zhi": {"anchor":"f(a)·f(b)<0 ⇒ ∃ξ∈(a,b)，f(ξ)=0","caption":"f 在闭区间 [a,b] 上连续，则它有界、能取到最大值与最小值，并具有介值性；特别地，f(a)·f(b)<0 时区间内必有零点（零点定理）。","keyPoints":["有界性与最值定理：闭区间上必取到最大值、最小值","介值定理：介于最小值与最大值之间的值都能取到","零点定理：f(a)·f(b)<0 ⇒ ∃ξ∈(a,b) 使 f(ξ)=0"],"example":"f(x)=x³−x−1 在 [1,2] 上连续且端点异号，故有零点。"},
  "kp-m2-p1-c2-dao-shu-ding-yi": {"anchor":"f′(x₀)=lim_{Δx→0}[f(x₀+Δx)−f(x₀)]/Δx","caption":"导数 f′(x₀)=lim_{Δx→0}[f(x₀+Δx)−f(x₀)]/Δx 是函数在一点处的瞬时变化率，它由差商的极限定义。","keyPoints":["导数是差商的极限，不是「变化量相除」","分段点处要用定义算左右导数，不能直接用求导公式","可导的等价形式：f(x₀+Δx)−f(x₀)=f′(x₀)Δx+o(Δx)"],"example":"f(x)=|x| 在 0 处：左右导数分别为 −1 与 1，故不可导。"},
  "kp-m2-p1-c2-ji-he-yi-yi": {"anchor":"y−f(x₀)=f′(x₀)(x−x₀)","caption":"导数的几何意义是切线斜率：f′(x₀) 就是曲线 y=f(x) 在 (x₀,f(x₀)) 处切线的斜率","keyPoints":["f′(x₀) 等于该点切线的斜率","可导 ⇔ 存在非竖直的切线","法线斜率与切线斜率互为负倒数"],"example":"y=x³ 在 x=1 处：f(1)=1、f′(1)=3，切线为 y−1=3(x−1)。"},
  "kp-m2-p1-c2-wu-li-yi-yi": {"anchor":"v(t)=s′(t)，a(t)=s″(t)","caption":"导数的物理意义是变化率：位移的导数是速度，速度的导数是加速度；凡是「变化快慢」的量都可以用导数表示。","keyPoints":["v(t)=s′(t)，a(t)=v′(t)=s″(t)","导数的正负表示增或减","「速率」是速度的绝对值"],"example":"s(t)=2t²，则 v(t)=4t，t=1 时 v=4。"},
  "kp-m2-p1-c2-ke-dao-yu-lian-xu": {"anchor":"可导 ⇒ 连续","caption":"可导一定连续，但连续不一定可导（如 y=|x| 在 0 处）。","keyPoints":["可导 ⇒ 连续；连续 ⇏ 可导","不连续 ⇒ 一定不可导（反向用）","连续但「尖点」或「竖直切线」处不可导"],"example":"y=|x| 在 0 处连续但不可导，说明连续不是充分条件。"},
  "kp-m2-p1-c2-wei-fen-gai-nian": {"anchor":"Δy=AΔx+o(Δx) ⇔ f′(x)=A","caption":"一元函数里「可微」与「可导」是等价的：若 Δy 能写成 AΔx+o(Δx)，则 A 就是 f′(x)，微分就是 dy=f′(x)dx。","keyPoints":["可微 ⇔ 可导（一元函数独有的结论）","可微意味着增量能被线性函数很好地近似","微分的核心是「线性主部」这个思想"],"example":"y=x²：Δy=2xΔx+(Δx)²，线性主部为 2xΔx，故 dy=2xdx。"},
  "kp-m2-p1-c2-dy-f-x-dx": {"anchor":"dy=f′(x)dx","caption":"dy=f′(x)dx 是微分的标准写法：它把「导数」与「自变量微分」相乘得到因变量的微分，求微分本质上就是求导再乘 dx。","keyPoints":["dy=f′(x)dx，求微分先求导","自变量的微分 dx=Δx","微分形式在复合函数中仍然成立（形式不变性）"],"example":"y=sin x 的微分为 dy=cos x dx。"},
  "kp-m2-p1-c2-xian-xing-zhu-bu": {"anchor":"Δy=dy+o(dx)，dy 为线性主部","caption":"Δy 中与 Δx 成正比的那部分 AΔx 就是线性主部，也就是微分；剩下的部分比 Δx 更高阶地趋于 0，可以忽略。","keyPoints":["线性主部 = 与 Δx 成正比的那一项","剩余部分比 Δx 更高阶，近似时可忽略","这是「以直代曲」的数学依据"],"example":"y=x³：Δy=3x²Δx+3x(Δx)²+(Δx)³，线性主部为 3x²Δx。"},
  "kp-m2-p1-c2-wei-fen-jin-si": {"anchor":"f(x₀+Δx)≈f(x₀)+f′(x₀)Δx","caption":"微分近似就是「以直代曲」：f(x₀+Δx)≈f(x₀)+f′(x₀)Δx，当 |Δx| 很小时误差可以接受。","keyPoints":["公式：f(x₀+Δx)≈f(x₀)+f′(x₀)Δx","|Δx| 越小误差越小","常用近似：√(1+x)≈1+x/2，eˣ≈1+x，ln(1+x)≈x"],"example":"e^{0.01}≈1+0.01=1.01。"},
  "kp-m2-p1-c2-yi-jie-wei-fen-xing-shi-bu-bian-xing": {"anchor":"dy=f′(x)dx（x 为中间变量时同样成立）","caption":"无论 x 是自变量还是中间变量，微分都可以写成 dy=f′(x)dx 的形式，这就是一阶微分形式不变性；它使微分运算与变量选择无关。","keyPoints":["dy=f′(x)dx 对自变量与中间变量都成立","形式不变性让换元与复合运算更统一","注意导数 f′(x) 的含义随变量角色变化"],"example":"y=sin(x²) 时 dy=cos(x²)·2x dx，外层导数与内层微分直接相乘。"},
  "kp-m2-p1-c2-ji-ben-chu-deng-han-shu-dao-shu-gong-shi": {"anchor":"(sin x)′=cos x；(tan x)′=1/cos²x","caption":"基本初等函数的导数构成求导的基础：幂函数、指数函数、对数函数、三角函数、反三角函数各有固定公式，其余函数的导数都由它们与求导法则推得。","keyPoints":["幂函数： (xᵃ)′=αxᵃ⁻¹","指数与对数： (eˣ)′=eˣ，(aˣ)′=aˣln a，(ln x)′=1/x","三角与反三角： (sin x)′=cos x，(tan x)′=1/cos²x，(arcsin x)′=1/√(1−x²)"],"example":"(x³+ln x)′=3x²+1/x。"},
  "kp-m2-p1-c2-si-ze-yun-suan": {"anchor":"(uv)′=u′v+uv′；(u/v)′=(u′v−uv′)/v²","caption":"(u±v)′=u′±v′，(uv)′=u′v+uv′，(u/v)′=(u′v−uv′)/v²（v≠0）；这些法则要求各部分可导。","keyPoints":["(uv)′=u′v+uv′，不要写成 u′v′","(u/v)′ 的分母是 v²，分子是 u′v−uv′","商法则可由乘积法则推出"],"example":"(x sin x)′=sin x+x cos x。"},
  "kp-m2-p1-c2-fu-he-han-shu": {"anchor":"[f(g(x))]′=f′(g(x))·g′(x)","caption":"复合函数求导用链式法则：外层导数乘以内层导数，[f(g(x))]′=f′(g(x))·g′(x)；多层复合就一层层乘下去。","keyPoints":["链式法则：外层对内层求导，再乘内层对自变量求导","多层复合要「由外到内」逐层乘","求导后不要漏乘最内层的导数"],"example":"(sin 2x)′=cos 2x·2=2cos 2x。"},
  "kp-m2-p1-c2-fan-han-shu-qiu-dao": {"anchor":"(f⁻¹)′(y)=1/f′(x)","caption":"反函数的导数等于原函数导数的倒数：(f⁻¹)′(y)=1/f′(x)，其中 y=f(x)。","keyPoints":["(f⁻¹)′(y)=1/f′(x)（f′(x)≠0）","反函数的定义域是原函数的值域","arcsin、arctan 的导数公式都由它推出"],"example":"y=eˣ 的反函数 x=ln y，导数为 1/eˣ=1/y。"},
  "kp-m2-p1-c2-yin-han-shu-qiu-dao": {"anchor":"F(x,y)=0 ⇒ y′=−Fₓ/Fᵧ（Fᵧ≠0）","caption":"方程 F(x,y)=0 确定隐函数时，两边同时对 x 求导，把 y 视为 x 的函数（用链式法则），再解出 y′；结果一般同时含 x 与 y。","keyPoints":["两边对 x 求导，遇 y 的项要乘 y′","求导后把含 y′ 的项集中解出","高阶导数要在此基础上继续求导"],"example":"x²+y²=1 ⇒ 2x+2yy′=0 ⇒ y′=−x/y。"},
  "kp-m2-p1-c2-can-shu-fang-cheng-qiu-dao": {"anchor":"dy/dx=(dy/dt)/(dx/dt)；d²y/dx²=[d/dt(dy/dx)]/(dx/dt)","caption":"参数方程 x=x(t)、y=y(t) 的导数 dy/dx=(dy/dt)/(dx/dt)；","keyPoints":["dy/dx=(dy/dt)/(dx/dt)，要求 dx/dt≠0","二阶导数要对 dy/dx 再对 t 求导，再除以 dx/dt","摆线、星形线等常考参数方程求导"],"example":"x=t²、y=t³ 时 dy/dx=3t²/(2t)=3t/2。"},
  "kp-m2-p1-c2-dui-shu-qiu-dao": {"anchor":"(ln y)′=y′/y","caption":"对数求导法先把 y 取对数，把乘积、商、幂的运算降级为加减乘，再求导；对幂指函数 u^v 尤其有效。","keyPoints":["适用对象：幂指函数、多个因子连乘除","步骤：取对数 → 求导 → 乘回 y","幂指函数也可直接用 e^{v ln u} 求导"],"example":"y=(x+1)²/(x−1) ⇒ ln y=2ln(x+1)−ln(x−1)。"},
  "kp-m2-p1-c2-fen-duan-han-shu-qiu-dao": {"anchor":"f′(a−)=f′(a+) ⇒ f 在 a 可导","caption":"分段函数在每段内部按普通公式求导，但在分界点必须回到导数定义，或比较左右导数是否相等；左右导数不相等就不可导。","keyPoints":["各段内部直接用求导公式","分界点必须用定义或左右导数判断","左右导数相等才可导，且导数值为该公共值"],"example":"f(x)=x²（x≥0）、x（x<0）在 0 处左右导数为 0 与 1，故不可导。"},
  "kp-m2-p1-c2-er-jie": {"anchor":"f″(x)=[f′(x)]′","caption":"二阶导数 f″(x) 是 f′(x) 的导数，表示变化率的变化率；它用于判断凹凸性、极值的充分条件与加速度等。","keyPoints":["f″=(f′)′，记号 f″ 或 d²y/dx²","f″>0 曲线凹（下凸），f″<0 曲线凸","f′(x₀)=0 且 f″(x₀)<0 ⇒ 极大值"],"example":"y=x³：y′=3x²，y″=6x。"},
  "kp-m2-p1-c2-n-jie": {"anchor":"f⁽ⁿ⁾(x)","caption":"n 阶导数 f⁽ⁿ⁾ 是对 f 连续求导 n 次；常用方法：对简单函数归纳规律、对有理分式先拆项、对乘积用莱布尼茨公式。","keyPoints":["简单函数：算前几阶找规律再归纳","有理分式：先部分分式分解再逐项求导","乘积：用莱布尼茨公式 (uv)⁽ⁿ⁾"],"example":"y=e^{2x} 的 n 阶导数为 2ⁿe^{2x}。"},
  "kp-m2-p1-c2-chang-jian-han-shu-zhou-qi-gui-l": {"anchor":"(xᵏ)⁽ⁿ⁾=k!/(k−n)!·x^{k−n}","caption":"三角函数求导四阶一循环，指数函数每阶乘一个常数，幂函数每阶降一次幂；把这些规律记住，n 阶导数就能直接写出。","keyPoints":["sin、cos 的导数四阶循环","(xᵏ)⁽ⁿ⁾=k(k−1)…(k−n+1)x^{k−n}（n≤k）","n>k 时幂函数的 n 阶导数为 0"],"example":"(x⁵)‴=5·4·3x²=60x²。"},
  "kp-m2-p1-c2-jian-dan-cheng-ji-gao-jie-dao-shu": {"anchor":"(x²v)⁽ⁿ⁾=x²v⁽ⁿ⁾+2nxv⁽ⁿ⁻¹⁾+n(n−1)v⁽ⁿ⁻²⁾","caption":"当乘积中有一个低次多项式（如 x²、x³）时，用莱布尼茨公式只需保留到该多项式的阶数，后面各项都因导数为 0 而消失，计算量很小。","keyPoints":["xᵏ 的 (k+1) 阶及以上导数都为 0","求和项数 = 多项式次数 + 1","系数仍要带组合数 Cₙᵏ"],"example":"(x²sin x)‴ 只需前三项。"},
  "kp-m2-p1-c2-fei-ma-ding-li": {"anchor":"f′(x₀)=0","caption":"费马定理：若 x₀ 是 f 的内点极值点且 f 在 x₀ 可导，则 f′(x₀)=0。","keyPoints":["条件：内点 + 极值 + 可导 ⇒ f′(x₀)=0","逆命题不成立（f′(x₀)=0 不一定是极值，如 y=x³）","端点极值不受此约束，费马定理只针对内点"],"example":"y=x³ 在 0 处导数为 0，但不是极值点，说明逆命题不成立。"},
  "kp-m2-p1-c2-luo-er-ding-li": {"anchor":"f(a)=f(b) ⇒ ∃ξ∈(a,b)，f′(ξ)=0","caption":"罗尔定理：f 在 [a,b] 上连续、(a,b) 内可导且 f(a)=f(b)，则存在 ξ∈(a,b) 使 f′(ξ)=0。","keyPoints":["三个条件：闭区间连续、开区间可导、端点值相等","结论：内部存在一点导数为 0","常用作构造辅助函数后证明存在性"],"example":"f(x)=x²−x 在 [0,1] 上满足条件，ξ=1/2 处导数为 0。"},
  "kp-m2-p1-c2-la-ge-lang-ri-zhong-zhi-ding-li": {"anchor":"f(b)−f(a)=f′(ξ)(b−a)","caption":"拉格朗日中值定理：f 在 [a,b] 上连续、(a,b) 内可导，则存在 ξ∈(a,b) 使 f(b)−f(a)=f′(","keyPoints":["公式：f(b)−f(a)=f′(ξ)(b−a)","可写成 f′(ξ)=[f(b)−f(a)]/(b−a)，即割线斜率等于某点切线斜率","常用来证明不等式与估计增量"],"example":"f(x)=x² 在 [1,2] 上：4−1=f′(ξ)(2−1) ⇒ ξ=3/2。"},
  "kp-m2-p1-c2-ke-xi-zhong-zhi-ding-li": {"anchor":"[f(b)−f(a)]/[g(b)−g(a)]=f′(ξ)/g′(ξ)","caption":"柯西中值定理：f、g 在 [a,b] 上连续、(a,b) 内可导且 g′(x)≠0","keyPoints":["公式：[f(b)−f(a)]/[g(b)−g(a)]=f′(ξ)/g′(ξ)","要求 g′(x)≠0（否则分母无意义）","取 g(x)=x 即退化为拉格朗日中值定理"],"example":"取 g(x)=x² 可推出 [f(b)−f(a)]/(b²−a²)=f′(ξ)/(2ξ)。"},
  "kp-m2-p1-c2-tai-le-duo-xiang-shi": {"anchor":"Pₙ(x)=Σₖ₌₀ⁿ f⁽ᵏ⁾(x₀)(x−x₀)ᵏ/k!","caption":"泰勒多项式是泰勒公式中的多项式部分 Pₙ(x)=Σₖ₌₀ⁿ f⁽ᵏ⁾(x₀)(x−x₀)ᵏ/k!","keyPoints":["Pₙ 与 f 在 x₀ 处的值与前 n 阶导数都相同","阶数越高逼近越好（在展开点附近）","余项衡量逼近误差，展开阶数越高误差越小"],"example":"sin x 的三次泰勒多项式为 x−x³/3!。"},
  "kp-m2-p1-c2-mai-ke-lao-lin-gong-shi": {"anchor":"f(x)=Σₖ₌₀ⁿ f⁽ᵏ⁾(0)xᵏ/k!+o(xⁿ)","caption":"麦克劳林公式是泰勒公式在 x₀=0 时的特例：f(x)=f(0)+f′(0)x+f″(0)x²/2!","keyPoints":["eˣ=1+x+x²/2!+…；sin x=x−x³/3!+x⁵/5!−…","cos x=1−x²/2!+x⁴/4!−…；ln(1+x)=x−x²/2+x³/3−…","(1+x)^α=1+αx+α(α−1)x²/2!+…"],"example":"e^x=1+x+x²/2+o(x²)。"},
  "kp-m2-p1-c2-pi-ya-nuo-yu-xiang": {"anchor":"Rₙ(x)=o((x−x₀)ⁿ)","caption":"皮亚诺余项形如 o((x−x₀)ⁿ)，只说明「比 n 次幂更高阶地趋于 0」，不给出具体大小；它的优点是条件弱（只要 n 阶导数存在），适合求极限。","keyPoints":["形式：Rₙ(x)=o((x−x₀)ⁿ)","只要求 n 阶导数存在，条件较弱","求极限时用皮亚诺余项即可"],"example":"lim_{x→0}(eˣ−1−x)/x²=1/2（用 eˣ=1+x+x²/2+o(x²)）。"},
  "kp-m2-p1-c2-la-ge-lang-ri-yu-xiang": {"anchor":"Rₙ(x)=f⁽ⁿ⁺¹⁾(ξ)(x−x₀)ⁿ⁺¹/(n+1)!","caption":"拉格朗日余项形如 f⁽ⁿ⁺¹⁾(ξ)(x−x₀)ⁿ⁺¹/(n+1)!","keyPoints":["形式：Rₙ(x)=f⁽ⁿ⁺¹⁾(ξ)(x−x₀)ⁿ⁺¹/(n+1)!","ξ 在 x 与 x₀ 之间（存在性，不具体）","要求 f 有 n+1 阶导数"],"example":"估计 e^{0.1} 的误差时，用 R₁=e^ξ(0.1)²/2≤0.006（ξ∈(0,0.1)）。"},
  "kp-m2-p1-c2-e-x": {"anchor":"eˣ=1+x+x²/2!+o(x²)","caption":"eˣ 的麦克劳林展开是 eˣ=1+x+x²/2!","keyPoints":["eˣ=1+x+x²/2!+…+xⁿ/n!+o(xⁿ)","每阶导数都是 eˣ，所以系数全是 1/k!","常用于含 eˣ 的极限与近似"],"example":"lim_{x→0}(eˣ−1−x)/x²=1/2。"},
  "kp-m2-p1-c2-sin-x": {"anchor":"sin x=x−x³/6+o(x³)","caption":"sin x 的展开式只含奇次项且符号交替：sin x=x−x³/3!","keyPoints":["sin x=x−x³/3!+x⁵/5!−…","只含奇次项（因为 sin x 是奇函数）","求三角相关极限时展开到足够阶"],"example":"lim_{x→0}(x−sin x)/x³=1/6。"},
  "kp-m2-p1-c2-cos-x": {"anchor":"cos x=1−x²/2+o(x²)","caption":"cos x 的展开式只含偶次项且符号交替：cos x=1−x²/2!","keyPoints":["cos x=1−x²/2!+x⁴/4!−…","cos x 的展开只含偶次项，指数与阶乘同为 2n","1−cos x∼x²/2 就来自这个展开"],"example":"lim_{x→0}(1−cos x)/x²=1/2。"},
  "kp-m2-p1-c2-ln-1-x": {"anchor":"ln(1+x)=x−x²/2+o(x²)","caption":"ln(1+x)=x−x²/2+x³/3−…（|x|<1），系数是 1/k 且符号交替；它是处理含对数极限的主要工具。","keyPoints":["ln(1+x)=x−x²/2+x³/3−…","系数为 (−1)^{k+1}/k","注意定义域 x>−1"],"example":"lim_{x→0}(ln(1+x)−x)/x²=−1/2。"},
  "kp-m2-p1-c2-1-x": {"anchor":"(1+x)^α=1+αx+α(α−1)x²/2+o(x²)","caption":"(1+x)^α=1+αx+α(α−1)x²/2!","keyPoints":["(1+x)^α=1+αx+α(α−1)x²/2+…","α 为任意实数（不必是正整数）","α=−1 时得到 1/(1+x)=1−x+x²−…"],"example":"√(1+x)=1+x/2−x²/8+o(x²)。"},
  "kp-m2-p1-c2-ji-xian": {"anchor":"lim f/g：把 f、g 展到同阶","caption":"泰勒展开是求复杂极限的可靠工具：把各因子展开到「分子分母最低次幂不再相消」的阶数，再比较同次项即可；它比等价无穷小替换更安全。","keyPoints":["展开阶数要够：分母是 xᵏ 就展到 xᵏ","加减结构尤其要用泰勒（等价替换会丢高阶项）","合并同类项后取最低次幂比较"],"example":"lim_{x→0}(tan x−sin x)/x³=1/2。"},
  "kp-m2-p1-c2-wu-qiong-xiao-jie-shu": {"anchor":"α∼cxᵏ ⇒ α 是 k 阶无穷小","caption":"把无穷小展开后，第一个非零项的幂次就是它的阶：例如 1−cos x=x²/2−… 是二阶无穷小，x−sin x=x³/6−… 是三阶无穷小。","keyPoints":["展开式中第一个非零项的幂次 = 阶数","同阶无穷小之比趋于非零常数","阶数比较常用于确定展开到多少阶"],"example":"tan x−x∼x³/3，故它是三阶无穷小。"},
  "kp-m2-p1-c2-jin-si": {"anchor":"f(x)≈f(0)+f′(0)x","caption":"用泰勒展开的前一两项就能做近似：eˣ≈1+x、√(1+x)≈1+x/2、ln(1+x)≈x，误差由余项控制。","keyPoints":["常用近似：eˣ≈1+x，sin x≈x，ln(1+x)≈x","误差由拉格朗日余项估计","x 越小泰勒近似越好，误差是高阶无穷小"],"example":"ln 1.02≈0.02。"},
  "kp-m2-p1-c2-bu-deng-shi": {"anchor":"eˣ=1+x+e^ξx²/2>1+x（x≠0）","caption":"泰勒展开常用来证明不等式：把函数展开后比较各项符号，或用拉格朗日余项的符号确定不等号方向，例如 eˣ>1+x（x>0）。","keyPoints":["余项符号决定不等号方向","eˣ>1+x（x≠0），ln(1+x)<x（x>0）","证明时注意自变量范围"],"example":"x>0 时 ln(1+x)<x，因为 ln(1+x)=x−x²/2+…"},
  "kp-m2-p1-c2-0-0": {"anchor":"lim f/g=lim f′/g′（0/0 型）","caption":"洛必达法则处理 0/0 型：在满足条件时 lim f/g=lim f′/g′。","keyPoints":["先确认类型是 0/0","要求 f、g 在去心邻域内可导且 g′≠0","一次求导后仍是 0/0 可以继续用"],"example":"lim_{x→0}(sin x)/x=lim cos x/1=1。"},
  "kp-m2-p1-c2-x-045koy": {"anchor":"lim f/g=lim f′/g′（∞/∞ 型）","caption":"∞/∞ 型同样可以用洛必达：lim f/g=lim f′/g′，条件与 0/0 型相同；求导后仍为 ∞/∞ 时继续使用。","keyPoints":["用洛必达前先确认是 ∞/∞ 型，型不对会算错","条件：可导且分母导数不为 0","也可以先比较增长阶（更快）"],"example":"lim_{x→∞} (ln x)/x=lim (1/x)/1=0。"},
  "kp-m2-p1-c2-qi-ta-wei-ding-shi-zhuan-hua": {"anchor":"1^∞：u^v=e^{v ln u}","caption":"0·∞ 化成商、∞−∞ 通分或有理化、1^∞/0⁰/∞⁰ 取对数，都能把未定式转化为 0/0 或 ∞/∞ 再处理。","keyPoints":["0·∞ ⇒ f/(1/g) 化成商","∞−∞ ⇒ 通分或有理化","1^∞、0⁰、∞⁰ ⇒ 取对数化成 0·∞"],"example":"lim_{x→0⁺} x ln x=lim (ln x)/(1/x)=0。"},
  "kp-m2-p1-c2-duo-ci-luo-bi-da": {"anchor":"lim f/g=lim f′/g′（每步都需满足条件）","caption":"连续使用洛必达的前提是每一步都满足条件；如果某一步求导后不再是未定式，就必须停下直接算。","keyPoints":["每一步都要验证类型与可导条件","一旦不是未定式立即停止","求导过程中式子变复杂时应改用泰勒"],"example":"lim_{x→0}(eˣ−1−x)/x² 连续用两次洛必达得 1/2。"},
  "kp-m2-p1-c2-shi-yong-tiao-jian": {"anchor":"lim f/g=lim f′/g′（三条都满足时）","caption":"洛必达的使用条件：① 是 0/0 或 ∞/∞ 型；② 分子分母在去心邻域内可导且分母导数不为 0；③ lim f′/g′ 存在（或为 ∞）。","keyPoints":["必须是 0/0 或 ∞/∞ 型","去心邻域内可导且 g′≠0","要求 lim f′/g′ 存在或为 ∞"],"example":"lim_{x→∞}(x+sin x)/x 不能用洛必达（求导后极限不存在），但直接看出极限为 1。"},
  "kp-m2-p1-c2-dan-diao-xing": {"anchor":"f′>0 ⇒ f 递增","caption":"f′>0 的区间上 f 单调递增，f′<0 的区间上单调递减；导数为 0 的点是分界点，需要判断符号是否变化。","keyPoints":["f′>0 ⇒ 递增；f′<0 ⇒ 递减（在区间上）","f′≡0 ⇒ f 为常数","求单调区间要先求定义域，再解 f′ 的符号"],"example":"f(x)=x³−3x：f′=3x²−3，在 (−∞,−1) 与 (1,+∞) 递增。"},
  "kp-m2-p1-c2-ji-zhi": {"anchor":"f′ 由正变负 ⇒ 极大值","caption":"极值是局部概念：f′ 由正变负处取极大值，由负变正处取极小值；f′(x₀)=0 只是必要条件，还要看符号变化或二阶导数。","keyPoints":["第一充分条件：f′ 变号（+→− 极大，−→+ 极小）","第二充分条件：f′(x₀)=0 且 f″(x₀)<0 为极大，>0 为极小","f′(x₀)=0 但不是极值的例子：y=x³"],"example":"y=x³−3x 在 x=−1 取极大值 2，在 x=1 取极小值 −2。"},
  "kp-m2-p1-c2-zui-da-zhi-yu-zui-xiao-zhi": {"anchor":"M=max{f(候选点)}","caption":"闭区间上求最值：算出所有驻点、不可导点与端点的函数值，比较大小即可；实际问题中若只有一个驻点且函数先增后减，该点就是最大值点。","keyPoints":["候选点：驻点、不可导点、区间端点","闭区间连续 ⇒ 一定有最大值与最小值","实际问题可用「唯一驻点 + 单调性」直接判定"],"example":"f(x)=x³−3x 在 [0,2] 上：比较 f(0)=0、f(1)=−2、f(2)=2，最大 2、最小 −2。"},
  "kp-m2-p1-c2-ao-tu-xing": {"anchor":"f″>0 ⇒ 凹","caption":"f″>0 时曲线是凹的（下凸），f″<0 时是凸的（上凸）；凹凸性也可以用弦与曲线的高低关系定义。","keyPoints":["f″>0 ⇒ 凹（下凸），f″<0 ⇒ 凸（上凸）","等价定义：凹 ⇔ f((x₁+x₂)/2)<[f(x₁)+f(x₂)]/2","凹凸性与一阶导数无关"],"example":"y=x² 的 f″=2>0，故曲线凹（开口向上）。"},
  "kp-m2-p1-c2-guai-dian": {"anchor":"f″ 变号 ⇒ 拐点","caption":"拐点是曲线凹凸性改变的点：f″ 在该点两侧变号；f″(x₀)=0 只是候选条件，必须验证符号确实变化。","keyPoints":["判据：f″ 在 x₀ 两侧变号","f″(x₀)=0 不一定是拐点（如 y=x⁴ 在 0 处）","f″(x₀)=0 且 f‴(x₀)≠0 ⇒ 是拐点"],"example":"y=x³ 在 0 处 f″=6x 变号，故 (0,0) 是拐点。"},
  "kp-m2-p1-c2-jian-jin-xian": {"anchor":"a=lim_{x→∞} f(x)/x，b=lim_{x→∞}[f(x)−ax]","caption":"渐近线有三类：铅直（x→x₀ 时 f→∞）、水平（x→∞ 时 f→b）、斜（f(x)−(ax+b)→0","keyPoints":["铅直渐近线出现在函数的无穷间断点处","水平渐近线是 x→∞ 时的极限值","斜渐近线要先求 a=lim f(x)/x，再求 b"],"example":"y=x+1/x 有铅直渐近线 x=0 与斜渐近线 y=x。"},
  "kp-m2-p1-c2-han-shu-zuo-tu": {"anchor":"五步：定义域 → f′ → f″ → 渐近线 → 描点","caption":"函数作图的标准流程是：定义域与对称性、单调性与极值、凹凸性与拐点、渐近线、特殊点；把每一步的信息汇总成表格再画图最清楚。","keyPoints":["先看定义域与奇偶性（能减少计算量）","单调性、极值、凹凸、拐点都要列表","渐近线是图形远处走向的关键"],"example":"y=x/(1+x²) 是奇函数，只需画 x>0 的部分再对称。"},
  "kp-m2-p1-c2-hu-wei-fen": {"anchor":"ds=√(1+y′²)dx；参数式 ds=√(x′²+y′²)dt","caption":"把曲线切得足够碎，每一小段都近似成直线段：横向走 dx、纵向变化 dy=y′dx，斜边就是这一小段的长度 ds，因此 ds=√(1+y′²)dx。","keyPoints":["ds=√(dx²+dy²)=√(1+y′²)dx","参数式：ds=√(x′²+y′²)dt","弧微分是长度元素，与曲率（方向变化率）是两回事"],"example":"y=x² 时 ds=√(1+4x²)dx；x=0 处 ds=dx。"},
  "kp-m2-p1-c2-qu-l": {"anchor":"κ=|y″|/(1+y′²)^{3/2}","caption":"曲率描述切线方向随弧长变化的快慢：同样走过一小段弧长，切线转得越快，曲率越大；直线的曲率为 0。","keyPoints":["曲率刻画「弯曲程度」，与参数化方式无关","直线的曲率为 0，圆的曲率为半径的倒数","参数式也有对应公式 κ=|x′y″−x″y′|/(x′²+y′²)^{3/2}"],"example":"半径为 R 的圆，曲率为 1/R。"},
  "kp-m2-p1-c2-qu-l-gong-shi": {"anchor":"κ=|y″|/(1+y′²)^{3/2}","caption":"当曲线由 y=y(x) 给出时，曲率的计算公式是 κ=|y″|/(1+y′²)^{3/2}；","keyPoints":["直角坐标：κ=|y″|/(1+y′²)^{3/2}","参数式：κ=|x′y″−x″y′|/(x′²+y′²)^{3/2}","分母的三次方来自弧微分"],"example":"y=x² 在 x=0 处：y′=0、y″=2，κ=2。"},
  "kp-m2-p1-c2-qu-l-ban-jing": {"anchor":"ρ=1/κ","caption":"曲率半径 ρ=1/κ 是「与该点弯曲程度相当的圆的半径」：曲率越大，曲率半径越小。","keyPoints":["ρ=1/κ，与曲率互为倒数","直线的曲率半径为无穷大","圆的曲率半径就是它的半径"],"example":"y=x² 在 x=0 处 κ=2，故 ρ=1/2。"},
  "kp-m2-p1-c2-qu-l-yuan": {"anchor":"圆心 = 该点沿法线方向移动 ρ","caption":"曲率圆（密切圆）是与曲线在该点有相同切线、相同曲率的圆，圆心在曲线的凹侧、半径为曲率半径；它给出了曲线在该点附近的圆形近似。","keyPoints":["曲率圆与曲线在该点相切且曲率相同","圆心在法线上、位于凹侧，半径 ρ=1/κ","用圆近似曲线是曲率圆的实际意义"],"example":"y=x² 在 x=0 处曲率圆为 x²+(y−1/2)²=1/4。"},
  "kp-m2-p1-c3-yuan-han-shu": {"anchor":"F′(x)=f(x)","caption":"f 的原函数就是「导数等于 f」的函数：F′=f。","keyPoints":["F′=f 就是原函数的定义","原函数一定在某个区间上讨论","初等函数的原函数未必是初等函数（如 e^{−x²}）"],"example":"x²/2 是 x 的原函数。"},
  "kp-m2-p1-c3-yuan-han-shu-zu": {"anchor":"F(x)+C","caption":"同一函数的任意两个原函数只相差一个常数，所以全部原函数构成 F(x)+C 的形式，称为原函数族；这正是不定积分要加常数 C 的原因。","keyPoints":["两个原函数之差必为常数","原函数族 = F(x)+C（C 取遍实数）","C 的任意性来自「常数导数为 0」"],"example":"x²/2、x²/2+3、x²/2−1 都是 x 的原函数。"},
  "kp-m2-p1-c3-bu-ding-ji-fen": {"anchor":"∫f(x)dx=F(x)+C","caption":"不定积分 ∫f(x)dx=F(x)+C 表示 f 的全部原函数，它的结果是函数族而不是一个函数；求不定积分就是求原函数，结果必须带常数 C。","keyPoints":["∫f(x)dx=F(x)+C，结果是函数族","求导与积分互为逆运算：(∫f dx)′=f","不定积分与定积分的区别：前者是函数，后者是数"],"example":"∫2x dx=x²+C。"},
  "kp-m2-p1-c3-ji-fen-chang-shu": {"anchor":"∫f dx=F(x)+C","caption":"积分常数 C 表示原函数族的任意性，在不定积分里不可省略；而在定积分中，常数会在上下限相减时抵消，所以定积分结果里不写 C。","keyPoints":["不定积分必须写 +C","定积分由 F(b)−F(a) 得到，常数自动抵消","同一个不定积分可以写成不同形式（相差常数）"],"example":"∫cos x dx=sin x+C。"},
  "kp-m2-p1-c3-ji-ben-xing-zhi": {"anchor":"∫(k₁f+k₂g)dx=k₁∫f dx+k₂∫g dx","caption":"不定积分的基本性质有两条：线性性（常数可提、和差可拆）与互逆性（微分与积分互为逆运算）。","keyPoints":["线性：∫(k₁f+k₂g)dx=k₁∫f dx+k₂∫g dx","互逆：(∫f dx)′=f(x)，∫f′(x)dx=f(x)+C","没有「积的积分等于积分之积」这种法则"],"example":"∫(2x+cos x)dx=x²+sin x+C。"},
  "kp-m2-p1-c3-mi-han-shu": {"anchor":"∫xᵃdx=xᵃ⁺¹/(α+1)+C（α≠−1）","caption":"∫xᵃdx=xᵃ⁺¹/(α+1)+C（α≠−1）；α=−1 是唯一的例外，此时 ∫dx/x=ln|x|+C，不能套幂公式。","keyPoints":["∫xᵃdx=xᵃ⁺¹/(α+1)+C（α≠−1）","α=−1 时用 ∫dx/x=ln|x|+C","负指数、分数指数都按同一公式处理"],"example":"∫√x dx=∫x^{1/2}dx=(2/3)x^{3/2}+C。"},
  "kp-m2-p1-c3-zhi-shu": {"anchor":"∫aˣdx=aˣ/ln a+C","caption":"指数函数积分：∫eˣdx=eˣ+C；底数不是 e 时要除以 ln a，∫aˣdx=aˣ/ln a+C。","keyPoints":["∫eˣdx=eˣ+C，最省事","∫aˣdx=aˣ/ln a+C","与换元结合可处理 e^{kx} 型"],"example":"∫e^{2x}dx=e^{2x}/2+C。"},
  "kp-m2-p1-c3-dui-shu-xing": {"anchor":"∫dx/x=ln|x|+C","caption":"对数型积分的特征是分母为 f、分子为 f′，结果就是 ln|f|；这类结构在换元法里出现频率极高，要养成「先看分子是不是分母的导数」的习惯。","keyPoints":["∫f′/f dx=ln|f|+C","分子差常数倍时把常数提到积分号外","结果必须带绝对值与 C"],"example":"∫cos x/sin x dx=ln|sin x|+C。"},
  "kp-m2-p1-c3-san-jiao": {"anchor":"∫cos x dx=sin x+C","caption":"三角函数积分的基本组：sin 积分得 −cos，cos 积分得 sin，tan 的积分是 −ln|cos x|；组合式子逐项处理。","keyPoints":["∫sin x dx=−cos x+C；∫cos x dx=sin x+C","∫tan x dx=−ln|cos x|+C","平方项用降幂公式 ∫sin²x dx=x/2−sin2x/4+C"],"example":"∫sin²x dx=∫(1−cos2x)/2 dx=x/2−sin2x/4+C。"},
  "kp-m2-p1-c3-fan-san-jiao-xing": {"anchor":"∫dx/√(a²−x²)=arcsin(x/a)+C","caption":"含 √(a²−x²) 分母的积分结果是 arcsin，含 a²+x² 分母的积分结果是 arctan；这类结构要能一眼认出来。","keyPoints":["∫dx/√(a²−x²)=arcsin(x/a)+C","∫dx/(a²+x²)=(1/a)arctan(x/a)+C","关键是分母是「平方和」还是「平方差开根」"],"example":"∫dx/√(9−x²)=arcsin(x/3)+C。"},
  "kp-m2-p1-c3-di-yi-lei-huan-yuan": {"anchor":"g′(x)dx=d[g(x)]","caption":"第一类换元（凑微分）不改变变量，只是把被积表达式整理成「某个函数的微分」的形式，从而直接套用基本积分表。","keyPoints":["目标：把 dx 前的东西凑成 d(内层函数)","常用凑法：xdx=d(x²)/2，dx/x=d(ln x)，cos x dx=d(sin x)","换元是「心里的」，最后要回代"],"example":"∫sin 2x dx=(1/2)∫sin 2x d(2x)=−cos 2x/2+C。"},
  "kp-m2-p1-c3-di-er-lei-huan-yuan": {"anchor":"x=φ(t) ⇒ dx=φ′(t)dt","caption":"第二类换元主动引入新变量 t 替换 x，目的是把根式或复杂结构化成容易积分的形式；三角代换与根式代换都属于这一类。","keyPoints":["三角代换处理 √(a²±x²)、√(x²−a²)","根式代换处理 ⁿ√(ax+b)","换元后积分限（定积分）要一起换"],"example":"∫dx/(1+√x) 令 t=√x。"},
  "kp-m2-p1-c3-san-jiao-dai-huan": {"anchor":"x=a sin t ⇒ √(a²−x²)=a cos t","caption":"遇到 √(a²−x²)、√(a²+x²)、√(x²−a²) 分别令 x=a sin t、x=a tan t","keyPoints":["√(a²−x²) ⇒ x=a sin t","√(a²+x²) ⇒ x=a tan t","√(x²−a²) ⇒ x=a sec t"],"example":"∫dx/√(1−x²)=arcsin x+C 就是 x=sin t 的结果。"},
  "kp-m2-p1-c3-gen-shi-dai-huan": {"anchor":"t=ⁿ√(ax+b) ⇒ x=(tⁿ−b)/a","caption":"被积函数含 ⁿ√(ax+b) 时，令 t=ⁿ√(ax+b)，把根号整体换成 t，从而化成有理函数积分；换元时 x 与 dx 都要用 t 表示。","keyPoints":["t=ⁿ√(ax+b) 一次消掉整个根号","要同时解出 x=(tⁿ−b)/a 与 dx","化成有理函数后再用部分分式"],"example":"∫dx/(1+√x) 令 t=√x，得 ∫2t/(1+t)dt。"},
  "kp-m2-p1-c3-gong-shi": {"anchor":"∫u dv=uv−∫v du","caption":"分部积分的公式是 ∫u dv=uv−∫v du，它来自乘积求导公式的逆用；核心是「把不好积的部分转移成好积的部分」。","keyPoints":["∫u dv=uv−∫v du","选 u 的标准：求导后更简单","出现循环时把原积分移项解出"],"example":"∫ln x dx=x ln x−x+C。"},
  "kp-m2-p1-c3-duo-xiang-shi-zhi-shu": {"anchor":"∫xⁿeˣdx=xⁿeˣ−n∫xⁿ⁻¹eˣdx","caption":"多项式乘指数时取多项式作 u、指数作 dv，一次分部就把多项式次数降一；n 次多项式最多分部 n 次即可积完。","keyPoints":["u=多项式，dv=指数 dx","多项式因子每分部一次次数降一，最终耗尽","降次到常数后可直接积分"],"example":"∫x²eˣdx=eˣ(x²−2x+2)+C。"},
  "kp-m2-p1-c3-duo-xiang-shi-san-jiao": {"anchor":"∫x sin x dx=−x cos x+∫cos x dx","caption":"多项式乘三角函数同样取多项式作 u、三角作 dv；分部后多项式降次，注意 v 的符号（sin 积成 −cos 会带负号）。","keyPoints":["u=多项式，dv=三角函数 dx","求 v 时符号容易错（∫sin=−cos）","n 次多项式最多分部 n 次"],"example":"∫x cos x dx=x sin x+cos x+C。"},
  "kp-m2-p1-c3-dui-shu-han-shu": {"anchor":"∫ln x dx=x ln x−x+C","caption":"含对数的积分一律取对数作 u：ln x 求导变成 1/x，分部后剩下的积分通常很简单。","keyPoints":["u=ln x 或 ln(x+a)","dv=其余（常取 dx）","结果中一般仍含 ln，但次数降低"],"example":"∫ln x dx=x ln x−x+C。"},
  "kp-m2-p1-c3-fan-san-jiao-han-shu": {"anchor":"∫arctan x dx=x arctan x−ln(1+x²)/2+C","caption":"反三角函数求导后变成有理式或根式，所以含反三角的积分取它作 u、其余作 dv，一次分部就能化简。","keyPoints":["u=arcsin x / arctan x 等","取 u 后其余部分整体作 dv，凑微分要顺手","分部后化成有理式或根式积分"],"example":"∫arcsin x dx=x arcsin x+√(1−x²)+C。"},
  "kp-m2-p1-c3-you-li-han-shu": {"anchor":"∫dx/(x−a)=ln|x−a|+C","caption":"有理函数积分的关键是化成部分分式：先保证是真分式（否则做除法），再按分母的因式类型拆开，最后逐项积分。","keyPoints":["真分式才能直接拆部分分式","有理函数积分先分解分母因式，再拆部分分式","结果通常含 ln 与 arctan"],"example":"∫dx/(x²+1)=arctan x+C。"},
  "kp-m2-p1-c3-bu-fen-fen-shi": {"anchor":"P/Q=Σ(简单分式)","caption":"部分分式是把一个复杂分式拆成若干简单分式之和，使每一项都能直接积分；设系数时用待定系数法（代值法或比较系数法）。","keyPoints":["按分母因式逐项设待定系数","k 重因式要写全 k 项部分分式，缺一不可","求待定系数时代入特殊值最快，如取 x=0"],"example":"(2x+3)/[(x−1)(x+1)]=5/2/(x−1)−1/2/(x+1)。"},
  "kp-m2-p1-c3-san-jiao-han-shu-you-li-shi": {"anchor":"t=tan(x/2)，dx=2dt/(1+t²)","caption":"三角函数有理式可用万能代换 t=tan(x/2) 化成 t 的有理函数再积分；但能用凑微分或恒等变形解决时更快，不要一上来就万能代换。","keyPoints":["t=tan(x/2)：sin x=2t/(1+t²)，cos x=(1−t²)/(1+t²)","万能代换一定可行但计算量大","优先尝试凑微分与恒等变形"],"example":"∫dx/(1+cos x)=tan(x/2)+C。"},
  "kp-m2-p1-c3-jian-dan-wu-li-han-shu": {"anchor":"t=ⁿ√(ax+b)","caption":"含根号的积分先想办法把根号消掉（根式代换或三角代换），变成有理函数后按有理函数积分流程处理。","keyPoints":["根号在分母时常用根式代换","根号形如 √(a²−x²) 时用三角代换","化成有理函数是最终目标"],"example":"∫dx/(1+√(1+x)) 令 t=√(1+x)。"},
  "kp-m2-p1-c3-ding-yi-yu-ji-he-yi-yi": {"anchor":"∫ₐᵇf(x)dx = 面积的代数和","caption":"定积分的定义是黎曼和的极限，几何意义是曲边梯形的面积：f≥0 时为面积本身，f 变号时表示面积的代数和。","keyPoints":["f≥0 时 ∫ₐᵇf 就是曲边梯形面积","f<0 的部分贡献负值","几何意义常用于判断积分值的正负与大小"],"example":"∫₋₁¹x dx=0（正负面积抵消）。"},
  "kp-m2-p1-c3-ji-ben-xing-zhi-2": {"anchor":"mL≤∫ₐᵇf(x)dx≤ML","caption":"定积分的基本性质包括线性性、区间可加性与保号性；它们不依赖原函数，可以直接用来比较积分大小或做估值。","keyPoints":["线性：∫(k₁f+k₂g)=k₁∫f+k₂∫g","可加：∫ₐᵇ=∫ₐᶜ+∫ᶜᵇ","保号与估值：f≤g ⇒ ∫f≤∫g；mL≤∫ₐᵇf≤ML"],"example":"∫₀¹x³dx≤∫₀¹x²dx。"},
  "kp-m2-p1-c3-ding-ji-fen-zhong-zhi-ding-li": {"anchor":"∫ₐᵇf(x)dx=f(ξ)(b−a)","caption":"定积分中值定理：f 在 [a,b] 上连续，则存在 ξ∈[a,b] 使 ∫ₐᵇf(x)dx=f(ξ)(b−a)；","keyPoints":["∫ₐᵇf=f(ξ)(b−a)，ξ 在区间内","前提是 f 在闭区间上连续","函数平均值 f̄=(1/(b−a))∫ₐᵇf 就是 f(ξ)"],"example":"∫₀¹x²dx=1/3=f(ξ)，故 ξ=1/√3。"},
  "kp-m2-p1-c3-ji-fen-shang-xian-han-shu": {"anchor":"Φ(x)=∫ₐˣf(t)dt ⇒ Φ′(x)=f(x)","caption":"Φ(x)=∫ₐˣf(t)dt 称为积分上限函数，若 f 连续则 Φ′(x)=f(x)；它是构造原函数的工具，也是牛顿—莱布尼茨公式的基础。","keyPoints":["Φ′(x)=f(x)（f 连续）","上下限都是函数时：d/dx∫_{u}^{v}f=f(v)v′−f(u)u′","被积函数含 x 时要先换元或把 x 提出来"],"example":"d/dx∫₀^{x²}sin t dt=sin(x²)·2x。"},
  "kp-m2-p1-c3-niu-dun-lai-bu-ni-ci-gong-shi": {"anchor":"∫ₐᵇf(x)dx=F(b)−F(a)","caption":"牛顿—莱布尼茨公式 ∫ₐᵇf(x)dx=F(b)−F(a)（F′=f）把定积分化为原函数在端点的差，是计算定积分的基本工具。","keyPoints":["∫ₐᵇf(x)dx=F(b)−F(a)，F 是 f 的任一个原函数","把「求和取极限」变成「两点作差」","换元时上下限要同步替换"],"example":"∫₀¹2x dx=[x²]₀¹=1。"},
  "kp-m2-p1-c3-wu-qiong-qu-jian": {"anchor":"lim_{R→+∞}∫ₐ^R f(x)dx","caption":"积分限含无穷时称为无穷区间反常积分，必须按极限定义处理：∫ₐ^{+∞}f=lim_{R→+∞}∫ₐ^R f。","keyPoints":["先积分再取极限，两步不能省","∫₁^{+∞}dx/xᵖ 在 p>1 时收敛","被积函数趋于 0 不是收敛的充分条件"],"example":"∫₁^{+∞}dx/x 发散（p=1）。"},
  "kp-m2-p1-c3-wu-jie-bei-ji-han-shu": {"anchor":"lim_{ε→0⁺}∫_ε^b f(x)dx","caption":"被积函数在区间内无界时（如 1/√x 在 x=0），积分要按瑕点处的极限定义；这种积分称为瑕积分。","keyPoints":["瑕点可能出现在端点，也可能在内部","内部有瑕点必须拆成两段","∫₀¹dx/xᵖ 在 p<1 时收敛"],"example":"∫₀¹dx/x^{0.5}=2 收敛；∫₀¹dx/x 发散。"},
  "kp-m2-p1-c3-shou-lian-fa-san": {"anchor":"∞ 处 p>1 收敛；瑕点处 p<1 收敛","caption":"判断反常积分的敛散要分清场景：无穷区间看 p>1，瑕点附近看 p<1；用等价无穷小找出主导项最方便。","keyPoints":["无穷区间：p>1 收敛","瑕点附近：p<1 收敛","两段都收敛才算整体收敛"],"example":"∫₀¹dx/x^{0.8} 收敛（p=0.8<1）。"},
  "kp-m2-p1-c3-qi-dian-chai-fen": {"anchor":"∫ₐᵇ=lim∫ₐ^{c−ε}+lim∫_{c+ε}^b","caption":"瑕点在区间内部时，把它作为拆分点把积分分成两段，逐段判断；这是避免「正负抵消得出错误结果」的必要步骤。","keyPoints":["内部瑕点 → 必须拆","每段单独按极限定义判断","任一段发散 ⇒ 整体发散"],"example":"∫₋₁¹dx/x² 在 0 处瑕点，拆开后都发散。"},
  "kp-m2-p1-c3-ping-mian-mian-ji": {"anchor":"A=∫ₐᵇ[f(x)−g(x)]dx","caption":"求平面面积先画图，确定上下（或左右）边界与交点，再按「上减下」积分；面积一定是正数，算出负值说明上下取反了。","keyPoints":["面积 = ∫(上−下)dx，结果为正","两曲线的交点决定积分限，先联立解交点","必要时改对 y 积分"],"example":"y=√x 与 y=x 围成的面积 =1/6。"},
  "kp-m2-p1-c3-qu-xian-hu-chang": {"anchor":"s=∫ₐᵇ√(1+y′²)dx","caption":"曲线弧长是弧微分的积分：s=∫ₐᵇ√(1+y′²)dx；参数式用 s=∫√(x′²+y′²)dt，极坐标用 s=∫√(r²+r′²)dθ。","keyPoints":["直角坐标：s=∫ₐᵇ√(1+y′²)dx","参数式：s=∫√(x′²+y′²)dt","极坐标：s=∫√(r²+r′²)dθ"],"example":"y=(2/3)x^{3/2} 在 [0,3] 上的弧长 =14/3。"},
  "kp-m2-p1-c3-xuan-zhuan-ti-ti-ji": {"anchor":"V=π∫ₐᵇf²(x)dx","caption":"绕 x 轴旋转的体积用圆盘法 V=π∫ₐᵇf²(x)dx；若是两曲线之间的区域旋转，则 V=π∫(f²−g²)dx。","keyPoints":["V=π∫ₐᵇf²(x)dx（绕 x 轴）","两曲线之间：V=π∫(f²−g²)dx","绕 y 轴时改对 y 积分"],"example":"y=√x 在 [0,1] 绕 x 轴：V=π∫₀¹x dx=π/2。"},
  "kp-m2-p1-c3-xuan-zhuan-ti-ce-mian-ji": {"anchor":"S=2π∫|y|ds","caption":"旋转体侧面积要把弧微元 ds 旋转成圆环再积分：S=2π∫|y|ds，其中 ds=√(1+y′²)dx。","keyPoints":["S=2π∫|y|ds","ds 不能漏（这是与体积公式最大的区别）","绕 y 轴时用 2π∫|x|ds"],"example":"球面面积 4πR² 可由半圆旋转得到。"},
  "kp-m2-p1-c3-ping-xing-jie-mian-ti-ji": {"anchor":"V=∫ₐᵇA(x)dx","caption":"若垂直于某轴的截面面积 A(x) 已知，体积 V=∫ₐᵇA(x)dx；这是「切片求和」的推广，适用于非旋转体。","keyPoints":["V=∫ₐᵇA(x)dx","关键是写出截面积函数","旋转体是平行截面体的特例，截面恰为圆"],"example":"已知正三角形截面的立体，A(x)=(√3/4)a²(x)。"},
  "kp-m2-p1-c3-gong": {"anchor":"W=∫ₐᵇF(x)dx","caption":"变力做功 W=∫ₐᵇF(x)dx；抽水做功要写清微元：每层水的重力乘以它被提升的距离。","keyPoints":["W=∫ₐᵇF(x)dx","抽水：微元重力 ρgA(x)dx × 提升距离","物理应用先写微元再积分，微元是建模关键"],"example":"把水抽到容器顶面：W=ρg∫₀ʰ(h−x)A(x)dx。"},
  "kp-m2-p1-c3-yin-li": {"anchor":"F=∫Gmρdx/r²（按方向分量积分）","caption":"细杆对质点的引力用微元法：把杆分成小段，每段质量 dm=ρdx，按万有引力定律写微元力，再沿杆积分（注意分解方向分量）。","keyPoints":["微元质量 dm=ρdx","微元力 dF=Gm·dm/r²","必须分解方向分量再积分"],"example":"细杆对延长线上距端点 a 处质点的引力含 ln(1+L/a)。"},
  "kp-m2-p1-c3-ye-ti-ya-li": {"anchor":"P=∫ρgx·L(x)dx","caption":"液体压力用微元法：深度 x 处压强为 ρgx，微元压力 dP=ρgx·L(x)dx，总压力 P=∫ρgx·L(x)dx。","keyPoints":["压强 = ρgx（x 为深度）","dP=ρgx·L(x)dx","关键是写出该深度处的宽度 L(x)"],"example":"宽 b、高 h 的矩形闸门顶与水面平齐：P=ρgbh²/2。"},
  "kp-m2-p1-c3-zhi-xin": {"anchor":"x̄=∫x dm/M","caption":"质心是质量分布的加权平均位置：x̄=∫x dm/∫dm；均匀物体的密度为常数，质心退化为形心。","keyPoints":["质心 = ∫x dm / ∫dm","非均匀物体要带密度函数","均匀物体：质心 = 形心"],"example":"均匀半圆板的质心在对称轴上距圆心 4R/(3π) 处。"},
  "kp-m2-p1-c3-xing-xin": {"anchor":"x̄=(1/A)∫x dA","caption":"形心是几何图形的中心，只与形状有关：x̄=(1/A)∫x dA。","keyPoints":["均匀物体的形心只依赖几何形状，与密度无关","x̄=(1/A)∫x dA","有对称轴时形心在对称轴上"],"example":"圆、矩形的形心就在几何中心。"},
  "kp-m2-p1-c3-han-shu-ping-jun-zhi": {"anchor":"f̄=(1/(b−a))∫ₐᵇf(x)dx","caption":"函数在 [a,b] 上的平均值 f̄=(1/(b−a))∫ₐᵇf(x)dx，几何意义是「等面积矩形的高度」，也正是定积分中值定理中的 f(ξ)。","keyPoints":["f̄=(1/(b−a))∫ₐᵇf(x)dx","几何意义：等面积矩形的高度","与中值定理中的 f(ξ) 相等"],"example":"f(x)=x 在 [0,2] 上的平均值为 1。"},
  "kp-m2-p1-c4-duo-yuan-han-shu-gai-nian": {"anchor":"z=f(x,y)，(x,y)∈D","caption":"多元函数是由有序数组（如 (x,y)）到实数 z 的单值对应；「单值」是底线——同一个输入点不允许对应两个不同的函数值。","keyPoints":["定义域 + 对应法则两要素","(x,y) 作为整体是一个点","单值对应：一个点只对应一个 z"],"example":"z=x²+y² 把每个平面点映成高度，是（旋转）抛物面。"},
  "kp-m2-p1-c4-er-yuan-han-shu-ding-yi-yu": {"anchor":"如 z=√(x−y) 的 D={x≥y}","caption":"定义域是使表达式有意义的全体 (x,y)：负数不开偶次方、分母不为零、对数真数为正；求完不等式组要画图看区域形状。","keyPoints":["逐条列不等式再取交集","边界画虚线（不含）或实线（含）","区域的开闭影响最值存在性"],"example":"z=1/√(1−x²−y²) 的定义域 1−x²−y²>0，即开圆盘 x²+y²<1。"},
  "kp-m2-p1-c4-er-yuan-han-shu-ji-he-yi-yi": {"anchor":"Σ: z=f(x,y)","caption":"z=f(x,y) 的图形是空间曲面：定义域每一点上方的「高度」f(x,y) 连成一片；用等值线（水平切片）与截线（固定一个变量）两个角度观察它。","keyPoints":["图形是 R³ 中的曲面","固定 y 的截线是一元函数曲线","等值线族 f=c 是曲面的俯视地图"],"example":"z=√(1−x²−y²) 是上半球面，等值线为同心圆。"},
  "kp-m2-p1-c4-you-jie-bi-qu-yu-shang-lian-xu-han-shu-1ejfup": {"anchor":"∃P₁,P₂∈D：f(P₁)=m≤f≤f(P₂)=M","caption":"二元连续函数在有界闭区域上必有最大值、最小值，且取得介于两者之间的一切值；这为「先求驻点再比边界」的最值流程提供了存在性保证。","keyPoints":["有界 + 闭 + 连续 ⇒ 最值存在","介值性：一切中间值都取得到","开区域或无界区域结论失效"],"example":"f=x²−y² 在闭圆盘 x²+y²≤1 上有最大值 1（(±1,0)）与最小值 −1（(0,±1)）。"},
  "kp-m2-p1-c4-er-chong-ji-xian": {"anchor":"lim₍ₓ,y₎→(0,0)f(x,y)=A ⇔ 与路径无关","caption":"二重极限 lim f(x,y)=A 要求点沿任意路径趋于目标时函数值都趋于 A——路径无关是定义的核心；任何一条路径上极限不同，极限就不存在。","keyPoints":["路径任意：直线、曲线、任意趋近方式","所有路径同一极限 A 才算存在","与一元「左右极限」完全不同层面的要求"],"example":"(x²y)/(x²+y²)→0：|x²y|≤(x²+y²)|y|→0 对一切路径成立。"},
  "kp-m2-p1-c4-duo-lu-jing-bi-jin": {"anchor":"沿 y=kx 的极限含 k ⇒ 不存在","caption":"研究二重极限先换几条路径试算：坐标轴、y=kx、y=kx² 是常用三套；路径之间结果不同立即判不存在，结果相同只说明「暂时没找到反例」。","keyPoints":["y=kx 检验直线方向依赖","y=kx² 检验更细的曲线路径","一致 ⇒ 仍需证明存在"],"example":"(xy)/(x²+y²) 沿 y=kx 得 k/(1+k²)，依赖 k，极限不存在。"},
  "kp-m2-p1-c4-yong-lu-jing-zheng-ming-ji-xian-bu-cun-0o8ubh": {"anchor":"lim路径₁ ≠ lim路径₂ ⇒ 极限不存在","caption":"证明极限不存在只需两条路径：沿路径一算出极限 a，沿路径二算出极限 b，a≠b 即证毕；这是多元极限里「否定」方向最省力的方法。","keyPoints":["两条路径、两个不同结果即够","常用路径：坐标轴、y=kx、y=kx²","只能证不存在，不能证存在"],"example":"(x²−y²)/(x²+y²)：沿 y=0 得 1，沿 x=0 得 −1，极限不存在。"},
  "kp-m2-p1-c4-ji-zuo-biao-si-xiang": {"anchor":"(x,y)→(0,0) ⇔ r=√(x²+y²)→0","caption":"令 x=r cosθ、y=r sinθ，点趋近原点就变成 r→0；","keyPoints":["x²+y²=r² 是核心替换","|cosθ|、|sinθ|≤1 用来放缩","对 θ 一致才有效，不能留 θ 于结果"],"example":"(x³+y³)/(x²+y²)=r(cos³θ+sin³θ)，绝对值 ≤2r→0，极限 0。"},
  "kp-m2-p1-c4-dian-lian-xu": {"anchor":"limₚ→ₚ₀f(P)=f(P₀)","caption":"f 在点 P₀ 连续即：P₀ 处有定义、二重极限存在、且极限值等于 f(P₀)；三者缺一即为间断点，多元间断点可以连成曲线。","keyPoints":["三要素齐备才连续，缺一即是间断点","初等函数在定义区域内连续","间断点判别按三要素逐条查"],"example":"f=(x²+y²)/(1+x²+y²) 处处连续（初等函数且分母恒正）。"},
  "kp-m2-p1-c4-qu-yu-lian-xu": {"anchor":"f∈C(D) ⇔ ∀P∈D 连续","caption":"f 在区域 D 内连续指 D 的每一点都连续；闭区域上还要求在边界点连续（沿区域的单侧意义），连续性是后面最值定理与可微讨论的地基。","keyPoints":["区域连续 = 内部每点连续","闭区域含边界点的连续","连续 ⇒ 极限可代入计算"],"example":"多项式函数在全平面连续，因此任何点求极限直接代入。"},
  "kp-m2-p1-c4-yi-jie-pian-dao": {"anchor":"f_x=lim_{Δx→0}（f(x+Δx,y)−f(x,y)）/Δx","caption":"f_x 是把 y 固定时对 x 的一元导数：f_x=lim_{Δx→0}[f(x+Δx,y)−f(x,y)]/Δx；","keyPoints":["固定其余变量，对目标变量求导","f_x、∂f/∂x、z_x 记号等价","偏导存在 ⇏ 连续（与一元不同）"],"example":"f=xʸ? 用 f=x²y³：f_x=2xy³、f_y=3x²y²。"},
  "kp-m2-p1-c4-er-jie-pian-dao": {"anchor":"z_xy=∂/∂y(z_x)","caption":"对一阶偏导继续求偏导得二阶偏导，共四个：z_xx、z_xy、z_yx、z_yy；","keyPoints":["四个二阶偏导：xx、xy、yx、yy","下标从左到右 = 求导次序","混合偏导连续时 xy=yx"],"example":"z=x³y³：z_x=3x²y³，z_xy=9x²y²，z_yy=6x³y。"},
  "kp-m2-p1-c4-hun-he-pian-dao": {"anchor":"f_xy=f_yx（连续时）","caption":"混合偏导 f_xy 与 f_yx 先后次序不同；当二者在所论点连续时必相等，于是可以挑「好算的次序」——这条性质是简化高阶偏导计算的主要工具。","keyPoints":["连续 ⇔ 可交换次序（充分条件）","混合偏导相等时，挑更简单的一侧计算","初等函数通常直接交换"],"example":"z=e^{xy}：z_xy 与 z_yx 都等于 e^{xy}(1+xy)。"},
  "kp-m2-p1-c4-ke-wei-ding-yi": {"anchor":"Δz=AΔx+BΔy+o(ρ)","caption":"f 在点可微指全增量能写成 Δz=AΔx+BΔy+o(ρ)，其中 ρ=√(Δx²+Δy²)；","keyPoints":["Δz=AΔx+BΔy+o(ρ)","A、B 与增量无关（是点的属性）","验证可微：用定义算极限 o(ρ)"],"example":"z=xy：Δz=yΔx+xΔy+ΔxΔy，末项 |ΔxΔy|≤ρ²/2 为 o(ρ)，可微。"},
  "kp-m2-p1-c4-dz-f-x-dx-f-y-dy": {"anchor":"dz=f_x dx+f_y dy","caption":"可微时全微分 dz=f_x dx+f_y dy：两个偏导就是线性主部的系数；求全微分的流程固定——先求两个偏导，再按公式装配。","keyPoints":["全微分公式 dz=f_x dx+f_y dy，先求两个偏导","自变量微分 dx=Δx、dy=Δy","可微是公式可用的前提"],"example":"z=e^{xy} 在 (1,0)：dz=(ye^{xy})dx+(xe^{xy})dy|_{(1,0)}=0·dx+1·dy=dy。"},
  "kp-m2-p1-c4-pian-dao-cun-zai-lian-xu-ke-wei-zhi-0cc19h": {"anchor":"偏导连续 ⇒ 可微 ⇒ 连续，且 ⇒ 偏导存在","caption":"多元的关系链是「偏导连续 ⇒ 可微 ⇒（连续 且 偏导存在）」，所有反向都不成立；判断题、选择题几乎年年考这条链上的某个箭头方向。","keyPoints":["偏导连续 ⇒ 可微（最强的充分条件）","可微 ⇒ 连续、可微 ⇒ 偏导存在","连续与偏导存在互不推出"],"example":"f=√(x²+y²) 在原点连续但不可微；f=xy/(x²+y²) 在原点偏导存在但不连续。"},
  "kp-m2-p1-c4-yi-jie-pian-dao-lian-shi-fa-ze": {"anchor":"z_x=f_u·u_x+f_v·v_x，z_y=f_u·u_y+f_v·v_y","caption":"复合函数求偏导沿「变量关系图」的每条路径取因子乘积再相加：z_x=f_u u_x+f_v v_x；图不画清、路径漏一条，结果就少一项。","keyPoints":["一条路径 = 一个乘积因子串","z_x=f_u u_x+f_v v_x","先画图、再逐路径、最后相加"],"example":"z=u²v、u=x cos y、v=x sin y：z_x=2u cos y+v sin y。"},
  "kp-m2-p1-c4-er-jie-pian-dao-2": {"anchor":"∂/∂x(f_u)=f_uu·u_x+f_uv·v_x","caption":"复合函数求二阶偏导的关键认知：一阶偏导 f_u、f_v 仍是 u、v 的复合函数，再求导时必须对它们再做一遍链式法则——这是丢分最集中的一步。","keyPoints":["f_u、f_v 仍是复合函数（同结构）","对它们求导再用链式法则展开","混合偏导连续时次序可交换"],"example":"z=f(u,v)、u=xy、v=x+y：∂/∂x(f_u)=f_uu·y+f_uv·1。"},
  "kp-m2-p1-c4-yi-lai-guan-xi-tu": {"anchor":"路径求导：根到叶逐层偏导相乘","caption":"依赖关系图（树状图）把「因变量—中间变量—自变量」的复合层次画清楚：每条从根到叶的路径对应一个乘积项，全部路径相加——图是链式法则的操作说明书。","keyPoints":["树状图的层数等于复合层数，路径数等于项数","路径数 = 乘积项数","同名变量（f(u,x)、u 含 x）最容易漏路径"],"example":"z=f(u,v)、u=x²、v=xy：树给出 z_x=2x f_u+y f_v。"},
  "kp-m2-p1-c4-yi-ge-fang-cheng-que-ding-de-yin-han-shu": {"anchor":"z_x=−F_x/F_z","caption":"F(x,y,z)=0 在条件下确定 z=z(x,y)，求偏导直接用公式 z_x=−F_x/F_z","keyPoints":["z_x=−F_x/F_z（F_z≠0 处）","推导：F(x,y,z(x,y))≡0 求偏导","代点前先算清 F_x、F_z 的值"],"example":"x²+y²+z²=3z：z_x=−2x/(2z−3)。"},
  "kp-m2-p1-c4-yin-han-shu-cun-zai-ding-li-de-li-jie": {"anchor":"F_z(P₀)≠0 ⇒ 存在邻域内唯一 z(x,y)","caption":"隐函数存在定理说：F 在点 P₀ 附近偏导连续且 F_z(P₀)≠0 时，方程局部唯一确定连续可微的 z(x,y)；","keyPoints":["F_z(P₀)≠0 是核心条件","结论只在该点邻域内成立","同时保证隐函数可求偏导"],"example":"x²+y²+z²=4z 即球面，在 (0,0,4)（顶点）F_z=2z−4=4≠0，附近可解 z。"},
  "kp-m2-p1-c4-duo-yuan-yin-han-shu-pian-dao": {"anchor":"[F_u F_v; G_u G_v]·[u_x; v_x]=−[F_x; G_x]","caption":"两个方程 F=0、G=0 确定两个隐函数 u(x,y)、v(x,y) 时，四个偏导由线性方程组解出：对方程组逐个求偏导","keyPoints":["逐条方程对 x（或 y）求导","整理成 u_x、v_x 的线性方程组","J=∂(F,G)/∂(u,v)≠0 保证可解"],"example":"F=u+v−x=0、G=u−v−y=0：u_x=v_x=1/2。"},
  "kp-m2-p1-c4-zhu-dian": {"anchor":"f_x=0 且 f_y=0","caption":"驻点指 f_x=f_y=0 的点，是极值点的候选名单；注意偏导不存在的点也可能是极值点（如尖点），也要列入候选，驻点本身不保证是极值。","keyPoints":["驻点：f_x(P₀)=0 且 f_y(P₀)=0","偏导不存在的点也进候选","驻点不一定是极值点，需过二阶充分条件"],"example":"z=x²+y² 的驻点 (0,0) 是极小值点；z=xy 的驻点 (0,0) 不是极值点。"},
  "kp-m2-p1-c4-bi-yao-tiao-jian": {"anchor":"极值点 ⇒ f_x=0 且 f_y=0","caption":"可微函数在极值点处必有两个偏导为零（费马定理的多元版）；它给出的是「必要」条件——找极值先解驻点，再靠充分条件筛选。","keyPoints":["极值点 ⇒ f_x=f_y=0（可微时）","极值点必是驻点，但逆命题不成立","应用：解方程组列候选名单"],"example":"z=x³+y³−3xy 的驻点：3x²=3y、3y²=3x，解得 (0,0) 与 (1,1)。"},
  "kp-m2-p1-c4-er-jie-chong-fen-tiao-jian": {"anchor":"Δ=AC−B²","caption":"驻点处记 A=f_xx、B=f_xy、C=f_yy：AC−B²>0 是极值点（A<0 极大、A>0 极小）","keyPoints":["AC−B²>0：极值（看 A 的符号定大小）","AC−B²<0：非极值（马鞍点）","AC−B²=0：失效，另想办法"],"example":"z=x³−y³+3x²+3y²−9x：在 (1,1) 处 A=6、B=0、C=−6，Δ=−36<0 非极值。"},
  "kp-m2-p1-c4-ji-da-ji-xiao": {"anchor":"∃U(P₀)：f(P)≤f(P₀)（极大）","caption":"极大值指在该点某邻域内 f(P₀)≥f(P)（极小反之）；极大与极小是局部概念，可以极大值小于另一个极小值，与整体最大最小值是两套话语。","keyPoints":["极大/极小按邻域定义","局部冠军 ≠ 全局冠军","极值只发生在定义域内点，边界谈最值"],"example":"z=−x²−y² 在 (0,0) 取极大值 0。"},
  "kp-m2-p1-c4-la-ge-lang-ri-cheng-shu-fa": {"anchor":"f_x+λφ_x=0，f_y+λφ_y=0，φ=0","caption":"求 f 在约束 φ=0 下的极值：构造 L=f+λφ，令 L_x=L_y=L_λ=0 解出全部候选点，再比较 f 值；","keyPoints":["L=f+λφ，三个未知数三个方程","解出候选点后必须比较 f","应用题可由实际意义定最值"],"example":"xy 在 x²+y²=1 下：L=xy+λ(x²+y²−1)，解得 xy=±1/2。"},
  "kp-m2-p1-c4-zui-da-zhi-zui-xiao-zhi-ying-yong": {"anchor":"max/min f(x,y) s.t. φ(x,y)=0","caption":"应用最值题的完整流程：设变量、写目标函数与约束、解出候选点；若实际问题保证最值存在且候选唯一，该点即最值点——省去逐点比较。","keyPoints":["目标函数 + 约束条件都来自题意","唯一候选 + 存在性 ⇒ 即最值点","最后回答题目所问的量"],"example":"表面积一定的长方体体积最大：三边相等（立方体）。"},
  "kp-m2-p1-c5-ding-yi": {"anchor":"∬_D f dσ=lim_{λ→0}Σf(ξᵢ,ηᵢ)Δσᵢ","caption":"二重积分是定积分「分割、近似、求和、取极限」思想在平面区域上的推广：把 D 切成小块、每块取点乘面积再求和，最粗小块直径趋零时的极限。","keyPoints":["和式极限与分割、取点方式无关（可积时）","连续函数在闭区域上必可积","λ→0 指最大直径趋零，不是块数趋于无穷"],"example":"f≡1 时任何分割都得 ΣΔσᵢ=面积，故 ∬1dσ=|D|。"},
  "kp-m2-p1-c5-ji-he-yi-yi": {"anchor":"V=∬_D f(x,y)dσ（f≥0）","caption":"f≥0 时 ∬_D f dσ 是以 D 为底、曲面 z=f(x,y) 为顶的柱体体积；f<0 的部分贡献「负体积」，整体值是正负部分的代数和。","keyPoints":["曲顶柱体体积（f≥0）","f≡1 ⇒ 积分=区域面积","变号函数按正负分区解释"],"example":"∬_{x²+y²≤1}(1−x²−y²)dσ 是抛物面下的体积 π/2。"},
  "kp-m2-p1-c5-ji-ben-xing-zhi": {"anchor":"m·|D|≤∬_D f dσ≤M·|D|","caption":"二重积分性质与定积分平行：线性、区域可加、保序性（大函数积分大）、估值定理与中值定理；它们是估计积分值与化简的第一工具。","keyPoints":["保序：f≤g ⇒ ∬f≤∬g","估值：m|D|≤∬f≤M|D|","中值：∬f=f(ξ,η)·|D|（连续时）"],"example":"f=√(1+x²+y²) 在单位圆盘上介于 1 与 √2：积分介于 π 与 √2π。"},
  "kp-m2-p1-c5-x-xing-qu-yu": {"anchor":"∫ₐᵇdx∫_{y₁(x)}^{y₂(x)}f dy","caption":"X 型区域：a≤x≤b、y₁(x)≤y≤y₂(x)，竖直直线穿入穿出各碰边界一次；","keyPoints":["上下边界是 x 的函数","先对 y 积（内层），再对 x（外层）","X 型区域外层限是常数，内层限含 x"],"example":"三角形 0≤x≤1、0≤y≤x：∫₀¹dx∫₀ˣf dy。"},
  "kp-m2-p1-c5-y-xing-qu-yu": {"anchor":"∫_c^d dy∫_{x₁(y)}^{x₂(y)}f dx","caption":"Y 型区域：c≤y≤d、x₁(y)≤x≤x₂(y)，水平直线穿入穿出各碰边界一次；","keyPoints":["左右边界是 y 的函数","先对 x 积（内层），再对 y（外层）","Y 型区域与 X 型互为对偶，水平穿线定限"],"example":"0≤y≤1、y²≤x≤y：∫₀¹dy∫_{y²}^y f dx。"},
  "kp-m2-p1-c5-xian-x-hou-y": {"anchor":"∫_c^d dy∫_{x₁(y)}^{x₂(y)}f dx","caption":"「先 x 后 y」指先对 x 积分（内层限是 y 的函数），再对 y 积分（外层限是常数）；适合 Y 型区域，或被积函数「先对 x 好积」的情形。","keyPoints":["内层限 x₁(y)、x₂(y) 允许含 y","外层 y 的限是常数","与穿线方向一致：水平穿线"],"example":"∫₀¹dy∫_{y²}^y xy dx：内层=x²y/2 从 y² 到 y，得 (y³−y⁵)/2。"},
  "kp-m2-p1-c5-xian-y-hou-x": {"anchor":"∫ₐᵇdx∫_{y₁(x)}^{y₂(x)}f dy","caption":"「先 y 后 x」是 X 型区域的标准次序：内层对 y（限是 x 的函数），外层对 x（常数限）；竖直穿线定内层上下界。","keyPoints":["内层限 y₁(x)、y₂(x) 允许含 x","外层 x 的限是常数","先 y 后 x 的穿线方向是竖直，从下边界穿到上边界"],"example":"∫₀¹dx∫₀^{x²}f dy：内层积出后是 x 的函数。"},
  "kp-m2-p1-c5-jiao-huan-ji-fen-ci-xu": {"anchor":"∫ₐᵇdx∫_{y₁}^{y₂}f dy=∫_c^d dy∫_{x₁}^{x₂}f dx","caption":"内层积不出来（如 e^{y²}、sin y/y、1/ln y）时交换次序：先由限反推区域并画图，再按另一方向定限；换序后往往立即化为可积形式。","keyPoints":["反推区域 → 画图 → 重定限，三步走","交换次序可能改变可积性，积不出就换序","区域描述复杂时耐心分块"],"example":"∫₀¹dy∫_{y}¹ (sin x/x)dx 换序为 ∫₀¹(sin x/x)dx∫₀ˣdy=∫₀¹sin x dx=1−cos1。"},
  "kp-m2-p1-c5-fen-qu-yu": {"anchor":"∬_D=∬_{D₁}+∬_{D₂}（可加性）","caption":"被积函数含绝对值、取整或分段表达式时，按「表达式改变的线」把区域拆开，各块用对应表达式积分后相加——区域可加性的直接应用。","keyPoints":["找到表达式的分界线（如 y=x）","分界线把 D 拆成几块","分区域后逐块积分，再把结果相加"],"example":"∬|x−y|dσ 在 [0,1]²：沿 y=x 拆两块，各块 |x−y| 分别是 y−x 与 x−y。"},
  "kp-m2-p1-c5-x-r-cos": {"anchor":"x=r cosθ","caption":"极坐标下 x=r cosθ：点到原点的距离 r 与 x 轴的夹角 θ 完全确定横坐标；θ 取 [0,2π)（或 [−π,π]），r≥0。","keyPoints":["横坐标替换为 x=r cosθ，与纵坐标成对使用","θ 的象限要用 (x,y) 的符号定","与 y=r sinθ 成对出现"],"example":"直线 x=1 在极坐标下是 r cosθ=1，即 r=1/cosθ。"},
  "kp-m2-p1-c5-y-r-sin": {"anchor":"y=r sinθ","caption":"极坐标下 y=r sinθ，与 x=r cosθ 搭配完成坐标替换；两式平方相加得 x²+y²=r²，相除得 tanθ=y/x——这两条是化简的钥匙。","keyPoints":["纵坐标替换为 y=r sinθ，平方和给出 r²","x²+y²=r²（平方和）","tanθ=y/x（象限修正）"],"example":"y=x 化为 r sinθ=r cosθ，即 tanθ=1，θ=π/4。"},
  "kp-m2-p1-c5-da-r-dr-d": {"anchor":"∬_D f dxdy=∫∫f(r cosθ,r sinθ)r dr dθ","caption":"极坐标面积微元 dA=r dr dθ：小扇环近似矩形「宽 dr × 弧长 r dθ」；这个 r 是坐标变换的雅可比，也是极坐标积分正确性的保障。","keyPoints":["面积微元换成 dA=r dr dθ，r 是雅可比","几何：宽 dr、长 r dθ 的小矩形","代换公式 ∬f dxdy=∬f·r dr dθ"],"example":"∬e^{−x²−y²}dσ 在第一象限单位圆：∫₀^{π/2}dθ∫₀¹e^{−r²}r dr=π(1−1/e)/4。"},
  "kp-m2-p1-c5-yuan-xing-huan-xing-shan-xing-qu-yu": {"anchor":"环域：∫_α^β dθ∫_{R₁}^{R₂}f·r dr","caption":"圆域、环域、扇形域在极坐标下都变成 r-θ 平面上的矩形：r 是常数区间、θ 是角度区间，二次积分的限全是常数——这是选极坐标的最大红利。","keyPoints":["圆盘：r∈[0,R]、θ∈[0,2π]","环域：r∈[R₁,R₂]","扇形：θ 限制在某角度段"],"example":"1≤x²+y²≤4 的全域：∫₀^{2π}dθ∫₁²r dr=3π。"},
  "kp-m2-p1-c5-dui-chen-xing": {"anchor":"D 关于 x 轴对称、f(x,−y)=−f ⇒ ∬_D f=0","caption":"区域关于 y 轴（或 x 轴）对称且被积函数对相应变量是偶函数时，积分等于半区域积分的两倍；是奇函数则直接为 0——先看对称再动笔。","keyPoints":["对称 + 奇 ⇒ 0","对称 + 偶 ⇒ 2×半域","对称性只对「相应变量」生效"],"example":"∬xy dσ 在单位圆盘：xy 对 x 是奇，积分为 0。"},
  "kp-m2-p1-c5-ji-ou-xing": {"anchor":"f(x,y)=f_偶+f_奇","caption":"被积函数可拆成奇偶部分时分别处理：奇偶性配合区域对称性，奇的部分清零、偶的部分折半；","keyPoints":["拆出奇部与偶部分别积","偶部在对称区域上翻倍","奇部在对应对称区域上为零"],"example":"∬(x³+3x²y)dσ 在 [−1,1]×[0,1]：x³ 对 x 奇 → 0；3x²y 保留。"},
  "kp-m2-p1-c5-qu-yu-chai-fen": {"anchor":"∬_D=∬_{D₁}+∬_{D₂}+…","caption":"区域既非 X 型也非 Y 型（或边界分段表达）时，用辅助线把它拆成若干简单区域，利用可加性分别积分；拆分线选「边界交点的连线」最自然。","keyPoints":["拆成 X 型或 Y 型之和","区域拆分以可加性为理论依据，拆完逐块算","拆分线怎么画不影响最终值，选好画的方向"],"example":"D 由 y=0、y=x、x+y=2 围成：按 x=1 拆成两个 X 型分别处理。"},
  "kp-m2-p1-c5-zuo-biao-xi-xuan-ze": {"anchor":"圆域 + x²+y² ⇒ 极坐标","caption":"坐标系选择的口诀：圆域、环域、扇形域，或被积函数含 x²+y²、y/x → 极坐标；矩形、直线边界 → 直角坐标；再按可积性决定次序。","keyPoints":["选坐标系时区域形状是第一判据，圆域用极坐标","被积函数结构是第二判据，含 x²+y² 就想 r²","两种坐标都不占优时选限简单的"],"example":"∬√(x²+y²)dσ 在圆盘：极坐标 ∫∫r·r dr dθ 一步到位。"},
  "kp-m2-p1-c5-ti-ji": {"anchor":"V=∬_D(z₂−z₁)dσ","caption":"立体由上曲面 z₂(x,y) 与下曲面 z₁(x,y) 夹投影区域 D 而成时，体积 V=∬_D(z₂−z₁)dσ；","keyPoints":["V=∬_D(z₂−z₁)dxdy","先求两曲面的交线定投影 D","上下关系随区域变化时分段积"],"example":"z=x²+y² 与 z=4 之间：V=∬_{x²+y²≤4}(4−x²−y²)dσ=8π。"},
  "kp-m2-p1-c5-ping-mian-bao-pian-zhi-liang": {"anchor":"m=∬_D ρ(x,y)dσ","caption":"面密度 ρ(x,y) 的薄片质量 m=∬_D ρ dσ；ρ 为常数时 m=ρ×面积。","keyPoints":["m=∬_D ρ(x,y)dσ","均匀薄片 m=ρ|D|","后续质心公式以 m 为分母"],"example":"ρ=xy 在 [0,1]×[0,1]：m=∫∫xy dxdy=1/4。"},
  "kp-m2-p1-c5-jian-dan-zhi-xin-wen-ti": {"anchor":"x̄=∬xρ dσ/m","caption":"薄片的质心 x̄=∬xρ dσ/m、ȳ=∬yρ dσ/m；均匀薄片质心只看几何形状（形心），对称区域先由对称性定一个坐标，往往只剩一个积分。","keyPoints":["x̄、ȳ 各是一次矩除以质量","均匀时 ρ 约掉（形心）","质心问题先用对称性定轴上坐标，少算一个积分"],"example":"均匀直角三角形 {0≤y≤1−x}：ȳ=(∬y dσ)/面积=(1/6)/(1/2)=1/3。"},
  "kp-m2-p1-c6-wei-fen-fang-cheng": {"anchor":"y′=f(x,y) 或 F(x,y,y′,…,y⁽ⁿ⁾)=0","caption":"微分方程是联系自变量、未知函数及其导数的方程，未知函数是一元函数时叫常微分方程；方程里出现导数，解它就是求函数而不是求数。","keyPoints":["方程必须含未知函数的导数，否则只是普通方程","未知函数是一元的叫常微分方程（本册范围）","解微分方程 = 由含导数的关系式求出未知函数"],"example":"y′=2x 是最简单的微分方程，解为 y=x²+C。"},
  "kp-m2-p1-c6-jie": {"anchor":"y″+2y′+y=0 是二阶方程","caption":"微分方程的阶就是方程中出现的最高阶导数的阶数；n 阶方程的通解里应含 n 个独立的任意常数，阶数与常数个数要对上。","keyPoints":["看最高阶导数定阶，不是看项数或次数","y⁽ⁿ⁾ 出现即至少 n 阶","n 阶方程通解含 n 个独立常数"],"example":"y⁽³⁾+(y″)⁴=y′ 是三阶方程——虽然 y″ 有四次方，阶只看导数的最高阶数。"},
  "kp-m2-p1-c6-jie-2": {"anchor":"把 y=φ(x) 代入，要求 F≡0","caption":"微分方程的解是代入方程后两端恒等的函数；解可以显式写成 y=f(x)，也可以由隐式方程 Φ(x,y)=0 确定，两者都算解。","keyPoints":["验证解：求导代入，要求两端恒等","显式解 y=f(x) 与隐式解 Φ(x,y)=0 都可以","解是函数，不是一个数"],"example":"y=e²ˣ 是 y″−4y=0 的解：4e²ˣ−4e²ˣ=0。"},
  "kp-m2-p1-c6-tong-jie": {"anchor":"二阶通解形如 y=C₁y₁(x)+C₂y₂(x)","caption":"n 阶微分方程的通解是含 n 个相互独立任意常数的解；「独立」指常数不能合并。","keyPoints":["通解含 n 个独立任意常数（n=方程阶数）","常数独立：合并后只剩一个就不算","通解未必是全部解（可能漏奇解）"],"example":"y″+y=0 的通解 y=C₁cos x+C₂sin x 恰含 2 个独立常数。"},
  "kp-m2-p1-c6-te-jie": {"anchor":"由 y(x₀)=y₀ 定 C","caption":"特解是不含任意常数的解，通常由初始条件把通解中的常数确定后得到；题目问「满足某条件的解」就是要找特解。","keyPoints":["特解不含任意常数，由初始条件定下来","由初始条件定出通解的常数","几何上是从通解曲线族中选出一条"],"example":"通解 y=Ceˣ 加条件 y(0)=3 得特解 y=3eˣ。"},
  "kp-m2-p1-c6-chu-shi-tiao-jian": {"anchor":"y(x₀)=y₀，y′(x₀)=y₁，…","caption":"初始条件是在某一点处给出的函数值与各阶导数值，如 y(x₀)=y₀、y′(x₀)=y₁；n 阶方程需要 n 个条件才能确定通解中的 n 个常数。","keyPoints":["n 阶方程配 n 个初始条件","条件都给在同一点 x₀ 处","一阶给函数值，二阶再加导数值"],"example":"y″+y=0 配 y(0)=1、y′(0)=0 得特解 y=cos x。"},
  "kp-m2-p1-c6-bian-liang-fen-li": {"anchor":"dy/dx=f(x)g(y) ⇒ dy/g(y)=f(x)dx","caption":"变量分离是把方程整理成「一端只含 y 与 dy、另一端只含 x 与 dx」的过程；能不能分离，取决于方程能否写成 f(x)dx=g(y)dy 的形状。","keyPoints":["含 y 的因子与含 x 的因子分到两端","乘积形式 dy/dx=f(x)g(y) 必可分离","分离变量后两端各自积分，常数只写一个"],"example":"dy/dx=eˣ·y 分离得 dy/y=eˣdx。"},
  "kp-m2-p1-c6-liang-bian-ji-fen": {"anchor":"∫dy/g(y)=∫f(x)dx+C","caption":"分离变量后对两端分别积分，得到通解；一端积出 ln|y| 之类时，要及时解成显式并把常数写成统一的 C。","keyPoints":["两端各积各的，常数只写一个 C","出现 ln|y| 时解成 y=Ce^{…}","积不出初等式时隐式解也算结果"],"example":"∫dy/y=∫2x dx ⇒ ln|y|=x²+C ⇒ y=Ce^{x²}。"},
  "kp-m2-p1-c6-chang-shu-jie-jian-cha": {"anchor":"如 y′=y²：除以 y² 丢了 y≡0","caption":"分离变量时要除以 g(y)，这一步会把 g(y)=0 对应的常数解丢掉；解完必须回头检查这些常数解是否也满足原方程，缺了要补上。","keyPoints":["除以 g(y) 的前提是 g(y)≠0","g(y)=0 的 y₀ 常给出常数解 y≡y₀","常数解可能取不到通解的任何 C 值"],"example":"y′=y² 有常数解 y≡0，而通解 y=−1/(x+C) 怎么取 C 都得不到它。"},
  "kp-m2-p1-c6-y-f-y-x-lei-xing": {"anchor":"y′=f(y/x)，如 y′=(x+y)/(x−y)=(1+u)/(1−u)","caption":"方程右端能写成只含 y/x 的函数时就是齐次型；分子分母同幂次的分式（如 (x+y)/(x−y)）同除以 x 就能化成这","keyPoints":["标志：右端整理后只含 y/x","分子分母同幂次的分式是常见伪装","认出后令 u=y/x"],"example":"y′=(x²+y²)/(xy) 同除 x² 得 y′=(1+u²)/u（u=y/x），是齐次型。"},
  "kp-m2-p1-c6-u-y-x-huan-yuan": {"anchor":"du/(f(u)−u)=dx/x","caption":"解齐次型方程令 y=ux，则 y′=u+xu′，代入后方程变成 xu′=f(u)−u——关于 u 与 x 的可分离变量方","keyPoints":["令 y=ux，y′=u+xu′（乘积求导）","代换后 xu′=f(u)−u，可分离","解出 u 后回代 u=y/x"],"example":"y′=y/x+1：xu′=1 ⇒ u=ln|x|+C ⇒ y=x ln|x|+Cx。"},
  "kp-m2-p1-c6-y-p-x-y-q-x": {"anchor":"y′+P(x)y=Q(x)","caption":"把一阶方程整理成 y′+P(x)y=Q(x) 的标准形是解题第一步——认出 P、Q 才能套通解公式；整理时先把 y′ 的系数除成 1。","keyPoints":["y′ 的系数必须先化成 1","P(x) 是 y 的系数（连同符号），Q(x) 是右端","整理本身就是解题的一半"],"example":"xy′+y=x² 先除 x：y′+y/x=x，得 P=1/x、Q=x。"},
  "kp-m2-p1-c6-tong-jie-gong-shi": {"anchor":"y=e^{−∫Pdx}(∫Qe^{∫Pdx}dx+C)","caption":"一阶线性方程 y′+P(x)y=Q(x) 的通解公式为 y=e^{−∫Pdx}(∫Qe^{∫Pdx}dx+C)；","keyPoints":["公式 y=e^{−∫Pdx}(∫Qe^{∫Pdx}dx+C)","e^{∫Pdx} 是积分因子：先积 P，乘进去","内层积分不加 C，最外层统一加"],"example":"y′+y/x=x²：e^{∫dx/x}=x，∫x²·x dx=x⁴/4，通解 y=x³/4+C/x。"},
  "kp-m2-p1-c6-chu-zhi-wen-ti": {"anchor":"y′=f(x,y)，y(x₀)=y₀","caption":"初值问题由微分方程和初始条件一起构成，求的是满足条件的特解；考试里的应用题几乎都是初值问题：先列方程，再给条件定常数。","keyPoints":["初值问题 = 方程 + 初始条件","目标是特解，不是通解","步骤：解通解 → 定常数 → 写特解"],"example":"y′=y，y(0)=2 ⇒ y=2eˣ。"},
  "kp-m2-p1-c6-y-f-x": {"anchor":"y″=f(x) ⇒ y=∫(∫f dx)dx+C₁x+C₂","caption":"y″=f(x) 直接积分两次，每积一次出一个常数；这是可降阶方程里最简单的一类，也是「积分一次降一阶」思想的原型。","keyPoints":["第一次积分得 y′=∫f(x)dx+C₁","第二次积分得 y=∫(∫f dx)dx+C₁x+C₂","两个初始条件分别定 C₁、C₂"],"example":"y″=6x ⇒ y′=3x²+C₁ ⇒ y=x³+C₁x+C₂。"},
  "kp-m2-p1-c6-y-f-x-y": {"anchor":"p′=f(x,p)，y=∫p dx+C","caption":"方程不含 y 时（y″=f(x,y′)），令 p=y′ 把它降为关于 p 的一阶方程 p′=f(x,p)","keyPoints":["缺 y ⇒ 令 p=y′，此时 y″=p′","先解一阶方程 p′=f(x,p)","再积 p=dy/dx 得 y"],"example":"xy″+y′=0 令 p=y′：xp′+p=0 ⇒ p=C₁/x ⇒ y=C₁ ln|x|+C₂。"},
  "kp-m2-p1-c6-y-f-y-y": {"anchor":"y″=p·dp/dy（链式法则）","caption":"方程不含 x 时（y″=f(y,y′)），令 p=y′ 并用链式法则把 y″ 写成 p·dp/dy","keyPoints":["缺 x ⇒ 令 p=y′，且 y″=p·dp/dy","先解 p 关于 y 的一阶方程","再解 dy/dx=p(y)（可分离）"],"example":"y″=2yy′ 令 p=y′：p dp/dy=2yp ⇒ p=y²+C₁，再解 dy/dx=y²+C₁。"},
  "kp-m2-p1-c6-qi-ci-jie-xian-xing-zu-he": {"anchor":"y=C₁y₁+C₂y₂","caption":"两个线性无关的齐次解做线性组合 C₁y₁+C₂y₂ 就得到二阶齐次方程的通解；判断无关最常用「之比是否恒为常数」。","keyPoints":["C₁y₁+C₂y₂ 是通解 ⇔ y₁、y₂ 无关","无关判据：y₁/y₂ ≢ 常数","组合后恰好含两个独立常数"],"example":"e²ˣ 与 e³ˣ 之比 e^{−x} 不是常数，故 y=C₁e²ˣ+C₂e³ˣ 是 y″−5y′+6y=0 的通解。"},
  "kp-m2-p1-c6-fei-qi-ci-tong-jie-jie-gou": {"anchor":"y=C₁y₁+C₂y₂+y*","caption":"非齐次方程的通解必须写全：对应齐次通解（含全部任意常数）加上本方程的一个特解；验证时把它代回方程，齐次部分抵消，只剩非齐次项。","keyPoints":["结构：y=C₁y₁+C₂y₂+y*","任意常数全部来自齐次部分","特解用待定系数法求（不含 C）"],"example":"y″−y=eˣ：齐次通解 C₁eˣ+C₂e^{−x}，特解 y*=(x/2)eˣ，两者相加。"},
  "kp-m2-p1-c6-te-zheng-fang-cheng": {"anchor":"r²+pr+q=0，r=(−p±√(p²−4q))/2","caption":"对常系数齐次方程 y″+py′+qy=0 试指数解 y=e^{rx}，约去 e^{rx} 得代数方程 r²+pr+q=0","keyPoints":["试 y=e^{rx}，约去 e^{rx} 得特征方程","特征方程 r²+pr+q=0","根的三种情况对应三种解形"],"example":"y″−5y′+6y=0 的特征方程 r²−5r+6=0，根 r=2、3。"},
  "kp-m2-p1-c6-bu-tong-shi-gen": {"anchor":"y=C₁e^{r₁x}+C₂e^{r₂x}","caption":"特征方程有两个不相等实根时，每个根各出一个指数解，它们线性无关，线性组合即通解；这是三种根型里最基本的一种。","keyPoints":["r₁≠r₂ ⇒ y=C₁e^{r₁x}+C₂e^{r₂x}","两解之比不是常数，线性无关","先求根，再按根型写解"],"example":"r²−3r+2=0 根 1、2，y=C₁eˣ+C₂e²ˣ。"},
  "kp-m2-p1-c6-zhong-gen": {"anchor":"y=(C₁+C₂x)e^{rx}","caption":"特征方程出现重根 r 时，重复的根不会自动给出第二个无关解，必须补 xe^{rx}；通解写成形如 (C₁+C₂x)e^{rx}。","keyPoints":["二重根 ⇒ y=(C₁+C₂x)e^{rx}","补的 xe^{rx} 保证线性无关","k 重根补到 x^{k−1}e^{rx}"],"example":"r²+2r+1=0 双根 −1，y=(C₁+C₂x)e^{−x}。"},
  "kp-m2-p1-c6-gong-e-fu-gen": {"anchor":"r=α±βi ⇒ y=e^{αx}(C₁cos βx+C₂sin βx)","caption":"特征根为共轭复数 α±βi 时，齐次通解写成实形式 y=e^{αx}(C₁cos βx+C₂sin βx)；","keyPoints":["y=e^{αx}(C₁cos βx+C₂sin βx)","β 是振荡角频率，α 是衰减率","判别式 p²−4q<0 时发生"],"example":"y″+4y=0：r=±2i，α=0、β=2，y=C₁cos 2x+C₂sin 2x。"},
  "kp-m2-p1-c6-mou-xie-gao-jie-chang-xi-shu-qi-ci-fang-111c2g": {"anchor":"n 阶通解 = n 个线性无关解的组合","caption":"高阶常系数齐次方程的特征方程可能同时出现单实根、重根与复根，按各自规则写出对应解，个数凑齐阶数 n，线性组合就是通解。","keyPoints":["单根出 e^{rx}，重根加幂，复根出振荡","解的总数必须等于阶数 n","按根型写全解后，最后统一做线性组合"],"example":"y⁽⁴⁾−y=0 特征根 ±1、±i，通解 C₁eˣ+C₂e^{−x}+C₃cos x+C₄sin x。"},
  "kp-m2-p1-c6-duo-xiang-shi": {"anchor":"y*=x^k(aₘxᵐ+…+a₀)","caption":"右端是多项式 Pₘ(x) 时，设特解 y*=x^kQₘ(x)：Qₘ 是同次待定多项式，k 按「0 是不是特征根、是单根还是重根」取 0、1、2。","keyPoints":["y*=x^kQₘ(x)，Qₘ 与 Pₘ 同次","0 非特征根 k=0；单根 k=1；重根 k=2","代入比较系数定出 Qₘ"],"example":"y″−2y′=x²：0 是单特征根，设 y*=x(ax²+bx+c)。"},
  "kp-m2-p1-c6-zhi-shu-han-shu": {"anchor":"y*=x^k e^{λx}(aₘxᵐ+…+a₀)","caption":"右端为 e^{λx}Pₘ(x) 时设特解 y*=x^ke^{λx}Qₘ(x)","keyPoints":["y*=x^k e^{λx}Qₘ(x)","k=λ 的特征根重数：非根 0、单根 1、二重根 2","Qₘ 仍是同次待定多项式"],"example":"y″−y=eˣ：λ=1 是单特征根，设 y*=axeˣ，代回解得 a=1/2。"},
  "kp-m2-p1-c6-zheng-xian": {"anchor":"y*=x^k(M cos ωx+N sin ωx)","caption":"右端为 A sin ωx 时，特解设 y*=M cos ωx+N sin ωx，两个待定系数一起上；","keyPoints":["特解同时设 cos 与 sin 两项","±ωi 是特征根时特解乘 x","代入比较系数解出 M、N"],"example":"y″+y=sin 2x：±2i 不是特征根，设 y*=M cos 2x+N sin 2x，解得 M=0、N=−1/3。"},
  "kp-m2-p1-c6-yu-xian": {"anchor":"y*=x^k(M cos ωx+N sin ωx)","caption":"右端为 A cos ωx 时的设法与正弦完全相同：特解设 M cos ωx+N sin ωx 两项（多设的那项解出 0 ","keyPoints":["与 sin 型同一套设法","解出某个系数为 0 是正常的","±ωi 是特征根时改设 x(M cos ωx+N sin ωx)"],"example":"y″+4y=cos x：设 y*=M cos x+N sin x，解得 M=1/3、N=0。"},
  "kp-m2-p1-c6-shang-shu-han-shu-de-he-yu-ji": {"anchor":"y*=y₁*+y₂*（和的情形）","caption":"右端是几种类型之和时，按叠加原理分别设特解再相加；右端是乘积（如 x eˣ、x²sin x）时","keyPoints":["和：f₁+f₂ 的特解 = 各自特解之和","积：按乘积的整体形状设待定式","各部分自己的 x^k 修正照常生效"],"example":"y″+y=x+sin x：设 y*=(ax²+bx+c)+x(M cos x+N sin x) 两部分相加。"},
  "kp-m2-p1-c6-yun-dong": {"anchor":"m x″=F(t,x,x′)","caption":"直线运动用 a=x″(t) 表示加速度，牛顿第二定律给出 mx″=F(t,x,x′)；","keyPoints":["a=x″，把 F 写成 t、x、x′ 的函数","mx″=F 是二阶方程（或先对 v=x′ 解一阶）","初始位置与初速度就是初始条件"],"example":"只受阻力 −kv：mv′=−kv ⇒ v=v₀e^{−kt/m}，速度按指数衰减。"},
  "kp-m2-p1-c6-zeng-zhang-shuai-jian": {"anchor":"N(t)=N₀e^{λt}","caption":"增长率与当前量成正比时 dN/dt=λN，解为 N=N₀e^{λt}：λ>0 指数增长、λ<0 指数衰减；人口增长、放射衰变、复利都是这一族模型。","keyPoints":["方程 dN/dt=λN，解 N=N₀e^{λt}","λ 的符号决定增长还是衰减","衰减情形半衰期 t=ln2/|λ|"],"example":"放射衰变 λ=−ln2/30 时，物质质量每 30 天减半。"},
  "kp-m2-p1-c6-jian-dan-ji-he-yu-wu-li-mo-xing": {"anchor":"条件 → 方程 → 通解 → 特解","caption":"简单建模的套路一致：把条件写成导数等式，按类型选解法（可分离/齐次/线性/二阶常系数），最后用题目给定的状态定常数。","keyPoints":["第一步永远是「把条件翻译成 y′、y″」","先识别方程类型再选解法，类型错方法全错","常数用题目给定的初始状态确定"],"example":"物体冷却：T′=−k(T−20)，T(0)=100 ⇒ T=20+80e^{−kt}。"},
  "kp-m2-p2-c1-er-jie-san-jie-n-jie": {"anchor":"三阶：a₁b₂c₃+a₂b₃c₁+a₃b₁c₂−a₃b₂c₁−a₂b₁c₃−a₁b₃c₂","caption":"二阶行列式 ad−bc、三阶可用对角线法则，n 阶由展开定义递归给出；行列式的最终结果是一个数，n 阶只是「规则」的推广而非形状的放大。","keyPoints":["二阶：主对角线乘积减副对角线乘积","三阶：六项三正三负（对角线法则）","n 阶按行（列）展开递归定义"],"example":"|2 0; 0 3|=6；三阶单位行列式 =1。"},
  "kp-m2-p2-c1-pai-lie-yu-ni-xu-shu-ji-ben-si-xiang": {"anchor":"τ(n(n−1)…21)=(n−1)+(n−2)+…+1=n(n−1)/2","caption":"n 级排列的逆序数 τ 数「前大后小」的对子，奇偶性给排列分奇偶；行列式的展开定义正是靠「行标排列 × 列标排列」的奇偶性决定每项的正负号。","keyPoints":["逐个数字数它前面比它大的个数","τ 奇 → 奇排列，τ 偶 → 偶排列","对换一次两个数字，τ 奇偶性改变"],"example":"排列 2 4 1 3：2 压 1，4 压 1、3，τ=3，奇排列。"},
  "kp-m2-p2-c1-zhuan-zhi": {"anchor":"|Aᵀ|=|A|","caption":"行列式的转置性质：|Aᵀ|=|A|，转置不改值；据此行列式的每条行性质自动获得列版本——「行列平权」是行列式性质体系的总纲。","keyPoints":["转置不变号 |Aᵀ|=|A|，行性质即列性质","由转置不变，行性质与列性质完全等价","与矩阵转置（得新矩阵）含义不同"],"example":"上三角行列式转置成下三角，对角线乘积不变。"},
  "kp-m2-p2-c1-xing-lie-hu-huan": {"anchor":"D′=(−1)ᵏD（k 为交换次数）","caption":"行列式任意两行（列）互换后变号——性质的总开关：由它可以解释「相同行为 0」，也把「化三角形」里需要的交换纳入符号管理。","keyPoints":["rᵢ↔rⱼ ⇒ D′=−D","偶数次交换后符号复原，只用看奇偶","配合倍加即可完成全部消元"],"example":"为把主元换成 1 而交换两行：行列式值添负号。"},
  "kp-m2-p2-c1-gong-yin-zi": {"anchor":"第 i 行提取 k：D′=kD","caption":"某一行（列）的公因子可以提到行列式记号外面；整行乘 k 等于行列式乘 k。","keyPoints":["一行公因子 → 提出 k","整矩阵数乘 → 提出 kⁿ","负号也是一种「公因子」"],"example":"某行全为偶数：提出 2 后行列式元素变整小，好算得多。"},
  "kp-m2-p2-c1-cheng-bi-li": {"anchor":"rᵢ=krⱼ ⇒ D=0","caption":"两行（列）对应元素成比例 ⇒ 行列式为 0：把比例因子提出后两行相同，交换变号给出 D=−D；判断题专用结论。","keyPoints":["两行成比例推出 D=0，提公因子后两行相同","推导：提公因子 + 相同行为 0","部分成比例（只有一列）不能下结论"],"example":"第二行是第一行的 −2 倍：行列式为 0。"},
  "kp-m2-p2-c1-bei-jia": {"anchor":"rᵢ→rᵢ+krⱼ：D 不变","caption":"某行的 k 倍加到另一行，行列式值不变——消元化三角形全靠它；它与「换行变号、提公因子」并称行列式三大变换。","keyPoints":["rᵢ→rᵢ+krⱼ 值不变","消元主力，无符号成本","被加行 rⱼ 保持原样"],"example":"r₂→r₂−(a₂₁/a₁₁)r₁ 消出第一列零（手算时通分更稳）。"},
  "kp-m2-p2-c1-xian-xing-xing-zhi": {"anchor":"|…(a+c)…|=|…a…|+|…c…|","caption":"行列式对某一行的每个元素是线性的：这一行可拆、可提公因子；「行内拆 + 行间倍加」组合起来能处理绝大多数文字行列式。","keyPoints":["单行拆成两个行列式之和","行列式单行可提公因子，注意不是 kⁿ","对「行」线性、对整个行列式不是线性"],"example":"含 (λ+1) 的行拆开后，其中一个行列式因成比例为 0。"},
  "kp-m2-p2-c1-m-ij": {"anchor":"Mᵢⱼ=余下的 n−1 阶行列式","caption":"Mᵢⱼ：划去第 i 行、第 j 列后剩余元素按原位置构成的 n−1 阶行列式；不带符号，是代数余子式的「原材料」。","keyPoints":["Mᵢⱼ 是行列式（数）","划掉一行一列，阶数减一","与位置 (i,j) 一一对应"],"example":"四阶行列式的 M₂₂ 是划掉 2 行 2 列后的三阶行列式。"},
  "kp-m2-p2-c1-a-ij": {"anchor":"Aᵢⱼ=(−1)^{i+j}Mᵢⱼ","caption":"Aᵢⱼ=(−1)^{i+j}Mᵢⱼ：符号由 (i+j) 奇偶决定，棋盘状排布；展开定理与伴随矩阵都以它为基本件。","keyPoints":["Aᵢⱼ=(−1)^{i+j}Mᵢⱼ","代数余子式符号规则：i+j 偶正奇负","ΣaᵢⱼAᵢⱼ=D（同行/列展开）"],"example":"A₃₃：3+3=6 偶，A₃₃=+M₃₃。"},
  "kp-m2-p2-c1-zhan-kai-ding-li": {"anchor":"ΣⱼaₖⱼAᵢⱼ=0（k≠i）","caption":"展开定理：行列式 = 任一行的元素与自己的代数余子式乘积之和；并且某元素与「别行」的代数余子式乘积之和恒为 0——这两句合起来才是完整定理。","keyPoints":["同行展开：ΣaᵢⱼAᵢⱼ=D","异行组合：ΣaₖⱼAᵢⱼ=0（k≠i）","异行结论常用于反求代数余子式"],"example":"已知 D 与第一行，把第一行换成 (1,1,…,1) 后的值 = ΣA₁ⱼ。"},
  "kp-m2-p2-c1-te-shu-hang-lie-xuan-ze": {"anchor":"爪形消元：对角线乘积收尾","caption":"特殊行列式按形选法：三角形/对角形直接乘对角线；两行成比例直接判 0；爪形（三斜边+对角）用倍加化三角；范德蒙德套连乘公式。","keyPoints":["对角/三角：对角线乘积","爪形行列式：用倍加消去斜边化三角","幂排列：范德蒙德连乘"],"example":"主对角 + 第一行第一列构成的爪形：逐列减去主对角行的倍数化三角。"},
  "kp-m2-p2-c1-hua-san-jiao": {"anchor":"D=(−1)ᵏ·∏对角元","caption":"化三角形法：用倍加（必要时交换并记号）把行列式化成上三角，值 = 对角线乘积；步骤机械、适合任何阶数，是行列式计算的兜底方法。","keyPoints":["化三角形从左到右逐列消零，步骤机械可靠","只用倍加则不需管符号","交换次数单独计数乘 (−1)ᵏ"],"example":"整数行列式用倍加保持整数运算，最后一步乘对角线。"},
  "kp-m2-p2-c1-zhan-kai": {"anchor":"D=ΣaᵢⱼAᵢⱼ","caption":"「展开」作为计算方法指：先把某行（列）化出尽量多的零，再按该行（列）展开定理降阶，反复直到二阶——与化三角形殊途同归。","keyPoints":["展开 = 降阶的反复使用","展开时每次选零最多的行列，项数最少","高阶行列式的通用手算路线"],"example":"五阶行列式连续两次展开降到三阶再用对角线法则。"},
  "kp-m2-p2-c1-jia-bian": {"anchor":"典型加边：第一列 1，第一行 0","caption":"加边法：给 n 阶行列式添上一行一列升成 n+1 阶（值不变），新造的边让每行都能用倍加消出统一零——看似升阶，实则大幅化简。","keyPoints":["加边保持值不变（特殊构造）","常用于「对角 + 密度行」型行列式","目标：加边后全行可消成三角"],"example":"对角线上全 aᵢ、其余全 1 的行列式，加边后逐行减第一行化三角。"},
  "kp-m2-p2-c1-di-tui": {"anchor":"Dₙ=(a+b)Dₙ₋₁−abDₙ₋₂（三对角型）","caption":"按第一行（列）展开后，若出现与原行列式同型的 n−1 阶与 n−2 阶行列式，就建立递推公式 Dₙ=…，再逐阶递推（或取特征方程）求解。","keyPoints":["识别「同型子式」是递推的前提","写 Dₙ=aDₙ₋₁+bDₙ₋₂ 型关系","初值 D₁、D₂ 定系数"],"example":"三对角行列式递推 Dₙ=Dₙ₋₁−Dₙ₋₂，得周期 6 的通项。"},
  "kp-m2-p2-c1-chai-fen": {"anchor":"|…aᵢⱼ+bᵢⱼ…|=|…aᵢⱼ…|+|…bᵢⱼ…|","caption":"利用单行线性性质把某个「含和式」的行拆成两个行列式，其中至少一个是简单（如对角、零多）行列式——拆分常与倍加配合使用。","keyPoints":["拆分性质一次只拆一行（列），其余行照抄","拆出一个「好算」的行列式","常用于含 λ、x 的文字行列式"],"example":"含 (x+1) 的行拆成 x 行与 1 行，其中一个行列式两行相同为 0。"},
  "kp-m2-p2-c1-fan-de-meng-de": {"anchor":"D=∏_{1≤i<j≤n}(xⱼ−xᵢ)","caption":"范德蒙德行列式：每行都是数 x₁,…,xₙ 的幂（0 到 n−1 次），值 = ∏(xⱼ−xᵢ)；它是「两行相等行列式为零」与插值多项式的共同源头。","keyPoints":["D=∏_{i<j}(xⱼ−xᵢ)","幂次从 0 排到 n−1","xᵢ=xⱼ 时 D=0"],"example":"x₁=1、x₂=2、x₃=3：D=(2−1)(3−1)(3−2)=2。"},
  "kp-m2-p2-c2-ling-ju-zhen": {"anchor":"Aₘₓₙ+Oₘₓₙ=A","caption":"零矩阵 O 是所有元素为 0 的矩阵，尺寸可以任意；它与零数的最大差别：两个非零矩阵相乘可以得到零矩阵——「没有零因子定律」。","keyPoints":["O 的任意元素都是 0","A+O=A（加法单位元）","AB=O ⇏ A=O 或 B=O"],"example":"A=(1 0; 0 0)、B=(0 0; 0 1)：AB=O 但 A、B 都非零。"},
  "kp-m2-p2-c2-dan-wei-ju-zhen": {"anchor":"Eₙ=(δᵢⱼ)，δᵢᵢ=1、其余 0","caption":"单位矩阵 E（I）是主对角线全 1、其余全 0 的方阵：AE=EA=A，是矩阵乘法的单位元；n 阶单位矩阵在一切 n 阶方阵中扮演「1」的角色。","keyPoints":["E 的对角线全 1、其余全 0（方阵）","AE=EA=A（左右乘都一样）","单位矩阵行列式 |E|=1，乘法单位元的值"],"example":"(A+E)²=A²+2A+E（E 与 A 可交换）。"},
  "kp-m2-p2-c2-shu-liang-ju-zhen": {"anchor":"(kE)ₙ 与一切 n 阶方阵交换","caption":"数量矩阵是 kE：对角线全为同一个数 k、其余为 0；它与任何同阶方阵可交换——「数乘矩阵」伪装成矩阵乘法的形式。","keyPoints":["数量矩阵 = kE（对角全 k）","(kE)A=A(kE)=kA（处处可交换）","k=1 时是单位矩阵，k=0 时是零矩阵"],"example":"(2E)A=2A：把数量矩阵当「标量」用。"},
  "kp-m2-p2-c2-dui-jiao-ju-zhen": {"anchor":"diag(a,b)·diag(c,d)=diag(ac,bd)","caption":"对角矩阵是主对角线以外全为 0 的方阵：diag(a₁,…,aₙ)；两个对角矩阵相乘就是各自对角线对应相乘，运算是所有方阵里最简单的。","keyPoints":["diag(a₁,…,aₙ) 只在对角线有元素","对角阵之积：对应对角元素相乘","对角阵之间永远可交换"],"example":"diag(1,2)³=diag(1,8)。"},
  "kp-m2-p2-c2-san-jiao-ju-zhen": {"anchor":"(AB)ᵢᵢ=aᵢᵢbᵢᵢ","caption":"三角矩阵指上三角或下三角矩阵：对角线一侧全为零；同侧三角矩阵相乘仍同侧，且乘积的对角线元素是两者对角元素对应相乘。","keyPoints":["上三角：对角线左下方全 0","同侧三角矩阵相乘保结构，对角元对应相乘","积的对角元 = 对应对角元之积"],"example":"上三角阵的行列式 = 对角线元素乘积（按行展开即得）。"},
  "kp-m2-p2-c2-dui-chen-ju-zhen": {"anchor":"(AB)ᵀ=BᵀAᵀ，对称时 (AB)ᵀ=BA","caption":"对称矩阵满足 Aᵀ=A：元素关于主对角线镜像（aᵢⱼ=aⱼᵢ）；对称矩阵的乘方仍对称、两个对称矩阵的乘积一般不对称（除非可交换）——它是二次型的主角。","keyPoints":["Aᵀ=A ⇔ aᵢⱼ=aⱼᵢ","Aᵏ 仍对称；AB 对称 ⇔ AB=BA","实对称矩阵可正交对角化（后续章）"],"example":"A、B 对称且 AB=BA ⇒ AB 对称；否则 (AB)ᵀ=BA≠AB。"},
  "kp-m2-p2-c2-fan-dui-chen-ju-zhen": {"anchor":"A_s=(A+Aᵀ)/2，A_a=(A−Aᵀ)/2","caption":"反对称矩阵满足 Aᵀ=−A：对角线元素全为 0、aᵢⱼ=−aⱼᵢ；任何方阵都能写成「对称 + 反对称」之和——A=(A+Aᵀ)/2+(A−Aᵀ)/2。","keyPoints":["Aᵀ=−A ⇒ aᵢᵢ=0","aᵢⱼ=−aⱼᵢ（镜像变号）","A = 对称部分 + 反对称部分"],"example":"A=(0 1; −1 0) 是反对称矩阵，对应「旋转 90°」。"},
  "kp-m2-p2-c2-zheng-jiao-ju-zhen": {"anchor":"AᵀA=E ⇒ |A|=±1","caption":"正交矩阵满足 AᵀA=E：列（行）向量组是标准正交组；它的转置就是逆（A⁻¹=Aᵀ），乘积保持长度与内积——是「旋转/反射」类变换的矩阵。","keyPoints":["AᵀA=E ⇔ A⁻¹=Aᵀ","列（行）向量都是单位向量且两两正交","正交变换保持长度：|Ax|=|x|"],"example":"平面旋转矩阵 (cosθ −sinθ; sinθ cosθ) 是正交矩阵。"},
  "kp-m2-p2-c2-jia-jian": {"anchor":"A+B=B+A，(A+B)+C=A+(B+C)","caption":"矩阵加减只在同型矩阵间进行：对应元素相加减；不满足交换律的问题在这里不存在（加法天然交换），关键约束是「同型」。","keyPoints":["A±B 要求同型（同行列数）","(A±B)ᵢⱼ=aᵢⱼ±bᵢⱼ","加法交换、结合律都成立"],"example":"(1 2)+(0 1)=(1 3)（1×2 矩阵）。"},
  "kp-m2-p2-c2-shu-cheng": {"anchor":"(kA)ᵢⱼ=k·aᵢⱼ","caption":"数乘 kA 是把 k 乘到每一个元素上；它与加法配合构成线性运算，满足 k(A+B)=kA+kB","keyPoints":["kA：每个元素乘 k","k(A+B)=kA+kB","|kA|=kⁿ|A|（n 阶方阵）"],"example":"2·(1 0; 0 1)=(2 0; 0 2)，行列式从 1 变 2²=4。"},
  "kp-m2-p2-c2-ju-zhen-cheng-fa": {"anchor":"(AB)ᵢⱼ=Σₖaᵢₖbₖⱼ","caption":"矩阵乘法 C=AB 的 (i,j) 元 = A 的第 i 行与 B 的第 j 列对应乘积之和；","keyPoints":["cᵢⱼ=Σₖ aᵢₖbₖⱼ（行乘列）","AₘₓₙBₙₓₛ 可乘，积为 m×s","AB≠BA 一般成立；AB=O ⇏ 有零因子"],"example":"(1 2)(2; 1)=1·2+2·1=4（1×1 矩阵）。"},
  "kp-m2-p2-c2-fang-zhen-mi": {"anchor":"Aᵏ=(βᵀα)^{k−1}A（秩一情形）","caption":"方阵的幂 Aᵏ 定义为 k 个 A 相乘（A⁰=E，负幂要求可逆）；求 Aᵏ 的三大技巧：对角化、秩一分解、递推关系（利用 A²=−A+E 型条件）。","keyPoints":["A⁰=E；Aᵏ 按定义连乘","秩一矩阵 A=αβᵀ ⇒ Aᵏ=(βᵀα)^{k−1}A","若有 A²=cA+dE 可建立递推"],"example":"A²=2A−E ⇒ Aⁿ 用递推 Aⁿ=2Aⁿ⁻¹−Aⁿ⁻² 求出。"},
  "kp-m2-p2-c2-bu-man-zu-jiao-huan-l-de-dian-xing-qing-0ef12z": {"anchor":"AB−BA 称为交换子，一般 ≠O","caption":"交换律失效的三种典型：尺寸不匹配（AB 可乘但 BA 不行）、尺寸匹配但元素不同、甚至 AB 与 BA 之差非零（如旋转与拉伸交换后结果不同）。","keyPoints":["AB 可乘 ⇏ BA 可乘","尺寸都匹配时元素也可能不同","(A+B)² 的中间项 = AB+BA，不可合并"],"example":"(1 0; 0 2) 与 (1 1; 0 1)：AB≠BA。"},
  "kp-m2-p2-c2-ding-yi": {"anchor":"Aₘₓₙ → Aᵀₙₓₘ","caption":"转置 Aᵀ 由「行列互换」定义：(Aᵀ)ᵢⱼ=aⱼᵢ；它把 m×n 矩阵变成 n×m 矩阵，是对称、正交等一切「结构性概念」的定义基础。","keyPoints":["(Aᵀ)ᵢⱼ=aⱼᵢ","m×n 转置成 n×m","转置是自逆运算：(Aᵀ)ᵀ=A"],"example":"(1 2 3) 转置为竖着的 3×1 列向量。"},
  "kp-m2-p2-c2-yun-suan-gui-l": {"anchor":"(A₁A₂…Aₛ)ᵀ=Aₛᵀ…A₂ᵀA₁ᵀ","caption":"转置的运算规律：(A±B)ᵀ=Aᵀ±Bᵀ、(kA)ᵀ=kAᵀ、(AB)ᵀ=BᵀAᵀ（反序）、(Aᵀ)ᵀ=A；「反序」是四条中唯一容易错的一条。","keyPoints":["转置的线性性：和差与数乘直接穿过","(AB)ᵀ=BᵀAᵀ（反序）","转置两次就还原，多次转置同理"],"example":"(ABC)ᵀ=CᵀBᵀAᵀ。"},
  "kp-m2-p2-c2-ab-t-b-ta-t": {"anchor":"(ABC)ᵀ=CᵀBᵀAᵀ","caption":"(AB)ᵀ=BᵀAᵀ：乘积的转置等于各转置按相反顺序相乘；可推广到 s 个矩阵——顺序完全倒过来。","keyPoints":["(AB)ᵀ=BᵀAᵀ","推广：(A₁…Aₛ)ᵀ=Aₛᵀ…A₁ᵀ","对称矩阵乘积对称 ⇔ 可交换"],"example":"A、B 对称时 (AB)ᵀ=BA，故 AB 对称 ⇔ AB=BA。"},
  "kp-m2-p2-c2-ab-a-b": {"anchor":"|AB|=|A|·|B|","caption":"方阵乘积的行列式等于行列式的乘积：|AB|=|A||B|（要求 A、B 同阶方阵）；","keyPoints":["|AB|=|A||B|（同阶方阵）","幂的行列式 |Aᵏ|=|A|ᵏ，指数搬到行列式外","|A|=0 ⇔ A 不可逆"],"example":"|A|=2、|B|=3：|AB|=6，|A³B²|=8·9=72。"},
  "kp-m2-p2-c2-ding-yi-2": {"anchor":"AA⁻¹=A⁻¹A=E","caption":"对 n 阶方阵 A，若存在方阵 B 使 AB=BA=E，则 B 是 A 的逆矩阵，记 B=A⁻¹；","keyPoints":["AB=BA=E（两侧都要）","可逆 ⇔ |A|≠0","逆唯一：一个方阵只有一个逆"],"example":"A=(2 0; 0 1) 的逆是 (1/2 0; 0 1)。"},
  "kp-m2-p2-c2-xing-zhi": {"anchor":"(Aᵏ)⁻¹=(A⁻¹)ᵏ（k 为正整数）","caption":"可逆矩阵的运算性质：A⁻¹ 唯一；(AB)⁻¹=B⁻¹A⁻¹；(Aᵀ)⁻¹=(A⁻¹)ᵀ；(kA)⁻¹=k⁻¹A⁻¹；","keyPoints":["(AB)⁻¹=B⁻¹A⁻¹（反序）","(Aᵀ)⁻¹=(A⁻¹)ᵀ","求逆是自逆运算：(A⁻¹)⁻¹=A"],"example":"化简 (AᵀB)⁻¹=B⁻¹(Aᵀ)⁻¹=B⁻¹(A⁻¹)ᵀ。"},
  "kp-m2-p2-c2-ke-ni-chong-fen-bi-yao-tiao-jian": {"anchor":"Aₙₓₙ 可逆 ⇔ r(A)=n","caption":"A 可逆的充要条件（数二口径）：|A|≠0、r(A)=n、行阶梯非零行数=n、Ax=0 仅零解、A 的行/列向量组线性无关——多个身份同一件事。","keyPoints":["|A|≠0 ⇔ r(A)=n","列向量组线性无关等价于满秩，两种说法互通","不可逆 ⇔ 退化为低秩"],"example":"行向量组相关 ⇒ |A|=0 ⇒ 不可逆。"},
  "kp-m2-p2-c2-ban-sui-ju-zhen-qiu-ni": {"anchor":"A⁻¹=A*/|A|","caption":"伴随矩阵 A* 由代数余子式按转置位置排成，A⁻¹=(1/|A|)A*（|A|≠0）；","keyPoints":["A* 的 (j,i) 元 = Aᵢⱼ（转置摆放！）","A⁻¹=(1/|A|)A*","AA*=A*A=|A|E"],"example":"二阶 (a b; c d) 的伴随是 (d −b; −c a)，逆=(1/(ad−bc))(d −b; −c a)。"},
  "kp-m2-p2-c2-san-lei-chu-deng-bian-huan": {"anchor":"rᵢ→rᵢ+krⱼ（倍加，最常用）","caption":"初等变换三类：交换两行（列）、某行（列）乘非零 k、某行（列）的 k 倍加到另一行（列）；行变换用于解方程组与求逆，列变换多用于求标准形。","keyPoints":["三种变换对行、列都定义","初等行变换保证方程组同解，解集不变","初等变换不改变矩阵的秩"],"example":"把增广矩阵化为行最简形即可读出通解。"},
  "kp-m2-p2-c2-chu-deng-ju-zhen": {"anchor":"倍乘矩阵 E₂(k) 的逆 = E₂(1/k)","caption":"初等矩阵：单位矩阵经过一次初等变换所得；三类对应三种变换，全部可逆且逆仍为初等矩阵——它们是「初等变换可以写成乘法」的载体。","keyPoints":["E 经一次初等变换 ⇒ 初等矩阵","初等矩阵可逆，逆是同族初等矩阵","初等矩阵转置仍是初等矩阵"],"example":"换行初等矩阵的逆就是它自己。"},
  "kp-m2-p2-c2-zuo-cheng-dui-ying-xing-bian-huan": {"anchor":"A⁻¹=Pₛ…P₁（初等矩阵之积）","caption":"左乘初等矩阵 = 对 A 做一次对应行变换；右乘 = 对应列变换。","keyPoints":["左乘 → 行变换；右乘 → 列变换","A 的行变换串 = Pₛ…P₁A","由 (A|E)→(E|A⁻¹) 可读出 A⁻¹=Pₛ…P₁"],"example":"「A 经两次行变换变成 B」⇔ B=P₂P₁A。"},
  "kp-m2-p2-c2-chu-deng-bian-huan-qiu-ni": {"anchor":"(A|E)→(E|A⁻¹)","caption":"(A|E) 做初等行变换化成 (E|A⁻¹)：原理是 A⁻¹ 左乘 (A|E)；","keyPoints":["(A|E) 行变换 → (E|A⁻¹)","原理：A⁻¹(A|E)=(E|A⁻¹)","左块出零行 ⇒ 不可逆"],"example":"三阶矩阵求逆约 6~8 步行变换完成。"},
  "kp-m2-p2-c2-ding-yi-3": {"anchor":"r(A)=非零行数（行阶梯形）","caption":"矩阵的秩 r(A) 是最高阶非零子式的阶数，也等于行（列）向量组的极大线性无关组所含向量个数；行秩=列秩=秩——三种说法同一件事。","keyPoints":["秩 = 非零子式的最高阶数","行秩 = 列秩 = r(A)","r(A)=n ⇔ 满秩 ⇔ 方阵 A 可逆"],"example":"4×5 矩阵化阶梯后有 3 个非零行 ⇒ r(A)=3。"},
  "kp-m2-p2-c2-zui-gao-jie-fei-ling-zi-shi": {"anchor":"r(A)=最高阶非零子式的阶数","caption":"r(A)=k 的含义：存在 k 阶子式不为 0，而所有 k+1 阶子式全为 0；这个 k 阶非零子式就是「最高阶非零子式」，是秩的原始定义。","keyPoints":["存在非零 k 阶子式 ⇒ r(A)≥k","全部 k+1 阶子式为 0 ⇒ r(A)≤k","找出一个非零最高阶子式即可确定秩"],"example":"矩阵有非零 3 阶子式而所有 4 阶子式为 0 ⇒ 秩 3。"},
  "kp-m2-p2-c2-jie-ti-xing": {"anchor":"r(A)=阶梯形非零行数","caption":"行阶梯形矩阵：零行在底部、非零行的首非零元列位置逐行严格向右；非零行个数就是秩——化阶梯形是求秩、解方程组的共同前置步骤。","keyPoints":["零行在底、首元逐行右移","非零行数 = r(A)","阶梯形不唯一，秩唯一"],"example":"5×4 矩阵化阶梯后 3 个非零行 ⇒ 秩 3。"},
  "kp-m2-p2-c2-chu-deng-bian-huan-qiu-zhi": {"anchor":"r(A)=非零行数","caption":"初等行变换不改变秩，因此求秩就是「化行阶梯形 + 数非零行」；这是求秩的标准方法，也顺带给出极大无关组（主元所在列对应的原向量）。","keyPoints":["行变换（列变换也行）不变秩","阶梯形非零行数 = r(A)","主元所在列 = 极大无关组的列"],"example":"行变换后得到 2 个非零行 ⇒ r(A)=2。"},
  "kp-m2-p2-c2-chang-jian-zhi-xing-zhi": {"anchor":"r(AB)≥r(A)+r(B)−n（Sylvester 下界）","caption":"常用秩性质：r(Aᵀ)=r(A)；r(A±B)≤r(A)+r(B)；r(AB)≤min(r(A),r(B))；","keyPoints":["r(AB)≤min(r(A),r(B))","A 可逆 ⇒ r(AB)=r(B)（可消去）","r(A+B)≤r(A)+r(B)"],"example":"A 可逆时 r(AB)=r(B)：左乘可逆阵不改变秩。"},
  "kp-m2-p2-c2-deng-jia-gai-nian": {"anchor":"A≌B ⇔ r(A)=r(B)","caption":"矩阵等价：A 经初等（行、列）变换变成 B，则 A 与 B 等价；","keyPoints":["等价 ⇔ 同型 + 等秩","等价 > 相似 > 合同？不——三者互不包含，适用对象不同","等价的标准形由秩唯一决定"],"example":"任意矩阵与其行阶梯形等价。"},
  "kp-m2-p2-c2-zhi-bu-bian": {"anchor":"A≌标准形(r) ⇔ r(A)=r","caption":"初等变换不改变矩阵的秩，因此等价矩阵秩相等；反过来同型的等秩矩阵必然等价——「秩不变」是等价关系的完整刻画。","keyPoints":["初等变换保持秩不变，等价矩阵同秩","矩阵等价的充要条件：同型且秩相等","求秩的过程就是找等价标准形"],"example":"化成 (E_r O; O O) 标准形，一眼读出秩 r。"},
  "kp-m2-p2-c2-fen-kuai-yun-suan": {"anchor":"(A B; C D)(E F; G H)=(AE+BG AF+BH; CE+DG CF+DH)","caption":"分块运算总则：把子块当元素做加、乘、转置；约束是「分法对齐」——加减同切分、乘法内标匹配、转置两层全转。","keyPoints":["块当元素：加、乘、转置照旧","乘法要求列分法与行分法一致","转置：块重排 + 块内转置"],"example":"大矩阵求幂按分块对角处理，化为小块求幂。"},
  "kp-m2-p2-c2-fen-kuai-dui-jiao-ju-zhen": {"anchor":"diag(A,B)⁻¹=diag(A⁻¹,B⁻¹)","caption":"分块对角矩阵：非对角块全为零、对角块为小方阵；它的幂、行列式、逆都按对角块「各自处理」——大问题拆成小问题。","keyPoints":["分块对角矩阵要求非对角块全 O，各块独立运算","|diag(A,B)|=|A|·|B|","diag(A,B)ᵏ=diag(Aᵏ,Bᵏ)；逆 = 各块求逆"],"example":"diag(A,B) 的秩 = r(A)+r(B)。"},
  "kp-m2-p2-c2-jian-dan-fen-kuai-qiu-ni": {"anchor":"(A O; C B)⁻¹=(A⁻¹ O; −B⁻¹CA⁻¹ B⁻¹)","caption":"分块对角阵的逆 = 各对角块分别求逆；分块三角矩阵 (A O; C B) 的逆有公式（A","keyPoints":["diag 块逆 = 各块逆","下三角分块 (A O; C B)⁻¹=(A⁻¹ O; −B⁻¹CA⁻¹ B⁻¹)","原理：设逆块待定，解块方程"],"example":"零块位置不同的分块上三角同理（公式镜像）。"},
  "kp-m2-p2-c3-xing-lie-xiang-liang": {"anchor":"αβᵀ=α(βᵀ) 的秩为 1（α,β 非零）","caption":"向量按排布分行向量（1×n）与列向量（n×1），本质是特殊形状的矩阵；内积 αᵀβ（列×行转置）得数，外积 αβᵀ 得秩 1 矩阵——形状决定一切。","keyPoints":["行向量 1×n、列向量 n×1","αᵀβ 是数；αβᵀ 是 n×n 秩 1 矩阵","转置在行、列之间切换"],"example":"(1,2,3)ᵀ(1,2,3) 是 3×3 矩阵，每行都是首行的倍数。"},
  "kp-m2-p2-c3-ling-xiang-liang": {"anchor":"1·0+0·α₁+…+0·αₛ=0（系数不全为零）","caption":"零向量 0 是分量全为 0 的向量：任何向量组只要包含 0 就必线性相关（取 0 的系数为 1、其余为 0）；这是「判相关」的第一反应。","keyPoints":["0 = 分量全零的向量","含 0 的向量组必线性相关","单个零向量也线性相关"],"example":"组 (0,1,2)（1,1,1)：含零向量，线性相关。"},
  "kp-m2-p2-c3-xiang-liang-zu-xian-xing-zu-he": {"anchor":"β=k₁α₁+…+kₛαₛ","caption":"k₁α₁+…+kₛαₛ 称为向量组的线性组合，能写成这种形式的向量「可由该组线性表示」；全组所有线性组合构成张成空间，维度 = 组的秩。","keyPoints":["组合 = 系数乘向量再相加","全部组合 = 张成空间（维度=秩）","表示系数解方程组求得"],"example":"α₁=(1,0)、α₂=(0,1)、β=(2,3)：β=2α₁+3α₂。"},
  "kp-m2-p2-c3-neng-fou-xian-xing-biao-shi": {"anchor":"r(A)=r(A,β) ⇔ 可表示","caption":"β 能否由 α₁,…,αₛ 线性表示 ⇔ r(α₁,…,αₛ)=r(α₁,…,αₛ,β)；能表示时若 α 组无关则表示唯一，相关则表示有无穷多种。","keyPoints":["可表示 ⇔ 两秩相等","组无关 ⇒ 表示唯一","组相关 ⇒ 表示不唯一（若有）"],"example":"β=(1,1) 由 (1,0)、(0,1) 表示唯一：β=α₁+α₂。"},
  "kp-m2-p2-c3-ding-yi": {"anchor":"r(α₁,…,αₛ)=s ⇔ 线性无关","caption":"线性相关：存在不全为零的数 k₁,…,kₛ 使 k₁α₁+…+kₛαₛ=0；线性无关：上式成立必须所有 kᵢ=0。","keyPoints":["相关 ⇔ 有非零系数组合出 0","无关 ⇔ 只有全零系数","等价判定：r(组)<s ⇔ 相关"],"example":"α₁=(1,0)、α₂=(2,0)：2α₁−α₂=0，相关。"},
  "kp-m2-p2-c3-qi-ci-fang-cheng-pan-ding": {"anchor":"Ax=0 有非零解 ⇔ r(A)<s","caption":"相关性判定统一到方程语言：x₁α₁+…+xₛαₛ=0 有无非零解；用消元求秩即可回答，s>r(A) 时非零解必然存在（组必相关）。","keyPoints":["相关 ⇔ 齐次方程组有非零解","s>r(A) ⇒ 相关","s=r(A) ⇒ 无关（仅零解）"],"example":"5 个 3 维向量：5>3 必相关。"},
  "kp-m2-p2-c3-hang-lie-shi-pan-ding": {"anchor":"|A|=0 ⇔ 相关","caption":"当向量个数等于维数时，按列拼成方阵算行列式：|A|≠0 线性无关，|A|=0 线性相关；这是「秩判定」在方阵情形的快速版。","keyPoints":["n 个 n 维向量 ⇔ 方阵","|A|=0 ⇔ 相关（有非零解）","个数≠维数时退回秩判定"],"example":"三阶行列式为 0 ⇒ 三个 3 维向量相关。"},
  "kp-m2-p2-c3-zhi-pan-ding": {"anchor":"r(α₁,…,αₛ)=s ⇔ 无关","caption":"一般情形的判定标准：向量组线性无关 ⇔ r(α₁,…,αₛ)=s（秩等于个数）；秩小于个数必相关——秩是相关性判定的「通用货币」。","keyPoints":["r=s ⇔ 无关；r<s ⇔ 相关","向量组求秩用行变换最直接，拼矩阵化阶梯","部分组秩 ≤ 整组秩"],"example":"4 个向量秩为 3 ⇒ 相关，且至少一个可由其余表示。"},
  "kp-m2-p2-c3-chang-yong-xing-zhi": {"anchor":"r(部分组)≤r(整组)","caption":"线性相关性常用性质：含零向量必相关；部分相关则整组相关；整组无关则部分无关；向量个数大于维数必相关；无关组添加向量后相关，则新向量可由原组唯一表示。","keyPoints":["部分相关 ⇒ 整组相关（逆否：整组无关 ⇒ 部分无关）","n+1 个 n 维向量必相关","无关组外添一个「可表示」向量 ⇒ 组相关"],"example":"α₁,α₂ 无关而 α₁,α₂,α₃ 相关 ⇒ α₃=λ₁α₁+λ₂α₂（表示唯一）。"},
  "kp-m2-p2-c3-ding-yi-2": {"anchor":"极大无关组含 r 个向量，r=向量组的秩","caption":"极大线性无关组：向量组中一个线性无关的部分组，再添入任何原组向量都变相关——「无关性 + 极大性」两条件；它所含向量个数就是向量组的秩。","keyPoints":["无关 + 再添任一原组向量变相关","极大无关组一般不唯一","所含向量个数 = 向量组的秩"],"example":"α₁=(1,0)、α₂=(2,0)、α₃=(0,1)：{α₁,α₃} 是极大无关组（{α₂,α₃} 也是）。"},
  "kp-m2-p2-c3-qiu-fa": {"anchor":"主元列号 = 极大无关组的下标","caption":"求极大无关组的标准流程：向量按列拼矩阵 → 行变换化行最简形 → 主元所在列对应的「原向量」构成一个极大无关组；其余列向量由主元列线性表出。","keyPoints":["按列拼、行变换、认主元列","主元列对应原向量（不是化简后的列）","非主元列的表示系数可从最简形读出"],"example":"最简形主元在第 1、3 列 ⇒ α₁、α₃ 是极大无关组，α₂ 的系数从第 2 列读出。"},
  "kp-m2-p2-c3-gai-nian": {"anchor":"r(向量组) = 极大无关组大小","caption":"向量组的秩定义为极大线性无关组所含向量的个数：它刻画向量组「真正有几个独立方向」，是把无穷多表示关系压缩成一个数的核心指标。","keyPoints":["秩 = 极大无关组的向量个数","0 ≤ 秩 ≤ 组内向量个数","全零向量组的秩为 0"],"example":"向量组 (1,0),(2,0),(0,1) 的极大无关组含 2 个向量，秩为 2。"},
  "kp-m2-p2-c3-yu-ju-zhen-zhi-guan-xi": {"anchor":"r(α₁,…,αₛ)=r(A)","caption":"向量组按列拼成矩阵后，向量组的秩就是矩阵的秩；由于行秩=列秩，行向量组、列向量组的秩都能用「化行阶梯数非零行」求出。","keyPoints":["向量组的秩 = 拼成矩阵的秩","行秩 = 列秩 = 矩阵秩","行组列组求秩统一走行变换，结果一样"],"example":"三个行向量求秩：拼成 3×n 矩阵直接化行阶梯。"},
  "kp-m2-p2-c3-hu-xiang-xian-xing-biao-shi": {"anchor":"r(Ⅱ)=r(Ⅰ,Ⅱ) 且 r(Ⅰ)=r(Ⅰ,Ⅱ) ⇔ 等价","caption":"两向量组等价指它们能互相线性表示：每个组都能表示出另一组的全部向量；「能表示」是单向关系，等价要求双向都通。","keyPoints":["等价 = 双向都能线性表示","自反、对称、传递（是等价关系）","等价 ⇔ 互相表示 ⇔ 合起来秩不变"],"example":"极大无关组与全组等价：一个方向构造、一个方向天然。"},
  "kp-m2-p2-c3-ding-yi-3": {"anchor":"(α,β)=αᵀβ=(β,α)","caption":"内积定义为对应分量乘积之和：(α,β)=a₁b₁+…+aₙbₙ，记号也写作 αᵀβ；它是把「几何长度、夹角、垂直」翻译进 n 维空间的全部基础。","keyPoints":["(α,β)=Σaᵢbᵢ（一个数）","对称性：(α,β)=(β,α)","线性性：(kα+lγ,β)=k(α,β)+l(γ,β)"],"example":"(1,0,−1)·(2,1,2)=2+0−2=0，两向量正交。"},
  "kp-m2-p2-c3-chang-du": {"anchor":"|α|=√Σaᵢ²","caption":"向量长度（模、范数）|α|=√(α,α)=√(a₁²+…+aₙ²)；长度为 1 的向量叫单位向量，|α|=0 当且仅当 α=零向量。","keyPoints":["|α|=√(α,α)","|kα|=|k|·|α|","单位化：α/|α|（α≠0）"],"example":"α=(3,4)：|α|=5，单位向量 (3/5,4/5)。"},
  "kp-m2-p2-c3-zheng-jiao": {"anchor":"(α,β)=0 ⇔ 正交","caption":"(α,β)=0 称 α 与 β 正交（n 维空间里的「垂直」）；零向量与任何向量正交，但谈正交组时通常只考虑非零向量。","keyPoints":["正交 ⇔ (α,β)=0","零向量与谁都正交（约定排除）","正交向量组（非零、两两正交）必线性无关"],"example":"(1,1,0) 与 (1,−1,0) 正交。"},
  "kp-m2-p2-c3-biao-zhun-zheng-jiao-xiang-liang-zu": {"anchor":"QᵀQ=E（拼成矩阵时）","caption":"标准正交向量组：两两正交且各自为单位向量；由 n 个 n 维标准正交向量可拼出正交矩阵，把一般向量组变成标准正交组靠施密特正交化 + 单位化。","keyPoints":["定义：(αᵢ,αⱼ)=δᵢⱼ","标准正交组必定线性无关，正交保证独立","构造：施密特正交化再单位化"],"example":"(1,1,0)、(1,−1,0) 正交化后单位化得标准正交组。"},
  "kp-m2-p2-c3-tou-ying": {"anchor":"prj_β(α)=(α,β)/|β|（数）；投影向量=系数×β","caption":"向量 α 在非零向量 β 上的投影向量 = [(α,β)/(β,β)]β：系数是「标量投影」、乘上单位方向是「向量投影」；施密特正交化减掉的就是它。","keyPoints":["投影向量 = [(α,β)/(β,β)]β","标量投影（带符号的长度）= (α,β)/|β|","α−投影 = 垂直分量"],"example":"α=(1,1)、β=(1,0)：投影=(1,0)，垂直分量=(0,1)。"},
  "kp-m2-p2-c3-xiao-chu-fen-liang": {"anchor":"γ=α₂−[(α₂,β₁)/(β₁,β₁)]β₁，(γ,β₁)=0","caption":"施密特的「消除分量」：α₂ 减去它沿 β₁ 方向的投影，得到与 β₁ 正交的剩余向量——几何上就是把「平行部分」拆掉，只留「垂直部分」。","keyPoints":["垂直分量 = α₂−投影","它与 β₁ 内积必为 0","对每个新向量重复减投影操作，直到全部正交"],"example":"α=(2,1)、β=(1,0)：γ=(2,1)−(2,0)=(0,1)，与 β 正交。"},
  "kp-m2-p2-c3-dan-wei-hua": {"anchor":"γᵢ=βᵢ/√(βᵢ,βᵢ)","caption":"正交化得到的是正交组（两两垂直但长度随意），再逐个除以自身长度就升级成标准正交组——「先正交、再单位」是标准流程，顺序不能反着混。","keyPoints":["γᵢ=βᵢ/|βᵢ|","先施密特正交化，后单位化","单位化不影响正交性，只把长度调到 1"],"example":"β=(0,1) 单位化还是 (0,1)；β=(2,2) 单位化得 (1/√2,1/√2)。"},
  "kp-m2-p2-c4-shi-yong-tiao-jian": {"anchor":"|A|≠0 且方阵 ⇒ xᵢ=Dᵢ/D","caption":"克拉默法则的适用前提：方程个数与未知数个数相等（系数矩阵为方阵）且系数行列式非零；不满足时改用高斯消元与秩判定。","keyPoints":["方阵 + |A|≠0 双条件","缺条件 ⇒ 用秩讨论","克拉默只给「唯一解」情形"],"example":"3×2 系数矩阵（3 方程 2 未知数）不能用克拉默。"},
  "kp-m2-p2-c4-gong-shi": {"anchor":"xᵢ=Dᵢ/D（i=1,…,n）","caption":"克拉默公式 xᵢ=Dᵢ/D：D 为系数行列式，Dᵢ 为把第 i 列换成常数列所得行列式；适用于唯一解情形（|A|≠0 的方阵方程组）。","keyPoints":["克拉默公式 xᵢ=Dᵢ/D，第 i 列换成常数列","Dᵢ 换的是第 i 列","条件 |A|≠0 必须先验"],"example":"D=3、D₂=6 ⇒ x₂=2。"},
  "kp-m2-p2-c4-ax-0": {"anchor":"r(A)<n ⇔ 有非零解","caption":"齐次线性方程组 Ax=0：常数项全为零；它必有零解 x=0，所以问题从来不是「有没有解」，而是「有没有非零解」——由秩完全决定。","keyPoints":["齐次方程 b=0，必有零解，问的是非零解","有非零解 ⇔ r(A)<n","解集是 n−r 维线性空间"],"example":"A 为 3×4（n=4）、r=2：基础解系含 4−2=2 个向量。"},
  "kp-m2-p2-c4-fei-ling-jie-cun-zai-tiao-jian": {"anchor":"r(A)<n ⇔ Ax=0 有非零解","caption":"齐次方程组 Ax=0 存在非零解的充要条件是 r(A)<n（未知数个数）：秩不够 n，自由未知量就出现，非零解随之出现。","keyPoints":["充要条件：r(A)<n","方程个数 m<n ⇒ 必有非零解","n 个未知 n 个方程时看 |A|：|A|=0 有非零解"],"example":"方阵 |A|=0 ⇒ r<n ⇒ 有非零解。"},
  "kp-m2-p2-c4-r-a-n": {"anchor":"dim(解空间)=n−r(A)","caption":"r(A)<n 是齐次方程组有非零解的等价刻画：n 是未知数个数；r 越小，解空间维数 n−r 越大，自由度越多。","keyPoints":["解空间维数 = n−r(A)","r(A)<n ⇔ 有非零解","r(A)=n ⇔ 只有零解"],"example":"r=1、n=3：解空间是二维平面（过原点）。"},
  "kp-m2-p2-c4-ji-chu-jie-xi": {"anchor":"ξ₁,…,ξ_{n−r} 线性无关，解集=span{ξ₁,…}","caption":"基础解系是齐次方程组解空间的极大无关组：n−r 个线性无关的解向量，所有解都是它们的线性组合——解出基础解系，齐次方程组就全部解完。","keyPoints":["含 n−r(A) 个线性无关的解向量","取法：自由未知量轮流取 1（其余取 0）","基础解系不唯一（但个数唯一）"],"example":"n=3、r=1：基础解系 2 个向量，通解 k₁ξ₁+k₂ξ₂。"},
  "kp-m2-p2-c4-tong-jie": {"anchor":"x=k₁ξ₁+…+k_{n−r}ξ_{n−r}+η*","caption":"齐次方程组的通解 = 基础解系的全部线性组合 x=k₁ξ₁+…+k_{n−r}ξ_{n−r}；非齐次的通解还要再「加一个特解」。","keyPoints":["齐次通解：k₁ξ₁+…+k_{n−r}ξ_{n−r}","非齐次通解 = 特解 + 齐次通解","通解覆盖且仅覆盖全部解"],"example":"r=2、n=4：通解 x=k₁ξ₁+k₂ξ₂+η*。"},
  "kp-m2-p2-c4-zeng-guang-ju-zhen": {"anchor":"(A|b) 的秩记 r(A,b)","caption":"增广矩阵 (A|b) 是在系数矩阵右侧拼上常数列得到的矩阵；方程组的全部信息（有解？","keyPoints":["(A|b)：比 A 多一列","r(A)=r(A|b) ⇔ 有解","行变换必须对整个增广矩阵做"],"example":"r(A)=2、r(A,b)=3 ⇒ 无解。"},
  "kp-m2-p2-c4-r-a-r-a-b-you-jie": {"anchor":"r(A)=r(A,b)=n ⇒ 唯一解","caption":"Ax=b 有解的充要条件：系数矩阵与增广矩阵的秩相等；此时若秩还等于 n 则唯一解、小于 n 则无穷多解——三分类全部由秩读出。","keyPoints":["r(A)=r(A,b) ⇔ 有解","=n 唯一；<n 无穷多","r(A)<r(A,b) 无解"],"example":"r(A)=r(A,b)=2、n=3 ⇒ 无穷多解，一个自由变量。"},
  "kp-m2-p2-c4-wei-yi-jie": {"anchor":"x=A⁻¹b（方阵可逆时）","caption":"Ax=b 有唯一解 ⇔ r(A)=r(A,b)=n：未知数全部被约束住，没有自由未知量；方阵情形对应 |A|≠0（可用克拉默或求逆）。","keyPoints":["唯一解 ⇔ r(A)=r(A,b)=n","唯一解意味着无自由未知量，秩等于 n","方阵时 ⇔ |A|≠0，x=A⁻¹b"],"example":"r(A)=r(A,b)=3、n=3：唯一解 x=(1,0,2)ᵀ 之类。"},
  "kp-m2-p2-c4-wu-qiong-duo-jie": {"anchor":"x=η*+k₁ξ₁+…+k_{n−r}ξ_{n−r}","caption":"Ax=b 有无穷多解 ⇔ r(A)=r(A,b)<n：有解但存在 n−r 个自由未知量，解集是「特解 + 齐次解空间」的仿射集合。","keyPoints":["无穷多解 ⇔ r(A)=r(A,b)<n","自由未知量 n−r 个","解集：特解 + 齐次通解"],"example":"n=3、r=2：解集是一条直线（1 维仿射集）。"},
  "kp-m2-p2-c4-wu-jie": {"anchor":"r(A)<r(A,b) ⇔ 无解","caption":"r(A)<r(A,b) ⇔ 无解：消元后出现「0=非零」的矛盾行；几何上是 b 落在了系数列向量张成空间之外。","keyPoints":["无解 ⇔ r(A)<r(A,b)","标志：矛盾行 (0…0|c)，c≠0","此时不存在特解与通解讨论"],"example":"(0 0 | 5) 一行出现 ⇒ 方程组无解。"},
  "kp-m2-p2-c4-qi-ci-jie-kong-jian": {"anchor":"N(A)={x：Ax=0}，dim N(A)=n−r(A)","caption":"Ax=0 的全体解构成 Rⁿ 的子空间（解空间/零空间），维数为 n−r(A)；「空间」意味着对加法与数乘封闭——这正是齐次解可以任意线性组合的原因。","keyPoints":["齐次解集对线性运算封闭，所以构成子空间","dim(解空间)=n−r(A)","基础解系是解空间的基"],"example":"r=2、n=4：解空间是 4 维空间中过原点的二维平面。"},
  "kp-m2-p2-c4-fei-qi-ci-te-jie": {"anchor":"Aη*=b","caption":"满足 Ax=b 的任一解都是特解：通常令自由未知量全取 0，解出主变量即得最省事的特解；通解里特解只出现一次、不带任意常数。","keyPoints":["特解：Ax=b 的任一解","快捷取法：自由变量全取 0","特解里不带参数 k，带参数的都属于齐次部分"],"example":"最简形给出 x₁=3−k、x₂=k：取 k=0 得特解 (3,0)ᵀ。"},
  "kp-m2-p2-c4-fei-qi-ci-tong-jie-te-jie-qi-ci-tong-jie": {"anchor":"x=η*+Σkᵢξᵢ","caption":"非齐次方程组的通解结构：x=η*+k₁ξ₁+…+k_{n−r}ξ_{n−r}——「一个特解定位置，齐次通解给自由」；","keyPoints":["通解 = 特解 η* + 齐次通解","任意常数 n−r 个","差结构：两非齐次解之差是齐次解"],"example":"n=3、r=1：x=η*+k₁ξ₁+k₂ξ₂，解集是平面。"},
  "kp-m2-p2-c4-gao-si-xiao-yuan": {"anchor":"(A|b)→(行最简形)","caption":"高斯消元：对增广矩阵做初等行变换化行阶梯（判断解的情况），再继续化行最简形（直接读解）；全程只用三类行变换，方程组保持同解。","keyPoints":["高斯消元用行变换做同解变形，解集不变","阶梯形定解的状态（无解/唯一/无穷）","化到行最简形可直接读出通解，主变量用参数表示"],"example":"最简形中主元列对应主变量，其余是自由变量。"},
  "kp-m2-p2-c4-zi-you-wei-zhi-liang": {"anchor":"自由变量数 = n−r","caption":"行最简形中，非主元列对应的未知量是自由未知量，共 n−r 个；它们的取值一旦给定，主变量随之唯一确定——「自由」正是无穷多解的来源。","keyPoints":["自由未知量个数 = n−r(A)","一般取非主元列的变量","轮流取 1（其余取 0）生成基础解系"],"example":"n=4、r=2：x₃、x₄ 自由，令 (x₃,x₄)=(1,0),(0,1)。"},
  "kp-m2-p2-c4-can-shu-jie": {"anchor":"x=η*+k₁ξ₁+…","caption":"参数化解法：自由未知量设为参数，主变量用参数表示，整理成向量线性组合的形式；最终答案写成「特解 + 基础解系的组合」最规范。","keyPoints":["自由变量 → 参数 k","回代时主变量用 k 表示，整理成向量形式","整理成 x=η*+Σkᵢξᵢ"],"example":"x₁=1−k、x₂=k：写成 x=(1,0)+k(−1,1)。"},
  "kp-m2-p2-c5-a": {"anchor":"Aα=λα（α≠0）","caption":"特征值与特征向量的定义式 Aα=λα：方阵 A 作用在非零向量 α 上只产生「伸缩」不改变方向（或反向）","keyPoints":["Aα=λα 是定义等式（λ 复数域讨论）","α 方向不变（或恰好反向）","一个特征值对应无穷多个特征向量（差常数倍）"],"example":"A=(2 0; 0 3)：e₁ 满足 Ae₁=2e₁，λ=2 对应 e₁。"},
  "kp-m2-p2-c5-0": {"anchor":"α≠0 且 Aα=λα","caption":"特征向量必须是非零向量：α=0 时 A·0=λ·0 对任何 λ 都成立，定义就失效了；「α≠0」是定义的一部分，验证特征向量先查它。","keyPoints":["零向量不是任何特征值的特征向量","特征向量非零是定义要求","特征值可以为 0（A 不可逆时）"],"example":"λ=0 时特征向量仍非零：Aα=0 的非零解就是 λ=0 的特征向量。"},
  "kp-m2-p2-c5-ji-he-yi-yi": {"anchor":"Aα=λα：|λα|/|α|=|λ|","caption":"几何上：特征向量是线性变换下「方向不改变」的方向，特征值是该方向上的伸缩倍数——λ>1 拉长、0<λ<1 压缩、λ<0 反向、λ=0 压扁到原点。","keyPoints":["特征向量 = 变换的不变方向","λ 是该方向上的伸缩率","λ=0 表示该方向被压没（A 降秩）"],"example":"对角矩阵 diag(2,3) 把 x 方向拉长 2 倍、y 方向 3 倍——坐标轴就是特征方向。"},
  "kp-m2-p2-c5-e-a-0": {"anchor":"f(λ)=|λE−A|","caption":"特征方程 |λE−A|=0：特征多项式是 λ 的 n 次首一多项式，n 个根（复数域计重数）就是全部特征值；展开时善用行（列）和相等的结构提取因式。","keyPoints":["|λE−A|=0 给出全部特征值","特征多项式是首一 n 次多项式，常数项含 |A|","Σλᵢ=tr(A)、∏λᵢ=|A| 验算"],"example":"二阶阵快速法：λ²−tr(A)λ+|A|=0。"},
  "kp-m2-p2-c5-te-zheng-duo-xiang-shi": {"anchor":"f(λ)=|λE−A|","caption":"特征多项式 f(λ)=|λE−A|：首项 λⁿ、常数项 (−1)ⁿ|A|、λⁿ⁻¹ 系数是 −tr(A)；相似矩阵特征多项式相同，是相似不变量的母体。","keyPoints":["f(λ)=λⁿ−tr(A)λⁿ⁻¹+…+(−1)ⁿ|A|","相似 ⇒ 特征多项式相同","f(A)=O（凯莱—哈密顿，扩展）"],"example":"二阶：f(λ)=λ²−tr(A)λ+|A|，根由韦达定理互验。"},
  "kp-m2-p2-c5-a-e-x-0": {"anchor":"解空间 = ker(A−λE)","caption":"求特征向量即解 (A−λE)x=0：非零解全部是对应 λ 的特征向量；行变换化最简形后，基础解系的非零线性组合就是这一特征值的特征子空间去掉零向量。","keyPoints":["(A−λE)x=0 的非零解 = 特征向量","基础解系含 n−r(A−λE) 个向量","几何重数由基础解系个数读出，即 n−r(A−λE)"],"example":"r(A−λE)=2（n=3）：基础解系 1 个向量，几何重数 1。"},
  "kp-m2-p2-c5-te-zheng-zi-kong-jian": {"anchor":"dim Vλ=n−r(A−λE)","caption":"λ 的特征子空间 Vλ 是 (A−λE)x=0 的解空间：维数是几何重数，介于 1 与代数重数之间；不同特征值的特征子空间除了零向量没有公共元素。","keyPoints":["Vλ=ker(A−λE)","1≤dim Vλ≤代数重数","Vλ∩Vμ={0}（λ≠μ）"],"example":"λ=1 与 λ=2 的特征向量不能相等（否则 λ=1=2 矛盾）。"},
  "kp-m2-p2-c5-ji": {"anchor":"tr(A)=λ₁+…+λₙ","caption":"迹 tr(A)=Σaᵢᵢ=Σλᵢ（全部特征值之和，计重数）；迹还满足 tr(A+B)=tr(A)+tr(B)","keyPoints":["迹等于特征值之和 tr(A)=Σλᵢ，最快的验算","tr(AB)=tr(BA)（循环性质）","常与 |A|=∏λᵢ 联用反求参数"],"example":"已知特征值 2、2、λ₃ 与 tr=7：λ₃=3。"},
  "kp-m2-p2-c5-hang-lie-shi": {"anchor":"|A|=λ₁⋯λₙ","caption":"|A|=λ₁λ₂…λₙ（全部特征值连乘，计重数）：由此 0 是否为特征值直接决定可逆性；也常与迹联立，用两条方程「反求」两个未知特征值。","keyPoints":["行列式等于特征值连乘 |A|=∏λᵢ，判零即判可逆","0 特征值 ⇔ 不可逆","与 tr 联用解参数题"],"example":"特征值 1、−2、3：|A|=−6，A 可逆。"},
  "kp-m2-p2-c5-mi": {"anchor":"Aᵏα=λᵏα","caption":"Aᵏ 的特征值是 λᵏ（特征向量不变）：由 Aᵏα=λᵏα 逐次归纳；配合「f(A) 的特征值=f(λ)」总思想，矩阵幂的问题化成数字幂。","keyPoints":["Aᵏ 的谱 = {λᵢᵏ}","Aᵏα=λᵏα（α 不变）","求 Aⁿ 的套路：先谱再组装"],"example":"λ=−1、2：A⁵ 的特征值 −1、32。"},
  "kp-m2-p2-c5-ni-ju-zhen": {"anchor":"A⁻¹α=λ⁻¹α","caption":"A 可逆时 A⁻¹ 的特征值为 1/λᵢ（特征向量不变）；由 Aα=λα 左乘 A⁻¹ 即得。","keyPoints":["A⁻¹ 的谱 = {1/λᵢ}（需 |A|≠0）","A* 的谱 = {|A|/λᵢ}","A⁻¹、A* 的特征向量全部不变，只有特征值变"],"example":"λ=4、−2：A⁻¹ 的特征值 1/4、−1/2。"},
  "kp-m2-p2-c5-b-p-1-ap": {"anchor":"B=P⁻¹AP","caption":"相似的定义：存在可逆矩阵 P 使 B=P⁻¹AP，称 A 相似于 B；相似是「同一线性变换在不同基下」的表现——同一个人换了套衣服。","keyPoints":["B=P⁻¹AP（P 可逆）⇔ A∽B","几何：同一线性变换在不同基下的矩阵","对角化 = 找 P 使相似对象是对角阵"],"example":"P=(α₁ α₂ … αₙ)（特征向量按列）时 P⁻¹AP=Λ。"},
  "kp-m2-p2-c5-xiang-si-bu-bian-liang": {"anchor":"A∽B ⇒ f_A(λ)=f_B(λ)","caption":"相似矩阵必同享：行列式、迹、秩、特征多项式与全部特征值（连带代数重数）；这些不变量常用来「反求相似中的参数」或判不相似。","keyPoints":["|A|=|B|、tr(A)=tr(B)、r(A)=r(B)","特征多项式相同 ⇒ 特征值相同","不变量不同 ⇒ 必不相似（逆否使用）"],"example":"A∽B 且 tr 差 1 ⇒ 题目给的 P 里藏参数，用 tr 列方程。"},
  "kp-m2-p2-c5-ding-yi": {"anchor":"P⁻¹AP=Λ","caption":"相似对角化：对 n 阶方阵 A，若存在可逆矩阵 P 使 P⁻¹AP=Λ（对角阵），则称 A 可相似对角化；","keyPoints":["定义：∃P 可逆，P⁻¹AP=Λ","P 的列 = 特征向量（顺序与 Λ 一致）","可对角化 ⇔ n 个线性无关特征向量"],"example":"两个不同特征值各一特征向量：P=(α₁ α₂)、Λ=diag(λ₁,λ₂)。"},
  "kp-m2-p2-c5-chong-fen-bi-yao-tiao-jian": {"anchor":"Σ(dim Vλᵢ)=n ⇔ 可对角化","caption":"A 可对角化的充要条件：A 有 n 个线性无关的特征向量，等价于每个特征值的几何重数等于代数重数；「n 个不同特征值」只是充分情形。","keyPoints":["充要：n 个无关特征向量","等价：∀λ，几何重数=代数重数","充分（非必要）：n 个互异特征值"],"example":"二重根几何重数 1：不可对角化（缺一个无关向量）。"},
  "kp-m2-p2-c5-n-ge-xian-xing-wu-guan-te-zheng-xiang-1tmz15": {"anchor":"Σ几何重数=n ⇔ 可对角化","caption":"A 可对角化 ⇔ A 有 n 个线性无关的特征向量 ⇔ 每个特征值的几何重数等于代数重数；不同特征值的特征向量天然无关，重根是唯一要小心的地方。","keyPoints":["充要：n 个线性无关特征向量","等价说法：每个 λ 的几何重数=代数重数","无重根 ⇒ 必可对角化"],"example":"三阶、特征值 1（单）、2（二重且几何重数 2）⇒ 可对角化。"},
  "kp-m2-p2-c5-zhong-gen-qing-kuang": {"anchor":"n−r(A−λE)=k","caption":"k 重特征值要对角化成功，必须解出恰好 k 个线性无关的特征向量（几何重数=k）；流程是解 (A−λE)x=0 看基础解系个数，缺一个就整体失败。","keyPoints":["k 重根需要 k 个无关特征向量","个数 = n−r(A−λE)","任何一个重根不达标 ⇒ 不可对角化"],"example":"三重根解出 3 个无关向量 ⇒ 合格，可对角化。"},
  "kp-m2-p2-c5-shi-te-zheng-zhi": {"anchor":"A=Aᵀ ⇒ λ∈R","caption":"实对称矩阵的特征值全为实数（复根不会出现）：这是实对称矩阵三大性质之一（另两个：不同特征值特征向量正交、必可正交对角化），也保证全程可在实数域操作。","keyPoints":["实对称 ⇒ λᵢ∈R","实对称矩阵的特征向量可取实向量，无需复数","全实特征值为正交对角化铺路，全程实数运算"],"example":"对称阵的特征方程判别式必 ≥0（二阶时直观可见）。"},
  "kp-m2-p2-c5-bu-tong-te-zheng-zhi-te-zheng-xiang-089sws": {"anchor":"(α,β)=0（λ≠μ）","caption":"实对称矩阵不同特征值的特征向量互相正交：由对称性 (Aα,β)=(α,Aβ) 与 λ≠μ 推出内积为零；重根内部不保证，需施密特正交化补齐。","keyPoints":["λ≠μ ⇒ (α,β)=0","同一 λ 内部要自己正交化","全体正交化后单位化拼 Q"],"example":"λ=0 与 λ=5 的特征向量内积必为 0。"},
  "kp-m2-p2-c5-zheng-jiao-dui-jiao-hua": {"anchor":"QᵀAQ=Λ，QᵀQ=E","caption":"正交对角化：把实对称矩阵化为 QᵀAQ=Λ，其中 Q 正交；操作链条：特征值 → 特征向量 → 重根内施密特正交化 → ","keyPoints":["产出：正交矩阵 Q 与对角阵 Λ","重根内部必须施密特正交化","结果用于二次型标准化"],"example":"三阶实对称、单根二重根各就各位：Q 三列单位正交。"},
  "kp-m2-p2-c6-ding-yi": {"anchor":"f(x)=xᵀAx，Aᵀ=A","caption":"二次型：系数在数域上、每个变量次数之和为 2 的齐次多项式；n 个变量的二次型唯一对应一个 n 阶实对称矩阵 A，写作 f=xᵀAx。","keyPoints":["齐二次：只有平方项与交叉项","f=xᵀAx，A 对称且唯一","交叉项系数对半放进矩阵"],"example":"f=2x₁x₂ ⇒ A=(0 1; 1 0)。"},
  "kp-m2-p2-c6-ju-zhen-biao-shi-x-tax": {"anchor":"f=xᵀAx=(Cy)ᵀA(Cy)=yᵀBy","caption":"把二次型写成 f=xᵀAx：A 实对称、由系数唯一确定；这一表示让「研究二次型」变成「研究对称矩阵」，化标准形对应合同变换 B=CᵀAC。","keyPoints":["f=xᵀAx 与对称 A 互相唯一确定","换元 x=Cy ⇒ B=CᵀAC","秩、惯性指数都是 B/ A 的不变量"],"example":"f=xᵀAx、A=(1 2; 2 1)：特征值 3、−1 直接给标准形系数。"},
  "kp-m2-p2-c6-dui-chen-ju-zhen": {"anchor":"Aᵀ=A 且 f=xᵀAx","caption":"二次型的矩阵 A 必须取对称矩阵（aᵢⱼ=aⱼᵢ=交叉项系数一半、aᵢᵢ=平方项系数）：这一约定保证表示唯一，也使特征值、合同等工具全部适用。","keyPoints":["A 对称：表示唯一的代价与好处","aᵢᵢ=平方系数、aᵢⱼ=c/2","对称 ⇒ 特征值全实（可用正交变换）"],"example":"f=−x₁²+6x₁x₂+5x₂² ⇒ A=(−1 3; 3 5)。"},
  "kp-m2-p2-c6-b-c-tac": {"anchor":"B=CᵀAC","caption":"线性变换 x=Cy 下二次型矩阵从 A 变成 B=CᵀAC：这种关系叫合同；「Cᵀ 在左、C 在右」与相似（P⁻¹ 在左）结构不同、别混写。","keyPoints":["B=CᵀAC（C 可逆）⇔ A 与 B 合同","与相似 P⁻¹AP 记号区分","合同变换保持惯性指数"],"example":"C=E 时 B=A（恒等变换）；C 换列时 B 是 A 的对称重排。"},
  "kp-m2-p2-c6-he-tong-ju-zhen": {"anchor":"B=CᵀAC，C 可逆","caption":"A 与 B 合同：存在可逆 C 使 B=CᵀAC（要求 A、B 对称）；","keyPoints":["合同：B=CᵀAC（对称矩阵间）","相似关系满足自反、对称、传递三条","合同 ⇔ 正负惯性指数对应相等"],"example":"A 与其标准形矩阵合同；实对称矩阵按惯性指数分类。"},
  "kp-m2-p2-c6-er-ci-xing-de-zhi-deng-yu-qi-dui-chen-0hic6u": {"anchor":"r(f)=r(A)","caption":"二次型的秩规定为对称矩阵 A 的秩：合同变换（可逆线性换元）不改秩，所以它等于标准形中非零平方项的个数——这一传递让秩成为最稳的不变量。","keyPoints":["r(f)=r(A)=p+q","合同变换保持秩不变，规范形项数稳定","标准形中非零平方项个数就是秩，可互验"],"example":"A 为 3 阶、r=2：规范形有两个 ±1 项、一个 0。"},
  "kp-m2-p2-c6-yong-chu-deng-bian-huan-huo-fei-ling-zi-0hxv1t": {"anchor":"r(A)=非零行数=非零平方项数","caption":"求二次型的秩两条路：对 A 做初等变换（合同变换对也行）化阶梯数非零行；或直接找 A 的最高阶非零子式——与矩阵秩的求法完全一致。","keyPoints":["A 化行阶梯数非零行","求秩也可以找最高阶非零子式，与阶梯法互验","结果 = 标准形非零项数（互验）"],"example":"A 的三阶子式全零、二阶子式非零 ⇒ 秩 2。"},
  "kp-m2-p2-c6-zhi-biao-shi-er-ci-xing-zhong-zhen-1e6ub9": {"anchor":"有效方向=r，零方向=n−r","caption":"二次型的秩 = 化简后真正「活着」的平方方向数：秩 r 的二次型在规范形里恰好有 r 个 ±1 方向","keyPoints":["r = 有效平方方向个数","n−r 个方向 f 恒为 0（核方向）","r=n 时无退化方向（A 可逆）"],"example":"f=x₁²（n=2、r=1）：y₂ 方向上函数恒为 0。"},
  "kp-m2-p2-c6-biao-zhun-xing": {"anchor":"f=d₁y₁²+d₂y₂²+…","caption":"标准形：只含平方项（无交叉项）的二次型 Σdᵢyᵢ²；任何二次型都能经可逆线性变换化为标准形——配方法与正交变换法是两条路。","keyPoints":["标准形：Σdᵢyᵢ²（系数任意实数）","不唯一（系数随变换变化）","非零系数个数 = 秩（不变）"],"example":"f=x₁²+2x₁x₂+x₂² 配方成 (x₁+x₂)²=y₁²，标准形只有一项。"},
  "kp-m2-p2-c6-gui-fan-xing": {"anchor":"f=y₁²+…+y_p²−y_{p+1}²−…−y_{p+q}²","caption":"规范形：标准形的进一步规范——非零系数全部变成 +1 或 −1：f=y₁²+…+y_p²−y_{p+1}²−…−y_{p","keyPoints":["系数只取 1、−1、0","正项 p 个、负项 q 个","规范形唯一（实二次型）"],"example":"标准形 4y₁²−9y₂² ⇒ 规范形 y₁²−y₂²（p=q=1）。"},
  "kp-m2-p2-c6-zheng-fu-guan-xing-zhi-shu": {"anchor":"p+q=r(A)，s=p−q","caption":"正惯性指数 p、负惯性指数 q：规范形中 +1 与 −1 项的个数，分别等于正、负特征值的个数；","keyPoints":["p=正项数=正特征值个数","q=负项数=负特征值个数","合同 ⇔ p、q 对应相等"],"example":"λ=3、−1、0：p=1、q=1、r=2。"},
  "kp-m2-p2-c6-ke-ni-xian-xing-bian-huan-bu-gai-bian-0gbrh4": {"anchor":"B=CᵀAC ⇒ p(B)=p(A)、q(B)=q(A)","caption":"惯性定理（数二表述）：可逆线性变换 x=Cy 无论如何取，化出的标准形里正项个数 p 与负项个数 q 始终不变——系数会","keyPoints":["p、q 是合同不变量","不同换元结果系数不同、个数相同","三个不变量稳定，是规范形唯一的原因"],"example":"配方法与正交变换法各自化简，p、q 必然一致。"},
  "kp-m2-p2-c6-gui-fan-xing-zhong-de-zheng-xiang-shu-0fb51n": {"anchor":"规范形由 (p,q) 唯一确定","caption":"实二次型的规范形 f=y₁²+…+y_p²−…−y_{p+q}² 中的 p、q","keyPoints":["p、q、零项数三个不变量","规范形唯一（实二次型）","合同分类 = (p,q) 标签分类"],"example":"n=3 的所有二次型按 (p,q) 分成 10 类（含顺序）。"},
  "kp-m2-p2-c6-yong-guan-xing-zhi-shu-pan-duan-er-ci-05vhle": {"anchor":"q=0 且 p=n ⇔ 正定","caption":"由惯性指数立刻读出符号结构：q=0 且 p=n 正定；p=0 且 q=n 负定；缺零项但不全正负为不定；","keyPoints":["正定 ⇔ p=n、q=0","不定 ⇔ p>0 且 q>0","半正定 ⇔ q=0 且 p<n"],"example":"p=2、q=1：不定（既有正方向又有负方向）。"},
  "kp-m2-p2-c6-pei-fang-fa": {"anchor":"ax²+2bxy+cy²=a(x+b/a·y)²+(c−b²/a)y²","caption":"配方法化标准形：每次围绕一个「有平方项」的变量把含它的项配成完全平方，换元后交叉项减少一个；","keyPoints":["配方法逐变量配方消交叉项，每次少一项","无平方项先作差和换元造出平方项","变换写成 x=Cy 便于验可逆"],"example":"f=x₁²+2x₁x₂+3x₂²=(x₁+x₂)²+2x₂²。"},
  "kp-m2-p2-c6-zheng-jiao-bian-huan-fa": {"anchor":"f=λ₁y₁²+λ₂y₂²+…","caption":"正交变换法：求实对称矩阵 A 的特征值 λᵢ 与单位正交特征向量，用 x=Qy 变换后 f=Σλᵢyᵢ²——标准形系数恰","keyPoints":["x=Qy，Q 正交（QᵀQ=E）","标准形系数 = 特征值 λᵢ","p=正特征值个数、q=负特征值个数"],"example":"A 特征值 3、−1：正交变换下 f=3y₁²−y₂²。"},
  "kp-m2-p2-c6-zheng-ding-ding-yi": {"anchor":"xᵀAx>0（∀x≠0）","caption":"正定二次型：对任意非零向量 x 都有 f(x)=xᵀAx>0（对称 A）；几何上 f=1 的等值面是椭球面——「除原点外处处向上」。","keyPoints":["∀x≠0：xᵀAx>0 ⇔ 正定","正定 ⇒ A 对称且可逆","负定的定义关于 f<0 对称成立"],"example":"f=x₁²+x₂² 正定；f=x₁²−x₂² 不正定（x=(0,1) 时为负）。"},
  "kp-m2-p2-c6-te-zheng-zhi-pan-bie": {"anchor":"A 正定 ⇔ λᵢ>0 ∀i","caption":"正定的特征值判别法：A 正定 ⇔ A 的特征值全部大于 0；由正交变换 f=Σλᵢyᵢ² 一眼看出——各方向都「向上」等价于各方向伸缩率都正。","keyPoints":["正定 ⇔ λᵢ>0（全部）","负定 ⇔ λᵢ<0（全部）","半正定 ⇔ λᵢ≥0 且有 0"],"example":"特征值 1、2、3：正定；1、0、2：半正定不正定。"},
  "kp-m2-p2-c6-shun-xu-zhu-zi-shi-pan-bie": {"anchor":"Δₖ=|Aₖ|>0（k=1,…,n）","caption":"顺序主子式判别法：A 正定 ⇔ 各阶顺序主子式（左上角 1 到 n 阶行列式）全部大于 0；它免去了求特征值，是手算正定判别的主力。","keyPoints":["Δ₁>0、Δ₂>0、…、Δₙ>0 ⇔ 正定","只看「顺序」主子式（左上角）","负定对应「奇负偶正」的推广判据"],"example":"A=(2 1; 1 2)：Δ₁=2、Δ₂=3，都正 ⇒ 正定。"}
}
